INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Mt', 12, 'pt', '[{"numero": 1, "texto": "Naquele tempo Jesus estava indo pelas plantações de cereais no sábado. Seus discípulos tinham fome, e começaram a arrancar espigas e a comer."}, {"numero": 2, "texto": "Quando os fariseus viram, disseram-lhe: Eis que os teus discípulos fazem o que não é lícito fazer no sábado."}, {"numero": 3, "texto": "Ele, porém, lhes disse: Não lestes o que Davi fez quando teve fome, ele e os que com ele estavam,"}, {"numero": 4, "texto": "Como ele entrou na casa de Deus, e comeu os pães da proposição, que a ele não era lícito comer, nem também aos que com ele estavam, a não ser somente aos sacerdotes?"}, {"numero": 5, "texto": "Ou não lestes na Lei que, nos sábados, os sacerdotes no Templo profanam o sábado, sem se tornarem culpados?"}, {"numero": 6, "texto": "Eu, porém, vos digo que o maior que o Templo está aqui."}, {"numero": 7, "texto": "Mas se vós soubésseis o que significa: ‘Quero misericórdia, e não sacrifício’, não condenaríeis os inocentes."}, {"numero": 8, "texto": "Porque o Filho do homem é Senhor até do sábado."}, {"numero": 9, "texto": "E partindo dali, [Jesus] entrou na sinagoga deles."}, {"numero": 10, "texto": "E eis que havia ali um homem que tinha uma mão definhada; e eles, a fim de o acusarem, perguntaram-lhe: É lícito curar nos sábados?"}, {"numero": 11, "texto": "E ele lhes respondeu: Qual de vós será a pessoa que, caso tenha uma ovelha, e se a tal cair em uma cova no sábado, não usará de sua força para a levantar?"}, {"numero": 12, "texto": "Ora, quanto mais vale um ser humano que uma ovelha! Assim, pois, é lícito fazer o bem nos sábados."}, {"numero": 13, "texto": "Então disse para aquele homem: Estende a tua mão. Ele a estendeu, e foi-lhe restaurada, sã como a outra."}, {"numero": 14, "texto": "Então os fariseus saíram e se reuniram para planejar contra ele, como o matariam."}, {"numero": 15, "texto": "Mas Jesus, sabendo disso, retirou-se dali. Muitas multidões o seguiram, e ele curou a todos."}, {"numero": 16, "texto": "E ele lhes ordenava que não o tornassem conhecido;"}, {"numero": 17, "texto": "Para que se cumprisse o que foi dito pelo profeta Isaías:"}, {"numero": 18, "texto": "Eis aqui meu servo a quem escolhi, meu amado em quem minha alma se agrada; sobre ele porei o meu Espírito, e ele anunciará justiça às nações."}, {"numero": 19, "texto": "Ele não fará brigas, nem gritará; ninguém ouvirá pelas ruas a sua voz."}, {"numero": 20, "texto": "A cana rachada ele não quebrará, o pavio que fumega ele não apagará, até que conduza a justiça à vitória."}, {"numero": 21, "texto": "E em seu nome as nações terão esperança."}, {"numero": 22, "texto": "Então lhe trouxeram um endemoninhado cego e mudo; e ele o curou de tal maneira que o cego e mudo passou a falar e a ver."}, {"numero": 23, "texto": "E todas as multidões se admiravam e diziam: Não é este o Filho de Davi?"}, {"numero": 24, "texto": "Mas quando os fariseus ouviam isso, diziam: Ele não expulsa os demônios, a não ser por Belzebu, o chefe dos demônios."}, {"numero": 25, "texto": "Porém Jesus, entendendo os pensamentos deles, disse-lhes: Todo reino dividido contra si mesmo é destruído; e toda cidade ou casa dividida contra si mesma não permanecerá."}, {"numero": 26, "texto": "Ora, se Satanás expulsa a Satanás, contra si mesmo está dividido; como, pois, permanecerá o seu reino?"}, {"numero": 27, "texto": "E se eu expulso os demônios por Belzebu, então por quem vossos filhos os expulsam? Portanto, eles mesmos serão vossos juízes."}, {"numero": 28, "texto": "Mas se eu pelo Espírito de Deus expulso os demônios, logo o Reino de Deus já chegou sobre vos."}, {"numero": 29, "texto": "Ou como pode alguém entrar na casa do valente, e saquear seus bens, sem primeiro amarrar ao valente? Depois disso saqueará sua casa."}, {"numero": 30, "texto": "Quem não é comigo é contra mim; e quem não ajunta comigo, espalha."}, {"numero": 31, "texto": "Por isso eu vos digo: todo pecado e blasfêmia serão perdoados aos seres humanos; mas a blasfêmia contra o Espírito não será perdoada aos seres humanos."}, {"numero": 32, "texto": "E qualquer um que falar palavra contra o Filho do homem lhe será perdoado; mas qualquer um que falar contra o Espírito Santo, não lhe será perdoado, nem na era presente, nem na futura."}, {"numero": 33, "texto": "Ou fazei a árvore boa, e seu fruto bom; ou fazei a árvore má, e seu fruto mau; pois pelo fruto se conhece a árvore."}, {"numero": 34, "texto": "Ninhada de víboras, como podeis vós falar boas coisas, sendo maus? Pois a boca fala do que o coração tem em abundância."}, {"numero": 35, "texto": "A pessoa boa tira coisas boas do bom tesouro do coração, e a pessoa má tira coisas más do tesouro mau."}, {"numero": 36, "texto": "Eu, porém, vos digo que de toda palavra imprudente que as pessoas falarem, dela prestarão contas no dia do juízo."}, {"numero": 37, "texto": "Porque por tuas palavras serás justificado, e por tuas palavras serás condenado."}, {"numero": 38, "texto": "Então responderam uns dos escribas e dos fariseus, dizendo: Mestre, queremos ver de ti algum sinal."}, {"numero": 39, "texto": "Mas ele lhes deu a seguinte resposta: Uma geração má e adúltera pede sinal; mas não lhe será dado, exceto o sinal do profeta Jonas."}, {"numero": 40, "texto": "Porque assim como Jonas esteve três dias e três noites no ventre da baleia, assim também o Filho do homem estará três dias e três noites no coração da terra."}, {"numero": 41, "texto": "Os de Nínive se levantarão no Juízo com esta geração, e a condenarão; porque se arrependeram com a pregação de Jonas. E eis aqui quem é maior que Jonas."}, {"numero": 42, "texto": "A rainha do sul se levantará no Juízo com esta geração, e a condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão. E eis aqui quem é maior que Salomão."}, {"numero": 43, "texto": "Quando o espírito imundo sai de alguém, anda por lugares secos buscando repouso, e não o acha."}, {"numero": 44, "texto": "Então diz: ‘Voltarei para a minha casa, de onde saí.’ E quando chega, a encontra desocupada, varrida, e arrumada."}, {"numero": 45, "texto": "Então vai, e toma consigo outros sete espíritos piores que ele; eles entram, e moram ali; e a última [condição] de tal pessoa se torna pior que a primeira. Assim também acontecerá com esta geração má."}, {"numero": 46, "texto": "Enquanto ele ainda estava falando às multidões, eis que sua mãe e seus irmãos estavam fora, querendo falar com ele."}, {"numero": 47, "texto": "E alguém lhe disse: Eis que tua mãe e teus irmãos estão fora, querendo falar contigo."}, {"numero": 48, "texto": "Porém ele disse em resposta ao que o avisou: Quem é minha mãe? E quem são meus irmãos?"}, {"numero": 49, "texto": "Então estendeu sua mão para os seus discípulos, e disse: Eis aqui minha mãe e meus irmãos;"}, {"numero": 50, "texto": "Pois qualquer um que fizer a vontade do meu Pai, que está nos céus, esse é meu irmão, e irmã, e mãe."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 12, 'en', '[{"numero": 1, "texto": "At that time Jesus went on the sabbath day through the corn; and his disciples were an hungred, and began to pluck the ears of corn and to eat."}, {"numero": 2, "texto": "But when the Pharisees saw it, they said unto him, Behold, thy disciples do that which is not lawful to do upon the sabbath day."}, {"numero": 3, "texto": "But he said unto them, Have ye not read what David did, when he was an hungred, and they that were with him;"}, {"numero": 4, "texto": "How he entered into the house of God, and did eat the shewbread, which was not lawful for him to eat, neither for them which were with him, but only for the priests?"}, {"numero": 5, "texto": "Or have ye not read in the law, how that on the sabbath days the priests in the temple profane the sabbath, and are blameless?"}, {"numero": 6, "texto": "But I say unto you, That in this place is one greater than the temple."}, {"numero": 7, "texto": "But if ye had known what this meaneth, I will have mercy, and not sacrifice, ye would not have condemned the guiltless."}, {"numero": 8, "texto": "For the Son of man is Lord even of the sabbath day."}, {"numero": 9, "texto": "And when he was departed thence, he went into their synagogue:"}, {"numero": 10, "texto": "And, behold, there was a man which had his hand withered. And they asked him, saying, Is it lawful to heal on the sabbath days? that they might accuse him."}, {"numero": 11, "texto": "And he said unto them, What man shall there be among you, that shall have one sheep, and if it fall into a pit on the sabbath day, will he not lay hold on it, and lift it out?"}, {"numero": 12, "texto": "How much then is a man better than a sheep? Wherefore it is lawful to do well on the sabbath days."}, {"numero": 13, "texto": "Then saith he to the man, Stretch forth thine hand. And he stretched it forth; and it was restored whole, like as the other."}, {"numero": 14, "texto": "Then the Pharisees went out, and held a council against him, how they might destroy him."}, {"numero": 15, "texto": "But when Jesus knew it, he withdrew himself from thence: and great multitudes followed him, and he healed them all;"}, {"numero": 16, "texto": "And charged them that they should not make him known:"}, {"numero": 17, "texto": "That it might be fulfilled which was spoken by Esaias the prophet, saying,"}, {"numero": 18, "texto": "Behold my servant, whom I have chosen; my beloved, in whom my soul is well pleased: I will put my spirit upon him, and he shall shew judgment to the Gentiles."}, {"numero": 19, "texto": "He shall not strive, nor cry; neither shall any man hear his voice in the streets."}, {"numero": 20, "texto": "A bruised reed shall he not break, and smoking flax shall he not quench, till he send forth judgment unto victory."}, {"numero": 21, "texto": "And in his name shall the Gentiles trust."}, {"numero": 22, "texto": "Then was brought unto him one possessed with a devil, blind, and dumb: and he healed him, insomuch that the blind and dumb both spake and saw."}, {"numero": 23, "texto": "And all the people were amazed, and said, Is not this the son of David?"}, {"numero": 24, "texto": "But when the Pharisees heard it, they said, This fellow doth not cast out devils, but by Beelzebub the prince of the devils."}, {"numero": 25, "texto": "And Jesus knew their thoughts, and said unto them, Every kingdom divided against itself is brought to desolation; and every city or house divided against itself shall not stand:"}, {"numero": 26, "texto": "And if Satan cast out Satan, he is divided against himself; how shall then his kingdom stand?"}, {"numero": 27, "texto": "And if I by Beelzebub cast out devils, by whom do your children cast them out? therefore they shall be your judges."}, {"numero": 28, "texto": "But if I cast out devils by the Spirit of God, then the kingdom of God is come unto you."}, {"numero": 29, "texto": "Or else how can one enter into a strong man''s house, and spoil his goods, except he first bind the strong man? and then he will spoil his house."}, {"numero": 30, "texto": "He that is not with me is against me; and he that gathereth not with me scattereth abroad."}, {"numero": 31, "texto": "Wherefore I say unto you, All manner of sin and blasphemy shall be forgiven unto men: but the blasphemy against the Holy Ghost shall not be forgiven unto men."}, {"numero": 32, "texto": "And whosoever speaketh a word against the Son of man, it shall be forgiven him: but whosoever speaketh against the Holy Ghost, it shall not be forgiven him, neither in this world, neither in the world to come."}, {"numero": 33, "texto": "Either make the tree good, and his fruit good; or else make the tree corrupt, and his fruit corrupt: for the tree is known by his fruit."}, {"numero": 34, "texto": "O generation of vipers, how can ye, being evil, speak good things? for out of the abundance of the heart the mouth speaketh."}, {"numero": 35, "texto": "A good man out of the good treasure of the heart bringeth forth good things: and an evil man out of the evil treasure bringeth forth evil things."}, {"numero": 36, "texto": "But I say unto you, That every idle word that men shall speak, they shall give account thereof in the day of judgment."}, {"numero": 37, "texto": "For by thy words thou shalt be justified, and by thy words thou shalt be condemned."}, {"numero": 38, "texto": "Then certain of the scribes and of the Pharisees answered, saying, Master, we would see a sign from thee."}, {"numero": 39, "texto": "But he answered and said unto them, An evil and adulterous generation seeketh after a sign; and there shall no sign be given to it, but the sign of the prophet Jonas:"}, {"numero": 40, "texto": "For as Jonas was three days and three nights in the whale''s belly; so shall the Son of man be three days and three nights in the heart of the earth."}, {"numero": 41, "texto": "The men of Nineveh shall rise in judgment with this generation, and shall condemn it: because they repented at the preaching of Jonas; and, behold, a greater than Jonas is here."}, {"numero": 42, "texto": "The queen of the south shall rise up in the judgment with this generation, and shall condemn it: for she came from the uttermost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here."}, {"numero": 43, "texto": "When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest, and findeth none."}, {"numero": 44, "texto": "Then he saith, I will return into my house from whence I came out; and when he is come, he findeth it empty, swept, and garnished."}, {"numero": 45, "texto": "Then goeth he, and taketh with himself seven other spirits more wicked than himself, and they enter in and dwell there: and the last state of that man is worse than the first. Even so shall it be also unto this wicked generation."}, {"numero": 46, "texto": "While he yet talked to the people, behold, his mother and his brethren stood without, desiring to speak with him."}, {"numero": 47, "texto": "Then one said unto him, Behold, thy mother and thy brethren stand without, desiring to speak with thee."}, {"numero": 48, "texto": "But he answered and said unto him that told him, Who is my mother? and who are my brethren?"}, {"numero": 49, "texto": "And he stretched forth his hand toward his disciples, and said, Behold my mother and my brethren!"}, {"numero": 50, "texto": "For whosoever shall do the will of my Father which is in heaven, the same is my brother, and sister, and mother."}]'::jsonb, 'King James Version'),
  ('Mt', 12, 'fr', '[{"numero": 1, "texto": "En ce temps-là, Jésus traversa des champs de blé un jour de sabbat. Ses disciples, qui avaient faim, se mirent à arracher des épis et à manger."}, {"numero": 2, "texto": "Les pharisiens, voyant cela, lui dirent: Voici, tes disciples font ce qu''''il n''''est pas permis de faire pendant le sabbat."}, {"numero": 3, "texto": "Mais Jésus leur répondit: N''''avez-vous pas lu ce que fit David, lorsqu''''il eut faim, lui et ceux qui étaient avec lui;"}, {"numero": 4, "texto": "comment il entra dans la maison de Dieu, et mangea les pains de proposition, qu''''il ne lui était pas permis de manger, non plus qu''''à ceux qui étaient avec lui, et qui étaient réservés aux sacrificateurs seuls?"}, {"numero": 5, "texto": "Ou, n''''avez-vous pas lu dans la loi que, les jours de sabbat, les sacrificateurs violent le sabbat dans le temple, sans se rendre coupables?"}, {"numero": 6, "texto": "Or, je vous le dis, il y a ici quelque chose de plus grand que le temple."}, {"numero": 7, "texto": "Si vous saviez ce que signifie: Je prends plaisir à la miséricorde, et non aux sacrifices, vous n''''auriez pas condamné des innocents."}, {"numero": 8, "texto": "Car le Fils de l''''homme est maître du sabbat."}, {"numero": 9, "texto": "Etant parti de là, Jésus entra dans la synagogue."}, {"numero": 10, "texto": "Et voici, il s''''y trouvait un homme qui avait la main sèche. Ils demandèrent à Jésus: Est-il permis de faire une guérison les jours de sabbat? C''''était afin de pouvoir l''''accuser."}, {"numero": 11, "texto": "Il leur répondit: Lequel d''''entre vous, s''''il n''''a qu''''une brebis et qu''''elle tombe dans une fosse le jour du sabbat, ne la saisira pour l''''en retirer?"}, {"numero": 12, "texto": "Combien un homme ne vaut-il pas plus qu''''une brebis! Il est donc permis de faire du bien les jours de sabbat."}, {"numero": 13, "texto": "Alors il dit à l''''homme: Etends ta main. Il l''''étendit, et elle devint saine comme l''''autre."}, {"numero": 14, "texto": "Les pharisiens sortirent, et ils se consultèrent sur les moyens de le faire périr."}, {"numero": 15, "texto": "Mais Jésus, l''''ayant su, s''''éloigna de ce lieu. Une grande foule le suivit. Il guérit tous les malades,"}, {"numero": 16, "texto": "et il leur recommanda sévèrement de ne pas le faire connaître,"}, {"numero": 17, "texto": "afin que s''''accomplît ce qui avait été annoncé par Esaïe, le prophète:"}, {"numero": 18, "texto": "Voici mon serviteur que j''''ai choisi, Mon bien-aimé en qui mon âme a pris plaisir. Je mettrai mon Esprit sur lui, Et il annoncera la justice aux nations."}, {"numero": 19, "texto": "Il ne contestera point, il ne criera point, Et personne n''''entendra sa voix dans les rues."}, {"numero": 20, "texto": "Il ne brisera point le roseau cassé, Et il n''''éteindra point le lumignon qui fume, Jusqu''''à ce qu''''il ait fait triompher la justice."}, {"numero": 21, "texto": "Et les nations espéreront en son nom."}, {"numero": 22, "texto": "Alors on lui amena un démoniaque aveugle et muet, et il le guérit, de sorte que le muet parlait et voyait."}, {"numero": 23, "texto": "Toute la foule étonnée disait: N''''est-ce point là le Fils de David?"}, {"numero": 24, "texto": "Les pharisiens, ayant entendu cela, dirent: Cet homme ne chasse les démons que par Béelzébul, prince des démons."}, {"numero": 25, "texto": "Comme Jésus connaissait leurs pensées, il leur dit: Tout royaume divisé contre lui-même est dévasté, et toute ville ou maison divisée contre elle-même ne peut subsister."}, {"numero": 26, "texto": "Si Satan chasse Satan, il est divisé contre lui-même; comment donc son royaume subsistera-t-il?"}, {"numero": 27, "texto": "Et si moi, je chasse les démons par Béelzébul, vos fils, par qui les chassent-ils? C''''est pourquoi ils seront eux-mêmes vos juges."}, {"numero": 28, "texto": "Mais, si c''''est par l''''Esprit de Dieu que je chasse les démons, le royaume de Dieu est donc venu vers vous."}, {"numero": 29, "texto": "Ou, comment quelqu''''un peut-il entrer dans la maison d''''un homme fort et piller ses biens, sans avoir auparavant lié cet homme fort? Alors seulement il pillera sa maison."}, {"numero": 30, "texto": "Celui qui n''''est pas avec moi est contre moi, et celui qui n''''assemble pas avec moi disperse."}, {"numero": 31, "texto": "C''''est pourquoi je vous dis: Tout péché et tout blasphème sera pardonné aux hommes, mais le blasphème contre l''''Esprit ne sera point pardonné."}, {"numero": 32, "texto": "Quiconque parlera contre le Fils de l''''homme, il lui sera pardonné; mais quiconque parlera contre le Saint-Esprit, il ne lui sera pardonné ni dans ce siècle ni dans le siècle à venir."}, {"numero": 33, "texto": "Ou dites que l''''arbre est bon et que son fruit est bon, ou dites que l''''arbre est mauvais et que son fruit est mauvais; car on connaît l''''arbre par le fruit."}, {"numero": 34, "texto": "Races de vipères, comment pourriez-vous dire de bonnes choses, méchants comme vous l''''êtes? Car c''''est de l''''abondance du coeur que la bouche parle."}, {"numero": 35, "texto": "L''''homme bon tire de bonnes choses de son bon trésor, et l''''homme méchant tire de mauvaises choses de son mauvais trésor."}, {"numero": 36, "texto": "Je vous le dis: au jour du jugement, les hommes rendront compte de toute parole vaine qu''''ils auront proférée."}, {"numero": 37, "texto": "Car par tes paroles tu seras justifié, et par tes paroles tu seras condamné."}, {"numero": 38, "texto": "Alors quelques-uns des scribes et des pharisiens prirent la parole, et dirent: Maître, nous voudrions te voir faire un miracle."}, {"numero": 39, "texto": "Il leur répondit: Une génération méchante et adultère demande un miracle; il ne lui sera donné d''''autre miracle que celui du prophète Jonas."}, {"numero": 40, "texto": "Car, de même que Jonas fut trois jours et trois nuits dans le ventre d''''un grand poisson, de même le Fils de l''''homme sera trois jours et trois nuits dans le sein de la terre."}, {"numero": 41, "texto": "Les hommes de Ninive se lèveront, au jour du jugement, avec cette génération et la condamneront, parce qu''''ils se repentirent à la prédication de Jonas; et voici, il y a ici plus que Jonas."}, {"numero": 42, "texto": "La reine du Midi se lèvera, au jour du jugement, avec cette génération et la condamnera, parce qu''''elle vint des extrémités de la terre pour entendre la sagesse de Salomon, et voici, il y a ici plus que Salomon."}, {"numero": 43, "texto": "Lorsque l''''esprit impur est sorti d''''un homme, il va par des lieux arides, cherchant du repos, et il n''''en trouve point."}, {"numero": 44, "texto": "Alors il dit: Je retournerai dans ma maison d''''où je suis sorti; et, quand il arrive, il la trouve vide, balayée et ornée."}, {"numero": 45, "texto": "Il s''''en va, et il prend avec lui sept autres esprits plus méchants que lui; ils entrent dans la maison, s''''y établissent, et la dernière condition de cet homme est pire que la première. Il en sera de même pour cette génération méchante."}, {"numero": 46, "texto": "Comme Jésus s''''adressait encore à la foule, voici, sa mère et ses frères, qui étaient dehors, cherchèrent à lui parler."}, {"numero": 47, "texto": "Quelqu''''un lui dit: Voici, ta mère et tes frères sont dehors, et ils cherchent à te parler."}, {"numero": 48, "texto": "Mais Jésus répondit à celui qui le lui disait: Qui est ma mère, et qui sont mes frères?"}, {"numero": 49, "texto": "Puis, étendant la main sur ses disciples, il dit: Voici ma mère et mes frères."}, {"numero": 50, "texto": "Car, quiconque fait la volonté de mon Père qui est dans les cieux, celui-là est mon frère, et ma soeur, et ma mère."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 12, 'es', '[{"numero": 1, "texto": "EN aquel tiempo iba Jesús por los sembrados en sábado; y sus discípulos tenían hambre, y comenzaron á coger espigas, y á comer."}, {"numero": 2, "texto": "Y viéndolo los Fariseos, le dijeron: He aquí tus discípulos hacen lo que no es lícito hacer en sábado."}, {"numero": 3, "texto": "Y él les dijo: ¿No habéis leído qué hizo David, teniendo él hambre y los que con él estaban:"}, {"numero": 4, "texto": "Cómo entró en la casa de Dios, y comió los panes de la proposición, que no le era lícito comer, ni á los que estaban con él, sino á solos los sacerdotes?"}, {"numero": 5, "texto": "O ¿no habéis leído en la ley, que los sábados en el templo los sacerdotes profanan el sábado, y son sin culpa?"}, {"numero": 6, "texto": "Pues os digo que uno mayor que el templo está aquí."}, {"numero": 7, "texto": "Mas si supieseis qué es: Misericordia quiero y no sacrificio, no condenaríais á los inocentes:"}, {"numero": 8, "texto": "Porque Señor es del sábado el Hijo del hombre."}, {"numero": 9, "texto": "Y partiéndose de allí, vino á la sinagoga de ellos."}, {"numero": 10, "texto": "Y he aquí había allí uno que tenía una mano seca: y le preguntaron, diciendo: ¿Es lícito curar en sábado? por acusarle."}, {"numero": 11, "texto": "Y él les dijo: ¿Qué hombre habrá de vosotros, que tenga una oveja, y si cayere ésta en una fosa en sábado, no le eche mano, y la levante?"}, {"numero": 12, "texto": "Pues ¿cuánto más vale un hombre que una oveja? Así que, lícito es en los sábados hacer bien."}, {"numero": 13, "texto": "Entonces dijo á aquel hombre: Extiende tu mano. Y él la extendió, y fué restituída sana como la otra."}, {"numero": 14, "texto": "Y salidos los Fariseos, consultaron contra él para destruirle."}, {"numero": 15, "texto": "Mas sabiéndolo Jesús, se apartó de allí: y le siguieron muchas gentes, y sanaba á todos."}, {"numero": 16, "texto": "Y él les encargaba eficazmente que no le descubriesen:"}, {"numero": 17, "texto": "Para que se cumpliese lo que estaba dicho por el profeta Isaías, que dijo:"}, {"numero": 18, "texto": "He aquí mi siervo, al cual he escogido; mi Amado, en el cual se agrada mi alma: pondré mi Espíritu sobre él, y á los Gentiles anunciará juicio."}, {"numero": 19, "texto": "No contenderá, ni voceará: ni nadie oirá en las calles su voz."}, {"numero": 20, "texto": "La caña cascada no quebrará, y el pábilo que humea no apagará, hasta que saque á victoria el juicio."}, {"numero": 21, "texto": "Y en su nombre esperarán los Gentiles."}, {"numero": 22, "texto": "Entonces fué traído á él un endemoniado, ciego y mudo, y le sanó; de tal manera, que el ciego y mudo hablaba y veía."}, {"numero": 23, "texto": "Y todas las gentes estaban atónitas, y decían: ¿Será éste aquel Hijo de David?"}, {"numero": 24, "texto": "Mas los Fariseos, oyéndolo, decían: Este no echa fuera los demonios, sino por Beelzebub, príncipe de los demonios."}, {"numero": 25, "texto": "Y Jesús, como sabía los pensamientos de ellos, les dijo: Todo reino dividido contra sí mismo, es desolado; y toda ciudad ó casa dividida contra sí misma, no permanecerá."}, {"numero": 26, "texto": "Y si Satanás echa fuera á Satanás, contra sí mismo está dividido; ¿cómo, pues, permanecerá su reino?"}, {"numero": 27, "texto": "Y si yo por Beelzebub echo fuera los demonios, ¿vuestros hijos por quién los echan? Por tanto, ellos serán vuestros jueces."}, {"numero": 28, "texto": "Y si por espíritu de Dios yo echo fuera los demonios, ciertamente ha llegado á vosotros el reino de Dios."}, {"numero": 29, "texto": "Porque, ¿cómo puede alguno entrar en la casa del valiente, y saquear sus alhajas, si primero no prendiere al valiente? y entonces saqueará su casa."}, {"numero": 30, "texto": "El que no es conmigo, contra mí es; y el que conmigo no recoge, derrama."}, {"numero": 31, "texto": "Por tanto os digo: Todo pecado y blasfemia será perdonado á los hombres: mas la blasfemia contra el Espíritu no será perdonada á los hombres."}, {"numero": 32, "texto": "Y cualquiera que hablare contra el Hijo del hombre, le será perdonado: mas cualquiera que hablare contra el Espíritu Santo, no le será perdonado, ni en este siglo, ni en el venidero."}, {"numero": 33, "texto": "O haced el árbol bueno, y su fruto bueno, ó haced el árbol corrompido, y su fruto dañado; porque por el fruto es conocido el árbol."}, {"numero": 34, "texto": "Generación de víboras, ¿cómo podéis hablar bien, siendo malos? porque de la abundancia del corazón habla la boca."}, {"numero": 35, "texto": "El hombre bueno del buen tesoro del corazón saca buenas cosas: y el hombre malo del mal tesoro saca malas cosas."}, {"numero": 36, "texto": "Mas yo os digo, que toda palabra ociosa que hablaren los hombres, de ella darán cuenta en el día del juicio."}, {"numero": 37, "texto": "Porque por tus palabras serás justificado, y por tus palabras serás condenado."}, {"numero": 38, "texto": "Entonces respondieron algunos de los escribas y de los Fariseos, diciendo: Maestro, deseamos ver de ti señal."}, {"numero": 39, "texto": "Y él respondió, y les dijo: La generación mala y adulterina demanda señal; mas señal no le será dada, sino la señal de Jonás profeta."}, {"numero": 40, "texto": "Porque como estuvo Jonás en el vientre de la ballena tres días y tres noches, así estará el Hijo del hombre en el corazón de la tierra tres días y tres noches."}, {"numero": 41, "texto": "Los hombres de Nínive se levantarán en el juicio con esta generación, y la condenarán; porque ellos se arrepintieron á la predicación de Jonás; y he aquí más que Jonás en este lugar."}, {"numero": 42, "texto": "La reina del Austro se levantará en el juicio con esta generación, y la condenará; porque vino de los fines de la tierra para oir la sabiduría de Salomón: y he aquí más que Salomón en este lugar."}, {"numero": 43, "texto": "Cuando el espíritu inmundo ha salido del hombre, anda por lugares secos, buscando reposo, y no lo halla."}, {"numero": 44, "texto": "Entonces dice: Me volveré á mi casa de donde salí: y cuando viene, la halla desocupada, barrida y adornada."}, {"numero": 45, "texto": "Entonces va, y toma consigo otros siete espíritus peores que él, y entrados, moran allí; y son peores las cosas últimas del tal hombre que las primeras: así también acontecerá á esta generación mala."}, {"numero": 46, "texto": "Y estando él aún hablando á las gentes, he aquí su madre y sus hermanos estaban fuera, que le querían hablar."}, {"numero": 47, "texto": "Y le dijo uno: He aquí tu madre y tus hermanos están fuera, que te quieren hablar."}, {"numero": 48, "texto": "Y respondiendo él al que le decía esto, dijo: ¿Quién es mi madre y quiénes son mis hermanos?"}, {"numero": 49, "texto": "Y extendiendo su mano hacia sus discípulos, dijo: He aquí mi madre y mis hermanos."}, {"numero": 50, "texto": "Porque todo aquel que hiciere la voluntad de mi Padre que está en los cielos, ese es mi hermano, y hermana, y madre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 13, 'pt', '[{"numero": 1, "texto": "Naquele dia, Jesus saiu de casa e se sentou junto ao mar."}, {"numero": 2, "texto": "E ajuntaram-se perto dele tantas multidões, de maneira que ele entrou num barco e se sentou; e toda a multidão ficou na praia,"}, {"numero": 3, "texto": "E ele lhes falou muitas coisas por parábolas. Ele disse: Eis que o semeador saiu a semear."}, {"numero": 4, "texto": "E enquanto semeava, caiu parte [das sementes] junto ao caminho, e vieram as aves e a comeram."}, {"numero": 5, "texto": "E outra [parte] caiu entre pedras, onde não havia muita terra, e logo nasceu, porque não tinha terra funda."}, {"numero": 6, "texto": "Mas quando o sol surgiu, queimou-se; e por não ter raiz, secou-se."}, {"numero": 7, "texto": "E outra [parte] caiu entre espinhos, e os espinhos cresceram e a sufocaram."}, {"numero": 8, "texto": "E outra [parte] caiu em boa terra, e rendeu fruto: um a cem, outro a sessenta, e outro a trinta."}, {"numero": 9, "texto": "Quem tem ouvidos para ouvir, ouça."}, {"numero": 10, "texto": "Então os discípulos se aproximaram, e lhe perguntaram: Por que falas a eles por parábolas?"}, {"numero": 11, "texto": "E ele lhes respondeu: Porque a vós é dado saber os mistérios do Reino dos céus, mas a eles não é dado."}, {"numero": 12, "texto": "Pois a quem tem, lhe será dado, e terá em abundância; mas a quem não tem, até aquilo que tem lhe será tirado."}, {"numero": 13, "texto": "Por isso falo a eles por parábolas; porque vendo, não veem; e ouvindo, não ouvem, nem entendem."}, {"numero": 14, "texto": "Assim neles se cumpre a profecia de Isaías, que diz: De fato ouvireis, mas não entendereis; De fato vereis, mas não percebereis."}, {"numero": 15, "texto": "Porque o coração deste povo está insensível; Com seus ouvidos dificilmente ouvem, e seus olhos fecharam; A fim de não haver que seus olhos vejam, seus ouvidos ouçam, Seus corações entendam, e se arrependam, E eu os cure."}, {"numero": 16, "texto": "Mas benditos são os vossos olhos, porque veem; e os vossos ouvidos, porque ouvem."}, {"numero": 17, "texto": "Pois em verdade vos digo que muitos profetas e justos desejaram ver o que vós vedes, mas não viram; e [desejaram] ouvir o que vós ouvis, mas não ouviram."}, {"numero": 18, "texto": "Portanto, ouvi vós a parábola do semeador:"}, {"numero": 19, "texto": "Quando alguém ouve a palavra do Reino e não a entende, o maligno vem e arranca o que foi semeado em seu coração; este é o que foi semeado junto ao caminho."}, {"numero": 20, "texto": "E o que foi semeado entre as pedras é o que ouve a palavra, e logo a recebe com alegria,"}, {"numero": 21, "texto": "mas não tem raiz em si mesmo. Em vez disso, dura um pouco, mas quando vem a aflição ou a perseguição pela palavra, logo tropeça na fé."}, {"numero": 22, "texto": "E o que foi semeado entre os espinhos é o que ouve a palavra, mas a ansiedade com o tempo presente e a sedução das riquezas sufocam a palavra, e fica sem dar fruto."}, {"numero": 23, "texto": "Mas o que foi semeado em boa terra, este é o que ouve e entende a palavra, e o que dá e produz fruto, um a cem, outro a sessenta, e outro a trinta."}, {"numero": 24, "texto": "E ele lhes declarou outra parábola, dizendo: O Reino dos céus é semelhante a um homem que semeia boa semente em seu campo,"}, {"numero": 25, "texto": "Mas, enquanto as pessoas dormiam, o inimigo dele veio, semeou joio entre o trigo, e foi embora."}, {"numero": 26, "texto": "E, quando a erva cresceu e produziu fruto, então apareceu também o joio."}, {"numero": 27, "texto": "Então os servos do dono da propriedade chegaram, e lhe perguntaram: “Senhor, não semeaste boa semente no teu campo? De onde, pois, veio o joio?”"}, {"numero": 28, "texto": "E ele lhes respondeu: “Um inimigo fez isto”. Em seguida, os servos lhe perguntaram: “Queres, pois, que vamos e o tiremos?”"}, {"numero": 29, "texto": "Ele, porém, lhes respondeu: “Não, para não haver que, enquanto tirais o joio, arranqueis com ele também o trigo."}, {"numero": 30, "texto": "Deixai-os crescer ambos juntos até a colheita; e no tempo da colheita direi aos que colhem: ‘Recolhei primeiro o joio, e amarrai-o em molhos, para o queimarem; mas ao trigo ajuntai no meu celeiro’.”"}, {"numero": 31, "texto": "Ele lhes propôs outra parábola: O Reino dos céus é semelhante a um grão de mostarda que alguém tomou e semeou no seu campo."}, {"numero": 32, "texto": "De fato, dentre todas as sementes, esta é a menor. Mas quando cresce, é a maior das hortaliças; e se torna [tamanha] árvore, que as aves do céu vêm e se aninham em seus ramos."}, {"numero": 33, "texto": "Ele lhes disse outra parábola: O Reino dos céus é semelhante ao fermento que uma mulher tomou e misturou em três medidas de farinha, até que tudo ficasse fermentado."}, {"numero": 34, "texto": "Tudo isto Jesus falou por parábolas às multidões. Sem parábolas ele não lhes falava,"}, {"numero": 35, "texto": "para que se cumprisse o que foi falado pelo profeta, que disse: Abrirei a minha boca em parábolas; Pronunciarei coisas escondidas desde a fundação do mundo."}, {"numero": 36, "texto": "Então Jesus despediu as multidões, e foi para casa. Seus discípulos se aproximaram dele, e disseram: Explica-nos a parábola do joio do campo."}, {"numero": 37, "texto": "E ele lhes respondeu: O que semeia a boa semente é o Filho do homem."}, {"numero": 38, "texto": "E o campo é o mundo; e a boa semente, estes são os filhos do Reino; e o joio são os filhos do maligno."}, {"numero": 39, "texto": "E o inimigo, que o semeou, é o diabo; e a colheita é o fim da era; e os que colhem são os anjos."}, {"numero": 40, "texto": "Portanto, como o joio é colhido e queimado no fogo, assim também será no fim desta era."}, {"numero": 41, "texto": "O Filho do homem enviará seus anjos, e eles recolherão do seu Reino todas as causas do pecado, assim como os que praticam injustiça,"}, {"numero": 42, "texto": "e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes."}, {"numero": 43, "texto": "Então os justos brilharão como o sol, no Reino de seu Pai. Quem tem ouvidos para ouvir, ouça."}, {"numero": 44, "texto": "O Reino dos céus também é semelhante a um tesouro escondido num campo, que um homem, depois de achá-lo, escondeu. Então, em sua alegria, vai, vende tudo quanto tem, e compra aquele campo."}, {"numero": 45, "texto": "O Reino dos céus também é semelhante a um homem negociante, que buscava boas pérolas."}, {"numero": 46, "texto": "Quando este achou uma pérola de grande valor, foi, vendeu tudo quanto tinha, e a comprou."}, {"numero": 47, "texto": "O Reino dos céus também é semelhante a uma rede lançada ao mar, que colhe toda espécie [de peixes] ."}, {"numero": 48, "texto": "E quando está cheia, [os pescadores] puxam-na à praia, sentam-se, e recolhem os bons em cestos, mas os ruins lançam fora."}, {"numero": 49, "texto": "Assim será ao fim da era; os anjos sairão, e separarão dentre os justos os maus,"}, {"numero": 50, "texto": "e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes."}, {"numero": 51, "texto": "E Jesus lhes perguntou: Entendestes todas estas coisas?Eles lhe responderam: Sim, Senhor."}, {"numero": 52, "texto": "E ele lhes disse: Portanto todo escriba que se tornou discípulo no Reino dos céus é semelhante a um chefe de casa, que do seu tesouro tira coisas novas e velhas."}, {"numero": 53, "texto": "E aconteceu que, quando Jesus acabou essas parábolas, retirou-se dali."}, {"numero": 54, "texto": "E vindo à sua terra, ensinava-os na sinagoga deles, de tal maneira que ficavam admirados, e diziam: De onde [vêm] a este tal sabedoria, e os milagres?"}, {"numero": 55, "texto": "Não é este o filho do carpinteiro? E não se chama sua mãe Maria, e seus irmãos Tiago, José, Simão, e Judas?"}, {"numero": 56, "texto": "Não estão todas as suas irmãs conosco? Ora, de onde [vem] a este tudo isto?"}, {"numero": 57, "texto": "E ofenderam-se por causa dele. Mas Jesus lhes disse: Não há profeta sem honra, a não ser em sua terra, e em sua casa."}, {"numero": 58, "texto": "E não fez ali muitos milagres por causa da incredulidade deles."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 13, 'en', '[{"numero": 1, "texto": "The same day went Jesus out of the house, and sat by the sea side."}, {"numero": 2, "texto": "And great multitudes were gathered together unto him, so that he went into a ship, and sat; and the whole multitude stood on the shore."}, {"numero": 3, "texto": "And he spake many things unto them in parables, saying, Behold, a sower went forth to sow;"}, {"numero": 4, "texto": "And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up:"}, {"numero": 5, "texto": "Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth:"}, {"numero": 6, "texto": "And when the sun was up, they were scorched; and because they had no root, they withered away."}, {"numero": 7, "texto": "And some fell among thorns; and the thorns sprung up, and choked them:"}, {"numero": 8, "texto": "But other fell into good ground, and brought forth fruit, some an hundredfold, some sixtyfold, some thirtyfold."}, {"numero": 9, "texto": "Who hath ears to hear, let him hear."}, {"numero": 10, "texto": "And the disciples came, and said unto him, Why speakest thou unto them in parables?"}, {"numero": 11, "texto": "He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given."}, {"numero": 12, "texto": "For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath."}, {"numero": 13, "texto": "Therefore speak I to them in parables: because they seeing see not; and hearing they hear not, neither do they understand."}, {"numero": 14, "texto": "And in them is fulfilled the prophecy of Esaias, which saith, By hearing ye shall hear, and shall not understand; and seeing ye shall see, and shall not perceive:"}, {"numero": 15, "texto": "For this people''s heart is waxed gross, and their ears are dull of hearing, and their eyes they have closed; lest at any time they should see with their eyes and hear with their ears, and should understand with their heart, and should be converted, and I should heal them."}, {"numero": 16, "texto": "But blessed are your eyes, for they see: and your ears, for they hear."}, {"numero": 17, "texto": "For verily I say unto you, That many prophets and righteous men have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them."}, {"numero": 18, "texto": "Hear ye therefore the parable of the sower."}, {"numero": 19, "texto": "When any one heareth the word of the kingdom, and understandeth it not, then cometh the wicked one, and catcheth away that which was sown in his heart. This is he which received seed by the way side."}, {"numero": 20, "texto": "But he that received the seed into stony places, the same is he that heareth the word, and anon with joy receiveth it;"}, {"numero": 21, "texto": "Yet hath he not root in himself, but dureth for a while: for when tribulation or persecution ariseth because of the word, by and by he is offended."}, {"numero": 22, "texto": "He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful."}, {"numero": 23, "texto": "But he that received seed into the good ground is he that heareth the word, and understandeth it; which also beareth fruit, and bringeth forth, some an hundredfold, some sixty, some thirty."}, {"numero": 24, "texto": "Another parable put he forth unto them, saying, The kingdom of heaven is likened unto a man which sowed good seed in his field:"}, {"numero": 25, "texto": "But while men slept, his enemy came and sowed tares among the wheat, and went his way."}, {"numero": 26, "texto": "But when the blade was sprung up, and brought forth fruit, then appeared the tares also."}, {"numero": 27, "texto": "So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares?"}, {"numero": 28, "texto": "He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up?"}, {"numero": 29, "texto": "But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them."}, {"numero": 30, "texto": "Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn."}, {"numero": 31, "texto": "Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field:"}, {"numero": 32, "texto": "Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof."}, {"numero": 33, "texto": "Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened."}, {"numero": 34, "texto": "All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them:"}, {"numero": 35, "texto": "That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world."}, {"numero": 36, "texto": "Then Jesus sent the multitude away, and went into the house: and his disciples came unto him, saying, Declare unto us the parable of the tares of the field."}, {"numero": 37, "texto": "He answered and said unto them, He that soweth the good seed is the Son of man;"}, {"numero": 38, "texto": "The field is the world; the good seed are the children of the kingdom; but the tares are the children of the wicked one;"}, {"numero": 39, "texto": "The enemy that sowed them is the devil; the harvest is the end of the world; and the reapers are the angels."}, {"numero": 40, "texto": "As therefore the tares are gathered and burned in the fire; so shall it be in the end of this world."}, {"numero": 41, "texto": "The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity;"}, {"numero": 42, "texto": "And shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth."}, {"numero": 43, "texto": "Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear."}, {"numero": 44, "texto": "Again, the kingdom of heaven is like unto treasure hid in a field; the which when a man hath found, he hideth, and for joy thereof goeth and selleth all that he hath, and buyeth that field."}, {"numero": 45, "texto": "Again, the kingdom of heaven is like unto a merchant man, seeking goodly pearls:"}, {"numero": 46, "texto": "Who, when he had found one pearl of great price, went and sold all that he had, and bought it."}, {"numero": 47, "texto": "Again, the kingdom of heaven is like unto a net, that was cast into the sea, and gathered of every kind:"}, {"numero": 48, "texto": "Which, when it was full, they drew to shore, and sat down, and gathered the good into vessels, but cast the bad away."}, {"numero": 49, "texto": "So shall it be at the end of the world: the angels shall come forth, and sever the wicked from among the just,"}, {"numero": 50, "texto": "And shall cast them into the furnace of fire: there shall be wailing and gnashing of teeth."}, {"numero": 51, "texto": "Jesus saith unto them, Have ye understood all these things? They say unto him, Yea, Lord."}, {"numero": 52, "texto": "Then said he unto them, Therefore every scribe which is instructed unto the kingdom of heaven is like unto a man that is an householder, which bringeth forth out of his treasure things new and old."}, {"numero": 53, "texto": "And it came to pass, that when Jesus had finished these parables, he departed thence."}, {"numero": 54, "texto": "And when he was come into his own country, he taught them in their synagogue, insomuch that they were astonished, and said, Whence hath this man this wisdom, and these mighty works?"}, {"numero": 55, "texto": "Is not this the carpenter''s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?"}, {"numero": 56, "texto": "And his sisters, are they not all with us? Whence then hath this man all these things?"}, {"numero": 57, "texto": "And they were offended in him. But Jesus said unto them, A prophet is not without honour, save in his own country, and in his own house."}, {"numero": 58, "texto": "And he did not many mighty works there because of their unbelief."}]'::jsonb, 'King James Version'),
  ('Mt', 13, 'fr', '[{"numero": 1, "texto": "Ce même jour, Jésus sortit de la maison, et s''''assit au bord de la mer."}, {"numero": 2, "texto": "Une grande foule s''''étant assemblée auprès de lui, il monta dans une barque, et il s''''assit. Toute la foule se tenait sur le rivage."}, {"numero": 3, "texto": "Il leur parla en paraboles sur beaucoup de choses, et il dit: Un semeur sortit pour semer."}, {"numero": 4, "texto": "Comme il semait, une partie de la semence tomba le long du chemin: les oiseaux vinrent, et la mangèrent."}, {"numero": 5, "texto": "Une autre partie tomba dans les endroits pierreux, où elle n''''avait pas beaucoup de terre: elle leva aussitôt, parce qu''''elle ne trouva pas un sol profond;"}, {"numero": 6, "texto": "mais, quand le soleil parut, elle fut brûlée et sécha, faute de racines."}, {"numero": 7, "texto": "Une autre partie tomba parmi les épines: les épines montèrent, et l''''étouffèrent."}, {"numero": 8, "texto": "Une autre partie tomba dans la bonne terre: elle donna du fruit, un grain cent, un autre soixante, un autre trente."}, {"numero": 9, "texto": "Que celui qui a des oreilles pour entendre entende."}, {"numero": 10, "texto": "Les disciples s''''approchèrent, et lui dirent: Pourquoi leur parles-tu en paraboles?"}, {"numero": 11, "texto": "Jésus leur répondit: Parce qu''''il vous a été donné de connaître les mystères du royaume des cieux, et que cela ne leur a pas été donné."}, {"numero": 12, "texto": "Car on donnera à celui qui a, et il sera dans l''''abondance, mais à celui qui n''''a pas on ôtera même ce qu''''il a."}, {"numero": 13, "texto": "C''''est pourquoi je leur parle en paraboles, parce qu''''en voyant ils ne voient point, et qu''''en entendant ils n''''entendent ni ne comprennent."}, {"numero": 14, "texto": "Et pour eux s''''accomplit cette prophétie d''''Esaïe: Vous entendrez de vos oreilles, et vous ne comprendrez point; Vous regarderez de vos yeux, et vous ne verrez point."}, {"numero": 15, "texto": "Car le coeur de ce peuple est devenu insensible; Ils ont endurci leurs oreilles, et ils ont fermé leurs yeux, De peur qu''''ils ne voient de leurs yeux, qu''''ils n''''entendent de leurs oreilles, Qu''''ils ne comprennent de leur coeur, Qu''''ils ne se convertissent, et que je ne les guérisse."}, {"numero": 16, "texto": "Mais heureux sont vos yeux, parce qu''''ils voient, et vos oreilles, parce qu''''elles entendent!"}, {"numero": 17, "texto": "Je vous le dis en vérité, beaucoup de prophètes et de justes ont désiré voir ce que vous voyez, et ne l''''ont pas vu, entendre ce que vous entendez, et ne l''''ont pas entendu."}, {"numero": 18, "texto": "Vous donc, écoutez ce que signifie la parabole du semeur."}, {"numero": 19, "texto": "Lorsqu''''un homme écoute la parole du royaume et ne la comprend pas, le malin vient et enlève ce qui a été semé dans son coeur: cet homme est celui qui a reçu la semence le long du chemin."}, {"numero": 20, "texto": "Celui qui a reçu la semence dans les endroits pierreux, c''''est celui qui entend la parole et la reçoit aussitôt avec joie;"}, {"numero": 21, "texto": "mais il n''''a pas de racines en lui-même, il manque de persistance, et, dès que survient une tribulation ou une persécution à cause de la parole, il y trouve une occasion de chute."}, {"numero": 22, "texto": "Celui qui a reçu la semence parmi les épines, c''''est celui qui entend la parole, mais en qui les soucis du siècle et la séduction des richesses étouffent cette parole, et la rendent infructueuse."}, {"numero": 23, "texto": "Celui qui a reçu la semence dans la bonne terre, c''''est celui qui entend la parole et la comprend; il porte du fruit, et un grain en donne cent, un autre soixante, un autre trente."}, {"numero": 24, "texto": "Il leur proposa une autre parabole, et il dit: Le royaume des cieux est semblable à un homme qui a semé une bonne semence dans son champ."}, {"numero": 25, "texto": "Mais, pendant que les gens dormaient, son ennemi vint, sema de l''''ivraie parmi le blé, et s''''en alla."}, {"numero": 26, "texto": "Lorsque l''''herbe eut poussé et donné du fruit, l''''ivraie parut aussi."}, {"numero": 27, "texto": "Les serviteurs du maître de la maison vinrent lui dire: Seigneur, n''''as-tu pas semé une bonne semence dans ton champ? D''''où vient donc qu''''il y a de l''''ivraie?"}, {"numero": 28, "texto": "Il leur répondit: C''''est un ennemi qui a fait cela. Et les serviteurs lui dirent: Veux-tu que nous allions l''''arracher?"}, {"numero": 29, "texto": "Non, dit-il, de peur qu''''en arrachant l''''ivraie, vous ne déraciniez en même temps le blé."}, {"numero": 30, "texto": "Laissez croître ensemble l''''un et l''''autre jusqu''''à la moisson, et, à l''''époque de la moisson, je dirai aux moissonneurs: Arrachez d''''abord l''''ivraie, et liez-la en gerbes pour la brûler, mais amassez le blé dans mon grenier."}, {"numero": 31, "texto": "Il leur proposa une autre parabole, et il dit: Le royaume des cieux est semblable à un grain de sénevé qu''''un homme a pris et semé dans son champ."}, {"numero": 32, "texto": "C''''est la plus petite de toutes les semences; mais, quand il a poussé, il est plus grand que les légumes et devient un arbre, de sorte que les oiseaux du ciel viennent habiter dans ses branches."}, {"numero": 33, "texto": "Il leur dit cette autre parabole: Le royaume des cieux est semblable à du levain qu''''une femme a pris et mis dans trois mesures de farine, jusqu''''à ce que la pâte soit toute levée."}, {"numero": 34, "texto": "Jésus dit à la foule toutes ces choses en paraboles, et il ne lui parlait point sans parabole,"}, {"numero": 35, "texto": "afin que s''''accomplît ce qui avait été annoncé par le prophète: J''''ouvrirai ma bouche en paraboles, Je publierai des choses cachées depuis la création du monde."}, {"numero": 36, "texto": "Alors il renvoya la foule, et entra dans la maison. Ses disciples s''''approchèrent de lui, et dirent: Explique-nous la parabole de l''''ivraie du champ."}, {"numero": 37, "texto": "Il répondit: Celui qui sème la bonne semence, c''''est le Fils de l''''homme;"}, {"numero": 38, "texto": "le champ, c''''est le monde; la bonne semence, ce sont les fils du royaume; l''''ivraie, ce sont les fils du malin;"}, {"numero": 39, "texto": "l''''ennemi qui l''''a semée, c''''est le diable; la moisson, c''''est la fin du monde; les moissonneurs, ce sont les anges."}, {"numero": 40, "texto": "Or, comme on arrache l''''ivraie et qu''''on la jette au feu, il en sera de même à la fin du monde."}, {"numero": 41, "texto": "Le Fils de l''''homme enverra ses anges, qui arracheront de son royaume tous les scandales et ceux qui commettent l''''iniquité:"}, {"numero": 42, "texto": "et ils les jetteront dans la fournaise ardente, où il y aura des pleurs et des grincements de dents."}, {"numero": 43, "texto": "Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Que celui qui a des oreilles pour entendre entende."}, {"numero": 44, "texto": "Le royaume des cieux est encore semblable à un trésor caché dans un champ. L''''homme qui l''''a trouvé le cache; et, dans sa joie, il va vendre tout ce qu''''il a, et achète ce champ."}, {"numero": 45, "texto": "Le royaume des cieux est encore semblable à un marchand qui cherche de belles perles."}, {"numero": 46, "texto": "Il a trouvé une perle de grand prix; et il est allé vendre tout ce qu''''il avait, et l''''a achetée."}, {"numero": 47, "texto": "Le royaume des cieux est encore semblable à un filet jeté dans la mer et ramassant des poissons de toute espèce."}, {"numero": 48, "texto": "Quand il est rempli, les pêcheurs le tirent; et, après s''''être assis sur le rivage, ils mettent dans des vases ce qui est bon, et ils jettent ce qui est mauvais."}, {"numero": 49, "texto": "Il en sera de même à la fin du monde. Les anges viendront séparer les méchants d''''avec les justes,"}, {"numero": 50, "texto": "et ils les jetteront dans la fournaise ardente, où il y aura des pleurs et des grincements de dents."}, {"numero": 51, "texto": "Avez-vous compris toutes ces choses? -Oui, répondirent-ils."}, {"numero": 52, "texto": "Et il leur dit: C''''est pourquoi, tout scribe instruit de ce qui regarde le royaume des cieux est semblable à un maître de maison qui tire de son trésor des choses nouvelles et des choses anciennes."}, {"numero": 53, "texto": "Lorsque Jésus eut achevé ces paraboles, il partit de là."}, {"numero": 54, "texto": "S''''étant rendu dans sa patrie, il enseignait dans la synagogue, de sorte que ceux qui l''''entendirent étaient étonnés et disaient: D''''où lui viennent cette sagesse et ces miracles?"}, {"numero": 55, "texto": "N''''est-ce pas le fils du charpentier? n''''est-ce pas Marie qui est sa mère? Jacques, Joseph, Simon et Jude, ne sont-ils pas ses frères?"}, {"numero": 56, "texto": "et ses soeurs ne sont-elles pas toutes parmi nous? D''''où lui viennent donc toutes ces choses?"}, {"numero": 57, "texto": "Et il était pour eux une occasion de chute. Mais Jésus leur dit: Un prophète n''''est méprisé que dans sa patrie et dans sa maison."}, {"numero": 58, "texto": "Et il ne fit pas beaucoup de miracles dans ce lieu, à cause de leur incrédulité."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 13, 'es', '[{"numero": 1, "texto": "Y AQUEL día, saliendo Jesús de casa, se sentó junto á la mar."}, {"numero": 2, "texto": "Y se allegaron á él muchas gentes; y entrándose él en el barco, se sentó, y toda la gente estaba á la ribera."}, {"numero": 3, "texto": "Y les habló muchas cosas por parábolas, diciendo: He aquí el que sembraba salió á sembrar."}, {"numero": 4, "texto": "Y sembrando, parte de la simiente cayó junto al camino; y vinieron las aves, y la comieron."}, {"numero": 5, "texto": "Y parte cayó en pedregales, donde no tenía mucha tierra; y nació luego, porque no tenía profundidad de tierra:"}, {"numero": 6, "texto": "Mas en saliendo el sol, se quemó; y secóse, porque no tenía raíz."}, {"numero": 7, "texto": "Y parte cayó en espinas; y las espinas crecieron, y la ahogaron."}, {"numero": 8, "texto": "Y parte cayó en buena tierra, y dió fruto, cuál á ciento, cuál á sesenta, y cuál á treinta."}, {"numero": 9, "texto": "Quien tiene oídos para oir, oiga."}, {"numero": 10, "texto": "Entonces, llegándose los discípulos, le dijeron: ¿Por qué les hablas por parábolas?"}, {"numero": 11, "texto": "Y él respondiendo, les dijo: Por que á vosotros es concedido saber los misterios del reino de los cielos; mas á ellos no es concedido."}, {"numero": 12, "texto": "Porque á cualquiera que tiene, se le dará, y tendrá más; pero al que no tiene, aun lo que tiene le será quitado."}, {"numero": 13, "texto": "Por eso les hablo por parábolas; porque viendo no ven, y oyendo no oyen, ni entienden."}, {"numero": 14, "texto": "De manera que se cumple en ellos la profecía de Isaías, que dice: De oído oiréis, y no entenderéis; y viendo veréis, y no miraréis."}, {"numero": 15, "texto": "Porque el corazón de este pueblo está engrosado, y de los oídos oyen pesadamente, y de sus ojos guiñan: para que no vean de los ojos, y oigan de los oídos, y del corazón entiendan, y se conviertan, y yo los sane."}, {"numero": 16, "texto": "Mas bienaventurados vuestros ojos, porque ven; y vuestros oídos, porque oyen."}, {"numero": 17, "texto": "Porque de cierto os digo, que muchos profetas y justos desearon ver lo que veis, y no lo vieron: y oir lo que oís, y no lo oyeron."}, {"numero": 18, "texto": "Oid, pues, vosotros la parábola del que siembra:"}, {"numero": 19, "texto": "Oyendo cualquiera la palabra del reino, y no entendiéndola, viene el malo, y arrebata lo que fué sembrado en su corazón: éste es el que fué sembrado junto al camino."}, {"numero": 20, "texto": "Y el que fué sembrado en pedregales, éste es el que oye la palabra, y luego la recibe con gozo."}, {"numero": 21, "texto": "Mas no tiene raíz en sí, antes es temporal: que venida la aflicción ó la persecución por la palabra, luego se ofende."}, {"numero": 22, "texto": "Y el que fué sembrado en espinas, éste es el que oye la palabra; pero el afán de este siglo y el engaño de las riquezas, ahogan la palabra, y hácese infructuosa."}, {"numero": 23, "texto": "Mas el que fué sembrado en buena tierra, éste es el que oye y entiende la palabra, y el que lleva fruto: y lleva uno á ciento, y otro á sesenta, y otro á treinta."}, {"numero": 24, "texto": "Otra parábola les propuso, diciendo: El reino de los cielos es semejante al hombre que siembra buena simiente en su campo:"}, {"numero": 25, "texto": "Mas durmiendo los hombres, vino su enemigo, y sembró cizaña entre el trigo, y se fué."}, {"numero": 26, "texto": "Y como la hierba salió é hizo fruto, entonces apareció también la cizaña."}, {"numero": 27, "texto": "Y llegándose los siervos del padre de la familia, le dijeron: Señor, ¿no sembraste buena simiente en tu campo? ¿de dónde, pues, tiene cizaña?"}, {"numero": 28, "texto": "Y él les dijo: Un hombre enemigo ha hecho esto. Y los siervos le dijeron: ¿Quieres, pues, que vayamos y la cojamos?"}, {"numero": 29, "texto": "Y él dijo: No; porque cogiendo la cizaña, no arranquéis también con ella el trigo."}, {"numero": 30, "texto": "Dejad crecer juntamente lo uno y lo otro hasta la siega; y al tiempo de la siega yo diré á los segadores: Coged primero la cizaña, y atadla en manojos para quemarla; mas recoged el trigo en mi alfolí."}, {"numero": 31, "texto": "Otra parábola les propuso, diciendo: El reino de los cielos es semejante al grano de mostaza, que tomándolo alguno lo sembró en su campo:"}, {"numero": 32, "texto": "El cual á la verdad es la más pequeña de todas las simientes; mas cuando ha crecido, es la mayor de las hortalizas, y se hace árbol, que vienen las aves del cielo y hacen nidos en sus ramas."}, {"numero": 33, "texto": "Otra parábola les dijo: El reino de los cielos es semejante á la levadura que tomó una mujer, y escondió en tres medidas de harina, hasta que todo quedó leudo."}, {"numero": 34, "texto": "Todo esto habló Jesús por parábolas á las gentes, y sin parábolas no les hablaba:"}, {"numero": 35, "texto": "Para que se cumpliese lo que fué dicho por el profeta, que dijo: Abriré en parábolas mi boca; rebosaré cosas escondidas desde la fundación del mundo."}, {"numero": 36, "texto": "Entonces, despedidas las gentes, Jesús se vino á casa; y llegándose á él sus discípulos, le dijeron: Decláranos la parábola de la cizaña del campo."}, {"numero": 37, "texto": "Y respondiendo él, les dijo: El que siembra la buena simiente es el Hijo del hombre;"}, {"numero": 38, "texto": "Y el campo es el mundo; y la buena simiente son los hijos del reino, y la cizaña son los hijos del malo;"}, {"numero": 39, "texto": "Y el enemigo que la sembró, es el diablo; y la siega es el fin del mundo, y los segadores son los ángeles."}, {"numero": 40, "texto": "De manera que como es cogida la cizaña, y quemada al fuego, así será en el fin de este siglo."}, {"numero": 41, "texto": "Enviará el Hijo del hombre sus ángeles, y cogerán de su reino todos los escándalos, y los que hacen iniquidad,"}, {"numero": 42, "texto": "Y los echarán en el horno de fuego: allí será el lloro y el crujir de dientes."}, {"numero": 43, "texto": "Entonces los justos resplandecerán como el sol en el reino de su Padre: el que tiene oídos para oir, oiga."}, {"numero": 44, "texto": "Además, el reino de los cielos es semejante al tesoro escondido en el campo; el cual hallado, el hombre lo encubre, y de gozo de ello va, y vende todo lo que tiene, y compra aquel campo."}, {"numero": 45, "texto": "También el reino de los cielos es semejante al hombre tratante, que busca buenas perlas;"}, {"numero": 46, "texto": "Que hallando una preciosa perla, fué y vendió todo lo que tenía, y la compró."}, {"numero": 47, "texto": "Asimismo el reino de los cielos es semejante á la red, que echada en la mar, coge de todas suertes de peces:"}, {"numero": 48, "texto": "La cual estando llena, la sacaron á la orilla; y sentados, cogieron lo bueno en vasos, y lo malo echaron fuera."}, {"numero": 49, "texto": "Así será al fin del siglo: saldrán los ángeles, y apartarán á los malos de entre los justos,"}, {"numero": 50, "texto": "Y los echarán en el horno del fuego: allí será el lloro y el crujir de dientes."}, {"numero": 51, "texto": "Díceles Jesús: ¿Habéis entendido todas estas cosas? Ellos responden: Sí, Señor."}, {"numero": 52, "texto": "Y él les dijo: Por eso todo escriba docto en el reino de los cielos, es semejante á un padre de familia, que saca de su tesoro cosas nuevas y cosas viejas."}, {"numero": 53, "texto": "Y aconteció que acabando Jesús estas parábolas, pasó de allí."}, {"numero": 54, "texto": "Y venido á su tierra, les enseñaba en la sinagoga de ellos, de tal manera que ellos estaban atónitos, y decían: ¿De dónde tiene éste esta sabiduría, y estas maravillas?"}, {"numero": 55, "texto": "¿No es éste el hijo del carpintero? ¿no se llama su madre María, y sus hermanos Jacobo y José, y Simón, y Judas?"}, {"numero": 56, "texto": "¿Y no están todas sus hermanas con nosotros? ¿De dónde, pues, tiene éste todas estas cosas?"}, {"numero": 57, "texto": "Y se escandalizaban en él. Mas Jesús les dijo: No hay profeta sin honra sino en su tierra y en su casa."}, {"numero": 58, "texto": "Y no hizo allí muchas maravillas, á causa de la incredulidad de ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 14, 'pt', '[{"numero": 1, "texto": "Naquele tempo Herodes, o tetrarca, ouviu relato a respeito de Jesus,"}, {"numero": 2, "texto": "e disse aos seus servos: Este é João Batista; ele ressuscitou dos mortos, e por isso os milagres operam nele."}, {"numero": 3, "texto": "Porque Herodes havia prendido a João, acorrentado-o, e posto na prisão, por causa de Herodias, mulher do seu irmão Filipe;"}, {"numero": 4, "texto": "pois João lhe dizia: Não te lícito que a tenhas."}, {"numero": 5, "texto": "[Herodes] queria matá-lo, mas tinha medo do povo, pois o consideravam profeta."}, {"numero": 6, "texto": "Porém, enquanto era celebrado o aniversário de Herodes, a filha de Herodias dançou no meio [das pessoas] , e agradou a Herodes."}, {"numero": 7, "texto": "Por isso prometeu a ela dar tudo o que pedisse."}, {"numero": 8, "texto": "E ela, tendo sido induzida por sua mãe, disse: Dá-me aqui num prato a cabeça de João Batista."}, {"numero": 9, "texto": "E o rei se entristeceu; mas devido ao juramento, e aos que estavam presentes, ordenou que isso fosse concedido."}, {"numero": 10, "texto": "Então mandou degolarem João na prisão."}, {"numero": 11, "texto": "Sua cabeça foi trazida num prato, e dada à garota, e ela a levou à sua mãe."}, {"numero": 12, "texto": "E seus discípulos vieram, tomaram o corpo, e o enterraram; e foram avisar a Jesus."}, {"numero": 13, "texto": "Depois de Jesus ouvir, retirou-se dali num barco, a um lugar deserto, sozinho; mas assim que as multidões ouviram acerca disso, seguiram-no a pé das cidades."}, {"numero": 14, "texto": "Quando Jesus saiu, viu uma grande multidão. Ele se compadeceu deles, e curou dentre eles os enfermos."}, {"numero": 15, "texto": "E chegando o entardecer, os seus discípulos se aproximaram dele, e disseram: O lugar é deserto, e já é tarde. Despede as multidões, para irem às aldeias, e comprarem para si de comer."}, {"numero": 16, "texto": "Mas Jesus lhes respondeu: Eles não precisam ir. Vós mesmos, dai-lhes de comer."}, {"numero": 17, "texto": "E eles lhe disseram: Nada temos aqui além de cinco pães e dois peixes."}, {"numero": 18, "texto": "Então disse: Trazei-os aqui a mim."}, {"numero": 19, "texto": "Ele mandou às multidões que se sentassem sobre a grama. Então tomou os cinco pães e os dois peixes, levantou os olhos ao céu, e [os] abençoou. Em seguida partiu os pães, deu-os aos discípulos, e os discípulos às multidões."}, {"numero": 20, "texto": "E todos comeram, e se fartaram. E do que sobrou dos pedaços levantaram doze cestos cheios."}, {"numero": 21, "texto": "E os que comeram foram quase cinco mil homens, sem contar as mulheres e as crianças."}, {"numero": 22, "texto": "E logo Jesus mandou os seus discípulos entrarem no barco, e que fossem adiante dele para a outra margem, enquanto ele despedia as multidões."}, {"numero": 23, "texto": "Depois de despedir as multidões, subiu ao monte, à parte, para orar. Tendo chegado a noite, ele estava ali sozinho."}, {"numero": 24, "texto": "E o barco já estava no meio do mar, atormentado pelas ondas, porque o vento era contrário."}, {"numero": 25, "texto": "Mas à quarta vigília da noite Jesus foi até eles, andando sobre o mar."}, {"numero": 26, "texto": "Quando os discípulos o viram andar sobre o mar, apavoraram-se, dizendo: É um fantasma! E gritaram de medo."}, {"numero": 27, "texto": "Mas Jesus logo lhes falou, dizendo: Tende coragem! Sou eu, não tenhais medo."}, {"numero": 28, "texto": "E Pedro lhe respondeu, dizendo: Senhor, se és tu, manda-me vir a ti sobre as águas."}, {"numero": 29, "texto": "E ele disse: Vem. Então Pedro desceu do barco e andou sobre as águas, para vir em direção a Jesus."}, {"numero": 30, "texto": "Mas quando viu o vento forte, teve medo; e começando a afundar, gritou: Senhor, salva-me!"}, {"numero": 31, "texto": "Imediatamente Jesus estendeu a mão, segurou-o, e disse-lhe: [Homem] de pouca fé, por que duvidaste?"}, {"numero": 32, "texto": "E quando subiram no barco, o vento se aquietou."}, {"numero": 33, "texto": "Então os que estavam no barco vieram e o adoraram, dizendo: Verdadeiramente tu és o Filho de Deus."}, {"numero": 34, "texto": "E havendo passado para a outra margem, chegaram à terra de Genesaré."}, {"numero": 35, "texto": "E quando os homens daquele lugar o reconheceram, deram aviso por toda aquela região em redor, e lhe trouxeram todos os que estavam enfermos."}, {"numero": 36, "texto": "E rogavam-lhe que tão somente tocassem a borda de sua roupa; e todos os que tocavam ficaram curados."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 14, 'en', '[{"numero": 1, "texto": "At that time Herod the tetrarch heard of the fame of Jesus,"}, {"numero": 2, "texto": "And said unto his servants, This is John the Baptist; he is risen from the dead; and therefore mighty works do shew forth themselves in him."}, {"numero": 3, "texto": "For Herod had laid hold on John, and bound him, and put him in prison for Herodias'' sake, his brother Philip''s wife."}, {"numero": 4, "texto": "For John said unto him, It is not lawful for thee to have her."}, {"numero": 5, "texto": "And when he would have put him to death, he feared the multitude, because they counted him as a prophet."}, {"numero": 6, "texto": "But when Herod''s birthday was kept, the daughter of Herodias danced before them, and pleased Herod."}, {"numero": 7, "texto": "Whereupon he promised with an oath to give her whatsoever she would ask."}, {"numero": 8, "texto": "And she, being before instructed of her mother, said, Give me here John Baptist''s head in a charger."}, {"numero": 9, "texto": "And the king was sorry: nevertheless for the oath''s sake, and them which sat with him at meat, he commanded it to be given her."}, {"numero": 10, "texto": "And he sent, and beheaded John in the prison."}, {"numero": 11, "texto": "And his head was brought in a charger, and given to the damsel: and she brought it to her mother."}, {"numero": 12, "texto": "And his disciples came, and took up the body, and buried it, and went and told Jesus."}, {"numero": 13, "texto": "When Jesus heard of it, he departed thence by ship into a desert place apart: and when the people had heard thereof, they followed him on foot out of the cities."}, {"numero": 14, "texto": "And Jesus went forth, and saw a great multitude, and was moved with compassion toward them, and he healed their sick."}, {"numero": 15, "texto": "And when it was evening, his disciples came to him, saying, This is a desert place, and the time is now past; send the multitude away, that they may go into the villages, and buy themselves victuals."}, {"numero": 16, "texto": "But Jesus said unto them, They need not depart; give ye them to eat."}, {"numero": 17, "texto": "And they say unto him, We have here but five loaves, and two fishes."}, {"numero": 18, "texto": "He said, Bring them hither to me."}, {"numero": 19, "texto": "And he commanded the multitude to sit down on the grass, and took the five loaves, and the two fishes, and looking up to heaven, he blessed, and brake, and gave the loaves to his disciples, and the disciples to the multitude."}, {"numero": 20, "texto": "And they did all eat, and were filled: and they took up of the fragments that remained twelve baskets full."}, {"numero": 21, "texto": "And they that had eaten were about five thousand men, beside women and children."}, {"numero": 22, "texto": "And straightway Jesus constrained his disciples to get into a ship, and to go before him unto the other side, while he sent the multitudes away."}, {"numero": 23, "texto": "And when he had sent the multitudes away, he went up into a mountain apart to pray: and when the evening was come, he was there alone."}, {"numero": 24, "texto": "But the ship was now in the midst of the sea, tossed with waves: for the wind was contrary."}, {"numero": 25, "texto": "And in the fourth watch of the night Jesus went unto them, walking on the sea."}, {"numero": 26, "texto": "And when the disciples saw him walking on the sea, they were troubled, saying, It is a spirit; and they cried out for fear."}, {"numero": 27, "texto": "But straightway Jesus spake unto them, saying, Be of good cheer; it is I; be not afraid."}, {"numero": 28, "texto": "And Peter answered him and said, Lord, if it be thou, bid me come unto thee on the water."}, {"numero": 29, "texto": "And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus."}, {"numero": 30, "texto": "But when he saw the wind boisterous, he was afraid; and beginning to sink, he cried, saying, Lord, save me."}, {"numero": 31, "texto": "And immediately Jesus stretched forth his hand, and caught him, and said unto him, O thou of little faith, wherefore didst thou doubt?"}, {"numero": 32, "texto": "And when they were come into the ship, the wind ceased."}, {"numero": 33, "texto": "Then they that were in the ship came and worshipped him, saying, Of a truth thou art the Son of God."}, {"numero": 34, "texto": "And when they were gone over, they came into the land of Gennesaret."}, {"numero": 35, "texto": "And when the men of that place had knowledge of him, they sent out into all that country round about, and brought unto him all that were diseased;"}, {"numero": 36, "texto": "And besought him that they might only touch the hem of his garment: and as many as touched were made perfectly whole."}]'::jsonb, 'King James Version'),
  ('Mt', 14, 'fr', '[{"numero": 1, "texto": "En ce temps-là, Hérode le tétrarque, ayant entendu parler de Jésus,"}, {"numero": 2, "texto": "dit à ses serviteurs: C''''est Jean-Baptiste! Il est ressuscité des morts, et c''''est pour cela qu''''il se fait par lui des miracles."}, {"numero": 3, "texto": "Car Hérode, qui avait fait arrêter Jean, l''''avait lié et mis en prison, à cause d''''Hérodias, femme de Philippe, son frère,"}, {"numero": 4, "texto": "parce que Jean lui disait: Il ne t''''est pas permis de l''''avoir pour femme."}, {"numero": 5, "texto": "Il voulait le faire mourir, mais il craignait la foule, parce qu''''elle regardait Jean comme un prophète."}, {"numero": 6, "texto": "Or, lorsqu''''on célébra l''''anniversaire de la naissance d''''Hérode, la fille d''''Hérodias dansa au milieu des convives, et plut à Hérode,"}, {"numero": 7, "texto": "de sorte qu''''il promit avec serment de lui donner ce qu''''elle demanderait."}, {"numero": 8, "texto": "A l''''instigation de sa mère, elle dit: Donne-moi ici, sur un plat, la tête de Jean-Baptiste."}, {"numero": 9, "texto": "Le roi fut attristé; mais, à cause de ses serments et des convives, il commanda qu''''on la lui donne,"}, {"numero": 10, "texto": "et il envoya décapiter Jean dans la prison."}, {"numero": 11, "texto": "Sa tête fut apportée sur un plat, et donnée à la jeune fille, qui la porta à sa mère."}, {"numero": 12, "texto": "Les disciples de Jean vinrent prendre son corps, et l''''ensevelirent. Et ils allèrent l''''annoncer à Jésus."}, {"numero": 13, "texto": "A cette nouvelle, Jésus partit de là dans une barque, pour se retirer à l''''écart dans un lieu désert; et la foule, l''''ayant su, sortit des villes et le suivit à pied."}, {"numero": 14, "texto": "Quand il sortit de la barque, il vit une grande foule, et fut ému de compassion pour elle, et il guérit les malades."}, {"numero": 15, "texto": "Le soir étant venu, les disciples s''''approchèrent de lui, et dirent: Ce lieu est désert, et l''''heure est déjà avancée; renvoie la foule, afin qu''''elle aille dans les villages, pour s''''acheter des vivres."}, {"numero": 16, "texto": "Jésus leur répondit: Ils n''''ont pas besoin de s''''en aller; donnez-leur vous-mêmes à manger."}, {"numero": 17, "texto": "Mais ils lui dirent: Nous n''''avons ici que cinq pains et deux poissons."}, {"numero": 18, "texto": "Et il dit: Apportez-les-moi."}, {"numero": 19, "texto": "Il fit asseoir la foule sur l''''herbe, prit les cinq pains et les deux poissons, et, levant les yeux vers le ciel, il rendit grâces. Puis, il rompit les pains et les donna aux disciples, qui les distribuèrent à la foule."}, {"numero": 20, "texto": "Tous mangèrent et furent rassasiés, et l''''on emporta douze paniers pleins des morceaux qui restaient."}, {"numero": 21, "texto": "Ceux qui avaient mangé étaient environ cinq mille hommes, sans les femmes et les enfants."}, {"numero": 22, "texto": "Aussitôt après, il obligea les disciples à monter dans la barque et à passer avant lui de l''''autre côté, pendant qu''''il renverrait la foule."}, {"numero": 23, "texto": "Quand il l''''eut renvoyée, il monta sur la montagne, pour prier à l''''écart; et, comme le soir était venu, il était là seul."}, {"numero": 24, "texto": "La barque, déjà au milieu de la mer, était battue par les flots; car le vent était contraire."}, {"numero": 25, "texto": "A la quatrième veille de la nuit, Jésus alla vers eux, marchant sur la mer."}, {"numero": 26, "texto": "Quand les disciples le virent marcher sur la mer, ils furent troublés, et dirent: C''''est un fantôme! Et, dans leur frayeur, ils poussèrent des cris."}, {"numero": 27, "texto": "Jésus leur dit aussitôt: Rassurez-vous, c''''est moi; n''''ayez pas peur!"}, {"numero": 28, "texto": "Pierre lui répondit: Seigneur, si c''''est toi, ordonne que j''''aille vers toi sur les eaux."}, {"numero": 29, "texto": "Et il dit: Viens! Pierre sortit de la barque, et marcha sur les eaux, pour aller vers Jésus."}, {"numero": 30, "texto": "Mais, voyant que le vent était fort, il eut peur; et, comme il commençait à enfoncer, il s''''écria: Seigneur, sauve-moi!"}, {"numero": 31, "texto": "Aussitôt Jésus étendit la main, le saisit, et lui dit: Homme de peu de foi, pourquoi as-tu douté?"}, {"numero": 32, "texto": "Et ils montèrent dans la barque, et le vent cessa."}, {"numero": 33, "texto": "Ceux qui étaient dans la barque vinrent se prosterner devant Jésus, et dirent: Tu es véritablement le Fils de Dieu."}, {"numero": 34, "texto": "Après avoir traversé la mer, ils vinrent dans le pays de Génésareth."}, {"numero": 35, "texto": "Les gens de ce lieu, ayant reconnu Jésus, envoyèrent des messagers dans tous les environs, et on lui amena tous les malades."}, {"numero": 36, "texto": "Ils le prièrent de leur permettre seulement de toucher le bord de son vêtement. Et tous ceux qui le touchèrent furent guéris."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 14, 'es', '[{"numero": 1, "texto": "EN aquel tiempo Herodes el tetrarca oyó la fama de Jesús,"}, {"numero": 2, "texto": "Y dijo á sus criados: Este es Juan el Bautista: él ha resucitado de los muertos, y por eso virtudes obran en él."}, {"numero": 3, "texto": "Porque Herodes había prendido á Juan, y le había aprisionado y puesto en la cárcel, por causa de Herodías, mujer de Felipe su hermano;"}, {"numero": 4, "texto": "Porque Juan le decía: No te es lícito tenerla."}, {"numero": 5, "texto": "Y quería matarle, mas temía al pueblo; porque le tenían como á profeta."}, {"numero": 6, "texto": "Mas celebrándose el día del nacimiento de Herodes, la hija de Herodías danzó en medio, y agradó á Herodes."}, {"numero": 7, "texto": "Y prometió él con juramento de darle todo lo que pidiese."}, {"numero": 8, "texto": "Y ella, instruída primero de su madre, dijo: Dame aquí en un plato la cabeza de Juan el Bautista."}, {"numero": 9, "texto": "Entonces el rey se entristeció; mas por el juramento, y por los que estaban juntamente á la mesa, mandó que se le diese."}, {"numero": 10, "texto": "Y enviando, degolló á Juan en la cárcel."}, {"numero": 11, "texto": "Y fué traída su cabeza en un plato, y dada á la muchacha; y ella la presentó á su madre."}, {"numero": 12, "texto": "Entonces llegaron sus discípulos, y tomaron el cuerpo, y lo enterraron; y fueron, y dieron las nuevas á Jesús."}, {"numero": 13, "texto": "Y oyéndolo Jesús, se apartó de allí en un barco á un lugar descierto, apartado: y cuando las gentes lo oyeron, le siguieron á pie de las ciudades."}, {"numero": 14, "texto": "Y saliendo Jesús, vió un gran gentío, y tuvo compasión de ellos, y sanó á los que de ellos había enfermos."}, {"numero": 15, "texto": "Y cuando fué la tarde del día, se llegaron á él sus discípulos, diciendo: El lugar es desierto, y el tiempo es ya pasado: despide las gentes, para que se vayan por las aldeas, y compren para sí de comer."}, {"numero": 16, "texto": "Y Jesús les dijo: No tienen necesidad de irse: dadles vosotros de comer."}, {"numero": 17, "texto": "Y ellos dijeron: No tenemos aquí sino cinco panes y dos peces."}, {"numero": 18, "texto": "Y él les dijo: Traédmelos acá."}, {"numero": 19, "texto": "Y mandando á las gentes recostarse sobre la hierba, tomando los cinco panes y los dos peces, alzando los ojos al cielo, bendijo, y partió y dió los panes á los discípulos, y los discípulos á las gentes."}, {"numero": 20, "texto": "Y comieron todos, y se hartaron; y alzaron lo que sobró de los pedazos, doce cestas llenas."}, {"numero": 21, "texto": "Y los que comieron fueron como cinco mil hombres, sin las mujeres y los niños."}, {"numero": 22, "texto": "Y luego Jesús hizo á sus discípulos entrar en el barco, é ir delante de él á la otra parte del lago, entre tanto que él despedía á las gentes."}, {"numero": 23, "texto": "Y despedidas las gentes, subió al monte, apartado, á orar: y como fué la tarde del día, estaba allí solo."}, {"numero": 24, "texto": "Y ya el barco estaba en medio de la mar, atormentado de las ondas; porque el viento era contrario."}, {"numero": 25, "texto": "Mas á la cuarta vela de la noche, Jesús fué á ellos andando sobre la mar."}, {"numero": 26, "texto": "Y los discípulos, viéndole andar sobre la mar, se turbaron, diciendo: Fantasma es. Y dieron voces de miedo."}, {"numero": 27, "texto": "Mas luego Jesús les habló, diciendo: Confiad, yo soy; no tengáis miedo."}, {"numero": 28, "texto": "Entonces le respondió Pedro, y dijo: Señor, si tú eres, manda que yo vaya á ti sobre las aguas."}, {"numero": 29, "texto": "Y él dijo: Ven. Y descendiendo Pedro del barco, andaba sobre las aguas para ir á Jesús."}, {"numero": 30, "texto": "Mas viendo el viento fuerte, tuvo miedo; y comenzándose á hundir, dió voces, diciendo: Señor, sálvame."}, {"numero": 31, "texto": "Y luego Jesús, extendiendo la mano, trabó de él, y le dice: Oh hombre de poca fe, ¿por qué dudaste?"}, {"numero": 32, "texto": "Y como ellos entraron en el barco, sosegóse el viento."}, {"numero": 33, "texto": "Entonces los que estaban en el barco, vinieron y le adoraron, diciendo: Verdaderamente eres Hijo de Dios."}, {"numero": 34, "texto": "Y llegando á la otra parte, vinieron á la tierra de Genezaret."}, {"numero": 35, "texto": "Y como le conocieron los hombres de aquel lugar, enviaron por toda aquella tierra alrededor, y trajeron á él todos los enfermos;"}, {"numero": 36, "texto": "Y le rogaban que solamente tocasen el borde de su manto; y todos los que tocaron, quedaron sanos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 15, 'pt', '[{"numero": 1, "texto": "Então [alguns] escribas e fariseus de Jerusalém se aproximaram de Jesus, e perguntaram:"}, {"numero": 2, "texto": "Por que os teus discípulos transgridem a tradição dos anciãos? Pois não lavam suas mãos quando comem pão."}, {"numero": 3, "texto": "Porém ele lhes respondeu: E vós, por que transgredis o mandamento de Deus por vossa tradição?"}, {"numero": 4, "texto": "Pois Deus mandou, dizendo: Honra ao teu pai e à [tua] mãe; e quem maldisser ao pai ou à mãe seja sentenciado à morte."}, {"numero": 5, "texto": "Mas vós dizeis: “Qualquer um que disser ao pai ou à mãe: ‘Todo o proveito que terias de mim é oferta exclusiva [para Deus] ’, não [precisa] honrar seu pai ou à sua mãe”."}, {"numero": 6, "texto": "E [assim] invalidastes o mandamento de Deus por vossa tradição."}, {"numero": 7, "texto": "Hipócritas! Isaías bem profetizou sobre vós, dizendo:"}, {"numero": 8, "texto": "Este povo com sua boca se aproxima de mim, e com os lábios me honra; mas o seu coração está longe de mim."}, {"numero": 9, "texto": "Em vão, porém, me veneram, ensinando doutrinas que são regras humanas."}, {"numero": 10, "texto": "Assim chamou a multidão para si, e disse-lhes: Ouvi e entendei."}, {"numero": 11, "texto": "Não é o que entra na boca que contamina o ser humano; mas sim o que sai da boca, isso contamina o ser humano."}, {"numero": 12, "texto": "Então os seus discípulos aproximaram-se dele, e lhe perguntaram: Tu sabes que os fariseus se ofenderam quando ouviram essa palavra?"}, {"numero": 13, "texto": "Mas ele respondeu: Toda planta que meu Pai celestial não plantou será arrancada pela raiz."}, {"numero": 14, "texto": "Deixai-os, são guias cegos de cegos. E se o cego guiar [outro] cego, ambos cairão na cova."}, {"numero": 15, "texto": "E Pedro lhe disse: Explica-nos esta parábola."}, {"numero": 16, "texto": "Porém Jesus disse: Até vós ainda estais sem entender?"}, {"numero": 17, "texto": "Não percebeis ainda que tudo o que entra na boca vai ao ventre, mas [depois] é lançado na privada?"}, {"numero": 18, "texto": "Porém as coisas que saem da boca procedem do coração; e elas contaminam o ser humano."}, {"numero": 19, "texto": "Pois do coração procedem maus pensamentos, mortes, adultérios, pecados sexuais, furtos, falsos testemunhos, blasfêmias."}, {"numero": 20, "texto": "Estas coisas são as que contaminam o ser humano; mas comer sem lavar as mãos não contamina o ser humano."}, {"numero": 21, "texto": "E, tendo Jesus partido dali, foi para as partes de Tiro e de Sidom."}, {"numero": 22, "texto": "E eis que uma mulher Cananeia, que tinha saído daquela região, clamou-lhe: Senhor, Filho de Davi, tem misericórdia de mim! Minha filha está miseravelmente endemoninhada."}, {"numero": 23, "texto": "Mas ele não lhe respondeu palavra. Então seus discípulos se aproximaram dele, e rogaram-lhe, dizendo: Manda-a embora, porque ela está gritando atrás de nós."}, {"numero": 24, "texto": "E ele respondeu: Não fui enviado para ninguém além das ovelhas perdidas da casa de Israel."}, {"numero": 25, "texto": "Então ela veio e se prostrou diante dele, dizendo: Senhor, socorre-me."}, {"numero": 26, "texto": "Mas ele respondeu: Não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos."}, {"numero": 27, "texto": "Ela, porém, disse: Sim, Senhor. Porém os cachorrinhos também comem, das migalhas que caem da mesa dos seus senhores."}, {"numero": 28, "texto": "Então Jesus lhe respondeu: Ó mulher, grande [é] a tua fé. A ti seja feito como tu queres. E desde aquela hora sua filha ficou curada."}, {"numero": 29, "texto": "E tendo Jesus partido dali, veio ao mar da Galileia. Ele subiu a um monte, e ali se sentou."}, {"numero": 30, "texto": "E vieram a ele muitas multidões, que tinham consigo mancos, cegos, mudos, aleijados, e muitos outros; e os lançaram aos pés de Jesus, e ele os curou."}, {"numero": 31, "texto": "Desta maneira, as multidões se maravilhavam quando viam os mudos falarem, os aleijados ficarem sãos, os mancos andarem, e os cegos verem; então glorificaram ao Deus de Israel."}, {"numero": 32, "texto": "Jesus chamou a si os seus discípulos, e disse: Estou compadecido com a multidão, porque já há três dias que estão comigo, e não têm o que comer. E não quero os deixar ir em jejum, para que não desmaiem no caminho."}, {"numero": 33, "texto": "E os seus discípulos lhe responderam: De onde conseguiremos tantos pães no deserto, para saciar tão grande multidão?"}, {"numero": 34, "texto": "Jesus lhes perguntou: Quantos pães tendes? E eles disseram: Sete; e uns poucos peixinhos."}, {"numero": 35, "texto": "Então mandou as multidões que se sentassem pelo chão."}, {"numero": 36, "texto": "Tomou os sete pães e os peixes, deu graças e os partiu. Em seguida, ele os deu aos seus discípulos, e os discípulos à multidão."}, {"numero": 37, "texto": "E todos comeram e se saciaram; e levantaram dos pedaços que sobraram sete cestos cheios."}, {"numero": 38, "texto": "E foram os que comeram quatro mil homens, sem contar as mulheres e as crianças."}, {"numero": 39, "texto": "Depois de despedir as multidões, [Jesus] entrou em um barco, e veio à região de Magdala."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 15, 'en', '[{"numero": 1, "texto": "Then came to Jesus scribes and Pharisees, which were of Jerusalem, saying,"}, {"numero": 2, "texto": "Why do thy disciples transgress the tradition of the elders? for they wash not their hands when they eat bread."}, {"numero": 3, "texto": "But he answered and said unto them, Why do ye also transgress the commandment of God by your tradition?"}, {"numero": 4, "texto": "For God commanded, saying, Honour thy father and mother: and, He that curseth father or mother, let him die the death."}, {"numero": 5, "texto": "But ye say, Whosoever shall say to his father or his mother, It is a gift, by whatsoever thou mightest be profited by me;"}, {"numero": 6, "texto": "And honour not his father or his mother, he shall be free. Thus have ye made the commandment of God of none effect by your tradition."}, {"numero": 7, "texto": "Ye hypocrites, well did Esaias prophesy of you, saying,"}, {"numero": 8, "texto": "This people draweth nigh unto me with their mouth, and honoureth me with their lips; but their heart is far from me."}, {"numero": 9, "texto": "But in vain they do worship me, teaching for doctrines the commandments of men."}, {"numero": 10, "texto": "And he called the multitude, and said unto them, Hear, and understand:"}, {"numero": 11, "texto": "Not that which goeth into the mouth defileth a man; but that which cometh out of the mouth, this defileth a man."}, {"numero": 12, "texto": "Then came his disciples, and said unto him, Knowest thou that the Pharisees were offended, after they heard this saying?"}, {"numero": 13, "texto": "But he answered and said, Every plant, which my heavenly Father hath not planted, shall be rooted up."}, {"numero": 14, "texto": "Let them alone: they be blind leaders of the blind. And if the blind lead the blind, both shall fall into the ditch."}, {"numero": 15, "texto": "Then answered Peter and said unto him, Declare unto us this parable."}, {"numero": 16, "texto": "And Jesus said, Are ye also yet without understanding?"}, {"numero": 17, "texto": "Do not ye yet understand, that whatsoever entereth in at the mouth goeth into the belly, and is cast out into the draught?"}, {"numero": 18, "texto": "But those things which proceed out of the mouth come forth from the heart; and they defile the man."}, {"numero": 19, "texto": "For out of the heart proceed evil thoughts, murders, adulteries, fornications, thefts, false witness, blasphemies:"}, {"numero": 20, "texto": "These are the things which defile a man: but to eat with unwashen hands defileth not a man."}, {"numero": 21, "texto": "Then Jesus went thence, and departed into the coasts of Tyre and Sidon."}, {"numero": 22, "texto": "And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, thou son of David; my daughter is grievously vexed with a devil."}, {"numero": 23, "texto": "But he answered her not a word. And his disciples came and besought him, saying, Send her away; for she crieth after us."}, {"numero": 24, "texto": "But he answered and said, I am not sent but unto the lost sheep of the house of Israel."}, {"numero": 25, "texto": "Then came she and worshipped him, saying, Lord, help me."}, {"numero": 26, "texto": "But he answered and said, It is not meet to take the children''s bread, and to cast it to dogs."}, {"numero": 27, "texto": "And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their masters'' table."}, {"numero": 28, "texto": "Then Jesus answered and said unto her, O woman, great is thy faith: be it unto thee even as thou wilt. And her daughter was made whole from that very hour."}, {"numero": 29, "texto": "And Jesus departed from thence, and came nigh unto the sea of Galilee; and went up into a mountain, and sat down there."}, {"numero": 30, "texto": "And great multitudes came unto him, having with them those that were lame, blind, dumb, maimed, and many others, and cast them down at Jesus'' feet; and he healed them:"}, {"numero": 31, "texto": "Insomuch that the multitude wondered, when they saw the dumb to speak, the maimed to be whole, the lame to walk, and the blind to see: and they glorified the God of Israel."}, {"numero": 32, "texto": "Then Jesus called his disciples unto him, and said, I have compassion on the multitude, because they continue with me now three days, and have nothing to eat: and I will not send them away fasting, lest they faint in the way."}, {"numero": 33, "texto": "And his disciples say unto him, Whence should we have so much bread in the wilderness, as to fill so great a multitude?"}, {"numero": 34, "texto": "And Jesus saith unto them, How many loaves have ye? And they said, Seven, and a few little fishes."}, {"numero": 35, "texto": "And he commanded the multitude to sit down on the ground."}, {"numero": 36, "texto": "And he took the seven loaves and the fishes, and gave thanks, and brake them, and gave to his disciples, and the disciples to the multitude."}, {"numero": 37, "texto": "And they did all eat, and were filled: and they took up of the broken meat that was left seven baskets full."}, {"numero": 38, "texto": "And they that did eat were four thousand men, beside women and children."}, {"numero": 39, "texto": "And he sent away the multitude, and took ship, and came into the coasts of Magdala."}]'::jsonb, 'King James Version'),
  ('Mt', 15, 'fr', '[{"numero": 1, "texto": "Alors des pharisiens et des scribes vinrent de Jérusalem auprès de Jésus, et dirent:"}, {"numero": 2, "texto": "Pourquoi tes disciples transgressent-ils la tradition des anciens? Car ils ne se lavent pas les mains, quand ils prennent leurs repas."}, {"numero": 3, "texto": "Il leur répondit: Et vous, pourquoi transgressez-vous le commandement de Dieu au profit de votre tradition?"}, {"numero": 4, "texto": "Car Dieu a dit: Honore ton père et ta mère; et: Celui qui maudira son père ou sa mère sera puni de mort."}, {"numero": 5, "texto": "Mais vous, vous dites: Celui qui dira à son père ou à sa mère: Ce dont j''''aurais pu t''''assister est une offrande à Dieu,"}, {"numero": 6, "texto": "n''''est pas tenu d''''honorer son père ou sa mère. Vous annulez ainsi la parole de Dieu au profit de votre tradition."}, {"numero": 7, "texto": "Hypocrites, Esaïe a bien prophétisé sur vous, quand il a dit:"}, {"numero": 8, "texto": "Ce peuple m''''honore des lèvres, Mais son coeur est éloigné de moi."}, {"numero": 9, "texto": "C''''est en vain qu''''ils m''''honorent, en enseignant des préceptes qui sont des commandements d''''hommes."}, {"numero": 10, "texto": "Ayant appelé à lui la foule, il lui dit: Ecoutez, et comprenez."}, {"numero": 11, "texto": "Ce n''''est pas ce qui entre dans la bouche qui souille l''''homme; mais ce qui sort de la bouche, c''''est ce qui souille l''''homme."}, {"numero": 12, "texto": "Alors ses disciples s''''approchèrent, et lui dirent: Sais-tu que les pharisiens ont été scandalisés des paroles qu''''ils ont entendues?"}, {"numero": 13, "texto": "Il répondit: Toute plante que n''''a pas plantée mon Père céleste sera déracinée."}, {"numero": 14, "texto": "Laissez-les: ce sont des aveugles qui conduisent des aveugles; si un aveugle conduit un aveugle, ils tomberont tous deux dans une fosse."}, {"numero": 15, "texto": "Pierre, prenant la parole, lui dit: Explique-nous cette parabole."}, {"numero": 16, "texto": "Et Jésus dit: Vous aussi, êtes-vous encore sans intelligence?"}, {"numero": 17, "texto": "Ne comprenez-vous pas que tout ce qui entre dans la bouche va dans le ventre, puis est jeté dans les lieux secrets?"}, {"numero": 18, "texto": "Mais ce qui sort de la bouche vient du coeur, et c''''est ce qui souille l''''homme."}, {"numero": 19, "texto": "Car c''''est du coeur que viennent les mauvaises pensées, les meurtres, les adultères, les impudicités, les vols, les faux témoignages, les calomnies."}, {"numero": 20, "texto": "Voilà les choses qui souillent l''''homme; mais manger sans s''''être lavé les mains, cela ne souille point l''''homme."}, {"numero": 21, "texto": "Jésus, étant parti de là, se retira dans le territoire de Tyr et de Sidon."}, {"numero": 22, "texto": "Et voici, une femme cananéenne, qui venait de ces contrées, lui cria: Aie pitié de moi, Seigneur, Fils de David! Ma fille est cruellement tourmentée par le démon."}, {"numero": 23, "texto": "Il ne lui répondit pas un mot, et ses disciples s''''approchèrent, et lui dirent avec instance: Renvoie-la, car elle crie derrière nous."}, {"numero": 24, "texto": "Il répondit: Je n''''ai été envoyé qu''''aux brebis perdues de la maison d''''Israël."}, {"numero": 25, "texto": "Mais elle vint se prosterner devant lui, disant: Seigneur, secours-moi!"}, {"numero": 26, "texto": "Il répondit: Il n''''est pas bien de prendre le pain des enfants, et de le jeter aux petits chiens."}, {"numero": 27, "texto": "Oui, Seigneur, dit-elle, mais les petits chiens mangent les miettes qui tombent de la table de leurs maîtres."}, {"numero": 28, "texto": "Alors Jésus lui dit: Femme, ta foi est grande; qu''''il te soit fait comme tu veux. Et, à l''''heure même, sa fille fut guérie."}, {"numero": 29, "texto": "Jésus quitta ces lieux, et vint près de la mer de Galilée. Etant monté sur la montagne, il s''''y assit."}, {"numero": 30, "texto": "Alors s''''approcha de lui une grande foule, ayant avec elle des boiteux, des aveugles, des muets, des estropiés, et beaucoup d''''autres malades. On les mit à ses pieds, et il les guérit;"}, {"numero": 31, "texto": "en sorte que la foule était dans l''''admiration de voir que les muets parlaient, que les estropiés étaient guéris, que les boiteux marchaient, que les aveugles voyaient; et elle glorifiait le Dieu d''''Israël."}, {"numero": 32, "texto": "Jésus, ayant appelé ses disciples, dit: Je suis ému de compassion pour cette foule; car voilà trois jours qu''''ils sont près de moi, et ils n''''ont rien à manger. Je ne veux pas les renvoyer à jeun, de peur que les forces ne leur manquent en chemin."}, {"numero": 33, "texto": "Les disciples lui dirent: Comment nous procurer dans ce lieu désert assez de pains pour rassasier une si grande foule?"}, {"numero": 34, "texto": "Jésus leur demanda: Combien avez-vous de pains? Sept, répondirent-ils, et quelques petits poissons."}, {"numero": 35, "texto": "Alors il fit asseoir la foule par terre,"}, {"numero": 36, "texto": "prit les sept pains et les poissons, et, après avoir rendu grâces, il les rompit et les donna à ses disciples, qui les distribuèrent à la foule."}, {"numero": 37, "texto": "Tous mangèrent et furent rassasiés, et l''''on emporta sept corbeilles pleines des morceaux qui restaient."}, {"numero": 38, "texto": "Ceux qui avaient mangé étaient quatre mille hommes, sans les femmes et les enfants."}, {"numero": 39, "texto": "Ensuite, il renvoya la foule, monta dans la barque, et se rendit dans la contrée de Magadan."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 15, 'es', '[{"numero": 1, "texto": "ENTONCES llegaron á Jesús ciertos escribas y Fariseos de Jerusalem, diciendo:"}, {"numero": 2, "texto": "¿Por qué tus discípulos traspasan la tradición de los ancianos? porque no se lavan las manos cuando comen pan."}, {"numero": 3, "texto": "Y él respondiendo, les dijo: ¿Por qué también vosotros traspasáis el mandamiento de Dios por vuestra tradición?"}, {"numero": 4, "texto": "Porque Dios mandó, diciendo: Honra al padre y á la madre, y, El que maldijere al padre ó á la madre, muera de muerte."}, {"numero": 5, "texto": "Mas vosotros decís: Cualquiera que dijere al padre ó á la madre: Es ya ofrenda mía á Dios todo aquello con que pudiera valerte;"}, {"numero": 6, "texto": "No deberá honrar á su padre ó á su madre con socorro. Así habéis invalidado el mandamiento de Dios por vuestra tradición."}, {"numero": 7, "texto": "Hipócritas, bien profetizó de vosotros Isaías, diciendo:"}, {"numero": 8, "texto": "Este pueblo de labios me honra; mas su corazón lejos está de mí."}, {"numero": 9, "texto": "Mas en vano me honran, enseñando doctrinas y mandamientos de hombres."}, {"numero": 10, "texto": "Y llamando á sí las gentes, les dijo: Oid, y entended:"}, {"numero": 11, "texto": "No lo que entra en la boca contamina al hombre; mas lo que sale de la boca, esto contamina al hombre."}, {"numero": 12, "texto": "Entonces llegándose sus discípulos, le dijeron: ¿Sabes que los Fariseos oyendo esta palabra se ofendieron?"}, {"numero": 13, "texto": "Mas respondiendo él, dijo: Toda planta que no plantó mi Padre celestial, será desarraigada."}, {"numero": 14, "texto": "Dejadlos: son ciegos guías de ciegos; y si el ciego guiare al ciego, ambos caerán en el hoyo."}, {"numero": 15, "texto": "Y respondiendo Pedro, le dijo: Decláranos esta parábola."}, {"numero": 16, "texto": "Y Jesús dijo: ¿Aun también vosotros sois sin entendimiento?"}, {"numero": 17, "texto": "¿No entendéis aún, que todo lo que entra en la boca, va al vientre, y es echado en la letrina?"}, {"numero": 18, "texto": "Mas lo que sale de la boca, del corazón sale; y esto contamina al hombre."}, {"numero": 19, "texto": "Porque del corazón salen los malos pensamientos, muertes, adulterios, fornicaciones, hurtos, falsos testimonios, blasfemias."}, {"numero": 20, "texto": "Estas cosas son las que contaminan al hombre: que comer con las manos por lavar no contamina al hombre."}, {"numero": 21, "texto": "Y saliendo Jesús de allí, se fué á las partes de Tiro y de Sidón."}, {"numero": 22, "texto": "Y he aquí una mujer Cananea, que había salido de aquellos términos, clamaba, diciéndole: Señor, Hijo de David, ten misericordia de mí; mi hija es malamente atormentada del demonio."}, {"numero": 23, "texto": "Mas él no le respondió palabra. Entonces llegándose sus discípulos, le rogaron, diciendo: Despáchala, pues da voces tras nosotros."}, {"numero": 24, "texto": "Y él respondiendo, dijo: No soy enviado sino á las ovejas perdidas de la casa de Israel."}, {"numero": 25, "texto": "Entonces ella vino, y le adoró, diciendo: Señor, socórreme."}, {"numero": 26, "texto": "Y respondiendo él, dijo: No es bien tomar el pan de los hijos, y echarlo á los perrillos."}, {"numero": 27, "texto": "Y ella dijo: Sí, Señor; mas los perrillos comen de las migajas que caen de la mesa de sus señores."}, {"numero": 28, "texto": "Entonces respondiendo Jesús, dijo: Oh mujer, grande es tu fe; sea hecho contigo como quieres. Y fué sana su hija desde aquella hora."}, {"numero": 29, "texto": "Y partido Jesús de allí, vino junto al mar de Galilea: y subiendo al monte, se sentó allí."}, {"numero": 30, "texto": "Y llegaron á él muchas gentes, que tenían consigo cojos, ciegos, mudos, mancos, y otros muchos enfermos: y los echaron á los pies de Jesús, y los sanó:"}, {"numero": 31, "texto": "De manera que se maravillaban las gentes, viendo hablar los mudos, los mancos sanos, andar los cojos, y ver los ciegos: y glorificaron al Dios de Israel."}, {"numero": 32, "texto": "Y Jesús llamando á sus discípulos, dijo: Tengo lástima de la gente, que ya hace tres días que perseveran conmigo, y no tienen qué comer; y enviarlos ayunos no quiero, porque no desmayen en el camino."}, {"numero": 33, "texto": "Entonces sus discípulos le dicen: ¿Dónde tenemos nosotros tantos panes en el desierto, que hartemos á tan gran compañía?"}, {"numero": 34, "texto": "Y Jesús les dice: ¿Cuántos panes tenéis? Y ellos dijeron: Siete, y unos pocos pececillos."}, {"numero": 35, "texto": "Y mandó á las gentes que se recostasen sobre la tierra."}, {"numero": 36, "texto": "Y tomando los siete panes y los peces, haciendo gracias, partió y dió á sus discípulos; y los discípulos á la gente."}, {"numero": 37, "texto": "Y comieron todos, y se hartaron: y alzaron lo que sobró de los pedazos, siete espuertas llenas."}, {"numero": 38, "texto": "Y eran los que habían comido, cuatro mil hombres, sin las mujeres y los niños."}, {"numero": 39, "texto": "Entonces, despedidas las gentes, subió en el barco: y vino á los términos de Magdalá."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 16, 'pt', '[{"numero": 1, "texto": "Então os fariseus e os saduceus se aproximaram dele e, a fim de tentá-lo, pediram-lhe que lhes mostrasse algum sinal do céu."}, {"numero": 2, "texto": "Mas ele lhes respondeu: Quando chega a tarde, dizeis: “ [Haverá] tempo bom, pois o céu está vermelho”."}, {"numero": 3, "texto": "E pela manhã: “Hoje [haverá] tempestade, pois o céu está de um vermelho sombrio”. Hipócritas! Vós bem sabeis distinguir a aparência do céu, mas os sinais dos tempos não podeis?"}, {"numero": 4, "texto": "Uma geração má e adúltera pede um sinal; mas nenhum sinal lhe será dado, a não ser o sinal do profeta Jonas. Então os deixou, e foi embora."}, {"numero": 5, "texto": "E quando os seus discípulos vieram para a outra margem, esqueceram-se de tomar pão."}, {"numero": 6, "texto": "E Jesus lhes disse: Ficai atentos, e tende cuidado com o fermento dos fariseus e saduceus."}, {"numero": 7, "texto": "E eles argumentaram entre si, dizendo: É porque não tomamos pão."}, {"numero": 8, "texto": "Jesus percebeu, e disse-lhes: Por que estais argumentando entre vós mesmos, ó [homens] de pouca fé, que não tomastes pão?"}, {"numero": 9, "texto": "Ainda não entendeis, nem vos lembrais dos cinco pães dos cinco mil, e quantos cestos levantastes?"}, {"numero": 10, "texto": "Nem dos sete pães dos quatro mil, e quantos cestos levantastes?"}, {"numero": 11, "texto": "Como não entendeis que não foi pelo pão que eu vos disse para tomardes cuidado com o fermento dos fariseus e saduceus?"}, {"numero": 12, "texto": "Então entenderam que ele não havia dito que tomassem cuidado com o fermento de pão, mas sim, com a doutrina dos fariseus e saduceus."}, {"numero": 13, "texto": "E tendo Jesus vindo às partes da Cesareia de Filipe, perguntou aos seus discípulos: Quem as pessoas dizem que eu, o Filho do homem, sou?"}, {"numero": 14, "texto": "E eles responderam: Alguns João Batista, outros Elias, e outros Jeremias ou algum dos profetas."}, {"numero": 15, "texto": "Ele lhes disse: E vós, quem dizeis que eu sou?"}, {"numero": 16, "texto": "E Simão Pedro respondeu: Tu és o Cristo, o Filho do Deus vivo!"}, {"numero": 17, "texto": "E Jesus lhe replicou: Bendito és tu, Simão, filho de Jonas; pois não foi carne e sangue que o revelou a ti, mas sim meu Pai, que [está] nos céus."}, {"numero": 18, "texto": "E eu também te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja; e as portas do Xeol não prevalecerão contra ela."}, {"numero": 19, "texto": "E a ti darei as chaves do Reino dos céus; e tudo o que ligares na terra terá sido ligado nos céus; e tudo o que desligares na terra terá sido desligado nos céus."}, {"numero": 20, "texto": "Então mandou aos seus discípulos que a ninguém dissessem que ele era Jesus, o Cristo."}, {"numero": 21, "texto": "Desde então Jesus começou a mostrar a seus discípulos que ele tinha que ir a Jerusalém, e sofrer muito pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas, e ser morto, e ser ressuscitado ao terceiro dia."}, {"numero": 22, "texto": "E Pedro o tomou à parte, e começou a repreendê-lo, dizendo: Misericórdia de ti, Senhor! De maneira nenhuma isso te aconteça."}, {"numero": 23, "texto": "Mas ele se virou, e disse a Pedro: Para trás de mim, Satanás! Tu és um meio de tropeço, porque não compreendes as coisas de Deus, mas sim as humanas."}, {"numero": 24, "texto": "Então Jesus disse a seus discípulos: Se alguém quiser vir após mim, negue-se a si mesmo, tome sobre si a sua cruz, e siga-me."}, {"numero": 25, "texto": "Pois qualquer um que quiser salvar a sua vida a perderá; porém qualquer um que por causa de mim perder a sua vida, [este] a achará."}, {"numero": 26, "texto": "Pois que proveito há para alguém, se ganhar o mundo todo, mas perder a sua alma? Ou que dará alguém em resgate da sua alma?"}, {"numero": 27, "texto": "Pois o Filho do homem virá na glória do seu Pai com os seus anjos, e então recompensará a cada um segundo as suas obras."}, {"numero": 28, "texto": "Em verdade vos digo, que há alguns, dos que aqui estão, que não experimentarão a morte, até que vejam o Filho do homem vir em seu Reino."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 16, 'en', '[{"numero": 1, "texto": "The Pharisees also with the Sadducees came, and tempting desired him that he would shew them a sign from heaven."}, {"numero": 2, "texto": "He answered and said unto them, When it is evening, ye say, It will be fair weather: for the sky is red."}, {"numero": 3, "texto": "And in the morning, It will be foul weather to day: for the sky is red and lowering. O ye hypocrites, ye can discern the face of the sky; but can ye not discern the signs of the times?"}, {"numero": 4, "texto": "A wicked and adulterous generation seeketh after a sign; and there shall no sign be given unto it, but the sign of the prophet Jonas. And he left them, and departed."}, {"numero": 5, "texto": "And when his disciples were come to the other side, they had forgotten to take bread."}, {"numero": 6, "texto": "Then Jesus said unto them, Take heed and beware of the leaven of the Pharisees and of the Sadducees."}, {"numero": 7, "texto": "And they reasoned among themselves, saying, It is because we have taken no bread."}, {"numero": 8, "texto": "Which when Jesus perceived, he said unto them, O ye of little faith, why reason ye among yourselves, because ye have brought no bread?"}, {"numero": 9, "texto": "Do ye not yet understand, neither remember the five loaves of the five thousand, and how many baskets ye took up?"}, {"numero": 10, "texto": "Neither the seven loaves of the four thousand, and how many baskets ye took up?"}, {"numero": 11, "texto": "How is it that ye do not understand that I spake it not to you concerning bread, that ye should beware of the leaven of the Pharisees and of the Sadducees?"}, {"numero": 12, "texto": "Then understood they how that he bade them not beware of the leaven of bread, but of the doctrine of the Pharisees and of the Sadducees."}, {"numero": 13, "texto": "When Jesus came into the coasts of Caesarea Philippi, he asked his disciples, saying, Whom do men say that I the Son of man am?"}, {"numero": 14, "texto": "And they said, Some say that thou art John the Baptist: some, Elias; and others, Jeremias, or one of the prophets."}, {"numero": 15, "texto": "He saith unto them, But whom say ye that I am?"}, {"numero": 16, "texto": "And Simon Peter answered and said, Thou art the Christ, the Son of the living God."}, {"numero": 17, "texto": "And Jesus answered and said unto him, Blessed art thou, Simon Barjona: for flesh and blood hath not revealed it unto thee, but my Father which is in heaven."}, {"numero": 18, "texto": "And I say also unto thee, That thou art Peter, and upon this rock I will build my church; and the gates of hell shall not prevail against it."}, {"numero": 19, "texto": "And I will give unto thee the keys of the kingdom of heaven: and whatsoever thou shalt bind on earth shall be bound in heaven: and whatsoever thou shalt loose on earth shall be loosed in heaven."}, {"numero": 20, "texto": "Then charged he his disciples that they should tell no man that he was Jesus the Christ."}, {"numero": 21, "texto": "From that time forth began Jesus to shew unto his disciples, how that he must go unto Jerusalem, and suffer many things of the elders and chief priests and scribes, and be killed, and be raised again the third day."}, {"numero": 22, "texto": "Then Peter took him, and began to rebuke him, saying, Be it far from thee, Lord: this shall not be unto thee."}, {"numero": 23, "texto": "But he turned, and said unto Peter, Get thee behind me, Satan: thou art an offence unto me: for thou savourest not the things that be of God, but those that be of men."}, {"numero": 24, "texto": "Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross, and follow me."}, {"numero": 25, "texto": "For whosoever will save his life shall lose it: and whosoever will lose his life for my sake shall find it."}, {"numero": 26, "texto": "For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?"}, {"numero": 27, "texto": "For the Son of man shall come in the glory of his Father with his angels; and then he shall reward every man according to his works."}, {"numero": 28, "texto": "Verily I say unto you, There be some standing here, which shall not taste of death, till they see the Son of man coming in his kingdom."}]'::jsonb, 'King James Version'),
  ('Mt', 16, 'fr', '[{"numero": 1, "texto": "Les pharisiens et les sadducéens abordèrent Jésus et, pour l''''éprouver, lui demandèrent de leur faire voir un signe venant du ciel."}, {"numero": 2, "texto": "Jésus leur répondit: Le soir, vous dites: Il fera beau, car le ciel est rouge;"}, {"numero": 3, "texto": "et le matin: Il y aura de l''''orage aujourd''''hui, car le ciel est d''''un rouge sombre. Vous savez discerner l''''aspect du ciel, et vous ne pouvez discerner les signes des temps."}, {"numero": 4, "texto": "Une génération méchante et adultère demande un miracle; il ne lui sera donné d''''autre miracle que celui de Jonas. Puis il les quitta, et s''''en alla."}, {"numero": 5, "texto": "Les disciples, en passant à l''''autre bord, avaient oublié de prendre des pains."}, {"numero": 6, "texto": "Jésus leur dit: Gardez-vous avec soin du levain des pharisiens et des sadducéens."}, {"numero": 7, "texto": "Les disciples raisonnaient en eux-mêmes, et disaient: C''''est parce que nous n''''avons pas pris de pains."}, {"numero": 8, "texto": "Jésus, l''''ayant connu, dit: Pourquoi raisonnez-vous en vous-mêmes, gens de peu de foi, sur ce que vous n''''avez pas pris de pains?"}, {"numero": 9, "texto": "Etes-vous encore sans intelligence, et ne vous rappelez-vous plus les cinq pains des cinq mille hommes et combien de paniers vous avez emportés,"}, {"numero": 10, "texto": "ni les sept pains des quatre mille hommes et combien de corbeilles vous avez emportées?"}, {"numero": 11, "texto": "Comment ne comprenez-vous pas que ce n''''est pas au sujet de pains que je vous ai parlé? Gardez-vous du levain des pharisiens et des sadducéens."}, {"numero": 12, "texto": "Alors ils comprirent que ce n''''était pas du levain du pain qu''''il avait dit de se garder, mais de l''''enseignement des pharisiens et des sadducéens."}, {"numero": 13, "texto": "Jésus, étant arrivé dans le territoire de Césarée de Philippe, demanda à ses disciples: Qui dit-on que je suis, moi, le Fils de l''''homme?"}, {"numero": 14, "texto": "Ils répondirent: Les uns disent que tu es Jean-Baptiste; les autres, Elie; les autres, Jérémie, ou l''''un des prophètes."}, {"numero": 15, "texto": "Et vous, leur dit-il, qui dites-vous que je suis?"}, {"numero": 16, "texto": "Simon Pierre répondit: Tu es le Christ, le Fils du Dieu vivant."}, {"numero": 17, "texto": "Jésus, reprenant la parole, lui dit: Tu es heureux, Simon, fils de Jonas; car ce ne sont pas la chair et le sang qui t''''ont révélé cela, mais c''''est mon Père qui est dans les cieux."}, {"numero": 18, "texto": "Et moi, je te dis que tu es Pierre, et que sur cette pierre je bâtirai mon Eglise, et que les portes du séjour des morts ne prévaudront point contre elle."}, {"numero": 19, "texto": "Je te donnerai les clefs du royaume des cieux: ce que tu lieras sur la terre sera lié dans les cieux, et ce que tu délieras sur la terre sera délié dans les cieux."}, {"numero": 20, "texto": "Alors il recommanda aux disciples de ne dire à personne qu''''il était le Christ."}, {"numero": 21, "texto": "Dès lors Jésus commença à faire connaître à ses disciples qu''''il fallait qu''''il allât à Jérusalem, qu''''il souffrît beaucoup de la part des anciens, des principaux sacrificateurs et des scribes, qu''''il fût mis à mort, et qu''''il ressuscitât le troisième jour."}, {"numero": 22, "texto": "Pierre, l''''ayant pris à part, se mit à le reprendre, et dit: A Dieu ne plaise, Seigneur! Cela ne t''''arrivera pas."}, {"numero": 23, "texto": "Mais Jésus, se retournant, dit à Pierre: Arrière de moi, Satan! tu m''''es en scandale; car tes pensées ne sont pas les pensées de Dieu, mais celles des hommes."}, {"numero": 24, "texto": "Alors Jésus dit à ses disciples: Si quelqu''''un veut venir après moi, qu''''il renonce à lui-même, qu''''il se charge de sa croix, et qu''''il me suive."}, {"numero": 25, "texto": "Car celui qui voudra sauver sa vie la perdra, mais celui qui la perdra à cause de moi la trouvera."}, {"numero": 26, "texto": "Et que servirait-il à un homme de gagner tout le monde, s''''il perdait son âme? ou, que donnerait un homme en échange de son âme?"}, {"numero": 27, "texto": "Car le Fils de l''''homme doit venir dans la gloire de son Père, avec ses anges; et alors il rendra à chacun selon ses oeuvres."}, {"numero": 28, "texto": "Je vous le dis en vérité, quelques-uns de ceux qui sont ici ne mourront point, qu''''ils n''''aient vu le Fils de l''''homme venir dans son règne."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 16, 'es', '[{"numero": 1, "texto": "Y LLEGÁNDOSE los Fariseos y los Saduceos para tentarle, le pedían que les mostrase señal del cielo."}, {"numero": 2, "texto": "Mas él respondiendo, les dijo: Cuando es la tarde del día, decís: Sereno; porque el cielo tiene arreboles."}, {"numero": 3, "texto": "Y á la mañana: Hoy tempestad; porque tiene arreboles el cielo triste. Hipócritas, que sabéis hacer diferencia en la faz del cielo; ¿y en las señales de los tiempos no podéis?"}, {"numero": 4, "texto": "La generación mala y adulterina demanda señal; mas señal no le será dada, sino la señal de Jonás profeta. Y dejándolos, se fué."}, {"numero": 5, "texto": "Y viniendo sus discípulos de la otra parte del lago, se habían olvidado de tomar pan."}, {"numero": 6, "texto": "Y Jesús les dijo: Mirad, y guardaos de la levadura de los Fariseos y de los Saduceos."}, {"numero": 7, "texto": "Y ellos pensaban dentro de sí, diciendo: Esto dice porque no tomamos pan."}, {"numero": 8, "texto": "Y entendiéndolo Jesús, les dijo: ¿Por qué pensáis dentro de vosotros, hombres de poca fe, que no tomasteis pan?"}, {"numero": 9, "texto": "¿No entendéis aún, ni os acordáis de los cinco panes entre cinco mil hombres, y cuántos cestos alzasteis?"}, {"numero": 10, "texto": "¿Ni de los siete panes entre cuatro mil, y cuántas espuertas tomasteis?"}, {"numero": 11, "texto": "¿Cómo es que no entendéis que no por el pan os dije, que os guardaseis de la levadura de los Fariseos y de los Saduceos?"}, {"numero": 12, "texto": "Entonces entendieron que no les había dicho que se guardasen de la levadura de pan, sino de la doctrina de los Fariseos y de los Saduceos."}, {"numero": 13, "texto": "Y viniendo Jesús á las partes de Cesarea de Filipo, preguntó á sus discípulos, diciendo: ¿Quién dicen los hombres que es el Hijo del hombre?"}, {"numero": 14, "texto": "Y ellos dijeron: Unos, Juan el Bautista; y otros, Elías; y otros, Jeremías, ó alguno de los profetas."}, {"numero": 15, "texto": "El les dice: Y vosotros, ¿quién decís que soy?"}, {"numero": 16, "texto": "Y respondiendo Simón Pedro, dijo: Tú eres el Cristo, el Hijo del Dios viviente."}, {"numero": 17, "texto": "Entonces, respondiendo Jesús, le dijo: Bienaventurado eres, Simón, hijo de Jonás; porque no te lo reveló carne ni sangre, mas mi Padre que está en los cielos."}, {"numero": 18, "texto": "Mas yo también te digo, que tú eres Pedro, y sobre esta piedra edificaré mi iglesia; y las puertas del infierno no prevalecerán contra ella."}, {"numero": 19, "texto": "Y á ti daré las llaves del reino de los cielos; y todo lo que ligares en la tierra será ligado en los cielos; y todo lo que desatares en la tierra será desatado en los cielos."}, {"numero": 20, "texto": "Entonces mandó á sus discípulos que á nadie dijesen que él era Jesús el Cristo."}, {"numero": 21, "texto": "Desde aquel tiempo comenzó Jesús á declarar á sus discípulos que le convenía ir á Jerusalem, y padecer mucho de los ancianos, y de los príncipes de los sacerdotes, y de los escribas; y ser muerto, y resucitar al tercer día."}, {"numero": 22, "texto": "Y Pedro, tomándolo aparte, comenzó á reprenderle, diciendo: Señor, ten compasión de ti: en ninguna manera esto te acontezca."}, {"numero": 23, "texto": "Entonces él, volviéndose, dijo á Pedro: Quítate de delante de mí, Satanás; me eres escándalo; porque no entiendes lo que es de Dios sino lo que es de los hombres."}, {"numero": 24, "texto": "Entonces Jesús dijo á sus discípulos: Si alguno quiere venir en pos de mí, niéguese á sí mismo, y tome su cruz, y sígame."}, {"numero": 25, "texto": "Porque cualquiera que quisiere salvar su vida, la perderá, y cualquiera que perdiere su vida por causa de mí, la hallará."}, {"numero": 26, "texto": "Porque ¿de qué aprovecha al hombre, si granjeare todo el mundo, y perdiere su alma? O ¿qué recompensa dará el hombre por su alma?"}, {"numero": 27, "texto": "Porque el Hijo del hombre vendrá en la gloria de su Padre con sus ángeles, y entonces pagará á cada uno conforme á sus obras."}, {"numero": 28, "texto": "De cierto os digo: hay algunos de los que están aquí, que no gustarán la muerte, hasta que hayan visto al Hijo del hombre viniendo en su reino."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 17, 'pt', '[{"numero": 1, "texto": "Seis dias depois, Jesus tomou consigo Pedro, Tiago, e seu irmão João, e os levou a sós a um monte alto."}, {"numero": 2, "texto": "Então transfigurou-se diante deles; seu rosto brilhou como o sol, e suas roupas se tornaram brancas como a luz."}, {"numero": 3, "texto": "E eis que lhes apareceram Moisés e Elias, falando com ele."}, {"numero": 4, "texto": "Pedro, então, disse a Jesus: Senhor, bom é para nós estarmos aqui. Se queres, façamos aqui três tendas: uma para ti, uma para Moisés, e uma para Elias."}, {"numero": 5, "texto": "Enquanto ele ainda estava falando, eis que uma nuvem brilhante os cobriu. E eis que uma voz da nuvem disse: Este é o meu Filho amado, em quem me agrado; a ele ouvi."}, {"numero": 6, "texto": "Quando os discípulos ouviram, caíram sobre seus rostos, e tiveram muito medo."}, {"numero": 7, "texto": "Jesus se aproximou deles, tocou-os, e disse: Levantai-vos, e não tenhais medo."}, {"numero": 8, "texto": "E quando eles levantaram seus olhos, não viram a ninguém, a não ser a Jesus somente."}, {"numero": 9, "texto": "E enquanto desciam do monte, Jesus lhes disse a seguinte ordem: Não conteis a visão a ninguém, até que o Filho do homem seja ressuscitado dos mortos."}, {"numero": 10, "texto": "E os seus discípulos lhe perguntaram: Por que, então, os escribas dizem que Elias tem que vir primeiro?"}, {"numero": 11, "texto": "Jesus lhes respondeu: Em verdade Elias virá primeiro, e restaurará todas as coisas."}, {"numero": 12, "texto": "Digo-vos, porém, que Elias já veio, mas não o reconheceram. Em vez disso fizeram dele tudo o que quiseram. Assim também o Filho do homem sofrerá por meio deles."}, {"numero": 13, "texto": "Então os discípulos entenderam que ele lhes falara a respeito de João Batista."}, {"numero": 14, "texto": "E quando chegaram à multidão, veio a ele um homem, que se ajoelhou diante dele, e disse:"}, {"numero": 15, "texto": "Senhor, tem misericórdia do meu filho, que é epilético, e sofre muito mal; porque cai muitas vezes no fogo, e muitas vezes na água."}, {"numero": 16, "texto": "E eu o trouxe aos teus discípulos, mas não o puderam curar."}, {"numero": 17, "texto": "Jesus respondeu: Ó geração incrédula e perversa! Até quando estarei convosco? Até quando vos suportarei? Trazei-o a mim aqui."}, {"numero": 18, "texto": "E Jesus o repreendeu. Então o demônio saiu dele, e o menino sarou desde aquela hora."}, {"numero": 19, "texto": "Depois os discípulos se aproximaram de Jesus em particular, e perguntaram: Por que nós não o pudemos expulsar?"}, {"numero": 20, "texto": "E Jesus lhes respondeu: Por causa da vossa incredulidade; pois em verdade vos digo, que se tivésseis fé como um grão de mostarda, diríeis a este monte: “Passa-te daqui para lá”, E ele passaria. E nada vos seria impossível."}, {"numero": 21, "texto": "Mas este tipo [de demônio] não sai, a não ser por oração e jejum."}, {"numero": 22, "texto": "E enquanto eles estavam na Galileia, Jesus lhes disse: O Filho do homem será entregue em mãos de homens."}, {"numero": 23, "texto": "E o matarão, e ele será ressuscitado ao terceiro dia.E eles se entristeceram muito."}, {"numero": 24, "texto": "E quando entraram em Cafarnaum, os cobradores da taxa de duas dracmas vieram a Pedro, e perguntaram: Vosso mestre não paga as duas dracmas?"}, {"numero": 25, "texto": "Ele respondeu: Sim. Quando ele entrou em casa, Jesus o antecipou, dizendo: Que te parece, Simão? De quem os reis da terra cobram tributos ou taxas? Dos seus filhos, ou dos outros?"}, {"numero": 26, "texto": "Pedro lhe respondeu: Dos outros. Jesus lhe disse: Logo, os filhos são livres de pagar."}, {"numero": 27, "texto": "Mas para não os ofendermos, vai ao mar, e lança o anzol. Toma o primeiro peixe que subir, e quando lhe abrir a boca, acharás uma moeda de quatro dracmas. Toma-a, e dá a eles por mim e por ti."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 17, 'en', '[{"numero": 1, "texto": "And after six days Jesus taketh Peter, James, and John his brother, and bringeth them up into an high mountain apart,"}, {"numero": 2, "texto": "And was transfigured before them: and his face did shine as the sun, and his raiment was white as the light."}, {"numero": 3, "texto": "And, behold, there appeared unto them Moses and Elias talking with him."}, {"numero": 4, "texto": "Then answered Peter, and said unto Jesus, Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles; one for thee, and one for Moses, and one for Elias."}, {"numero": 5, "texto": "While he yet spake, behold, a bright cloud overshadowed them: and behold a voice out of the cloud, which said, This is my beloved Son, in whom I am well pleased; hear ye him."}, {"numero": 6, "texto": "And when the disciples heard it, they fell on their face, and were sore afraid."}, {"numero": 7, "texto": "And Jesus came and touched them, and said, Arise, and be not afraid."}, {"numero": 8, "texto": "And when they had lifted up their eyes, they saw no man, save Jesus only."}, {"numero": 9, "texto": "And as they came down from the mountain, Jesus charged them, saying, Tell the vision to no man, until the Son of man be risen again from the dead."}, {"numero": 10, "texto": "And his disciples asked him, saying, Why then say the scribes that Elias must first come?"}, {"numero": 11, "texto": "And Jesus answered and said unto them, Elias truly shall first come, and restore all things."}, {"numero": 12, "texto": "But I say unto you, That Elias is come already, and they knew him not, but have done unto him whatsoever they listed. Likewise shall also the Son of man suffer of them."}, {"numero": 13, "texto": "Then the disciples understood that he spake unto them of John the Baptist."}, {"numero": 14, "texto": "And when they were come to the multitude, there came to him a certain man, kneeling down to him, and saying,"}, {"numero": 15, "texto": "Lord, have mercy on my son: for he is lunatick, and sore vexed: for ofttimes he falleth into the fire, and oft into the water."}, {"numero": 16, "texto": "And I brought him to thy disciples, and they could not cure him."}, {"numero": 17, "texto": "Then Jesus answered and said, O faithless and perverse generation, how long shall I be with you? how long shall I suffer you? bring him hither to me."}, {"numero": 18, "texto": "And Jesus rebuked the devil; and he departed out of him: and the child was cured from that very hour."}, {"numero": 19, "texto": "Then came the disciples to Jesus apart, and said, Why could not we cast him out?"}, {"numero": 20, "texto": "And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you."}, {"numero": 21, "texto": "Howbeit this kind goeth not out but by prayer and fasting."}, {"numero": 22, "texto": "And while they abode in Galilee, Jesus said unto them, The Son of man shall be betrayed into the hands of men:"}, {"numero": 23, "texto": "And they shall kill him, and the third day he shall be raised again. And they were exceeding sorry."}, {"numero": 24, "texto": "And when they were come to Capernaum, they that received tribute money came to Peter, and said, Doth not your master pay tribute?"}, {"numero": 25, "texto": "He saith, Yes. And when he was come into the house, Jesus prevented him, saying, What thinkest thou, Simon? of whom do the kings of the earth take custom or tribute? of their own children, or of strangers?"}, {"numero": 26, "texto": "Peter saith unto him, Of strangers. Jesus saith unto him, Then are the children free."}, {"numero": 27, "texto": "Notwithstanding, lest we should offend them, go thou to the sea, and cast an hook, and take up the fish that first cometh up; and when thou hast opened his mouth, thou shalt find a piece of money: that take, and give unto them for me and thee."}]'::jsonb, 'King James Version'),
  ('Mt', 17, 'fr', '[{"numero": 1, "texto": "Six jours après, Jésus prit avec lui Pierre, Jacques, et Jean, son frère, et il les conduisit à l''''écart sur une haute montagne."}, {"numero": 2, "texto": "Il fut transfiguré devant eux; son visage resplendit comme le soleil, et ses vêtements devinrent blancs comme la lumière."}, {"numero": 3, "texto": "Et voici, Moïse et Elie leur apparurent, s''''entretenant avec lui."}, {"numero": 4, "texto": "Pierre, prenant la parole, dit à Jésus: Seigneur, il est bon que nous soyons ici; si tu le veux, je dresserai ici trois tentes, une pour toi, une pour Moïse, et une pour Elie."}, {"numero": 5, "texto": "Comme il parlait encore, une nuée lumineuse les couvrit. Et voici, une voix fit entendre de la nuée ces paroles: Celui-ci est mon Fils bien-aimé, en qui j''''ai mis toute mon affection: écoutez-le!"}, {"numero": 6, "texto": "Lorsqu''''ils entendirent cette voix, les disciples tombèrent sur leur face, et furent saisis d''''une grande frayeur."}, {"numero": 7, "texto": "Mais Jésus, s''''approchant, les toucha, et dit: Levez-vous, n''''ayez pas peur!"}, {"numero": 8, "texto": "Ils levèrent les yeux, et ne virent que Jésus seul."}, {"numero": 9, "texto": "Comme ils descendaient de la montagne, Jésus leur donna cet ordre: Ne parlez à personne de cette vision, jusqu''''à ce que le Fils de l''''homme soit ressuscité des morts."}, {"numero": 10, "texto": "Les disciples lui firent cette question: Pourquoi donc les scribes disent-ils qu''''Elie doit venir premièrement?"}, {"numero": 11, "texto": "Il répondit: Il est vrai qu''''Elie doit venir, et rétablir toutes choses."}, {"numero": 12, "texto": "Mais je vous dis qu''''Elie est déjà venu, qu''''ils ne l''''ont pas reconnu, et qu''''ils l''''ont traité comme ils ont voulu. De même le Fils de l''''homme souffrira de leur part."}, {"numero": 13, "texto": "Les disciples comprirent alors qu''''il leur parlait de Jean-Baptiste."}, {"numero": 14, "texto": "Lorsqu''''ils furent arrivés près de la foule, un homme vint se jeter à genoux devant Jésus, et dit:"}, {"numero": 15, "texto": "Seigneur, aie pitié de mon fils, qui est lunatique, et qui souffre cruellement; il tombe souvent dans le feu, et souvent dans l''''eau."}, {"numero": 16, "texto": "Je l''''ai amené à tes disciples, et ils n''''ont pas pu le guérir."}, {"numero": 17, "texto": "Race incrédule et perverse, répondit Jésus, jusques à quand serai-je avec vous? jusques à quand vous supporterai-je? Amenez-le-moi ici."}, {"numero": 18, "texto": "Jésus parla sévèrement au démon, qui sortit de lui, et l''''enfant fut guéri à l''''heure même."}, {"numero": 19, "texto": "Alors les disciples s''''approchèrent de Jésus, et lui dirent en particulier: Pourquoi n''''avons-nous pu chasser ce démon?"}, {"numero": 20, "texto": "C''''est à cause de votre incrédulité, leur dit Jésus. Je vous le dis en vérité, si vous aviez de la foi comme un grain de sénevé, vous diriez à cette montagne: Transporte-toi d''''ici là, et elle se transporterait; rien ne vous serait impossible."}, {"numero": 21, "texto": "Mais cette sorte de démon ne sort que par la prière et par le jeûne."}, {"numero": 22, "texto": "Pendant qu''''ils parcouraient la Galilée, Jésus leur dit: Le Fils de l''''homme doit être livré entre les mains des hommes;"}, {"numero": 23, "texto": "ils le feront mourir, et le troisième jour il ressuscitera. Ils furent profondément attristés."}, {"numero": 24, "texto": "Lorsqu''''ils arrivèrent à Capernaüm, ceux qui percevaient les deux drachmes s''''adressèrent à Pierre, et lui dirent: Votre maître ne paie-t-il pas les deux drachmes?"}, {"numero": 25, "texto": "Oui, dit-il. Et quand il fut entré dans la maison, Jésus le prévint, et dit: Que t''''en semble, Simon? Les rois de la terre, de qui perçoivent-ils des tributs ou des impôts? de leurs fils, ou des étrangers?"}, {"numero": 26, "texto": "Il lui dit: Des étrangers. Et Jésus lui répondit: Les fils en sont donc exempts."}, {"numero": 27, "texto": "Mais, pour ne pas les scandaliser, va à la mer, jette l''''hameçon, et tire le premier poisson qui viendra; ouvre-lui la bouche, et tu trouveras un statère. Prends-le, et donne-le-leur pour moi et pour toi."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 17, 'es', '[{"numero": 1, "texto": "Y DESPUÉS de seis días, Jesús toma á Pedro, y á Jacobo, y á Juan su hermano, y los lleva aparte á un monte alto:"}, {"numero": 2, "texto": "Y se transfiguró delante de ellos; y resplandeció su rostro como el sol, y sus vestidos fueron blancos como la luz."}, {"numero": 3, "texto": "Y he aquí les aparecieron Moisés y Elías, hablando con él."}, {"numero": 4, "texto": "Y respondiendo Pedro, dijo á Jesús: Señor, bien es que nos quedemos aquí: si quieres, hagamos aquí tres pabellones: para ti uno, y para Moisés otro, y otro para Elías."}, {"numero": 5, "texto": "Y estando aún él hablando, he aquí una nube de luz que los cubrió; y he aquí una voz de la nube, que dijo: Este es mi Hijo amado, en el cual tomo contentamiento: á él oid."}, {"numero": 6, "texto": "Y oyendo esto los discípulos, cayeron sobre sus rostros, y temieron en gran manera."}, {"numero": 7, "texto": "Entonces Jesús llegando, los tocó, y dijo: Levantaos, y no temáis."}, {"numero": 8, "texto": "Y alzando ellos sus ojos, á nadie vieron, sino á solo Jesús."}, {"numero": 9, "texto": "Y como descendieron del monte, les mandó Jesús, diciendo: No digáis á nadie la visión, hasta que el Hijo del hombre resucite de los muertos."}, {"numero": 10, "texto": "Entonces sus discípulos le preguntaron, diciendo: ¿Por qué dicen pues los escribas que es menester que Elías venga primero?"}, {"numero": 11, "texto": "Y respondiendo Jesús, les dijo: A la verdad, Elías vendrá primero, y restituirá todas las cosas."}, {"numero": 12, "texto": "Mas os digo, que ya vino Elías, y no le conocieron; antes hicieron en él todo lo que quisieron: así también el Hijo del hombre padecerá de ellos."}, {"numero": 13, "texto": "Los discípulos entonces entendieron, que les habló de Juan el Bautista."}, {"numero": 14, "texto": "Y como ellos llegaron al gentío, vino á él un hombre hincándosele de rodillas,"}, {"numero": 15, "texto": "Y diciendo: Señor, ten misericordia de mi hijo, que es lunático, y padece malamente; porque muchas veces cae en el fuego, y muchas en el agua."}, {"numero": 16, "texto": "Y le he presentado á tus discípulos, y no le han podido sanar."}, {"numero": 17, "texto": "Y respondiendo Jesús, dijo: ¡Oh generación infiel y torcida! ¿hasta cuándo tengo de estar con vosotros? ¿hasta cuándo os tengo de sufrir? traédmele acá."}, {"numero": 18, "texto": "Y Jesús le reprendió, y salió el demonio de él; y el mozo fué sano desde aquella hora."}, {"numero": 19, "texto": "Entonces, llegándose los discípulos á Jesús, aparte, dijeron: ¿Por qué nosotros no lo pudimos echar fuera?"}, {"numero": 20, "texto": "Y Jesús les dijo: Por vuestra incredulidad; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, diréis á este monte: Pásate de aquí allá: y se pasará: y nada os será imposible."}, {"numero": 21, "texto": "Mas este linaje no sale sino por oración y ayuno."}, {"numero": 22, "texto": "Y estando ellos en Galilea, Jesús les dijo: El Hijo del hombre será entregado en manos de hombres,"}, {"numero": 23, "texto": "Y le matarán; mas al tercer día resucitará. Y ellos se entristecieron en gran manera."}, {"numero": 24, "texto": "Y como llegaron á Capernaum, vinieron á Pedro los que cobraban las dos dracmas, y dijeron: ¿Vuestro Maestro no paga las dos dracmas?"}, {"numero": 25, "texto": "El dice: Sí. Y entrando él en casa, Jesús le habló antes, diciendo: ¿Qué te parece, Simón? Los reyes de la tierra, ¿de quién cobran los tributos ó el censo? ¿de sus hijos ó de los extraños?"}, {"numero": 26, "texto": "Pedro le dice: De los extraños. Jesús le dijo: Luego los hijos son francos."}, {"numero": 27, "texto": "Mas porque no los escandalicemos, ve á la mar, y echa el anzuelo, y el primer pez que viniere, tómalo, y abierta su boca, hallarás un estatero: tómalo, y dáselo por mí y por ti."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 18, 'pt', '[{"numero": 1, "texto": "Naquela hora os discípulos se aproximaram de Jesus, e perguntaram: Ora, quem é o maior no Reino dos céus?"}, {"numero": 2, "texto": "Então Jesus chamou a si uma criança, e a pôs no meio deles,"}, {"numero": 3, "texto": "e disse: Em verdade vos digo, que se vós não converterdes, e fordes como crianças, de maneira nenhuma entrareis no Reino dos céus."}, {"numero": 4, "texto": "Assim, qualquer um que for humilde como esta criança, este é o maior no reino dos céus."}, {"numero": 5, "texto": "E qualquer um que receber a uma criança como esta em meu nome, recebe a mim."}, {"numero": 6, "texto": "Mas qualquer um que conduzir ao pecado a um destes pequeninos que creem em mim, melhor lhe fora que uma grande pedra de moinho lhe fosse pendurada ao pescoço, e se afundasse no fundo do mar."}, {"numero": 7, "texto": "Ai do mundo por causa das tentações do pecado! Pois é necessário que as tentações venham, mas ai daquela pessoa por quem a tentação vem!"}, {"numero": 8, "texto": "Portanto, se a tua mão ou o teu pé te faz pecar, corta-os, e lança-os de ti; melhor te é entrar manco ou aleijado na vida do que, tendo duas mãos ou dois pés, ser lançado no fogo eterno."}, {"numero": 9, "texto": "E se o teu olho te faz pecar, arranca-o, e lança-o de ti. Melhor te é entrar com um olho na vida do que, tendo dois olhos, ser lançado no inferno de fogo."}, {"numero": 10, "texto": "Olhai para que não desprezeis a algum destes pequeninos; porque eu vos digo que os seus anjos nos céus sempre veem a face do meu Pai, que [está] nos céus."}, {"numero": 11, "texto": "Pois o Filho do homem veio para salvar o que havia se perdido."}, {"numero": 12, "texto": "Que vos parece? Se alguém tivesse cem ovelhas, e uma delas se desviasse, por acaso não iria ele pelos montes, deixando as noventa e nove, em busca da desviada?"}, {"numero": 13, "texto": "E se acontecesse de achá-la, em verdade vos digo que ele se alegra mais daquela, do que das noventa e nove que se não desviaram."}, {"numero": 14, "texto": "Da mesma maneira, não é da vontade do vosso Pai, que [está] nos céus, que um sequer destes pequeninos se perca."}, {"numero": 15, "texto": "Porém, se teu irmão pecar contra ti, vai repreendê-lo entre ti e ele só; se te ouvir, ganhaste o teu irmão."}, {"numero": 16, "texto": "Mas se não ouvir, toma ainda contigo um ou dois, para que toda palavra se confirme pela boca de duas ou três testemunhas."}, {"numero": 17, "texto": "E se não lhes der ouvidos, comunica à igreja; e se também não der ouvidos à igreja, considera-o como gentio e publicano."}, {"numero": 18, "texto": "Em verdade vos digo que tudo o que vós ligardes na terra será ligado no céu; e tudo o que desligardes na terra será desligado no céu."}, {"numero": 19, "texto": "E digo-vos também que, se dois de vós concordarem na terra acerca de qualquer coisa que pedirem, isso lhes será feito por meu Pai, que [está] nos céus."}, {"numero": 20, "texto": "Pois onde dois ou três estiverem reunidos em meu nome, ali eu estou no meio deles."}, {"numero": 21, "texto": "Então Pedro aproximou-se dele, e perguntou: Senhor, até quantas vezes meu irmão pecará contra mim, e eu lhe perdoarei? Até sete?"}, {"numero": 22, "texto": "Jesus lhe respondeu: Eu não te digo até sete, mas sim até setenta vezes sete."}, {"numero": 23, "texto": "Por isso o Reino dos céus é comparável a um certo rei, que quis fazer acerto de contas com os seus servos."}, {"numero": 24, "texto": "E começando a fazer acerto de contas, foi-lhe apresentado um que lhe devia dez mil talentos."}, {"numero": 25, "texto": "Como ele não tinha com que pagar, o seu senhor mandou que ele, sua mulher, filhos, e tudo quanto tinha fossem vendidos para se fazer o pagamento."}, {"numero": 26, "texto": "Então aquele servo caiu e ficou prostrado diante dele, dizendo: “Senhor, tem paciência comigo, e tudo te pagarei”."}, {"numero": 27, "texto": "O senhor daquele servo compadeceu-se dele, então o soltou e lhe perdoou a dívida."}, {"numero": 28, "texto": "Todavia, depois daquele servo sair, achou um companheiro de serviço seu, que lhe devia cem denários; então o agarrou e o sufocou, dizendo: “Paga-me o que [me] deves!”"}, {"numero": 29, "texto": "Então o seu colega se prostrou diante dos seus pés, e lhe suplicou, dizendo: “Tem paciência comigo, e tudo te pagarei”."}, {"numero": 30, "texto": "Mas ele não quis. Em vez disso foi lançá-lo na prisão até que pagasse a dívida."}, {"numero": 31, "texto": "Quando os seus companheiros de serviço viram o que se passava, entristeceram-se muito. Então vieram denunciar ao seu senhor tudo o que havia se passado."}, {"numero": 32, "texto": "Assim o seu senhor o chamou, e lhe disse: “Servo mau! Toda aquela dívida te perdoei, porque me suplicaste."}, {"numero": 33, "texto": "Não tinhas tu a obrigação de ter tido misericórdia do sevo colega teu, assim como eu tive misericórdia de ti?”"}, {"numero": 34, "texto": "E, enfurecido, o seu senhor o entregou aos torturadores até que pagasse tudo o que lhe devia."}, {"numero": 35, "texto": "Assim também meu Pai celestial vos fará, se não perdoardes de coração cada um ao seu irmão suas ofensas."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 18, 'en', '[{"numero": 1, "texto": "At the same time came the disciples unto Jesus, saying, Who is the greatest in the kingdom of heaven?"}, {"numero": 2, "texto": "And Jesus called a little child unto him, and set him in the midst of them,"}, {"numero": 3, "texto": "And said, Verily I say unto you, Except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven."}, {"numero": 4, "texto": "Whosoever therefore shall humble himself as this little child, the same is greatest in the kingdom of heaven."}, {"numero": 5, "texto": "And whoso shall receive one such little child in my name receiveth me."}, {"numero": 6, "texto": "But whoso shall offend one of these little ones which believe in me, it were better for him that a millstone were hanged about his neck, and that he were drowned in the depth of the sea."}, {"numero": 7, "texto": "Woe unto the world because of offences! for it must needs be that offences come; but woe to that man by whom the offence cometh!"}, {"numero": 8, "texto": "Wherefore if thy hand or thy foot offend thee, cut them off, and cast them from thee: it is better for thee to enter into life halt or maimed, rather than having two hands or two feet to be cast into everlasting fire."}, {"numero": 9, "texto": "And if thine eye offend thee, pluck it out, and cast it from thee: it is better for thee to enter into life with one eye, rather than having two eyes to be cast into hell fire."}, {"numero": 10, "texto": "Take heed that ye despise not one of these little ones; for I say unto you, That in heaven their angels do always behold the face of my Father which is in heaven."}, {"numero": 11, "texto": "For the Son of man is come to save that which was lost."}, {"numero": 12, "texto": "How think ye? if a man have an hundred sheep, and one of them be gone astray, doth he not leave the ninety and nine, and goeth into the mountains, and seeketh that which is gone astray?"}, {"numero": 13, "texto": "And if so be that he find it, verily I say unto you, he rejoiceth more of that sheep, than of the ninety and nine which went not astray."}, {"numero": 14, "texto": "Even so it is not the will of your Father which is in heaven, that one of these little ones should perish."}, {"numero": 15, "texto": "Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother."}, {"numero": 16, "texto": "But if he will not hear thee, then take with thee one or two more, that in the mouth of two or three witnesses every word may be established."}, {"numero": 17, "texto": "And if he shall neglect to hear them, tell it unto the church: but if he neglect to hear the church, let him be unto thee as an heathen man and a publican."}, {"numero": 18, "texto": "Verily I say unto you, Whatsoever ye shall bind on earth shall be bound in heaven: and whatsoever ye shall loose on earth shall be loosed in heaven."}, {"numero": 19, "texto": "Again I say unto you, That if two of you shall agree on earth as touching any thing that they shall ask, it shall be done for them of my Father which is in heaven."}, {"numero": 20, "texto": "For where two or three are gathered together in my name, there am I in the midst of them."}, {"numero": 21, "texto": "Then came Peter to him, and said, Lord, how oft shall my brother sin against me, and I forgive him? till seven times?"}, {"numero": 22, "texto": "Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven."}, {"numero": 23, "texto": "Therefore is the kingdom of heaven likened unto a certain king, which would take account of his servants."}, {"numero": 24, "texto": "And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents."}, {"numero": 25, "texto": "But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made."}, {"numero": 26, "texto": "The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all."}, {"numero": 27, "texto": "Then the lord of that servant was moved with compassion, and loosed him, and forgave him the debt."}, {"numero": 28, "texto": "But the same servant went out, and found one of his fellowservants, which owed him an hundred pence: and he laid hands on him, and took him by the throat, saying, Pay me that thou owest."}, {"numero": 29, "texto": "And his fellowservant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all."}, {"numero": 30, "texto": "And he would not: but went and cast him into prison, till he should pay the debt."}, {"numero": 31, "texto": "So when his fellowservants saw what was done, they were very sorry, and came and told unto their lord all that was done."}, {"numero": 32, "texto": "Then his lord, after that he had called him, said unto him, O thou wicked servant, I forgave thee all that debt, because thou desiredst me:"}, {"numero": 33, "texto": "Shouldest not thou also have had compassion on thy fellowservant, even as I had pity on thee?"}, {"numero": 34, "texto": "And his lord was wroth, and delivered him to the tormentors, till he should pay all that was due unto him."}, {"numero": 35, "texto": "So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses."}]'::jsonb, 'King James Version'),
  ('Mt', 18, 'fr', '[{"numero": 1, "texto": "En ce moment, les disciples s''''approchèrent de Jésus, et dirent: Qui donc est le plus grand dans le royaume des cieux?"}, {"numero": 2, "texto": "Jésus, ayant appelé un petit enfant, le plaça au milieu d''''eux,"}, {"numero": 3, "texto": "et dit: Je vous le dis en vérité, si vous ne vous convertissez et si vous ne devenez comme les petits enfants, vous n''''entrerez pas dans le royaume des cieux."}, {"numero": 4, "texto": "C''''est pourquoi, quiconque se rendra humble comme ce petit enfant sera le plus grand dans le royaume des cieux."}, {"numero": 5, "texto": "Et quiconque reçoit en mon nom un petit enfant comme celui-ci, me reçoit moi-même."}, {"numero": 6, "texto": "Mais, si quelqu''''un scandalisait un de ces petits qui croient en moi, il vaudrait mieux pour lui qu''''on suspendît à son cou une meule de moulin, et qu''''on le jetât au fond de la mer."}, {"numero": 7, "texto": "Malheur au monde à cause des scandales! Car il est nécessaire qu''''il arrive des scandales; mais malheur à l''''homme par qui le scandale arrive!"}, {"numero": 8, "texto": "Si ta main ou ton pied est pour toi une occasion de chute, coupe-les et jette-les loin de toi; mieux vaut pour toi entrer dans la vie boiteux ou manchot, que d''''avoir deux pieds ou deux mains et d''''être jeté dans le feu éternel."}, {"numero": 9, "texto": "Et si ton oeil est pour toi une occasion de chute, arrache-le et jette-le loin de toi; mieux vaut pour toi entrer dans la vie, n''''ayant qu''''un oeil, que d''''avoir deux yeux et d''''être jeté dans le feu de la géhenne."}, {"numero": 10, "texto": "Gardez-vous de mépriser un seul de ces petits; car je vous dis que leurs anges dans les cieux voient continuellement la face de mon Père qui est dans les cieux."}, {"numero": 11, "texto": "Car le Fils de l''''homme est venu sauver ce qui était perdu."}, {"numero": 12, "texto": "Que vous en semble? Si un homme a cent brebis, et que l''''une d''''elles s''''égare, ne laisse-t-il pas les quatre-vingt-dix-neuf autres sur les montagnes, pour aller chercher celle qui s''''est égarée?"}, {"numero": 13, "texto": "Et, s''''il la trouve, je vous le dis en vérité, elle lui cause plus de joie que les quatre-vingt-dix-neuf qui ne se sont pas égarées."}, {"numero": 14, "texto": "De même, ce n''''est pas la volonté de votre Père qui est dans les cieux qu''''il se perde un seul de ces petits."}, {"numero": 15, "texto": "Si ton frère a péché, va et reprends-le entre toi et lui seul. S''''il t''''écoute, tu as gagné ton frère."}, {"numero": 16, "texto": "Mais, s''''il ne t''''écoute pas, prends avec toi une ou deux personnes, afin que toute l''''affaire se règle sur la déclaration de deux ou de trois témoins."}, {"numero": 17, "texto": "S''''il refuse de les écouter, dis-le à l''''Eglise; et s''''il refuse aussi d''''écouter l''''Eglise, qu''''il soit pour toi comme un païen et un publicain."}, {"numero": 18, "texto": "Je vous le dis en vérité, tout ce que vous lierez sur la terre sera lié dans le ciel, et tout ce que vous délierez sur la terre sera délié dans le ciel."}, {"numero": 19, "texto": "Je vous dis encore que, si deux d''''entre vous s''''accordent sur la terre pour demander une chose quelconque, elle leur sera accordée par mon Père qui est dans les cieux."}, {"numero": 20, "texto": "Car là où deux ou trois sont assemblés en mon nom, je suis au milieu d''''eux."}, {"numero": 21, "texto": "Alors Pierre s''''approcha de lui, et dit: Seigneur, combien de fois pardonnerai-je à mon frère, lorsqu''''il péchera contre moi? Sera-ce jusqu''''à sept fois?"}, {"numero": 22, "texto": "Jésus lui dit: Je ne te dis pas jusqu''''à sept fois, mais jusqu''''à septante fois sept fois."}, {"numero": 23, "texto": "C''''est pourquoi, le royaume des cieux est semblable à un roi qui voulut faire rendre compte à ses serviteurs."}, {"numero": 24, "texto": "Quand il se mit à compter, on lui en amena un qui devait dix mille talents."}, {"numero": 25, "texto": "Comme il n''''avait pas de quoi payer, son maître ordonna qu''''il fût vendu, lui, sa femme, ses enfants, et tout ce qu''''il avait, et que la dette fût acquittée."}, {"numero": 26, "texto": "Le serviteur, se jetant à terre, se prosterna devant lui, et dit: Seigneur, aie patience envers moi, et je te paierai tout."}, {"numero": 27, "texto": "Emu de compassion, le maître de ce serviteur le laissa aller, et lui remit la dette."}, {"numero": 28, "texto": "Après qu''''il fut sorti, ce serviteur rencontra un de ses compagnons qui lui devait cent deniers. Il le saisit et l''''étranglait, en disant: Paie ce que tu me dois."}, {"numero": 29, "texto": "Son compagnon, se jetant à terre, le suppliait, disant: Aie patience envers moi, et je te paierai."}, {"numero": 30, "texto": "Mais l''''autre ne voulut pas, et il alla le jeter en prison, jusqu''''à ce qu''''il eût payé ce qu''''il devait."}, {"numero": 31, "texto": "Ses compagnons, ayant vu ce qui était arrivé, furent profondément attristés, et ils allèrent raconter à leur maître tout ce qui s''''était passé."}, {"numero": 32, "texto": "Alors le maître fit appeler ce serviteur, et lui dit: Méchant serviteur, je t''''avais remis en entier ta dette, parce que tu m''''en avais supplié;"}, {"numero": 33, "texto": "ne devais-tu pas aussi avoir pitié de ton compagnon, comme j''''ai eu pitié de toi?"}, {"numero": 34, "texto": "Et son maître, irrité, le livra aux bourreaux, jusqu''''à ce qu''''il eût payé tout ce qu''''il devait."}, {"numero": 35, "texto": "C''''est ainsi que mon Père céleste vous traitera, si chacun de vous ne pardonne à son frère de tout son coeur."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 18, 'es', '[{"numero": 1, "texto": "EN aquel tiempo se llegaron los discípulos á Jesús, diciendo: ¿Quién es el mayor en el reino de los cielos?"}, {"numero": 2, "texto": "Y llamando Jesús á un niño, le puso en medio de ellos,"}, {"numero": 3, "texto": "Y dijo: De cierto os digo, que si no os volviereis, y fuereis como niños, no entraréis en el reino de los cielos."}, {"numero": 4, "texto": "Así que, cualquiera que se humillare como este niño, éste es el mayor en el reino de los cielos."}, {"numero": 5, "texto": "Y cualquiera que recibiere á un tal niño en mi nombre, á mí recibe."}, {"numero": 6, "texto": "Y cualquiera que escandalizare á alguno de estos pequeños que creen en mí, mejor le fuera que se le colgase al cuello una piedra de molino de asno, y que se le anegase en el profundo de la mar."}, {"numero": 7, "texto": "¡Ay del mundo por los escándalos! porque necesario es que vengan escándalos; mas ¡ay de aquel hombre por el cual viene el escándalo!"}, {"numero": 8, "texto": "Por tanto, si tu mano ó tu pie te fuere ocasión de caer, córtalo y échalo de ti: mejor te es entrar cojo ó manco en la vida, que teniendo dos manos ó dos pies ser echado en el fuego eterno."}, {"numero": 9, "texto": "Y si tu ojo te fuere ocasión de caer, sácalo y échalo de ti: mejor te es entrar con un solo ojo en la vida, que teniendo dos ojos ser echado en el infierno del fuego."}, {"numero": 10, "texto": "Mirad no tengáis en poco á alguno de estos pequeños; porque os digo que sus ángeles en los cielos ven siempre la faz de mi Padre que está en los cielos."}, {"numero": 11, "texto": "Porque el Hijo del hombre ha venido para salvar lo que se había perdido."}, {"numero": 12, "texto": "¿Qué os parece? Si tuviese algún hombre cien ovejas, y se descarriase una de ellas, ¿no iría por los montes, dejadas las noventa y nueve, á buscar la que se había descarriado?"}, {"numero": 13, "texto": "Y si aconteciese hallarla, de cierto os digo, que más se goza de aquélla, que de las noventa y nueve que no se descarriaron."}, {"numero": 14, "texto": "Así, no es la voluntad de vuestro Padre que está en los cielos, que se pierda uno de estos pequeños."}, {"numero": 15, "texto": "Por tanto, si tu hermano pecare contra ti, ve, y redargúyele entre ti y él solo: si te oyere, has ganado á tu hermano."}, {"numero": 16, "texto": "Mas si no te oyere, toma aún contigo uno ó dos, para que en boca de dos ó de tres testigos conste toda palabra."}, {"numero": 17, "texto": "Y si no oyere á ellos, dilo á la iglesia: y si no oyere á la iglesia, tenle por étnico y publicano."}, {"numero": 18, "texto": "De cierto os digo que todo lo que ligareis en la tierra, será ligado en el cielo; y todo lo que desatareis en la tierra, será desatado en el cielo."}, {"numero": 19, "texto": "Otra vez os digo, que si dos de vosotros se convinieren en la tierra, de toda cosa que pidieren, les será hecho por mi Padre que está en los cielos."}, {"numero": 20, "texto": "Porque donde están dos ó tres congregados en mi nombre, allí estoy en medio de ellos."}, {"numero": 21, "texto": "Entonces Pedro, llegándose á él, dijo: Señor, ¿cuántas veces perdonaré á mi hermano que pecare contra mí? ¿hasta siete?"}, {"numero": 22, "texto": "Jesús le dice: No te digo hasta siete, mas aun hasta setenta veces siete."}, {"numero": 23, "texto": "Por lo cual, el reino de los cielos es semejante á un hombre rey, que quiso hacer cuentas con sus siervos."}, {"numero": 24, "texto": "Y comenzando á hacer cuentas, le fué presentado uno que le debía diez mil talentos."}, {"numero": 25, "texto": "Mas á éste, no pudiendo pagar, mandó su señor venderle, y á su mujer é hijos, con todo lo que tenía, y que se le pagase."}, {"numero": 26, "texto": "Entonces aquel siervo, postrado, le adoraba, diciendo: Señor, ten paciencia conmigo, y yo te lo pagaré todo."}, {"numero": 27, "texto": "El señor, movido á misericordia de aquel siervo, le soltó y le perdonó la deuda."}, {"numero": 28, "texto": "Y saliendo aquel siervo, halló á uno de sus consiervos, que le debía cien denarios; y trabando de él, le ahogaba, diciendo: Págame lo que debes."}, {"numero": 29, "texto": "Entonces su consiervo, postrándose á sus pies, le rogaba, diciendo: Ten paciencia conmigo, y yo te lo pagaré todo."}, {"numero": 30, "texto": "Mas él no quiso; sino fué, y le echó en la cárcel hasta que pagase la deuda."}, {"numero": 31, "texto": "Y viendo sus consiervos lo que pasaba, se entristecieron mucho, y viniendo, declararon á su señor todo lo que había pasado."}, {"numero": 32, "texto": "Entonces llamándole su señor, le dice: Siervo malvado, toda aquella deuda te perdoné, porque me rogaste:"}, {"numero": 33, "texto": "¿No te convenía también á ti tener misericordia de tu consiervo, como también yo tuve misericordia de ti?"}, {"numero": 34, "texto": "Entonces su señor, enojado, le entregó á los verdugos, hasta que pagase todo lo que le debía."}, {"numero": 35, "texto": "Así también hará con vosotros mi Padre celestial, si no perdonareis de vuestros corazones cada uno á su hermano sus ofensas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 19, 'pt', '[{"numero": 1, "texto": "E aconteceu que, quando Jesus acabou essas palavras, partiu da Galileia, e veio para a região da Judeia, além do Jordão."}, {"numero": 2, "texto": "E muitas multidões o seguiram, e ele os curou ali."}, {"numero": 3, "texto": "Então os fariseus se aproximaram dele e, provando-o, perguntaram-lhe: É lícito ao homem se divorciar da sua mulher por qualquer causa?"}, {"numero": 4, "texto": "Porém ele lhes respondeu: Não tendes lido que aquele que [os] fez no princípio, macho e fêmea os fez,"}, {"numero": 5, "texto": "e disse: Portanto o homem deixará pai e mãe, e se unirá a sua mulher, e os dois serão uma única carne?"}, {"numero": 6, "texto": "Assim eles já não são mais dois, mas sim uma única carne; portanto, o que Deus juntou, o ser humano não separe."}, {"numero": 7, "texto": "Eles lhe disseram: Por que, pois, Moisés mandou [lhe] dar carta de separação, e divorciar-se dela?"}, {"numero": 8, "texto": "[Jesus] lhes disse: Por causa da dureza dos vossos corações Moisés vos permitiu divorciardes de vossas mulheres; mas no princípio não foi assim."}, {"numero": 9, "texto": "Porém eu vos digo que qualquer um que se divorciar de sua mulher, a não ser por causa de pecado sexual, e se casar com outra, adultera; e o que se casar com a divorciada [também] adultera."}, {"numero": 10, "texto": "Os seus discípulos lhe disseram: Se assim é a condição do homem com a mulher, não convém se casar."}, {"numero": 11, "texto": "Porém ele lhes disse: Nem todos recebem esta palavra, a não ser aqueles a quem é dado;"}, {"numero": 12, "texto": "Pois há castrados que nasceram assim do ventre da mãe; e há castrados que foram castrados pelos homens; e há castrados que castraram a si mesmos por causa do Reino dos céus. Quem pode receber [isto] ,receba."}, {"numero": 13, "texto": "Então lhe trouxeram crianças, para que pusesse as mãos sobre elas e orasse, mas os discípulos os repreendiam."}, {"numero": 14, "texto": "Mas Jesus disse: Deixai as crianças, e não as impeçais de vir a mim, porque delas é o Reino dos céus."}, {"numero": 15, "texto": "Ele pôs as mãos sobre elas, e depois partiu-se dali."}, {"numero": 16, "texto": "E eis que alguém se aproximou, e perguntou-lhe: “Bom Mestre, que bem farei para eu ter a vida eterna?”"}, {"numero": 17, "texto": "E ele lhe disse: “Por que me chamas bom? Ninguém há bom, a não ser um: Deus. Porém, se queres entrar na vida, guarda os mandamentos.”"}, {"numero": 18, "texto": "Perguntou-lhe ele: “Quais?” E Jesus respondeu: “Não cometerás homicídio, não adulterarás, não furtarás, não darás falso testemunho;"}, {"numero": 19, "texto": "honra ao teu pai e à [tua] mãe; e amarás ao teu próximo como a ti mesmo.”"}, {"numero": 20, "texto": "O rapaz lhe disse: “Tenho guardado tudo isso desde a minha juventude. Que me falta ainda?”"}, {"numero": 21, "texto": "Disse-lhe Jesus: “Se queres ser completo, vai, vende o que tens, e dá aos pobres. Assim terás um tesouro no céu. Então vem, segue-me.”"}, {"numero": 22, "texto": "Mas quando o rapaz ouviu essa palavra, foi embora triste, porque tinha muitos bens."}, {"numero": 23, "texto": "Jesus, então, disse aos seus discípulos: “Em verdade vos digo que dificilmente um rico entrará no reino dos céus."}, {"numero": 24, "texto": "Aliás, eu vos digo que é mais fácil um camelo passar pela abertura de uma agulha do que o rico entrar no reino de Deus.”"}, {"numero": 25, "texto": "Quando os seus discípulos ouviram [isso] , espantaram-se muito, e disseram: “Quem, pois, pode se salvar?”"}, {"numero": 26, "texto": "Jesus olhou [para eles] ,e lhes respondeu: Para os seres humanos, isto é impossível; mas para Deus tudo é possível."}, {"numero": 27, "texto": "Então Pedro se pôs a falar, e lhe perguntou: Eis que deixamos tudo, e te seguimos; o que, pois, conseguiremos ter?"}, {"numero": 28, "texto": "E Jesus lhes disse: Em verdade vos digo que vós que me seguistes, na regeneração, quando o Filho do homem se sentar no trono de sua glória, vós também vos sentareis sobre doze tronos, para julgar as doze tribos de Israel."}, {"numero": 29, "texto": "E qualquer um que houver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou mulher, ou filhos, ou terras por causa do meu nome, receberá cem vezes tanto, e herdará a vida eterna."}, {"numero": 30, "texto": "Porém muitos primeiros serão últimos; e últimos, primeiros."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 19, 'en', '[{"numero": 1, "texto": "And it came to pass, that when Jesus had finished these sayings, he departed from Galilee, and came into the coasts of Judaea beyond Jordan;"}, {"numero": 2, "texto": "And great multitudes followed him; and he healed them there."}, {"numero": 3, "texto": "The Pharisees also came unto him, tempting him, and saying unto him, Is it lawful for a man to put away his wife for every cause?"}, {"numero": 4, "texto": "And he answered and said unto them, Have ye not read, that he which made them at the beginning made them male and female,"}, {"numero": 5, "texto": "And said, For this cause shall a man leave father and mother, and shall cleave to his wife: and they twain shall be one flesh?"}, {"numero": 6, "texto": "Wherefore they are no more twain, but one flesh. What therefore God hath joined together, let not man put asunder."}, {"numero": 7, "texto": "They say unto him, Why did Moses then command to give a writing of divorcement, and to put her away?"}, {"numero": 8, "texto": "He saith unto them, Moses because of the hardness of your hearts suffered you to put away your wives: but from the beginning it was not so."}, {"numero": 9, "texto": "And I say unto you, Whosoever shall put away his wife, except it be for fornication, and shall marry another, committeth adultery: and whoso marrieth her which is put away doth commit adultery."}, {"numero": 10, "texto": "His disciples say unto him, If the case of the man be so with his wife, it is not good to marry."}, {"numero": 11, "texto": "But he said unto them, All men cannot receive this saying, save they to whom it is given."}, {"numero": 12, "texto": "For there are some eunuchs, which were so born from their mother''s womb: and there are some eunuchs, which were made eunuchs of men: and there be eunuchs, which have made themselves eunuchs for the kingdom of heaven''s sake. He that is able to receive it, let him receive it."}, {"numero": 13, "texto": "Then were there brought unto him little children, that he should put his hands on them, and pray: and the disciples rebuked them."}, {"numero": 14, "texto": "But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven."}, {"numero": 15, "texto": "And he laid his hands on them, and departed thence."}, {"numero": 16, "texto": "And, behold, one came and said unto him, Good Master, what good thing shall I do, that I may have eternal life?"}, {"numero": 17, "texto": "And he said unto him, Why callest thou me good? there is none good but one, that is, God: but if thou wilt enter into life, keep the commandments."}, {"numero": 18, "texto": "He saith unto him, Which? Jesus said, Thou shalt do no murder, Thou shalt not commit adultery, Thou shalt not steal, Thou shalt not bear false witness,"}, {"numero": 19, "texto": "Honour thy father and thy mother: and, Thou shalt love thy neighbour as thyself."}, {"numero": 20, "texto": "The young man saith unto him, All these things have I kept from my youth up: what lack I yet?"}, {"numero": 21, "texto": "Jesus said unto him, If thou wilt be perfect, go and sell that thou hast, and give to the poor, and thou shalt have treasure in heaven: and come and follow me."}, {"numero": 22, "texto": "But when the young man heard that saying, he went away sorrowful: for he had great possessions."}, {"numero": 23, "texto": "Then said Jesus unto his disciples, Verily I say unto you, That a rich man shall hardly enter into the kingdom of heaven."}, {"numero": 24, "texto": "And again I say unto you, It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God."}, {"numero": 25, "texto": "When his disciples heard it, they were exceedingly amazed, saying, Who then can be saved?"}, {"numero": 26, "texto": "But Jesus beheld them, and said unto them, With men this is impossible; but with God all things are possible."}, {"numero": 27, "texto": "Then answered Peter and said unto him, Behold, we have forsaken all, and followed thee; what shall we have therefore?"}, {"numero": 28, "texto": "And Jesus said unto them, Verily I say unto you, That ye which have followed me, in the regeneration when the Son of man shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Israel."}, {"numero": 29, "texto": "And every one that hath forsaken houses, or brethren, or sisters, or father, or mother, or wife, or children, or lands, for my name''s sake, shall receive an hundredfold, and shall inherit everlasting life."}, {"numero": 30, "texto": "But many that are first shall be last; and the last shall be first."}]'::jsonb, 'King James Version'),
  ('Mt', 19, 'fr', '[{"numero": 1, "texto": "Lorsque Jésus eut achevé ces discours, il quitta la Galilée, et alla dans le territoire de la Judée, au delà du Jourdain."}, {"numero": 2, "texto": "Une grande foule le suivit, et là il guérit les malades."}, {"numero": 3, "texto": "Les pharisiens l''''abordèrent, et dirent, pour l''''éprouver: Est-il permis à un homme de répudier sa femme pour un motif quelconque?"}, {"numero": 4, "texto": "Il répondit: N''''avez-vous pas lu que le créateur, au commencement, fit l''''homme et la femme"}, {"numero": 5, "texto": "et qu''''il dit: C''''est pourquoi l''''homme quittera son père et sa mère, et s''''attachera à sa femme, et les deux deviendront une seule chair?"}, {"numero": 6, "texto": "Ainsi ils ne sont plus deux, mais ils sont une seule chair. Que l''''homme donc ne sépare pas ce que Dieu a joint."}, {"numero": 7, "texto": "Pourquoi donc, lui dirent-ils, Moïse a-t-il prescrit de donner à la femme une lettre de divorce et de la répudier?"}, {"numero": 8, "texto": "Il leur répondit: C''''est à cause de la dureté de votre coeur que Moïse vous a permis de répudier vos femmes; au commencement, il n''''en était pas ainsi."}, {"numero": 9, "texto": "Mais je vous dis que celui qui répudie sa femme, sauf pour infidélité, et qui en épouse une autre, commet un adultère."}, {"numero": 10, "texto": "Ses disciples lui dirent: Si telle est la condition de l''''homme à l''''égard de la femme, il n''''est pas avantageux de se marier."}, {"numero": 11, "texto": "Il leur répondit: Tous ne comprennent pas cette parole, mais seulement ceux à qui cela est donné."}, {"numero": 12, "texto": "Car il y a des eunuques qui le sont dès le ventre de leur mère; il y en a qui le sont devenus par les hommes; et il y en a qui se sont rendus tels eux-mêmes, à cause du royaume des cieux. Que celui qui peut comprendre comprenne."}, {"numero": 13, "texto": "Alors on lui amena des petits enfants, afin qu''''il leur imposât les mains et priât pour eux. Mais les disciples les repoussèrent."}, {"numero": 14, "texto": "Et Jésus dit: Laissez les petits enfants, et ne les empêchez pas de venir à moi; car le royaume des cieux est pour ceux qui leur ressemblent."}, {"numero": 15, "texto": "Il leur imposa les mains, et il partit de là."}, {"numero": 16, "texto": "Et voici, un homme s''''approcha, et dit à Jésus: Maître, que dois-je faire de bon pour avoir la vie éternelle?"}, {"numero": 17, "texto": "Il lui répondit: Pourquoi m''''interroges-tu sur ce qui est bon? Un seul est le bon. Si tu veux entrer dans la vie, observe les commandements."}, {"numero": 18, "texto": "Lesquels? lui dit-il. Et Jésus répondit: Tu ne tueras point; tu ne commettras point d''''adultère; tu ne déroberas point; tu ne diras point de faux témoignage;"}, {"numero": 19, "texto": "honore ton père et ta mère; et: tu aimeras ton prochain comme toi-même."}, {"numero": 20, "texto": "Le jeune homme lui dit: J''''ai observé toutes ces choses; que me manque-t-il encore?"}, {"numero": 21, "texto": "Jésus lui dit: Si tu veux être parfait, va, vends ce que tu possèdes, donne-le aux pauvres, et tu auras un trésor dans le ciel. Puis viens, et suis-moi."}, {"numero": 22, "texto": "Après avoir entendu ces paroles, le jeune homme s''''en alla tout triste; car il avait de grands biens."}, {"numero": 23, "texto": "Jésus dit à ses disciples: Je vous le dis en vérité, un riche entrera difficilement dans le royaume des cieux."}, {"numero": 24, "texto": "Je vous le dis encore, il est plus facile à un chameau de passer par le trou d''''une aiguille qu''''à un riche d''''entrer dans le royaume de Dieu."}, {"numero": 25, "texto": "Les disciples, ayant entendu cela, furent très étonnés, et dirent: Qui peut donc être sauvé?"}, {"numero": 26, "texto": "Jésus les regarda, et leur dit: Aux hommes cela est impossible, mais à Dieu tout est possible."}, {"numero": 27, "texto": "Pierre, prenant alors la parole, lui dit: Voici, nous avons tout quitté, et nous t''''avons suivi; qu''''en sera-t-il pour nous?"}, {"numero": 28, "texto": "Jésus leur répondit: Je vous le dis en vérité, quand le Fils de l''''homme, au renouvellement de toutes choses, sera assis sur le trône de sa gloire, vous qui m''''avez suivi, vous serez de même assis sur douze trônes, et vous jugerez les douze tribus d''''Israël."}, {"numero": 29, "texto": "Et quiconque aura quitté, à cause de mon nom, ses frères, ou ses soeurs, ou son père, ou sa mère, ou sa femme, ou ses enfants, ou ses terres, ou ses maisons, recevra le centuple, et héritera la vie éternelle."}, {"numero": 30, "texto": "Plusieurs des premiers seront les derniers, et plusieurs des derniers seront les premiers."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 19, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que acabando Jesús estas palabras, se pasó de Galilea, y vino á los términos de Judea, pasado el Jordán."}, {"numero": 2, "texto": "Y le siguieron muchas gentes, y los sanó allí."}, {"numero": 3, "texto": "Entonces se llegaron á él los Fariseos, tentándole, y diciéndole: ¿Es lícito al hombre repudiar á su mujer por cualquiera causa?"}, {"numero": 4, "texto": "Y él respondiendo, les dijo: ¿No habéis leído que el que los hizo al principio, macho y hembra los hizo,"}, {"numero": 5, "texto": "Y dijo: Por tanto, el hombre dejará padre y madre, y se unirá á su mujer, y serán dos en una carne?"}, {"numero": 6, "texto": "Así que, no son ya más dos, sino una carne: por tanto, lo que Dios juntó, no lo aparte el hombre."}, {"numero": 7, "texto": "Dícenle: ¿Por qué, pues, Moisés mandó dar carta de divorcio, y repudiarla?"}, {"numero": 8, "texto": "Díceles: Por la dureza de vuestro corazón Moisés os permitió repudiar á vuestras mujeres: mas al principio no fué así."}, {"numero": 9, "texto": "Y yo os digo que cualquiera que repudiare á su mujer, si no fuere por causa de fornicación, y se casare con otra, adultera: y el que se casare con la repudiada, adultera."}, {"numero": 10, "texto": "Dícenle sus discípulos: Si así es la condición del hombre con su mujer, no conviene casarse."}, {"numero": 11, "texto": "Entonces él les dijo: No todos reciben esta palabra, sino aquellos á quienes es dado."}, {"numero": 12, "texto": "Porque hay eunucos que nacieron así del vientre de su madre; y hay eunucos, que son hechos eunucos por los hombres; y hay eunucos que se hicieron á sí mismos eunucos por causa del reino de los cielos; el que pueda ser capaz de eso, séalo."}, {"numero": 13, "texto": "Entonces le fueron presentados unos niños, para que pusiese las manos sobre ellos, y orase; y los discípulos les riñeron."}, {"numero": 14, "texto": "Y Jesús dijo: Dejad á los niños, y no les impidáis de venir á mí; porque de los tales es el reino de los cielos."}, {"numero": 15, "texto": "Y habiendo puesto sobre ellos las manos, se partió de allí."}, {"numero": 16, "texto": "Y he aquí, uno llegándose le dijo: Maestro bueno, ¿qué bien haré para tener la vida eterna?"}, {"numero": 17, "texto": "Y él le dijo: ¿Por qué me llamas bueno? Ninguno es bueno sino uno, es á saber, Dios: y si quieres entrar en la vida, guarda los mandamientos."}, {"numero": 18, "texto": "Dícele: ¿Cuáles? Y Jesús dijo: No matarás: No adulterarás: No hurtarás: No dirás falso testimonio:"}, {"numero": 19, "texto": "Honra á tu padre y á tu madre: y, Amarás á tu prójimo como á ti mismo."}, {"numero": 20, "texto": "Dícele el mancebo: Todo esto guardé desde mi juventud: ¿qué más me falta?"}, {"numero": 21, "texto": "Dícele Jesús: Si quieres ser perfecto, anda, vende lo que tienes, y dalo á los pobres, y tendrás tesoro en el cielo; y ven, sígueme."}, {"numero": 22, "texto": "Y oyendo el mancebo esta palabra, se fué triste, porque tenía muchas posesiones."}, {"numero": 23, "texto": "Entonces Jesús dijo á sus discípulos: De cierto os digo, que un rico difícilmente entrará en el reino de los cielos."}, {"numero": 24, "texto": "Mas os digo, que más liviano trabajo es pasar un camello por el ojo de una aguja, que entrar un rico en el reino de Dios."}, {"numero": 25, "texto": "Mas sus discípulos, oyendo estas cosas, se espantaron en gran manera, diciendo: ¿Quién pues podrá ser salvo?"}, {"numero": 26, "texto": "Y mirándolos Jesús, les dijo: Para con los hombres imposible es esto; mas para con Dios todo es posible."}, {"numero": 27, "texto": "Entonces respondiendo Pedro, le dijo: He aquí, nosotros hemos dejado todo, y te hemos seguido: ¿qué pues tendremos?"}, {"numero": 28, "texto": "Y Jesús les dijo: De cierto os digo, que vosotros que me habéis seguido, en la regeneración, cuando se sentará el Hijo del hombre en el trono de su gloria, vosotros también os sentaréis sobre doce tronos, para juzgar á las doce tribus de Israel."}, {"numero": 29, "texto": "Y cualquiera que dejare casas, ó hermanos, ó hermanas, ó padre, ó madre, ó mujer, ó hijos, ó tierras, por mi nombre, recibirá cien veces tanto, y heredará la vida eterna."}, {"numero": 30, "texto": "Mas muchos primeros serán postreros, y postreros primeros."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 20, 'pt', '[{"numero": 1, "texto": "Pois o reino dos céus é semelhante a um homem, dono de propriedade, que saiu de madrugada para empregar trabalhadores para a sua vinha."}, {"numero": 2, "texto": "Ele entrou em acordo com os trabalhadores por um denário ao dia, e os mandou à sua vinha."}, {"numero": 3, "texto": "E quando saiu perto da hora terceira, viu outros que estavam desocupados na praça."}, {"numero": 4, "texto": "Então disse-lhes: “Ide vós também à vinha, e vos darei o que for justo”. E eles foram."}, {"numero": 5, "texto": "Saindo novamente perto da hora sexta e nona, fez o mesmo."}, {"numero": 6, "texto": "E quando saiu perto da décima primeira hora, achou outros que estavam desocupados, e lhes perguntou: “Por que estais aqui o dia todo desocupados?”"}, {"numero": 7, "texto": "Eles lhe disseram: “Porque ninguém nos empregou”. Ele lhes respondeu: “Ide vós também à vinha, e recebereis o que for justo”."}, {"numero": 8, "texto": "E chegando o anoitecer, o senhor da vinha disse ao seu mordomo: “Chama aos trabalhadores, e paga-lhes o salário, começando dos últimos, até os primeiros”."}, {"numero": 9, "texto": "Então vieram os de cerca da hora décima primeira, e receberam um denário cada um."}, {"numero": 10, "texto": "Quando os primeiros vieram, pensavam que receberiam mais; porém eles também receberam um denário cada um."}, {"numero": 11, "texto": "Assim, ao receberem, murmuraram contra o chefe de casa,"}, {"numero": 12, "texto": "dizendo: “Estes últimos trabalharam uma única hora, e tu os igualaste conosco, que suportamos a carga e o calor do dia”."}, {"numero": 13, "texto": "Ele, porém, respondeu a um deles: “Amigo, nada de errado estou fazendo contigo. Não concordaste tu comigo por um denário?"}, {"numero": 14, "texto": "Toma o que é teu, e vai embora; e quero dar a este último tanto quanto a ti."}, {"numero": 15, "texto": "Acaso não me é lícito fazer do que é meu o que eu quiser? Ou o teu olho é mau, porque eu sou bom?”"}, {"numero": 16, "texto": "Assim os últimos serão primeiros; e os primeiros, últimos; pois muitos são chamados, mas poucos escolhidos."}, {"numero": 17, "texto": "E enquanto Jesus subia a Jerusalém, tomou consigo os doze discípulos à parte no caminho, e lhes disse:"}, {"numero": 18, "texto": "Eis que estamos subindo a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes e aos escribas, e o condenarão à morte."}, {"numero": 19, "texto": "E o entregarão aos gentios, para que dele escarneçam, e o açoitem, e crucifiquem; mas ao terceiro dia ressuscitará."}, {"numero": 20, "texto": "Então se aproximou dele a mãe dos filhos de Zebedeu, com os seus filhos. Ela o adorou para lhe pedir algo."}, {"numero": 21, "texto": "E ele lhe perguntou: O que queres? Ela lhe disse: Dá ordem para que estes meus dois filhos se sentem, um à tua direita e outro à tua esquerda, no teu Reino."}, {"numero": 22, "texto": "Porém Jesus respondeu: Não sabeis o que pedis. Podeis vós beber o cálice que eu beberei, e ser batizados com o batismo com que eu sou batizado? Eles lhe disseram: Podemos."}, {"numero": 23, "texto": "E ele lhes disse: De fato meu cálice bebereis, e com o batismo com que eu sou batizado sereis batizados; mas sentar-se à minha direita, e à minha esquerda, não me cabe concedê-lo, mas [será] para os que por meu Pai está preparado."}, {"numero": 24, "texto": "E quando os dez ouviram [isso] ,indignaram-se contra os dois irmãos."}, {"numero": 25, "texto": "Então Jesus os chamou a si, e disse: Vós bem sabeis que os chefes dos gentios os dominam, e os grandes usam de autoridade sobre eles."}, {"numero": 26, "texto": "Mas não será assim entre vós. Ao contrário, quem quiser se tornar grande entre vós seja o vosso assistente;"}, {"numero": 27, "texto": "e quem quiser ser o primeiro entre vós seja o vosso servo;"}, {"numero": 28, "texto": "assim como o Filho do homem não veio para ser servido, mas sim para servir, e para dar a sua vida em resgate por muitos."}, {"numero": 29, "texto": "Quando eles saíram de Jericó, uma grande multidão o seguiu."}, {"numero": 30, "texto": "E eis que dois cegos assentados junto ao caminho, ao ouvirem que Jesus passava, clamaram: Senhor, Filho de Davi, tem misericórdia de nós!"}, {"numero": 31, "texto": "E a multidão os repreendia, para que se calassem, mas eles clamavam ainda mais: Senhor, Filho de Davi, tem misericórdia de nós!"}, {"numero": 32, "texto": "Então Jesus parou, chamou-os, e perguntou: Que quereis que eu vos faça?"}, {"numero": 33, "texto": "Eles lhe responderam: Senhor, que nossos olhos sejam abertos."}, {"numero": 34, "texto": "E Jesus, compadecido deles, tocou-lhes os olhos. E logo os olhos deles enxergaram, e o seguiram."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 20, 'en', '[{"numero": 1, "texto": "For the kingdom of heaven is like unto a man that is an householder, which went out early in the morning to hire labourers into his vineyard."}, {"numero": 2, "texto": "And when he had agreed with the labourers for a penny a day, he sent them into his vineyard."}, {"numero": 3, "texto": "And he went out about the third hour, and saw others standing idle in the marketplace,"}, {"numero": 4, "texto": "And said unto them; Go ye also into the vineyard, and whatsoever is right I will give you. And they went their way."}, {"numero": 5, "texto": "Again he went out about the sixth and ninth hour, and did likewise."}, {"numero": 6, "texto": "And about the eleventh hour he went out, and found others standing idle, and saith unto them, Why stand ye here all the day idle?"}, {"numero": 7, "texto": "They say unto him, Because no man hath hired us. He saith unto them, Go ye also into the vineyard; and whatsoever is right, that shall ye receive."}, {"numero": 8, "texto": "So when even was come, the lord of the vineyard saith unto his steward, Call the labourers, and give them their hire, beginning from the last unto the first."}, {"numero": 9, "texto": "And when they came that were hired about the eleventh hour, they received every man a penny."}, {"numero": 10, "texto": "But when the first came, they supposed that they should have received more; and they likewise received every man a penny."}, {"numero": 11, "texto": "And when they had received it, they murmured against the goodman of the house,"}, {"numero": 12, "texto": "Saying, These last have wrought but one hour, and thou hast made them equal unto us, which have borne the burden and heat of the day."}, {"numero": 13, "texto": "But he answered one of them, and said, Friend, I do thee no wrong: didst not thou agree with me for a penny?"}, {"numero": 14, "texto": "Take that thine is, and go thy way: I will give unto this last, even as unto thee."}, {"numero": 15, "texto": "Is it not lawful for me to do what I will with mine own? Is thine eye evil, because I am good?"}, {"numero": 16, "texto": "So the last shall be first, and the first last: for many be called, but few chosen."}, {"numero": 17, "texto": "And Jesus going up to Jerusalem took the twelve disciples apart in the way, and said unto them,"}, {"numero": 18, "texto": "Behold, we go up to Jerusalem; and the Son of man shall be betrayed unto the chief priests and unto the scribes, and they shall condemn him to death,"}, {"numero": 19, "texto": "And shall deliver him to the Gentiles to mock, and to scourge, and to crucify him: and the third day he shall rise again."}, {"numero": 20, "texto": "Then came to him the mother of Zebedees children with her sons, worshipping him, and desiring a certain thing of him."}, {"numero": 21, "texto": "And he said unto her, What wilt thou? She saith unto him, Grant that these my two sons may sit, the one on thy right hand, and the other on the left, in thy kingdom."}, {"numero": 22, "texto": "But Jesus answered and said, Ye know not what ye ask. Are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with? They say unto him, We are able."}, {"numero": 23, "texto": "And he saith unto them, Ye shall drink indeed of my cup, and be baptized with the baptism that I am baptized with: but to sit on my right hand, and on my left, is not mine to give, but it shall be given to them for whom it is prepared of my Father."}, {"numero": 24, "texto": "And when the ten heard it, they were moved with indignation against the two brethren."}, {"numero": 25, "texto": "But Jesus called them unto him, and said, Ye know that the princes of the Gentiles exercise dominion over them, and they that are great exercise authority upon them."}, {"numero": 26, "texto": "But it shall not be so among you: but whosoever will be great among you, let him be your minister;"}, {"numero": 27, "texto": "And whosoever will be chief among you, let him be your servant:"}, {"numero": 28, "texto": "Even as the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many."}, {"numero": 29, "texto": "And as they departed from Jericho, a great multitude followed him."}, {"numero": 30, "texto": "And, behold, two blind men sitting by the way side, when they heard that Jesus passed by, cried out, saying, Have mercy on us, O Lord, thou son of David."}, {"numero": 31, "texto": "And the multitude rebuked them, because they should hold their peace: but they cried the more, saying, Have mercy on us, O Lord, thou son of David."}, {"numero": 32, "texto": "And Jesus stood still, and called them, and said, What will ye that I shall do unto you?"}, {"numero": 33, "texto": "They say unto him, Lord, that our eyes may be opened."}, {"numero": 34, "texto": "So Jesus had compassion on them, and touched their eyes: and immediately their eyes received sight, and they followed him."}]'::jsonb, 'King James Version'),
  ('Mt', 20, 'fr', '[{"numero": 1, "texto": "Car le royaume des cieux est semblable à un maître de maison qui sortit dès le matin, afin de louer des ouvriers pour sa vigne."}, {"numero": 2, "texto": "Il convint avec eux d''''un denier par jour, et il les envoya à sa vigne."}, {"numero": 3, "texto": "Il sortit vers la troisième heure, et il en vit d''''autres qui étaient sur la place sans rien faire."}, {"numero": 4, "texto": "Il leur dit: Allez aussi à ma vigne, et je vous donnerai ce qui sera raisonnable. Et ils y allèrent."}, {"numero": 5, "texto": "Il sortit de nouveau vers la sixième heure et vers la neuvième, et il fit de même."}, {"numero": 6, "texto": "Etant sorti vers la onzième heure, il en trouva d''''autres qui étaient sur la place, et il leur dit: Pourquoi vous tenez-vous ici toute la journée sans rien faire?"}, {"numero": 7, "texto": "Ils lui répondirent: C''''est que personne ne nous a loués. Allez aussi à ma vigne, leur dit-il."}, {"numero": 8, "texto": "Quand le soir fut venu, le maître de la vigne dit à son intendant: Appelle les ouvriers, et paie-leur le salaire, en allant des derniers aux premiers."}, {"numero": 9, "texto": "Ceux de la onzième heure vinrent, et reçurent chacun un denier."}, {"numero": 10, "texto": "Les premiers vinrent ensuite, croyant recevoir davantage; mais ils reçurent aussi chacun un denier."}, {"numero": 11, "texto": "En le recevant, ils murmurèrent contre le maître de la maison,"}, {"numero": 12, "texto": "et dirent: Ces derniers n''''ont travaillé qu''''une heure, et tu les traites à l''''égal de nous, qui avons supporté la fatigue du jour et la chaleur."}, {"numero": 13, "texto": "Il répondit à l''''un d''''eux: Mon ami, je ne te fais pas tort; n''''es-tu pas convenu avec moi d''''un denier?"}, {"numero": 14, "texto": "Prends ce qui te revient, et va-t''''en. Je veux donner à ce dernier autant qu''''à toi."}, {"numero": 15, "texto": "Ne m''''est-il pas permis de faire de mon bien ce que je veux? Ou vois-tu de mauvais oeil que je sois bon? -"}, {"numero": 16, "texto": "Ainsi les derniers seront les premiers, et les premiers seront les derniers."}, {"numero": 17, "texto": "Pendant que Jésus montait à Jérusalem, il prit à part les douze disciples, et il leur dit en chemin:"}, {"numero": 18, "texto": "Voici, nous montons à Jérusalem, et le Fils de l''''homme sera livré aux principaux sacrificateurs et aux scribes. Ils le condamneront à mort,"}, {"numero": 19, "texto": "et ils le livreront aux païens, pour qu''''ils se moquent de lui, le battent de verges, et le crucifient; et le troisième jour il ressuscitera."}, {"numero": 20, "texto": "Alors la mère des fils de Zébédée s''''approcha de Jésus avec ses fils, et se prosterna, pour lui faire une demande."}, {"numero": 21, "texto": "Il lui dit: Que veux-tu? Ordonne, lui dit-elle, que mes deux fils, que voici, soient assis, dans ton royaume, l''''un à ta droite et l''''autre à ta gauche."}, {"numero": 22, "texto": "Jésus répondit: Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que je dois boire? Nous le pouvons, dirent-ils."}, {"numero": 23, "texto": "Et il leur répondit: Il est vrai que vous boirez ma coupe; mais pour ce qui est d''''être assis à ma droite et à ma gauche, cela ne dépend pas de moi, et ne sera donné qu''''à ceux à qui mon Père l''''a réservé."}, {"numero": 24, "texto": "Les dix, ayant entendu cela, furent indignés contre les deux frères."}, {"numero": 25, "texto": "Jésus les appela, et dit: Vous savez que les chefs des nations les tyrannisent, et que les grands les asservissent."}, {"numero": 26, "texto": "Il n''''en sera pas de même au milieu de vous. Mais quiconque veut être grand parmi vous, qu''''il soit votre serviteur;"}, {"numero": 27, "texto": "et quiconque veut être le premier parmi vous, qu''''il soit votre esclave."}, {"numero": 28, "texto": "C''''est ainsi que le Fils de l''''homme est venu, non pour être servi, mais pour servir et donner sa vie comme la rançon de plusieurs."}, {"numero": 29, "texto": "Lorsqu''''ils sortirent de Jéricho, une grande foule suivit Jésus."}, {"numero": 30, "texto": "Et voici, deux aveugles, assis au bord du chemin, entendirent que Jésus passait, et crièrent: Aie pitié de nous, Seigneur, Fils de David!"}, {"numero": 31, "texto": "La foule les reprenait, pour les faire taire; mais ils crièrent plus fort: Aie pitié de nous, Seigneur, Fils de David!"}, {"numero": 32, "texto": "Jésus s''''arrêta, les appela, et dit: Que voulez-vous que je vous fasse?"}, {"numero": 33, "texto": "Ils lui dirent: Seigneur, que nos yeux s''''ouvrent."}, {"numero": 34, "texto": "Emu de compassion, Jésus toucha leurs yeux; et aussitôt ils recouvrèrent la vue, et le suivirent."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 20, 'es', '[{"numero": 1, "texto": "PORQUE el reino de los cielos es semejante á un hombre, padre de familia, que salió por la mañana á ajustar obreros para su viña."}, {"numero": 2, "texto": "Y habiéndose concertado con los obreros en un denario al día, los envió á su viña."}, {"numero": 3, "texto": "Y saliendo cerca de la hora de las tres, vió otros que estaban en la plaza ociosos;"}, {"numero": 4, "texto": "Y les dijo: Id también vosotros á mi viña, y os daré lo que fuere justo. Y ellos fueron."}, {"numero": 5, "texto": "Salió otra vez cerca de las horas sexta y nona, é hizo lo mismo."}, {"numero": 6, "texto": "Y saliendo cerca de la hora undécima, halló otros que estaban ociosos; y díceles: ¿Por qué estáis aquí todo el día ociosos?"}, {"numero": 7, "texto": "Dícenle: Porque nadie nos ha ajustado. Díceles: Id también vosotros á la viña, y recibiréis lo que fuere justo."}, {"numero": 8, "texto": "Y cuando fué la tarde del día, el señor de la viña dijo á su mayordomo: Llama á los obreros y págales el jornal, comenzando desde los postreros hasta los primeros."}, {"numero": 9, "texto": "Y viniendo los que habían ido cerca de la hora undécima, recibieron cada uno un denario."}, {"numero": 10, "texto": "Y viniendo también los primeros, pensaron que habían de recibir más; pero también ellos recibieron cada uno un denario."}, {"numero": 11, "texto": "Y tomándolo, murmuraban contra el padre de la familia,"}, {"numero": 12, "texto": "Diciendo: Estos postreros sólo han trabajado una hora, y los has hecho iguales á nosotros, que hemos llevado la carga y el calor del día."}, {"numero": 13, "texto": "Y él respondiendo, dijo á uno de ellos: Amigo, no te hago agravio; ¿no te concertaste conmigo por un denario?"}, {"numero": 14, "texto": "Toma lo que es tuyo, y vete; mas quiero dar á este postrero, como á ti."}, {"numero": 15, "texto": "¿No me es lícito á mí hacer lo que quiero con lo mío? ó ¿es malo tu ojo, porque yo soy bueno?"}, {"numero": 16, "texto": "Así los primeros serán postreros, y los postreros primeros: porque muchos son llamados, mas pocos escogidos."}, {"numero": 17, "texto": "Y subiendo Jesús á Jerusalem, tomó sus doce discípulos aparte en el camino, y les dijo:"}, {"numero": 18, "texto": "He aquí subimos á Jerusalem, y el Hijo del hombre será entregado á los príncipes de los sacerdotes y á los escribas, y le condenarán á muerte;"}, {"numero": 19, "texto": "Y le entregarán á los Gentiles para que le escarnezcan, y azoten, y crucifiquen; mas al tercer día resucitará."}, {"numero": 20, "texto": "Entonces se llegó á él la madre de los hijos de Zebedeo con sus hijos, adorándole, y pidiéndole algo."}, {"numero": 21, "texto": "Y él le dijo: ¿Qué quieres? Ella le dijo: Di que se sienten estos dos hijos míos, el uno á tu mano derecha, y el otro á tu izquierda, en tu reino."}, {"numero": 22, "texto": "Entonces Jesús respondiendo, dijo: No sabéis lo que pedís: ¿podéis beber el vaso que yo he de beber, y ser bautizados del bautismo de que yo soy bautizado? Y ellos le dicen: Podemos."}, {"numero": 23, "texto": "Y él les dice: A la verdad mi vaso beberéis, y del bautismo de que yo soy bautizado, seréis bautizados; mas el sentaros á mi mano derecha y á mi izquierda, no es mío darlo, sino á aquellos para quienes está aparejado de mi Padre."}, {"numero": 24, "texto": "Y como los diez oyeron esto, se enojaron de los dos hermanos."}, {"numero": 25, "texto": "Entonces Jesús llamándolos, dijo: Sabéis que los príncipes de los Gentiles se enseñorean sobre ellos, y los que son grandes ejercen sobre ellos potestad."}, {"numero": 26, "texto": "Mas entre vosotros no será así; sino el que quisiere entre vosotros hacerse grande, será vuestro servidor;"}, {"numero": 27, "texto": "Y el que quisiere entre vosotros ser el primero, será vuestro siervo:"}, {"numero": 28, "texto": "Como el Hijo del hombre no vino para ser servido, sino para servir, y para dar su vida en rescate por muchos."}, {"numero": 29, "texto": "Entonces saliendo ellos de Jericó, le seguía gran compañía."}, {"numero": 30, "texto": "Y he aquí dos ciegos sentados junto al camino, como oyeron que Jesús pasaba, clamaron, diciendo: Señor, Hijo de David, ten misericordia de nosotros."}, {"numero": 31, "texto": "Y la gente les reñía para que callasen; mas ellos clamaban más, diciendo: Señor, Hijo de David, ten misericordia de nosotros."}, {"numero": 32, "texto": "Y parándose Jesús, los llamó, y dijo: ¿Qué queréis que haga por vosotros?"}, {"numero": 33, "texto": "Ellos le dicen: Señor, que sean abiertos nuestros ojos."}, {"numero": 34, "texto": "Entonces Jesús, teniendo misericordia de ellos, les tocó los ojos, y luego sus ojos recibieron la vista; y le siguieron."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 21, 'pt', '[{"numero": 1, "texto": "E quando se aproximaram de Jerusalém, e chegaram a Betfagé, ao monte das Oliveiras, então Jesus mandou dois discípulos, dizendo-lhes:"}, {"numero": 2, "texto": "Ide à aldeia em vossa frente, e logo achareis uma jumenta amarrada, e um jumentinho com ela; desamarra-a, e trazei-os a mim."}, {"numero": 3, "texto": "E se alguém vos disser algo, direis: “O Senhor precisa deles, mas logo os devolverá”."}, {"numero": 4, "texto": "Ora, tudo isto aconteceu para que se cumprisse o que foi dito pelo profeta, que disse:"}, {"numero": 5, "texto": "Dizei à filha de Sião: “Eis que o teu rei vem a ti, manso, e sentado sobre um jumento; um jumentinho, filho de uma animal de carga”."}, {"numero": 6, "texto": "Os discípulos foram, e fizeram como Jesus havia lhes mandado;"}, {"numero": 7, "texto": "Então trouxeram a jumenta e o jumentinho, puseram as suas capas sobre eles, e fizeram [-no] montar sobre elas."}, {"numero": 8, "texto": "E uma grande multidão estendia suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho."}, {"numero": 9, "texto": "E as multidões que iam adiante, e as que seguiam, clamavam: Hosana ao Filho de Davi! Bendito o que vem no nome do Senhor! Hosana nas alturas!"}, {"numero": 10, "texto": "Enquanto ele entrava em Jerusalém, toda a cidade se alvoroçou, perguntando: Quem é este?"}, {"numero": 11, "texto": "E as multidões respondiam: Este é Jesus, o Profeta de Nazaré de Galileia."}, {"numero": 12, "texto": "Jesus entrou no Templo de Deus; então expulsou todos os que estavam vendendo e comprando no Templo, e virou as mesas dos cambistas e as cadeiras dos que vendiam pombas."}, {"numero": 13, "texto": "E disse-lhes: Está escrito: “Minha casa será chamada casa de oração”; mas vós a tornastes em covil de ladrões!"}, {"numero": 14, "texto": "E cegos e mancos vieram a ele no Templo, e ele os curou."}, {"numero": 15, "texto": "Quando os chefes dos sacerdotes e os escribas viram as maravilhas que ele fazia, e as crianças gritando no Templo: “Hosana ao Filho de Davi!”, eles ficaram indignados."}, {"numero": 16, "texto": "E perguntaram-lhe: Ouves o que estas [crianças] dizem? E Jesus lhes respondeu: Sim. Nunca lestes: “Da boca das crianças e dos bebês providenciaste o louvor?”"}, {"numero": 17, "texto": "Então ele os deixou, e saiu da cidade para Betânia, e ali passou a noite."}, {"numero": 18, "texto": "E pela manhã, enquanto voltava para a cidade, teve fome."}, {"numero": 19, "texto": "Quando ele viu uma figueira perto do caminho, veio a ela, mas nada nela achou, a não ser somente folhas. E disse-lhe: Nunca de ti nasça fruto, jamais!E imediatamente a figueira se secou."}, {"numero": 20, "texto": "Os discípulos viram, e ficaram maravilhados, dizendo: Como a figueira se secou de imediato?"}, {"numero": 21, "texto": "Porém Jesus lhes respondeu: Em verdade vos digo: se tiverdes fé, e não duvidardes, vós não somente fareis isto à figueira, mas até se disserdes a este monte: “Levanta-te, e lança-te no mar”, isso se fará."}, {"numero": 22, "texto": "E tudo o que pedirdes em oração, crendo, recebereis."}, {"numero": 23, "texto": "Depois de entrar no templo, quando ele estava ensinando, os chefes dos sacerdotes e os anciãos do povo se aproximaram dele, perguntando: Com que autoridade fazes isto? E quem te deu esta autoridade?"}, {"numero": 24, "texto": "Jesus lhes respondeu: Eu também vos farei uma pergunta. Se vós a responderdes a mim, também eu vos responderei com que autoridade faço isto."}, {"numero": 25, "texto": "De onde era o batismo de João? Do céu, ou dos seres humanos?E eles pensaram entre si mesmos, dizendo: Se dissermos: “Do céu”, ele nos dirá: “Por que, então, não crestes nele?"}, {"numero": 26, "texto": "Mas se dissermos: “Dos seres humanos”, temos medo da multidão, pois todos consideram João como profeta."}, {"numero": 27, "texto": "Então responderam a Jesus: Não sabemos. E ele lhes disse: Nem eu vos digo com que autoridade faço isto."}, {"numero": 28, "texto": "Mas que vos parece? Um homem tinha dois filhos. Aproximando-se do primeiro, disse: “Filho, vai hoje trabalhar na minha vinha.”"}, {"numero": 29, "texto": "Porém ele respondeu: “Não quero”; mas depois se arrependeu, e foi."}, {"numero": 30, "texto": "E, aproximando-se do segundo, disse da mesma maneira. E ele respondeu: “Eu [vou] , senhor”, mas não foi."}, {"numero": 31, "texto": "Qual dos dois fez a vontade do pai? Eles lhe responderam: O primeiro. Jesus lhes disse: Em verdade vos digo que os publicanos e as prostitutas estão indo adiante de vós ao Reino de Deus."}, {"numero": 32, "texto": "Pois João veio a vós mesmos no caminho de justiça, mas não crestes nele; enquanto que os publicanos e as prostitutas nele creram. Vós, porém, mesmo tendo visto [isto] , nem assim vos arrependestes, a fim de nele crer."}, {"numero": 33, "texto": "Ouvi outra parábola. Havia um homem, dono de uma propriedade. Ele plantou uma vinha, cercou-a, fundou nela uma prensa de uvas, e construiu uma torre. Depois a arrendou a uns lavradores, e partiu-se para um lugar distante."}, {"numero": 34, "texto": "Quando chegou o tempo dos frutos, enviou seus servos aos lavradores, para receberem os frutos que a ele pertenciam."}, {"numero": 35, "texto": "Mas os lavradores tomaram os seus servos, e feriram um, mataram outro, e apedrejaram outro."}, {"numero": 36, "texto": "Outra vez enviou outros servos, em maior número que os primeiros, mas fizeram-lhes o mesmo."}, {"numero": 37, "texto": "E por último lhes enviou o seu filho, dizendo: “Respeitarão ao meu filho”."}, {"numero": 38, "texto": "Mas quando os lavradores viram o filho, disseram entre si: “Este é o herdeiro. Venhamos matá-lo, e tomemos a sua herança”."}, {"numero": 39, "texto": "Então o agarraram, lançaram-no para fora da vinha, e o mataram."}, {"numero": 40, "texto": "Ora, quando o senhor da vinha chegar, o que fará com aqueles lavradores?"}, {"numero": 41, "texto": "Eles lhe responderam: Aos maus dará uma morte má, e arrendará a vinha a outros lavradores, que lhe deem os frutos em seus tempos [de colheita] ."}, {"numero": 42, "texto": "Jesus lhes disse: Nunca lestes nas Escrituras: “A pedra que os construtores rejeitaram, essa se tornou cabeça da esquina. Isto foi feito pelo Senhor, e é maravilhoso aos nossos olhos”?"}, {"numero": 43, "texto": "Portanto eu vos digo que o reino de Deus será tirado de vós, e será dado a um povo que produza os frutos dele."}, {"numero": 44, "texto": "E quem cair sobre esta pedra será quebrado; mas sobre quem ela cair, ela o tornará em pó."}, {"numero": 45, "texto": "Quando os chefes dos sacerdotes e os fariseus ouviram estas suas parábolas, entenderam que [Jesus] estava falando deles."}, {"numero": 46, "texto": "E procuravam prendê-lo, mas temeram as multidões, pois elas o consideravam profeta."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 21, 'en', '[{"numero": 1, "texto": "And when they drew nigh unto Jerusalem, and were come to Bethphage, unto the mount of Olives, then sent Jesus two disciples,"}, {"numero": 2, "texto": "Saying unto them, Go into the village over against you, and straightway ye shall find an ass tied, and a colt with her: loose them, and bring them unto me."}, {"numero": 3, "texto": "And if any man say ought unto you, ye shall say, The Lord hath need of them; and straightway he will send them."}, {"numero": 4, "texto": "All this was done, that it might be fulfilled which was spoken by the prophet, saying,"}, {"numero": 5, "texto": "Tell ye the daughter of Sion, Behold, thy King cometh unto thee, meek, and sitting upon an ass, and a colt the foal of an ass."}, {"numero": 6, "texto": "And the disciples went, and did as Jesus commanded them,"}, {"numero": 7, "texto": "And brought the ass, and the colt, and put on them their clothes, and they set him thereon."}, {"numero": 8, "texto": "And a very great multitude spread their garments in the way; others cut down branches from the trees, and strawed them in the way."}, {"numero": 9, "texto": "And the multitudes that went before, and that followed, cried, saying, Hosanna to the son of David: Blessed is he that cometh in the name of the Lord; Hosanna in the highest."}, {"numero": 10, "texto": "And when he was come into Jerusalem, all the city was moved, saying, Who is this?"}, {"numero": 11, "texto": "And the multitude said, This is Jesus the prophet of Nazareth of Galilee."}, {"numero": 12, "texto": "And Jesus went into the temple of God, and cast out all them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves,"}, {"numero": 13, "texto": "And said unto them, It is written, My house shall be called the house of prayer; but ye have made it a den of thieves."}, {"numero": 14, "texto": "And the blind and the lame came to him in the temple; and he healed them."}, {"numero": 15, "texto": "And when the chief priests and scribes saw the wonderful things that he did, and the children crying in the temple, and saying, Hosanna to the son of David; they were sore displeased,"}, {"numero": 16, "texto": "And said unto him, Hearest thou what these say? And Jesus saith unto them, Yea; have ye never read, Out of the mouth of babes and sucklings thou hast perfected praise?"}, {"numero": 17, "texto": "And he left them, and went out of the city into Bethany; and he lodged there."}, {"numero": 18, "texto": "Now in the morning as he returned into the city, he hungered."}, {"numero": 19, "texto": "And when he saw a fig tree in the way, he came to it, and found nothing thereon, but leaves only, and said unto it, Let no fruit grow on thee henceforward for ever. And presently the fig tree withered away."}, {"numero": 20, "texto": "And when the disciples saw it, they marvelled, saying, How soon is the fig tree withered away!"}, {"numero": 21, "texto": "Jesus answered and said unto them, Verily I say unto you, If ye have faith, and doubt not, ye shall not only do this which is done to the fig tree, but also if ye shall say unto this mountain, Be thou removed, and be thou cast into the sea; it shall be done."}, {"numero": 22, "texto": "And all things, whatsoever ye shall ask in prayer, believing, ye shall receive."}, {"numero": 23, "texto": "And when he was come into the temple, the chief priests and the elders of the people came unto him as he was teaching, and said, By what authority doest thou these things? and who gave thee this authority?"}, {"numero": 24, "texto": "And Jesus answered and said unto them, I also will ask you one thing, which if ye tell me, I in like wise will tell you by what authority I do these things."}, {"numero": 25, "texto": "The baptism of John, whence was it? from heaven, or of men? And they reasoned with themselves, saying, If we shall say, From heaven; he will say unto us, Why did ye not then believe him?"}, {"numero": 26, "texto": "But if we shall say, Of men; we fear the people; for all hold John as a prophet."}, {"numero": 27, "texto": "And they answered Jesus, and said, We cannot tell. And he said unto them, Neither tell I you by what authority I do these things."}, {"numero": 28, "texto": "But what think ye? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard."}, {"numero": 29, "texto": "He answered and said, I will not: but afterward he repented, and went."}, {"numero": 30, "texto": "And he came to the second, and said likewise. And he answered and said, I go, sir: and went not."}, {"numero": 31, "texto": "Whether of them twain did the will of his father? They say unto him, The first. Jesus saith unto them, Verily I say unto you, That the publicans and the harlots go into the kingdom of God before you."}, {"numero": 32, "texto": "For John came unto you in the way of righteousness, and ye believed him not: but the publicans and the harlots believed him: and ye, when ye had seen it, repented not afterward, that ye might believe him."}, {"numero": 33, "texto": "Hear another parable: There was a certain householder, which planted a vineyard, and hedged it round about, and digged a winepress in it, and built a tower, and let it out to husbandmen, and went into a far country:"}, {"numero": 34, "texto": "And when the time of the fruit drew near, he sent his servants to the husbandmen, that they might receive the fruits of it."}, {"numero": 35, "texto": "And the husbandmen took his servants, and beat one, and killed another, and stoned another."}, {"numero": 36, "texto": "Again, he sent other servants more than the first: and they did unto them likewise."}, {"numero": 37, "texto": "But last of all he sent unto them his son, saying, They will reverence my son."}, {"numero": 38, "texto": "But when the husbandmen saw the son, they said among themselves, This is the heir; come, let us kill him, and let us seize on his inheritance."}, {"numero": 39, "texto": "And they caught him, and cast him out of the vineyard, and slew him."}, {"numero": 40, "texto": "When the lord therefore of the vineyard cometh, what will he do unto those husbandmen?"}, {"numero": 41, "texto": "They say unto him, He will miserably destroy those wicked men, and will let out his vineyard unto other husbandmen, which shall render him the fruits in their seasons."}, {"numero": 42, "texto": "Jesus saith unto them, Did ye never read in the scriptures, The stone which the builders rejected, the same is become the head of the corner: this is the Lord''s doing, and it is marvellous in our eyes?"}, {"numero": 43, "texto": "Therefore say I unto you, The kingdom of God shall be taken from you, and given to a nation bringing forth the fruits thereof."}, {"numero": 44, "texto": "And whosoever shall fall on this stone shall be broken: but on whomsoever it shall fall, it will grind him to powder."}, {"numero": 45, "texto": "And when the chief priests and Pharisees had heard his parables, they perceived that he spake of them."}, {"numero": 46, "texto": "But when they sought to lay hands on him, they feared the multitude, because they took him for a prophet."}]'::jsonb, 'King James Version'),
  ('Mt', 21, 'fr', '[{"numero": 1, "texto": "Lorsqu''''ils approchèrent de Jérusalem, et qu''''ils furent arrivés à Bethphagé, vers la montagne des oliviers, Jésus envoya deux disciples,"}, {"numero": 2, "texto": "en leur disant: Allez au village qui est devant vous; vous trouverez aussitôt une ânesse attachée, et un ânon avec elle; détachez-les, et amenez-les-moi."}, {"numero": 3, "texto": "Si quelqu''''un vous dit quelque chose, vous répondrez: Le Seigneur en a besoin. Et à l''''instant il les laissera aller."}, {"numero": 4, "texto": "Or, ceci arriva afin que s''''accomplît ce qui avait été annoncé par le prophète:"}, {"numero": 5, "texto": "Dites à la fille de Sion: Voici, ton roi vient à toi, Plein de douceur, et monté sur un âne, Sur un ânon, le petit d''''une ânesse."}, {"numero": 6, "texto": "Les disciples allèrent, et firent ce que Jésus leur avait ordonné."}, {"numero": 7, "texto": "Ils amenèrent l''''ânesse et l''''ânon, mirent sur eux leurs vêtements, et le firent asseoir dessus."}, {"numero": 8, "texto": "La plupart des gens de la foule étendirent leurs vêtements sur le chemin; d''''autres coupèrent des branches d''''arbres, et en jonchèrent la route."}, {"numero": 9, "texto": "Ceux qui précédaient et ceux qui suivaient Jésus criaient: Hosanna au Fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna dans les lieux très hauts!"}, {"numero": 10, "texto": "Lorsqu''''il entra dans Jérusalem, toute la ville fut émue, et l''''on disait: Qui est celui-ci?"}, {"numero": 11, "texto": "La foule répondait: C''''est Jésus, le prophète, de Nazareth en Galilée."}, {"numero": 12, "texto": "Jésus entra dans le temple de Dieu. Il chassa tous ceux qui vendaient et qui achetaient dans le temple; il renversa les tables des changeurs, et les sièges des vendeurs de pigeons."}, {"numero": 13, "texto": "Et il leur dit: Il est écrit: Ma maison sera appelée une maison de prière. Mais vous, vous en faites une caverne de voleurs."}, {"numero": 14, "texto": "Des aveugles et des boiteux s''''approchèrent de lui dans le temple. Et il les guérit."}, {"numero": 15, "texto": "Mais les principaux sacrificateurs et les scribes furent indignés, à la vue des choses merveilleuses qu''''il avait faites, et des enfants qui criaient dans le temple: Hosanna au Fils de David!"}, {"numero": 16, "texto": "Ils lui dirent: Entends-tu ce qu''''ils disent? Oui, leur répondit Jésus. N''''avez-vous jamais lu ces paroles: Tu as tiré des louanges de la bouche des enfants et de ceux qui sont à la mamelle?"}, {"numero": 17, "texto": "Et, les ayant laissés, il sortit de la ville pour aller à Béthanie, où il passa la nuit."}, {"numero": 18, "texto": "Le matin, en retournant à la ville, il eut faim."}, {"numero": 19, "texto": "Voyant un figuier sur le chemin, il s''''en approcha; mais il n''''y trouva que des feuilles, et il lui dit: Que jamais fruit ne naisse de toi! Et à l''''instant le figuier sécha."}, {"numero": 20, "texto": "Les disciples, qui virent cela, furent étonnés, et dirent: Comment ce figuier est-il devenu sec en un instant?"}, {"numero": 21, "texto": "Jésus leur répondit: Je vous le dis en vérité, si vous aviez de la foi et que vous ne doutiez point, non seulement vous feriez ce qui a été fait à ce figuier, mais quand vous diriez à cette montagne: Ote-toi de là et jette-toi dans la mer, cela se ferait."}, {"numero": 22, "texto": "Tout ce que vous demanderez avec foi par la prière, vous le recevrez."}, {"numero": 23, "texto": "Jésus se rendit dans le temple, et, pendant qu''''il enseignait, les principaux sacrificateurs et les anciens du peuple vinrent lui dire: Par quelle autorité fais-tu ces choses, et qui t''''a donné cette autorité?"}, {"numero": 24, "texto": "Jésus leur répondit: Je vous adresserai aussi une question; et, si vous m''''y répondez, je vous dirai par quelle autorité je fais ces choses."}, {"numero": 25, "texto": "Le baptême de Jean, d''''où venait-il? du ciel, ou des hommes? Mais ils raisonnèrent ainsi entre eux; Si nous répondons: Du ciel, il nous dira: Pourquoi donc n''''avez-vous pas cru en lui?"}, {"numero": 26, "texto": "Et si nous répondons: Des hommes, nous avons à craindre la foule, car tous tiennent Jean pour un prophète."}, {"numero": 27, "texto": "Alors ils répondirent à Jésus: Nous ne savons. Et il leur dit à son tour: Moi non plus, je ne vous dirai pas par quelle autorité je fais ces choses."}, {"numero": 28, "texto": "Que vous en semble? Un homme avait deux fils; et, s''''adressant au premier, il dit: Mon enfant, va travailler aujourd''''hui dans ma vigne."}, {"numero": 29, "texto": "Il répondit: Je ne veux pas. Ensuite, il se repentit, et il alla."}, {"numero": 30, "texto": "S''''adressant à l''''autre, il dit la même chose. Et ce fils répondit: Je veux bien, seigneur. Et il n''''alla pas."}, {"numero": 31, "texto": "Lequel des deux a fait la volonté du père? Ils répondirent: Le premier. Et Jésus leur dit: Je vous le dis en vérité, les publicains et les prostituées vous devanceront dans le royaume de Dieu."}, {"numero": 32, "texto": "Car Jean est venu à vous dans la voie de la justice, et vous n''''avez pas cru en lui. Mais les publicains et les prostituées ont cru en lui; et vous, qui avez vu cela, vous ne vous êtes pas ensuite repentis pour croire en lui."}, {"numero": 33, "texto": "Ecoutez une autre parabole. Il y avait un homme, maître de maison, qui planta une vigne. Il l''''entoura d''''une haie, y creusa un pressoir, et bâtit une tour; puis il l''''afferma à des vignerons, et quitta le pays."}, {"numero": 34, "texto": "Lorsque le temps de la récolte fut arrivé, il envoya ses serviteurs vers les vignerons, pour recevoir le produit de sa vigne."}, {"numero": 35, "texto": "Les vignerons, s''''étant saisis de ses serviteurs, battirent l''''un, tuèrent l''''autre, et lapidèrent le troisième."}, {"numero": 36, "texto": "Il envoya encore d''''autres serviteurs, en plus grand nombre que les premiers; et les vignerons les traitèrent de la même manière."}, {"numero": 37, "texto": "Enfin, il envoya vers eux son fils, en disant: Ils auront du respect pour mon fils."}, {"numero": 38, "texto": "Mais, quand les vignerons virent le fils, ils dirent entre eux: Voici l''''héritier; venez, tuons-le, et emparons-nous de son héritage."}, {"numero": 39, "texto": "Et ils se saisirent de lui, le jetèrent hors de la vigne, et le tuèrent."}, {"numero": 40, "texto": "Maintenant, lorsque le maître de la vigne viendra, que fera-t-il à ces vignerons?"}, {"numero": 41, "texto": "Ils lui répondirent: Il fera périr misérablement ces misérables, et il affermera la vigne à d''''autres vignerons, qui lui en donneront le produit au temps de la récolte."}, {"numero": 42, "texto": "Jésus leur dit: N''''avez-vous jamais lu dans les Ecritures: La pierre qu''''ont rejetée ceux qui bâtissaient Est devenue la principale de l''''angle; C''''est du Seigneur que cela est venu, Et c''''est un prodige à nos yeux?"}, {"numero": 43, "texto": "C''''est pourquoi, je vous le dis, le royaume de Dieu vous sera enlevé, et sera donné à une nation qui en rendra les fruits."}, {"numero": 44, "texto": "Celui qui tombera sur cette pierre s''''y brisera, et celui sur qui elle tombera sera écrasé."}, {"numero": 45, "texto": "Après avoir entendu ses paraboles, les principaux sacrificateurs et les pharisiens comprirent que c''''était d''''eux que Jésus parlait,"}, {"numero": 46, "texto": "et ils cherchaient à se saisir de lui; mais ils craignaient la foule, parce qu''''elle le tenait pour un prophète."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 21, 'es', '[{"numero": 1, "texto": "Y COMO se acercaron á Jerusalem, y vinieron á Bethfagé, al monte de las Olivas, entonces Jesús envió dos discípulos,"}, {"numero": 2, "texto": "Diciéndoles: Id á la aldea que está delante de vosotros, y luego hallaréis una asna atada, y un pollino con ella: desatadla, y traédmelos."}, {"numero": 3, "texto": "Y si alguno os dijere algo, decid: El Señor los ha menester. Y luego los dejará."}, {"numero": 4, "texto": "Y todo esto fué hecho, para que se cumpliese lo que fué dicho por el profeta, que dijo:"}, {"numero": 5, "texto": "Decid á la hija de Sión: He aquí, tu Rey viene á ti, manso, y sentado sobre una asna, y sobre un pollino, hijo de animal de yugo."}, {"numero": 6, "texto": "Y los discípulos fueron, é hicieron como Jesús les mandó;"}, {"numero": 7, "texto": "Y trajeron el asna y el pollino, y pusieron sobre ellos sus mantos; y se sentó sobre ellos."}, {"numero": 8, "texto": "Y la compañía, que era muy numerosa, tendía sus mantos en el camino: y otros cortaban ramos de los árboles, y los tendían por el camino."}, {"numero": 9, "texto": "Y las gentes que iban delante, y las que iban detrás, aclamaban diciendo: ¡Hosanna al Hijo de David! ¡Bendito el que viene en el nombre del Señor! ¡Hosanna en las alturas!"}, {"numero": 10, "texto": "Y entrando él en Jerusalem, toda la ciudad se alborotó, diciendo: ¿Quién es éste?"}, {"numero": 11, "texto": "Y las gentes decían: Este es Jesús, el profeta, de Nazaret de Galilea."}, {"numero": 12, "texto": "Y entró Jesús en el templo de Dios, y echó fuera todos los que vendían y compraban en el templo, y trastornó las mesas de los cambiadores, y las sillas de los que vendían palomas;"}, {"numero": 13, "texto": "Y les dice: Escrito está: Mi casa, casa de oración será llamada; mas vosotros cueva de ladrones la habéis hecho."}, {"numero": 14, "texto": "Entonces vinieron á él ciegos y cojos en el templo, y los sanó."}, {"numero": 15, "texto": "Mas los príncipes de los sacerdotes y los escribas, viendo las maravillas que hacía, y á los muchachos aclamando en el templo y diciendo: ¡Hosanna al Hijo de David! se indignaron,"}, {"numero": 16, "texto": "Y le dijeron: ¿Oyes lo que éstos dicen? Y Jesús les dice: Sí: ¿nunca leísteis: De la boca de los niños y de los que maman perfeccionaste la alabanza?"}, {"numero": 17, "texto": "Y dejándolos, se salió fuera de la ciudad, á Bethania; y posó allí."}, {"numero": 18, "texto": "Y por la mañana volviendo á la ciudad, tuvo hambre."}, {"numero": 19, "texto": "Y viendo una higuera cerca del camino, vino á ella, y no halló nada en ella, sino hojas solamente; y le dijo: Nunca más para siempre nazca de ti fruto. Y luego se secó la higuera."}, {"numero": 20, "texto": "Y viendo esto los discípulos, maravillados decían: ¿Cómo se secó luego la higuera?"}, {"numero": 21, "texto": "Y respondiendo Jesús les dijo: De cierto os digo, que si tuviereis fe, y no dudareis, no sólo haréis esto de la higuera: mas si á este monte dijereis: Quítate y échate en la mar, será hecho."}, {"numero": 22, "texto": "Y todo lo que pidiereis en oración, creyendo, lo recibiréis."}, {"numero": 23, "texto": "Y como vino al templo, llegáronse á él cuando estaba enseñando, los príncipes de los sacerdotes y los ancianos del pueblo, diciendo: ¿Con qué autoridad haces esto? ¿y quién te dió esta autoridad?"}, {"numero": 24, "texto": "Y respondiendo Jesús, les dijo: Yo también os preguntaré una palabra, la cual si me dijereis, también yo os diré con qué autoridad hago esto."}, {"numero": 25, "texto": "El bautismo de Juan, ¿de dónde era? ¿del cielo, ó de los hombres? Ellos entonces pensaron entre sí, diciendo: Si dijéremos, del cielo, nos dirá: ¿Por qué pues no le creísteis?"}, {"numero": 26, "texto": "Y si dijéremos, de los hombres, tememos al pueblo; porque todos tienen á Juan por profeta."}, {"numero": 27, "texto": "Y respondiendo á Jesús, dijeron: No sabemos. Y él también les dijo: Ni yo os digo con qué autoridad hago esto."}, {"numero": 28, "texto": "Mas, ¿qué os parece? Un hombre tenía dos hijos, y llegando al primero, le dijo: Hijo, ve hoy á trabajar en mi viña."}, {"numero": 29, "texto": "Y respondiendo él, dijo: No quiero; mas después, arrepentido, fué."}, {"numero": 30, "texto": "Y llegando al otro, le dijo de la misma manera; y respondiendo él, dijo: Yo, señor, voy. Y no fué."}, {"numero": 31, "texto": "¿Cuál de los dos hizo la voluntad de su padre? Dicen ellos: El primero. Díceles Jesús: De cierto os digo, que los publicanos y las rameras os van delante al reino de Dios."}, {"numero": 32, "texto": "Porque vino á vosotros Juan en camino de justicia, y no le creísteis; y los publicanos y las rameras le creyeron; y vosotros, viendo esto, no os arrepentisteis después para creerle."}, {"numero": 33, "texto": "Oid otra parábola: Fué un hombre, padre de familia, el cual plantó una viña; y la cercó de vallado, y cavó en ella un lagar, y edificó una torre, y la dió á renta á labradores, y se partió lejos."}, {"numero": 34, "texto": "Y cuando se acercó el tiempo de los frutos, envió sus siervos á los labradores, para que recibiesen sus frutos."}, {"numero": 35, "texto": "Mas los labradores, tomando á los siervos, al uno hirieron, y al otro mataron, y al otro apedrearon."}, {"numero": 36, "texto": "Envió de nuevo otros siervos, más que los primeros; é hicieron con ellos de la misma manera."}, {"numero": 37, "texto": "Y á la postre les envió su hijo, diciendo: Tendrán respeto á mi hijo."}, {"numero": 38, "texto": "Mas los labradores, viendo al hijo, dijeron entre sí: Este es el heredero; venid, matémosle, y tomemos su heredad."}, {"numero": 39, "texto": "Y tomado, le echaron fuera de la viña, y le mataron."}, {"numero": 40, "texto": "Pues cuando viniere el señor de la viña, ¿qué hará á aquellos labradores?"}, {"numero": 41, "texto": "Dícenle: á los malos destruirá miserablemente, y su viña dará á renta á otros labradores, que le paguen el fruto á sus tiempos."}, {"numero": 42, "texto": "Díceles Jesús: ¿Nunca leísteis en las Escrituras: La piedra que desecharon los que edificaban, ésta fué hecha por cabeza de esquina: por el Señor es hecho esto, y es cosa maravillosa en nuestros ojos?"}, {"numero": 43, "texto": "Por tanto os digo, que el reino de Dios será quitado de vosotros, y será dado á gente que haga los frutos de él."}, {"numero": 44, "texto": "Y el que cayere sobre esta piedra, será quebrantado; y sobre quien ella cayere, le desmenuzará."}, {"numero": 45, "texto": "Y oyendo los príncipes de los sacerdotes y los Fariseos sus parábolas, entendieron que hablaba de ellos."}, {"numero": 46, "texto": "Y buscando cómo echarle mano, temieron al pueblo; porque le tenían por profeta."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 22, 'pt', '[{"numero": 1, "texto": "Então Jesus voltou a lhes falar por parábolas, dizendo:"}, {"numero": 2, "texto": "O reino dos céus é semelhante a um rei que fez uma festa de casamento para o seu filho;"}, {"numero": 3, "texto": "e mandou a seus servos que chamassem os convidados para a festa de casamento, mas não quiseram vir."}, {"numero": 4, "texto": "Outra vez ele mandou outros servos, dizendo: “Dizei aos convidados: ‘Eis que já preparei meu jantar: meus bois e animais cevados já foram mortos, e tudo está pronto. Vinde à festa de casamento’”."}, {"numero": 5, "texto": "Porém eles não deram importância e foram embora, um ao seu campo, e outro ao seu comércio;"}, {"numero": 6, "texto": "e outros agarraram os servos dele, e os humilharam e os mataram."}, {"numero": 7, "texto": "Quando o rei Então enviou os seus exércitos, destruiu aqueles homicidas, e incendiou a cidade deles."}, {"numero": 8, "texto": "Em seguida, disse aos seus servos: “Certamente a festa de casamento está pronta, porém os convidados não eram dignos."}, {"numero": 9, "texto": "Ide, pois, às saídas dos caminhos, e convidai à festa de casamento tantos quantos achardes."}, {"numero": 10, "texto": "Aqueles servos saíram pelos caminhos, e ajuntaram todos quantos acharam, tanto maus como bons; e a festa de casamento se encheu de convidados."}, {"numero": 11, "texto": "Mas quando o rei entrou para ver os convidados, percebeu ali um homem que não estava vestido com roupa adequada para a festa de casamento."}, {"numero": 12, "texto": "Então lhe perguntou: “Amigo, como entraste aqui sem ter roupa para a festa?” E ele emudeceu."}, {"numero": 13, "texto": "Então o rei disse aos servos: “Amarrai-o nos pés e nas mãos, tomai-o, e lançai-o nas trevas de fora. Ali haverá pranto e o ranger de dentes”."}, {"numero": 14, "texto": "Pois muitos são chamados, porém poucos escolhidos."}, {"numero": 15, "texto": "Então os fariseus foram embora, e se reuniram para tramar como o apanhariam em cilada por algo que dissesse."}, {"numero": 16, "texto": "Depois lhe enviaram seus discípulos, juntamente com os apoiadores de Herodes, e perguntaram: Mestre, bem sabemos que tu és verdadeiro, e que com verdade ensinas o caminho de Deus, e que não te importas com a opinião de ninguém, porque não dás atenção à aparência humana."}, {"numero": 17, "texto": "Dize-nos, pois, o que te parece: é lícito dar tributo a César, ou não?"}, {"numero": 18, "texto": "Mas Jesus, entendendo a sua malícia, disse: Por que me tentais, hipócritas?"}, {"numero": 19, "texto": "Mostrai-me a moeda do tributo.E eles lhe trouxeram um denário."}, {"numero": 20, "texto": "E ele lhes perguntou: De quem é esta imagem, e a inscrição?"}, {"numero": 21, "texto": "Eles lhe responderam: De César. Então ele lhes disse: Dai, pois, a César o que é de César, e a Deus o que é de Deus."}, {"numero": 22, "texto": "Quando ouviram isso, eles ficaram admirados; então o deixaram e se retiraram."}, {"numero": 23, "texto": "Naquele mesmo dia chegaram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe,"}, {"numero": 24, "texto": "dizendo: Mestre, Moisés disse: Se um homem morrer sem ter filhos, seu irmão se casará com sua mulher, e gerará descendência ao seu irmão."}, {"numero": 25, "texto": "Ora, havia entre nós sete irmãos. O primeiro se casou, e depois morreu; e sem ter tido filhos, deixou sua mulher ao seu irmão."}, {"numero": 26, "texto": "E da mesma maneira também foi com o segundo, o terceiro, até os sete."}, {"numero": 27, "texto": "Por último, depois de todos, a mulher também morreu."}, {"numero": 28, "texto": "Assim, na ressurreição, a mulher será de qual dos sete? Pois todos a tiveram."}, {"numero": 29, "texto": "Jesus, porém, lhes respondeu: Errais, por não conhecerdes as Escrituras, nem o poder de Deus."}, {"numero": 30, "texto": "Porque na ressurreição, nem se tomam, nem se dão em casamento; mas são como os anjos de Deus no céu."}, {"numero": 31, "texto": "E sobre a ressurreição dos mortos, não lestes o que Deus vos falou:"}, {"numero": 32, "texto": "Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó? Deus não é Deus dos mortos, mas sim dos vivos!"}, {"numero": 33, "texto": "Quando as multidões ouviram [isto] ,ficaram admiradas de sua doutrina."}, {"numero": 34, "texto": "E os fariseus, ao ouvirem que ele havia feito os saduceus se calarem, reuniram-se."}, {"numero": 35, "texto": "E um deles, especialista da Lei, tentando-o, perguntou-lhe:"}, {"numero": 36, "texto": "Mestre, qual é o grande mandamento na Lei?"}, {"numero": 37, "texto": "E Jesus lhe respondeu: Amarás ao Senhor teu Deus com todo o teu coração, com toda a tua alma, e com todo o teu entendimento:"}, {"numero": 38, "texto": "este é o primeiro e grande mandamento."}, {"numero": 39, "texto": "E o segundo, semelhante a este, [é] : Amarás o teu próximo como a ti mesmo."}, {"numero": 40, "texto": "Destes dois mandamentos dependem toda a Lei e os Profetas."}, {"numero": 41, "texto": "E, estando os fariseus reunidos, Jesus lhes perguntou,"}, {"numero": 42, "texto": "dizendo: Que pensais vós acerca do Cristo? De quem ele é filho? Eles lhe responderam: De Davi."}, {"numero": 43, "texto": "[Jesus] lhes disse: Como, pois, Davi, em espírito, o chama Senhor, dizendo:"}, {"numero": 44, "texto": "Disse o Senhor a meu Senhor: “Senta-te à minha direita, até que eu ponha os teus inimigos como estrado de teus pés”."}, {"numero": 45, "texto": "Ora, se Davi o chama Senhor, como é seu filho?"}, {"numero": 46, "texto": "E ninguém podia lhe responder palavra; nem ninguém ousou desde aquele dia a mais lhe perguntar."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 22, 'en', '[{"numero": 1, "texto": "And Jesus answered and spake unto them again by parables, and said,"}, {"numero": 2, "texto": "The kingdom of heaven is like unto a certain king, which made a marriage for his son,"}, {"numero": 3, "texto": "And sent forth his servants to call them that were bidden to the wedding: and they would not come."}, {"numero": 4, "texto": "Again, he sent forth other servants, saying, Tell them which are bidden, Behold, I have prepared my dinner: my oxen and my fatlings are killed, and all things are ready: come unto the marriage."}, {"numero": 5, "texto": "But they made light of it, and went their ways, one to his farm, another to his merchandise:"}, {"numero": 6, "texto": "And the remnant took his servants, and entreated them spitefully, and slew them."}, {"numero": 7, "texto": "But when the king heard thereof, he was wroth: and he sent forth his armies, and destroyed those murderers, and burned up their city."}, {"numero": 8, "texto": "Then saith he to his servants, The wedding is ready, but they which were bidden were not worthy."}, {"numero": 9, "texto": "Go ye therefore into the highways, and as many as ye shall find, bid to the marriage."}, {"numero": 10, "texto": "So those servants went out into the highways, and gathered together all as many as they found, both bad and good: and the wedding was furnished with guests."}, {"numero": 11, "texto": "And when the king came in to see the guests, he saw there a man which had not on a wedding garment:"}, {"numero": 12, "texto": "And he saith unto him, Friend, how camest thou in hither not having a wedding garment? And he was speechless."}, {"numero": 13, "texto": "Then said the king to the servants, Bind him hand and foot, and take him away, and cast him into outer darkness, there shall be weeping and gnashing of teeth."}, {"numero": 14, "texto": "For many are called, but few are chosen."}, {"numero": 15, "texto": "Then went the Pharisees, and took counsel how they might entangle him in his talk."}, {"numero": 16, "texto": "And they sent out unto him their disciples with the Herodians, saying, Master, we know that thou art true, and teachest the way of God in truth, neither carest thou for any man: for thou regardest not the person of men."}, {"numero": 17, "texto": "Tell us therefore, What thinkest thou? Is it lawful to give tribute unto Caesar, or not?"}, {"numero": 18, "texto": "But Jesus perceived their wickedness, and said, Why tempt ye me, ye hypocrites?"}, {"numero": 19, "texto": "Shew me the tribute money. And they brought unto him a penny."}, {"numero": 20, "texto": "And he saith unto them, Whose is this image and superscription?"}, {"numero": 21, "texto": "They say unto him, Caesar''s. Then saith he unto them, Render therefore unto Caesar the things which are Caesar''s; and unto God the things that are God''s."}, {"numero": 22, "texto": "When they had heard these words, they marvelled, and left him, and went their way."}, {"numero": 23, "texto": "The same day came to him the Sadducees, which say that there is no resurrection, and asked him,"}, {"numero": 24, "texto": "Saying, Master, Moses said, If a man die, having no children, his brother shall marry his wife, and raise up seed unto his brother."}, {"numero": 25, "texto": "Now there were with us seven brethren: and the first, when he had married a wife, deceased, and, having no issue, left his wife unto his brother:"}, {"numero": 26, "texto": "Likewise the second also, and the third, unto the seventh."}, {"numero": 27, "texto": "And last of all the woman died also."}, {"numero": 28, "texto": "Therefore in the resurrection whose wife shall she be of the seven? for they all had her."}, {"numero": 29, "texto": "Jesus answered and said unto them, Ye do err, not knowing the scriptures, nor the power of God."}, {"numero": 30, "texto": "For in the resurrection they neither marry, nor are given in marriage, but are as the angels of God in heaven."}, {"numero": 31, "texto": "But as touching the resurrection of the dead, have ye not read that which was spoken unto you by God, saying,"}, {"numero": 32, "texto": "I am the God of Abraham, and the God of Isaac, and the God of Jacob? God is not the God of the dead, but of the living."}, {"numero": 33, "texto": "And when the multitude heard this, they were astonished at his doctrine."}, {"numero": 34, "texto": "But when the Pharisees had heard that he had put the Sadducees to silence, they were gathered together."}, {"numero": 35, "texto": "Then one of them, which was a lawyer, asked him a question, tempting him, and saying,"}, {"numero": 36, "texto": "Master, which is the great commandment in the law?"}, {"numero": 37, "texto": "Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind."}, {"numero": 38, "texto": "This is the first and great commandment."}, {"numero": 39, "texto": "And the second is like unto it, Thou shalt love thy neighbour as thyself."}, {"numero": 40, "texto": "On these two commandments hang all the law and the prophets."}, {"numero": 41, "texto": "While the Pharisees were gathered together, Jesus asked them,"}, {"numero": 42, "texto": "Saying, What think ye of Christ? whose son is he? They say unto him, The son of David."}, {"numero": 43, "texto": "He saith unto them, How then doth David in spirit call him Lord, saying,"}, {"numero": 44, "texto": "The Lord said unto my Lord, Sit thou on my right hand, till I make thine enemies thy footstool?"}, {"numero": 45, "texto": "If David then call him Lord, how is he his son?"}, {"numero": 46, "texto": "And no man was able to answer him a word, neither durst any man from that day forth ask him any more questions."}]'::jsonb, 'King James Version'),
  ('Mt', 22, 'fr', '[{"numero": 1, "texto": "Jésus, prenant la parole, leur parla de nouveau en paraboles, et il dit:"}, {"numero": 2, "texto": "Le royaume des cieux est semblable à un roi qui fit des noces pour son fils."}, {"numero": 3, "texto": "Il envoya ses serviteurs appeler ceux qui étaient invités aux noces; mais ils ne voulurent pas venir."}, {"numero": 4, "texto": "Il envoya encore d''''autres serviteurs, en disant: Dites aux conviés: Voici, j''''ai préparé mon festin; mes boeufs et mes bêtes grasses sont tués, tout est prêt, venez aux noces."}, {"numero": 5, "texto": "Mais, sans s''''inquiéter de l''''invitation, ils s''''en allèrent, celui-ci à son champ, celui-là à son trafic;"}, {"numero": 6, "texto": "et les autres se saisirent des serviteurs, les outragèrent et les tuèrent."}, {"numero": 7, "texto": "Le roi fut irrité; il envoya ses troupes, fit périr ces meurtriers, et brûla leur ville."}, {"numero": 8, "texto": "Alors il dit à ses serviteurs: Les noces sont prêtes; mais les conviés n''''en étaient pas dignes."}, {"numero": 9, "texto": "Allez donc dans les carrefours, et appelez aux noces tous ceux que vous trouverez."}, {"numero": 10, "texto": "Ces serviteurs allèrent dans les chemins, rassemblèrent tous ceux qu''''ils trouvèrent, méchants et bons, et la salle des noces fut pleine de convives."}, {"numero": 11, "texto": "Le roi entra pour voir ceux qui étaient à table, et il aperçut là un homme qui n''''avait pas revêtu un habit de noces."}, {"numero": 12, "texto": "Il lui dit: Mon ami, comment es-tu entré ici sans avoir un habit de noces? Cet homme eut la bouche fermée."}, {"numero": 13, "texto": "Alors le roi dit aux serviteurs: Liez-lui les pieds et les mains, et jetez-le dans les ténèbres du dehors, où il y aura des pleurs et des grincements de dents."}, {"numero": 14, "texto": "Car il y a beaucoup d''''appelés, mais peu d''''élus."}, {"numero": 15, "texto": "Alors les pharisiens allèrent se consulter sur les moyens de surprendre Jésus par ses propres paroles."}, {"numero": 16, "texto": "Ils envoyèrent auprès de lui leurs disciples avec les hérodiens, qui dirent: Maître, nous savons que tu es vrai, et que tu enseignes la voie de Dieu selon la vérité, sans t''''inquiéter de personne, car tu ne regardes pas à l''''apparence des hommes."}, {"numero": 17, "texto": "Dis-nous donc ce qu''''il t''''en semble: est-il permis, ou non, de payer le tribut à César?"}, {"numero": 18, "texto": "Jésus, connaissant leur méchanceté, répondit: Pourquoi me tentez-vous, hypocrites?"}, {"numero": 19, "texto": "Montrez-moi la monnaie avec laquelle on paie le tribut. Et ils lui présentèrent un denier."}, {"numero": 20, "texto": "Il leur demanda: De qui sont cette effigie et cette inscription?"}, {"numero": 21, "texto": "De César, lui répondirent-ils. Alors il leur dit: Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu."}, {"numero": 22, "texto": "Etonnés de ce qu''''ils entendaient, ils le quittèrent, et s''''en allèrent."}, {"numero": 23, "texto": "Le même jour, les sadducéens, qui disent qu''''il n''''y a point de résurrection, vinrent auprès de Jésus, et lui firent cette question:"}, {"numero": 24, "texto": "Maître, Moïse a dit: Si quelqu''''un meurt sans enfants, son frère épousera sa veuve, et suscitera une postérité à son frère."}, {"numero": 25, "texto": "Or, il y avait parmi nous sept frères. Le premier se maria, et mourut; et, comme il n''''avait pas d''''enfants, il laissa sa femme à son frère."}, {"numero": 26, "texto": "Il en fut de même du second, puis du troisième, jusqu''''au septième."}, {"numero": 27, "texto": "Après eux tous, la femme mourut aussi."}, {"numero": 28, "texto": "A la résurrection, duquel des sept sera-t-elle donc la femme? Car tous l''''ont eue."}, {"numero": 29, "texto": "Jésus leur répondit: Vous êtes dans l''''erreur, parce que vous ne comprenez ni les Ecritures, ni la puissance de Dieu."}, {"numero": 30, "texto": "Car, à la résurrection, les hommes ne prendront point de femmes, ni les femmes de maris, mais ils seront comme les anges de Dieu dans le ciel."}, {"numero": 31, "texto": "Pour ce qui est de la résurrection des morts, n''''avez-vous pas lu ce que Dieu vous a dit:"}, {"numero": 32, "texto": "Je suis le Dieu d''''Abraham, le Dieu d''''Isaac, et le Dieu de Jacob? Dieu n''''est pas Dieu des morts, mais des vivants."}, {"numero": 33, "texto": "La foule, qui écoutait, fut frappée de l''''enseignement de Jésus."}, {"numero": 34, "texto": "Les pharisiens, ayant appris qu''''il avait réduit au silence les sadducéens, se rassemblèrent,"}, {"numero": 35, "texto": "et l''''un d''''eux, docteur de la loi, lui fit cette question, pour l''''éprouver:"}, {"numero": 36, "texto": "Maître, quel est le plus grand commandement de la loi?"}, {"numero": 37, "texto": "Jésus lui répondit: Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, et de toute ta pensée."}, {"numero": 38, "texto": "C''''est le premier et le plus grand commandement."}, {"numero": 39, "texto": "Et voici le second, qui lui est semblable: Tu aimeras ton prochain comme toi-même."}, {"numero": 40, "texto": "De ces deux commandements dépendent toute la loi et les prophètes."}, {"numero": 41, "texto": "Comme les pharisiens étaient assemblés, Jésus les interrogea,"}, {"numero": 42, "texto": "en disant: Que pensez-vous du Christ? De qui est-il fils? Ils lui répondirent: De David."}, {"numero": 43, "texto": "Et Jésus leur dit: Comment donc David, animé par l''''Esprit, l''''appelle-t-il Seigneur, lorsqu''''il dit:"}, {"numero": 44, "texto": "Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, Jusqu''''à ce que je fasse de tes ennemis ton marchepied?"}, {"numero": 45, "texto": "Si donc David l''''appelle Seigneur, comment est-il son fils?"}, {"numero": 46, "texto": "Nul ne put lui répondre un mot. Et, depuis ce jour, personne n''''osa plus lui proposer des questions."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 22, 'es', '[{"numero": 1, "texto": "Y RESPONDIENDO Jesús, les volvió á hablar en parábolas, diciendo:"}, {"numero": 2, "texto": "El reino de los cielos es semejante á un hombre rey, que hizo bodas á su hijo;"}, {"numero": 3, "texto": "Y envió sus siervos para que llamasen los llamados á las bodas; mas no quisieron venir."}, {"numero": 4, "texto": "Volvió á enviar otros siervos, diciendo: Decid á los llamados: He aquí, mi comida he aparejado; mis toros y animales engordados son muertos, y todo está prevenido: venid á las bodas."}, {"numero": 5, "texto": "Mas ellos no se cuidaron, y se fueron, uno á su labranza, y otro á sus negocios;"}, {"numero": 6, "texto": "Y otros, tomando á sus siervos, los afrentaron y los mataron."}, {"numero": 7, "texto": "Y el rey, oyendo esto, se enojó; y enviando sus ejércitos, destruyó á aquellos homicidas, y puso fuego á su ciudad."}, {"numero": 8, "texto": "Entonces dice á sus siervos: Las bodas á la verdad están aparejadas; mas los que eran llamados no eran dignos."}, {"numero": 9, "texto": "Id pues á las salidas de los caminos, y llamad á las bodas á cuantos hallareis."}, {"numero": 10, "texto": "Y saliendo los siervos por los caminos, juntaron á todos los que hallaron, juntamente malos y buenos: y las bodas fueron llenas de convidados."}, {"numero": 11, "texto": "Y entró el rey para ver los convidados, y vió allí un hombre no vestido de boda."}, {"numero": 12, "texto": "Y le dijo: Amigo, ¿cómo entraste aquí no teniendo vestido de boda? Mas él cerró la boca."}, {"numero": 13, "texto": "Entonces el rey dijo á los que servían: Atado de pies y de manos tomadle, y echadle en las tinieblas de afuera: allí será el lloro y el crujir de dientes."}, {"numero": 14, "texto": "Porque muchos son llamados, y pocos escogidos."}, {"numero": 15, "texto": "Entonces, idos los Fariseos, consultaron cómo le tomarían en alguna palabra."}, {"numero": 16, "texto": "Y envían á él los discípulos de ellos, con los Herodianos, diciendo: Maestro, sabemos que eres amador de la verdad, y que enseñas con verdad el camino de Dios, y que no te curas de nadie, porque no tienes acepción de persona de hombres."}, {"numero": 17, "texto": "Dinos pues, ¿qué te parece? ¿es lícito dar tributo á César, ó no?"}, {"numero": 18, "texto": "Mas Jesús, entendida la malicia de ellos, les dice: ¿Por qué me tentáis, hipócritas?"}, {"numero": 19, "texto": "Mostradme la moneda del tributo. Y ellos le presentaron un denario."}, {"numero": 20, "texto": "Entonces les dice: ¿Cúya es esta figura, y lo que está encima escrito?"}, {"numero": 21, "texto": "Dícenle: De César. Y díceles: Pagad pues á César lo que es de César, y á Dios lo que es de Dios."}, {"numero": 22, "texto": "Y oyendo esto, se maravillaron; y dejándole se fueron."}, {"numero": 23, "texto": "Aquel día llegaron á él los Saduceos, que dicen no haber resurrección, y le preguntaron,"}, {"numero": 24, "texto": "Diciendo: Maestro, Moisés dijo: Si alguno muriere sin hijos, su hermano se casará con su mujer, y despertará simiente á su hermano."}, {"numero": 25, "texto": "Fueron pues, entre nosotros siete hermanos: y el primero tomó mujer, y murió; y no teniendo generación, dejó su mujer á su hermano."}, {"numero": 26, "texto": "De la misma manera también el segundo, y el tercero, hasta los siete."}, {"numero": 27, "texto": "Y después de todos murió también la mujer."}, {"numero": 28, "texto": "En la resurrección pues, ¿de cuál de los siete será ella mujer? porque todos la tuvieron."}, {"numero": 29, "texto": "Entonces respondiendo Jesús, les dijo: Erráis ignorando las Escrituras, y el poder de Dios."}, {"numero": 30, "texto": "Porque en la resurrección, ni los hombres tomarán mujeres, ni las mujeres maridos; mas son como los ángeles de Dios en el cielo."}, {"numero": 31, "texto": "Y de la resurrección de los muertos, ¿no habéis leído lo que os es dicho por Dios, que dice:"}, {"numero": 32, "texto": "Yo soy el Dios de Abraham, y el Dios de Isaac, y el Dios de Jacob? Dios no es Dios de muertos, sino de vivos."}, {"numero": 33, "texto": "Y oyendo esto las gentes, estaban atónitas de su doctrina."}, {"numero": 34, "texto": "Entonces los Fariseos, oyendo que había cerrado la boca á los Saduceos, se juntaron á una."}, {"numero": 35, "texto": "Y preguntó uno de ellos, intérprete de la ley, tentándole y diciendo:"}, {"numero": 36, "texto": "Maestro, ¿cuál es el mandamiento grande en la ley?"}, {"numero": 37, "texto": "Y Jesús le dijo: Amarás al Señor tu Dios de todo tu corazón, y de toda tu alma, y de toda tu mente."}, {"numero": 38, "texto": "Este es el primero y el grande mandamiento."}, {"numero": 39, "texto": "Y el segundo es semejante á éste: Amarás á tu prójimo como á ti mismo."}, {"numero": 40, "texto": "De estos dos mandamientos depende toda la ley y los profetas."}, {"numero": 41, "texto": "Y estando juntos los Fariseos, Jesús les preguntó,"}, {"numero": 42, "texto": "Diciendo: ¿Qué os parece del Cristo? ¿de quién es Hijo? Dícenle: De David."}, {"numero": 43, "texto": "El les dice: ¿Pues cómo David en Espíritu le llama Señor, diciendo:"}, {"numero": 44, "texto": "Dijo el Señor á mi Señor: Siéntate á mi diestra, entre tanto que pongo tus enemigos por estrado de tus pies?"}, {"numero": 45, "texto": "Pues si David le llama Señor, ¿cómo es su Hijo?"}, {"numero": 46, "texto": "Y nadie le podía responder palabra; ni osó alguno desde aquel día preguntarle más."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 23, 'pt', '[{"numero": 1, "texto": "Então Jesus falou às multidões e aos seus discípulos,"}, {"numero": 2, "texto": "dizendo: Os escribas e os fariseus se sentam sobre o assento de Moisés."}, {"numero": 3, "texto": "Portanto, tudo o que eles vos disserem que guardeis, guardai, e fazei. Mas não façais segundo as suas obras, porque eles dizem e não fazem."}, {"numero": 4, "texto": "Pois eles amarram cargas pesadas e difíceis de levar, e as põem sobre os ombros das pessoas; porém eles nem sequer com o seu dedo as querem mover."}, {"numero": 5, "texto": "E fazem todas as suas obras a fim de serem vistos pelas pessoas: por isso alargam seus filactérios, ) e fazem compridas as franjas de suas roupas."}, {"numero": 6, "texto": "Eles amam os primeiros assentos nas ceias, as primeiras cadeiras nas sinagogas,"}, {"numero": 7, "texto": "as saudações nas praças, e serem chamados: “Rabi, Rabi” pelas pessoas."}, {"numero": 8, "texto": "Mas vós, não sejais chamados Rabi, porque o vosso Mestre é um: o Cristo; e todos vós sois irmãos."}, {"numero": 9, "texto": "E não chameis a ninguém na terra vosso pai; porque o vosso Pai é um: aquele que está nos céus."}, {"numero": 10, "texto": "Nem sejais chamados mestres; porque o vosso mestre é um: o Cristo."}, {"numero": 11, "texto": "Porém o maior de vós será vosso servo."}, {"numero": 12, "texto": "E o que a si mesmo se exaltar será humilhado; e o que a si mesmo se humilhar será exaltado."}, {"numero": 13, "texto": "Mas ai de vós, escribas e fariseus, hipócritas! Porque fechais o Reino dos céus em frente das pessoas; pois nem vós entrais, nem permitis a entrada do que estão para entrar."}, {"numero": 14, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque devorais as casas das viúvas, e [isso] com pretexto de longas orações; por isso recebereis mais grave condenação."}, {"numero": 15, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque rodeais o mar e a terra para fazerdes um prosélito; e quando é feito, vós o tornais filho do inferno duas vezes mais que a vós."}, {"numero": 16, "texto": "Ai de vós, guias cegos, que dizeis: “Qualquer um que jurar pelo templo, nada é; mas qualquer um que jurar pelo ouro do templo, devedor é”."}, {"numero": 17, "texto": "Tolos e cegos! Pois qual é maior: o ouro, ou o templo que santifica o ouro?"}, {"numero": 18, "texto": "Também [dizeis] : “Qualquer um que jurar pelo altar, nada é; mas quem jurar pela oferta que [está] sobre ele, devedor é”."}, {"numero": 19, "texto": "Tolos e cegos! Pois qual é maior: a oferta, ou o altar que santifica a oferta?"}, {"numero": 20, "texto": "Portanto, quem jurar pelo altar, jura por ele, e por tudo o que está sobre ele."}, {"numero": 21, "texto": "E quem jurar pelo templo, jura por ele, e por aquele que nele habita."}, {"numero": 22, "texto": "E quem jurar pelo Céu, jura pelo trono de Deus, e por aquele que sobre ele está sentado."}, {"numero": 23, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque dais o dízimo da hortelã, do endro, e do cominho, e desprezais o que é mais importante da Lei: a justiça, a misericórdia, e a fidelidade; estas coisas devem ser feitas, sem se desprezar as outras."}, {"numero": 24, "texto": "Guias cegos, que coais um mosquito, e engolis um camelo!"}, {"numero": 25, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque limpais o exterior do copo ou do prato, mas por dentro estão cheios de extorsão e cobiça."}, {"numero": 26, "texto": "Fariseu cego! Limpa primeiro o interior do copo e do prato, para que também o exterior deles fique limpo."}, {"numero": 27, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque sois semelhantes aos sepulcros caiados, que por fora realmente parecem belos, mas por dentro estão cheios de ossos de cadáveres, e de toda imundícia."}, {"numero": 28, "texto": "Assim também vós, por fora, realmente pareceis justos às pessoas, mas por dentro estais cheios de hipocrisia e de injustiça."}, {"numero": 29, "texto": "Ai de vós, escribas e fariseus, hipócritas! Porque edificais os sepulcros dos profetas, adornais os monumentos dos justos,"}, {"numero": 30, "texto": "e dizeis: “Se estivéssemos nos dias dos nossos pais, nunca teríamos sido cúmplices deles quando derramaram o sangue dos profetas”."}, {"numero": 31, "texto": "Assim vós mesmos dais testemunho de que sois filhos dos que mataram os profetas."}, {"numero": 32, "texto": "Completai, pois, a medida de vossos pais."}, {"numero": 33, "texto": "Serpentes, ninhada de víboras! Como escapareis da condenação do inferno?"}, {"numero": 34, "texto": "Por isso, eis que eu vos envio profetas, sábios, e escribas; a uns deles matareis e crucificareis, e a [outros] deles açoitareis em vossas sinagogas, e perseguireis de cidade em cidade;"}, {"numero": 35, "texto": "para que venha sobre vós todo o sangue justo que foi derramado sobre a terra, desde o sangue do justo Abel, até o sangue de Zacarias, filho de Baraquias, ao qual matastes entre o templo e o altar."}, {"numero": 36, "texto": "Em verdade vos digo que tudo isto virá sobre esta geração."}, {"numero": 37, "texto": "Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que te são enviados! Quantas vezes eu quis ajuntar os teus filhos, como a galinha ajunta os seus pintos debaixo das asas; porém não quisestes!"}, {"numero": 38, "texto": "Eis que vossa casa vos será deixada desolada."}, {"numero": 39, "texto": "Pois eu vos digo que a partir de agora não me vereis, até que digais: “Bendito aquele que vem no nome do Senhor”."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 23, 'en', '[{"numero": 1, "texto": "Then spake Jesus to the multitude, and to his disciples,"}, {"numero": 2, "texto": "Saying The scribes and the Pharisees sit in Moses'' seat:"}, {"numero": 3, "texto": "All therefore whatsoever they bid you observe, that observe and do; but do not ye after their works: for they say, and do not."}, {"numero": 4, "texto": "For they bind heavy burdens and grievous to be borne, and lay them on men''s shoulders; but they themselves will not move them with one of their fingers."}, {"numero": 5, "texto": "But all their works they do for to be seen of men: they make broad their phylacteries, and enlarge the borders of their garments,"}, {"numero": 6, "texto": "And love the uppermost rooms at feasts, and the chief seats in the synagogues,"}, {"numero": 7, "texto": "And greetings in the markets, and to be called of men, Rabbi, Rabbi."}, {"numero": 8, "texto": "But be not ye called Rabbi: for one is your Master, even Christ; and all ye are brethren."}, {"numero": 9, "texto": "And call no man your father upon the earth: for one is your Father, which is in heaven."}, {"numero": 10, "texto": "Neither be ye called masters: for one is your Master, even Christ."}, {"numero": 11, "texto": "But he that is greatest among you shall be your servant."}, {"numero": 12, "texto": "And whosoever shall exalt himself shall be abased; and he that shall humble himself shall be exalted."}, {"numero": 13, "texto": "But woe unto you, scribes and Pharisees, hypocrites! for ye shut up the kingdom of heaven against men: for ye neither go in yourselves, neither suffer ye them that are entering to go in."}, {"numero": 14, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye devour widows'' houses, and for a pretence make long prayer: therefore ye shall receive the greater damnation."}, {"numero": 15, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye compass sea and land to make one proselyte, and when he is made, ye make him twofold more the child of hell than yourselves."}, {"numero": 16, "texto": "Woe unto you, ye blind guides, which say, Whosoever shall swear by the temple, it is nothing; but whosoever shall swear by the gold of the temple, he is a debtor!"}, {"numero": 17, "texto": "Ye fools and blind: for whether is greater, the gold, or the temple that sanctifieth the gold?"}, {"numero": 18, "texto": "And, Whosoever shall swear by the altar, it is nothing; but whosoever sweareth by the gift that is upon it, he is guilty."}, {"numero": 19, "texto": "Ye fools and blind: for whether is greater, the gift, or the altar that sanctifieth the gift?"}, {"numero": 20, "texto": "Whoso therefore shall swear by the altar, sweareth by it, and by all things thereon."}, {"numero": 21, "texto": "And whoso shall swear by the temple, sweareth by it, and by him that dwelleth therein."}, {"numero": 22, "texto": "And he that shall swear by heaven, sweareth by the throne of God, and by him that sitteth thereon."}, {"numero": 23, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye pay tithe of mint and anise and cummin, and have omitted the weightier matters of the law, judgment, mercy, and faith: these ought ye to have done, and not to leave the other undone."}, {"numero": 24, "texto": "Ye blind guides, which strain at a gnat, and swallow a camel."}, {"numero": 25, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye make clean the outside of the cup and of the platter, but within they are full of extortion and excess."}, {"numero": 26, "texto": "Thou blind Pharisee, cleanse first that which is within the cup and platter, that the outside of them may be clean also."}, {"numero": 27, "texto": "Woe unto you, scribes and Pharisees, hypocrites! for ye are like unto whited sepulchres, which indeed appear beautiful outward, but are within full of dead men''s bones, and of all uncleanness."}, {"numero": 28, "texto": "Even so ye also outwardly appear righteous unto men, but within ye are full of hypocrisy and iniquity."}, {"numero": 29, "texto": "Woe unto you, scribes and Pharisees, hypocrites! because ye build the tombs of the prophets, and garnish the sepulchres of the righteous,"}, {"numero": 30, "texto": "And say, If we had been in the days of our fathers, we would not have been partakers with them in the blood of the prophets."}, {"numero": 31, "texto": "Wherefore ye be witnesses unto yourselves, that ye are the children of them which killed the prophets."}, {"numero": 32, "texto": "Fill ye up then the measure of your fathers."}, {"numero": 33, "texto": "Ye serpents, ye generation of vipers, how can ye escape the damnation of hell?"}, {"numero": 34, "texto": "Wherefore, behold, I send unto you prophets, and wise men, and scribes: and some of them ye shall kill and crucify; and some of them shall ye scourge in your synagogues, and persecute them from city to city:"}, {"numero": 35, "texto": "That upon you may come all the righteous blood shed upon the earth, from the blood of righteous Abel unto the blood of Zacharias son of Barachias, whom ye slew between the temple and the altar."}, {"numero": 36, "texto": "Verily I say unto you, All these things shall come upon this generation."}, {"numero": 37, "texto": "O Jerusalem, Jerusalem, thou that killest the prophets, and stonest them which are sent unto thee, how often would I have gathered thy children together, even as a hen gathereth her chickens under her wings, and ye would not!"}, {"numero": 38, "texto": "Behold, your house is left unto you desolate."}, {"numero": 39, "texto": "For I say unto you, Ye shall not see me henceforth, till ye shall say, Blessed is he that cometh in the name of the Lord."}]'::jsonb, 'King James Version'),
  ('Mt', 23, 'fr', '[{"numero": 1, "texto": "Alors Jésus, parlant à la foule et à ses disciples,"}, {"numero": 2, "texto": "dit: Les scribes et les pharisiens sont assis dans la chaire de Moïse."}, {"numero": 3, "texto": "Faites donc et observez tout ce qu''''ils vous disent; mais n''''agissez pas selon leurs oeuvres. Car ils disent, et ne font pas."}, {"numero": 4, "texto": "Ils lient des fardeaux pesants, et les mettent sur les épaules des hommes, mais ils ne veulent pas les remuer du doigt."}, {"numero": 5, "texto": "Ils font toutes leurs actions pour être vus des hommes. Ainsi, ils portent de larges phylactères, et ils ont de longues franges à leurs vêtements;"}, {"numero": 6, "texto": "ils aiment la première place dans les festins, et les premiers sièges dans les synagogues;"}, {"numero": 7, "texto": "ils aiment à être salués dans les places publiques, et à être appelés par les hommes Rabbi, Rabbi."}, {"numero": 8, "texto": "Mais vous, ne vous faites pas appeler Rabbi; car un seul est votre Maître, et vous êtes tous frères."}, {"numero": 9, "texto": "Et n''''appelez personne sur la terre votre père; car un seul est votre Père, celui qui est dans les cieux."}, {"numero": 10, "texto": "Ne vous faites pas appeler directeurs; car un seul est votre Directeur, le Christ."}, {"numero": 11, "texto": "Le plus grand parmi vous sera votre serviteur."}, {"numero": 12, "texto": "Quiconque s''''élèvera sera abaissé, et quiconque s''''abaissera sera élevé."}, {"numero": 13, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous fermez aux hommes le royaume des cieux; vous n''''y entrez pas vous-mêmes, et vous n''''y laissez pas entrer ceux qui veulent entrer."}, {"numero": 14, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous dévorez les maisons des veuves, et que vous faites pour l''''apparence de longues prières; à cause de cela, vous serez jugés plus sévèrement."}, {"numero": 15, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous courez la mer et la terre pour faire un prosélyte; et, quand il l''''est devenu, vous en faites un fils de la géhenne deux fois plus que vous."}, {"numero": 16, "texto": "Malheur à vous, conducteurs aveugles! qui dites: Si quelqu''''un jure par le temple, ce n''''est rien; mais, si quelqu''''un jure par l''''or du temple, il est engagé."}, {"numero": 17, "texto": "Insensés et aveugles! lequel est le plus grand, l''''or, ou le temple qui sanctifie l''''or?"}, {"numero": 18, "texto": "Si quelqu''''un, dites-vous encore, jure par l''''autel, ce n''''est rien; mais, si quelqu''''un jure par l''''offrande qui est sur l''''autel, il est engagé."}, {"numero": 19, "texto": "Aveugles! lequel est le plus grand, l''''offrande, ou l''''autel qui sanctifie l''''offrande?"}, {"numero": 20, "texto": "Celui qui jure par l''''autel jure par l''''autel et par tout ce qui est dessus;"}, {"numero": 21, "texto": "celui qui jure par le temple jure par le temple et par celui qui l''''habite;"}, {"numero": 22, "texto": "et celui qui jure par le ciel jure par le trône de Dieu et par celui qui y est assis."}, {"numero": 23, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous payez la dîme de la menthe, de l''''aneth et du cumin, et que vous laissez ce qui est plus important dans la loi, la justice, la miséricorde et la fidélité: c''''est là ce qu''''il fallait pratiquer, sans négliger les autres choses."}, {"numero": 24, "texto": "Conducteurs aveugles! qui coulez le moucheron, et qui avalez le chameau."}, {"numero": 25, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous nettoyez le dehors de la coupe et du plat, et qu''''au dedans ils sont pleins de rapine et d''''intempérance."}, {"numero": 26, "texto": "Pharisien aveugle! nettoie premièrement l''''intérieur de la coupe et du plat, afin que l''''extérieur aussi devienne net."}, {"numero": 27, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous ressemblez à des sépulcres blanchis, qui paraissent beaux au dehors, et qui, au dedans, sont pleins d''''ossements de morts et de toute espèce d''''impuretés."}, {"numero": 28, "texto": "Vous de même, au dehors, vous paraissez justes aux hommes, mais, au dedans, vous êtes pleins d''''hypocrisie et d''''iniquité."}, {"numero": 29, "texto": "Malheur à vous, scribes et pharisiens hypocrites! parce que vous bâtissez les tombeaux des prophètes et ornez les sépulcres des justes,"}, {"numero": 30, "texto": "et que vous dites: Si nous avions vécu du temps de nos pères, nous ne nous serions pas joints à eux pour répandre le sang des prophètes."}, {"numero": 31, "texto": "Vous témoignez ainsi contre vous-mêmes que vous êtes les fils de ceux qui ont tué les prophètes."}, {"numero": 32, "texto": "Comblez donc la mesure de vos pères."}, {"numero": 33, "texto": "Serpents, race de vipères! comment échapperez-vous au châtiment de la géhenne?"}, {"numero": 34, "texto": "C''''est pourquoi, voici, je vous envoie des prophètes, des sages et des scribes. Vous tuerez et crucifierez les uns, vous battrez de verges les autres dans vos synagogues, et vous les persécuterez de ville en ville,"}, {"numero": 35, "texto": "afin que retombe sur vous tout le sang innocent répandu sur la terre, depuis le sang d''''Abel le juste jusqu''''au sang de Zacharie, fils de Barachie, que vous avez tué entre le temple et l''''autel."}, {"numero": 36, "texto": "Je vous le dis en vérité, tout cela retombera sur cette génération."}, {"numero": 37, "texto": "Jérusalem, Jérusalem, qui tues les prophètes et qui lapides ceux qui te sont envoyés, combien de fois ai-je voulu rassembler tes enfants, comme une poule rassemble ses poussins sous ses ailes, et vous ne l''''avez pas voulu!"}, {"numero": 38, "texto": "Voici, votre maison vous sera laissée déserte;"}, {"numero": 39, "texto": "car, je vous le dis, vous ne me verrez plus désormais, jusqu''''à ce que vous disiez: Béni soit celui qui vient au nom du Seigneur!"}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 23, 'es', '[{"numero": 1, "texto": "ENTONCES habló Jesús á las gentes y á sus discípulos,"}, {"numero": 2, "texto": "Diciendo: Sobre la cátedra de Moisés se sentaron los escribas y los Fariseos:"}, {"numero": 3, "texto": "Así que, todo lo que os dijeren que guardéis, guardadlo y hacedlo; mas no hagáis conforme á sus obras: porque dicen, y no hacen."}, {"numero": 4, "texto": "Porque atan cargas pesadas y difíciles de llevar, y las ponen sobre los hombros de los hombres; mas ni aun con su dedo las quieren mover."}, {"numero": 5, "texto": "Antes, todas sus obras hacen para ser mirados de los hombres; porque ensanchan sus filacterias, y extienden los flecos de sus mantos;"}, {"numero": 6, "texto": "Y aman los primeros asientos en las cenas, y las primeras sillas en las sinagogas;"}, {"numero": 7, "texto": "Y las salutaciones en las plazas, y ser llamados de los hombres Rabbí, Rabbí."}, {"numero": 8, "texto": "Mas vosotros, no queráis ser llamados Rabbí; porque uno es vuestro Maestro, el Cristo; y todos vosotros sois hermanos."}, {"numero": 9, "texto": "Y vuestro padre no llaméis á nadie en la tierra; porque uno es vuestro Padre, el cual está en los cielos."}, {"numero": 10, "texto": "Ni seáis llamados maestros; porque uno es vuestro Maestro, el Cristo."}, {"numero": 11, "texto": "El que es el mayor de vosotros, sea vuestro siervo."}, {"numero": 12, "texto": "Porque el que se ensalzare, será humillado; y el que se humillare, será ensalzado."}, {"numero": 13, "texto": "Mas ¡ay de vosotros, escribas y Fariseos, hipócritas! porque cerráis el reino de los cielos delante de los hombres; que ni vosotros entráis, ni á los que están entrando dejáis entrar."}, {"numero": 14, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque coméis las casas de las viudas, y por pretexto hacéis larga oración: por esto llevaréis más grave juicio."}, {"numero": 15, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque rodeáis la mar y la tierra por hacer un prosélito; y cuando fuere hecho, le hacéis hijo del infierno doble más que vosotros."}, {"numero": 16, "texto": "¡Ay de vosotros, guías ciegos! que decís: Cualquiera que jurare por el templo es nada; mas cualquiera que jurare por el oro del templo, deudor es."}, {"numero": 17, "texto": "¡Insensatos y ciegos! porque ¿cuál es mayor, el oro, ó el templo que santifica al oro?"}, {"numero": 18, "texto": "Y: Cualquiera que jurare por el altar, es nada; mas cualquiera que jurare por el presente que está sobre él, deudor es."}, {"numero": 19, "texto": "¡Necios y ciegos! porque, ¿cuál es mayor, el presente, ó el altar que santifica al presente?"}, {"numero": 20, "texto": "Pues el que jurare por el altar, jura por él, y por todo lo que está sobre él;"}, {"numero": 21, "texto": "Y el que jurare por el templo, jura por él, y por Aquél que habita en él;"}, {"numero": 22, "texto": "Y el que jura por el cielo, jura por el trono de Dios, y por Aquél que está sentado sobre él."}, {"numero": 23, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque diezmáis la menta y el eneldo y el comino, y dejasteis lo que es lo más grave de la ley, es á saber, el juicio y la misericordia y la fe: esto era menester hacer, y no dejar lo otro."}, {"numero": 24, "texto": "¡Guías ciegos, que coláis el mosquito, mas tragáis el camello!"}, {"numero": 25, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque limpiáis lo que está de fuera del vaso y del plato; mas de dentro están llenos de robo y de injusticia."}, {"numero": 26, "texto": "¡Fariseo ciego, limpia primero lo de dentro del vaso y del plato, para que también lo de fuera se haga limpio!"}, {"numero": 27, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque sois semejantes á sepulcros blanqueados, que de fuera, á la verdad, se muestran hermosos, mas de dentro están llenos de huesos de muertos y de toda suciedad."}, {"numero": 28, "texto": "Así también vosotros de fuera, á la verdad, os mostráis justos á los hombres; mas de dentro, llenos estáis de hipocresía é iniquidad."}, {"numero": 29, "texto": "¡Ay de vosotros, escribas y Fariseos, hipócritas! porque edificáis los sepulcros de los profetas, y adornáis los monumentos de los justos,"}, {"numero": 30, "texto": "Y decís: Si fuéramos en los días de nuestros padres, no hubiéramos sido sus compañeros en la sangre de los profetas."}, {"numero": 31, "texto": "Así que, testimonio dais á vosotros mismos, que sois hijos de aquellos que mataron á los profetas."}, {"numero": 32, "texto": "¡Vosotros también henchid la medida de vuestros padres!"}, {"numero": 33, "texto": "¡Serpientes, generación de víboras! ¿cómo evitaréis el juicio del infierno?"}, {"numero": 34, "texto": "Por tanto, he aquí, yo envío á vosotros profetas, y sabios, y escribas: y de ellos, á unos mataréis y crucificaréis, y á otros de ellos azotaréis en vuestras sinagogas, y perseguiréis de ciudad en ciudad:"}, {"numero": 35, "texto": "Para que venga sobre vosotros toda la sangre justa que se ha derramado sobre la tierra, desde la sangre de Abel el justo, hasta la sangre de Zacarías, hijo de Barachîas, al cual matasteis entre el templo y el altar."}, {"numero": 36, "texto": "De cierto os digo que todo esto vendrá sobre esta generación."}, {"numero": 37, "texto": "¡Jerusalem, Jerusalem, que matas á los profetas, y apedreas á los que son enviados á ti! ¡cuántas veces quise juntar tus hijos, como la gallina junta sus pollos debajo de las alas, y no quisiste!"}, {"numero": 38, "texto": "He aquí vuestra casa os es dejada desierta."}, {"numero": 39, "texto": "Porque os digo que desde ahora no me veréis, hasta que digáis: Bendito el que viene en el nombre del Señor."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 24, 'pt', '[{"numero": 1, "texto": "Jesus saiu do templo, e se foi. Então seus discípulos se aproximaram dele para lhe mostrarem os edifícios do complexo do templo."}, {"numero": 2, "texto": "Mas Jesus lhes disse: Não vedes tudo isto? Em verdade vos digo, que não será deixada aqui pedra sobre pedra, que não seja derrubada."}, {"numero": 3, "texto": "E, depois de se assentar no monte das Oliveiras, os discípulos se aproximaram dele reservadamente, perguntando: Dize-nos, quando serão estas coisas, e que sinal haverá da tua vinda, e do fim da era?"}, {"numero": 4, "texto": "E Jesus lhes respondeu: Permanecei atentos, para que ninguém vos engane."}, {"numero": 5, "texto": "Porque muitos virão em meu nome, dizendo: “Eu sou o Cristo”, e enganarão a muitos."}, {"numero": 6, "texto": "E ouvireis de guerras, e de rumores de guerras. Olhai que não vos espanteis; porque é necessário, que tudo [isto] aconteça, mas ainda não é o fim."}, {"numero": 7, "texto": "Pois se levantará nação contra nação, e reino contra reino; e haverá fomes, pestilências, e terremotos em diversos lugares."}, {"numero": 8, "texto": "Mas todas estas coisas são o começo das dores."}, {"numero": 9, "texto": "Então vos entregarão para serdes afligidos, e vos matarão; e sereis odiados por todas as nações, por causa do meu nome."}, {"numero": 10, "texto": "E muitos tropeçarão na fé; e trairão uns aos outros, e uns aos outros se odiarão."}, {"numero": 11, "texto": "E muitos falsos profetas se levantarão, e enganarão a muitos."}, {"numero": 12, "texto": "E, por se multiplicar a injustiça, o amor de muitos se esfriará."}, {"numero": 13, "texto": "Mas o que perseverar até o fim, esse será salvo."}, {"numero": 14, "texto": "E este Evangelho do Reino será pregado em todo o mundo, como testemunho a todas as nações, e então virá o fim."}, {"numero": 15, "texto": "Portanto, quando virdes que a abominação da desolação, dita pelo profeta Daniel, está no lugar santo, (quem lê, entenda),"}, {"numero": 16, "texto": "então os que estiveram na Judeia fujam para os montes;"}, {"numero": 17, "texto": "o que estiver no sobre o telhado não desça para tirar alguma coisa de sua casa;"}, {"numero": 18, "texto": "e o que estiver no campo não volte atrás para tomar as suas roupas."}, {"numero": 19, "texto": "Mas ai das grávidas e das que amamentarem naqueles dias!"}, {"numero": 20, "texto": "Orai, porém, para que a vossa fuga não aconteça no inverno, nem no sábado."}, {"numero": 21, "texto": "Pois haverá então grande aflição, como nunca houve desde o princípio do mundo até agora, nem jamais haverá."}, {"numero": 22, "texto": "E se aqueles dias não fossem encurtados, ninguém se salvaria; mas por causa dos escolhidos, aqueles dias serão encurtados."}, {"numero": 23, "texto": "Então, se alguém vos disser: “Olha o Cristo aqui”, ou “ [Olha ele] ali”, não creiais,"}, {"numero": 24, "texto": "pois se levantarão falsos cristos e falsos profetas; e farão tão grandes sinais e prodígios que, se fosse possível, enganariam até os escolhidos."}, {"numero": 25, "texto": "Eis que eu tenho vos dito com antecedência."}, {"numero": 26, "texto": "Portanto, se vos disserem: “Eis que ele está no deserto”, não saiais; “Eis que ele está em um recinto”, não creiais."}, {"numero": 27, "texto": "Porque, assim como o relâmpago, que sai do oriente, e aparece até o ocidente, assim também será a vinda do Filho do homem."}, {"numero": 28, "texto": "Pois onde estiver o cadáver, ali se ajuntarão os abutres."}, {"numero": 29, "texto": "E logo depois da aflição daqueles dias, o sol se escurecerá, a lua não dará o seu brilho, as estrelas cairão do céu, e as forças dos céus se estremecerão."}, {"numero": 30, "texto": "Então aparecerá no céu o sinal do Filho do homem. Naquela hora todas as tribos da terra lamentarão, e verão ao Filho do homem, que vem sobre as nuvens do céu, com poder e grande glória."}, {"numero": 31, "texto": "E enviará os seus anjos com grande som de trombeta, e ajuntarão os seus escolhidos desde os quatro ventos, de uma extremidade à outra dos céus."}, {"numero": 32, "texto": "Aprendei a parábola da figueira: “Quando os seus ramos já ficam verdes, e as folhas brotam, sabeis que o verão [está] perto”."}, {"numero": 33, "texto": "Assim também vós, quando virdes todas estas coisas, sabei que já está perto, às portas."}, {"numero": 34, "texto": "Em verdade vos digo que esta geração não passará, até que todas estas coisas aconteçam."}, {"numero": 35, "texto": "O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão."}, {"numero": 36, "texto": "Porém daquele dia e hora, ninguém sabe, nem os anjos do céu, a não ser meu Pai somente."}, {"numero": 37, "texto": "Assim como foram os dias de Noé, assim também será a vinda do Filho do homem."}, {"numero": 38, "texto": "Pois, assim como nos dias antes do dilúvio comiam, bebiam, casavam, e davam-se em casamento, até o dia em que Noé entrou na arca;"}, {"numero": 39, "texto": "e não sabiam, até que veio o dilúvio, e levou todos, assim também será a vinda do Filho do homem."}, {"numero": 40, "texto": "Naquela hora dois estarão no campo; um será tomado, e o outro será deixado."}, {"numero": 41, "texto": "Duas estarão moendo em um moinho; uma será tomada, e a outra será deixada."}, {"numero": 42, "texto": "Vigiai, pois, porque não sabeis em que hora o vosso Senhor virá."}, {"numero": 43, "texto": "Porém sabei isto: se o dono de casa soubesse a que hora da noite o ladrão viria, vigiaria, e não deixaria invadir a sua casa."}, {"numero": 44, "texto": "Portanto também vós estai prontos, porque o Filho do homem virá na hora que não esperais."}, {"numero": 45, "texto": "Pois quem é o servo fiel e prudente, ao qual o seu senhor pôs sobre os seus trabalhadores, para [lhes] dar alimento no tempo devido?"}, {"numero": 46, "texto": "Feliz será aquele servo a quem, quando o seu senhor vier, achar fazendo assim."}, {"numero": 47, "texto": "Em verdade vos digo que ele o porá sobre todos os seus bens."}, {"numero": 48, "texto": "Porém se aquele servo mau disser em seu coração: “Meu senhor está demorando a chegar”,"}, {"numero": 49, "texto": "e começar a espancar os [seus] companheiros de serviço, e a comer, e a beber com os beberrões,"}, {"numero": 50, "texto": "o senhor daquele servo chegará num dia que ele não espera, e numa hora que ele não sabe,"}, {"numero": 51, "texto": "e o despedaçará, e porá sua parte com os hipócritas; ali haverá pranto e ranger de dentes."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 24, 'en', '[{"numero": 1, "texto": "And Jesus went out, and departed from the temple: and his disciples came to him for to shew him the buildings of the temple."}, {"numero": 2, "texto": "And Jesus said unto them, See ye not all these things? verily I say unto you, There shall not be left here one stone upon another, that shall not be thrown down."}, {"numero": 3, "texto": "And as he sat upon the mount of Olives, the disciples came unto him privately, saying, Tell us, when shall these things be? and what shall be the sign of thy coming, and of the end of the world?"}, {"numero": 4, "texto": "And Jesus answered and said unto them, Take heed that no man deceive you."}, {"numero": 5, "texto": "For many shall come in my name, saying, I am Christ; and shall deceive many."}, {"numero": 6, "texto": "And ye shall hear of wars and rumours of wars: see that ye be not troubled: for all these things must come to pass, but the end is not yet."}, {"numero": 7, "texto": "For nation shall rise against nation, and kingdom against kingdom: and there shall be famines, and pestilences, and earthquakes, in divers places."}, {"numero": 8, "texto": "All these are the beginning of sorrows."}, {"numero": 9, "texto": "Then shall they deliver you up to be afflicted, and shall kill you: and ye shall be hated of all nations for my name''s sake."}, {"numero": 10, "texto": "And then shall many be offended, and shall betray one another, and shall hate one another."}, {"numero": 11, "texto": "And many false prophets shall rise, and shall deceive many."}, {"numero": 12, "texto": "And because iniquity shall abound, the love of many shall wax cold."}, {"numero": 13, "texto": "But he that shall endure unto the end, the same shall be saved."}, {"numero": 14, "texto": "And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come."}, {"numero": 15, "texto": "When ye therefore shall see the abomination of desolation, spoken of by Daniel the prophet, stand in the holy place, (whoso readeth, let him understand:)"}, {"numero": 16, "texto": "Then let them which be in Judaea flee into the mountains:"}, {"numero": 17, "texto": "Let him which is on the housetop not come down to take any thing out of his house:"}, {"numero": 18, "texto": "Neither let him which is in the field return back to take his clothes."}, {"numero": 19, "texto": "And woe unto them that are with child, and to them that give suck in those days!"}, {"numero": 20, "texto": "But pray ye that your flight be not in the winter, neither on the sabbath day:"}, {"numero": 21, "texto": "For then shall be great tribulation, such as was not since the beginning of the world to this time, no, nor ever shall be."}, {"numero": 22, "texto": "And except those days should be shortened, there should no flesh be saved: but for the elect''s sake those days shall be shortened."}, {"numero": 23, "texto": "Then if any man shall say unto you, Lo, here is Christ, or there; believe it not."}, {"numero": 24, "texto": "For there shall arise false Christs, and false prophets, and shall shew great signs and wonders; insomuch that, if it were possible, they shall deceive the very elect."}, {"numero": 25, "texto": "Behold, I have told you before."}, {"numero": 26, "texto": "Wherefore if they shall say unto you, Behold, he is in the desert; go not forth: behold, he is in the secret chambers; believe it not."}, {"numero": 27, "texto": "For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of man be."}, {"numero": 28, "texto": "For wheresoever the carcase is, there will the eagles be gathered together."}, {"numero": 29, "texto": "Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken:"}, {"numero": 30, "texto": "And then shall appear the sign of the Son of man in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of man coming in the clouds of heaven with power and great glory."}, {"numero": 31, "texto": "And he shall send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from one end of heaven to the other."}, {"numero": 32, "texto": "Now learn a parable of the fig tree; When his branch is yet tender, and putteth forth leaves, ye know that summer is nigh:"}, {"numero": 33, "texto": "So likewise ye, when ye shall see all these things, know that it is near, even at the doors."}, {"numero": 34, "texto": "Verily I say unto you, This generation shall not pass, till all these things be fulfilled."}, {"numero": 35, "texto": "Heaven and earth shall pass away, but my words shall not pass away."}, {"numero": 36, "texto": "But of that day and hour knoweth no man, no, not the angels of heaven, but my Father only."}, {"numero": 37, "texto": "But as the days of Noah were, so shall also the coming of the Son of man be."}, {"numero": 38, "texto": "For as in the days that were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noe entered into the ark,"}, {"numero": 39, "texto": "And knew not until the flood came, and took them all away; so shall also the coming of the Son of man be."}, {"numero": 40, "texto": "Then shall two be in the field; the one shall be taken, and the other left."}, {"numero": 41, "texto": "Two women shall be grinding at the mill; the one shall be taken, and the other left."}, {"numero": 42, "texto": "Watch therefore: for ye know not what hour your Lord doth come."}, {"numero": 43, "texto": "But know this, that if the goodman of the house had known in what watch the thief would come, he would have watched, and would not have suffered his house to be broken up."}, {"numero": 44, "texto": "Therefore be ye also ready: for in such an hour as ye think not the Son of man cometh."}, {"numero": 45, "texto": "Who then is a faithful and wise servant, whom his lord hath made ruler over his household, to give them meat in due season?"}, {"numero": 46, "texto": "Blessed is that servant, whom his lord when he cometh shall find so doing."}, {"numero": 47, "texto": "Verily I say unto you, That he shall make him ruler over all his goods."}, {"numero": 48, "texto": "But and if that evil servant shall say in his heart, My lord delayeth his coming;"}, {"numero": 49, "texto": "And shall begin to smite his fellowservants, and to eat and drink with the drunken;"}, {"numero": 50, "texto": "The lord of that servant shall come in a day when he looketh not for him, and in an hour that he is not aware of,"}, {"numero": 51, "texto": "And shall cut him asunder, and appoint him his portion with the hypocrites: there shall be weeping and gnashing of teeth."}]'::jsonb, 'King James Version'),
  ('Mt', 24, 'fr', '[{"numero": 1, "texto": "Comme Jésus s''''en allait, au sortir du temple, ses disciples s''''approchèrent pour lui en faire remarquer les constructions."}, {"numero": 2, "texto": "Mais il leur dit: Voyez-vous tout cela? Je vous le dis en vérité, il ne restera pas ici pierre sur pierre qui ne soit renversée."}, {"numero": 3, "texto": "Il s''''assit sur la montagne des oliviers. Et les disciples vinrent en particulier lui faire cette question: Dis-nous, quand cela arrivera-t-il, et quel sera le signe de ton avènement et de la fin du monde?"}, {"numero": 4, "texto": "Jésus leur répondit: Prenez garde que personne ne vous séduise."}, {"numero": 5, "texto": "Car plusieurs viendront sous mon nom, disant: C''''est moi qui suis le Christ. Et ils séduiront beaucoup de gens."}, {"numero": 6, "texto": "Vous entendrez parler de guerres et de bruits de guerres: gardez-vous d''''être troublés, car il faut que ces choses arrivent. Mais ce ne sera pas encore la fin."}, {"numero": 7, "texto": "Une nation s''''élèvera contre une nation, et un royaume contre un royaume, et il y aura, en divers lieux, des famines et des tremblements de terre."}, {"numero": 8, "texto": "Tout cela ne sera que le commencement des douleurs."}, {"numero": 9, "texto": "Alors on vous livrera aux tourments, et l''''on vous fera mourir; et vous serez haïs de toutes les nations, à cause de mon nom."}, {"numero": 10, "texto": "Alors aussi plusieurs succomberont, et ils se trahiront, se haïront les uns les autres."}, {"numero": 11, "texto": "Plusieurs faux prophètes s''''élèveront, et ils séduiront beaucoup de gens."}, {"numero": 12, "texto": "Et, parce que l''''iniquité se sera accrue, la charité du plus grand nombre se refroidira."}, {"numero": 13, "texto": "Mais celui qui persévérera jusqu''''à la fin sera sauvé."}, {"numero": 14, "texto": "Cette bonne nouvelle du royaume sera prêchée dans le monde entier, pour servir de témoignage à toutes les nations. Alors viendra la fin."}, {"numero": 15, "texto": "C''''est pourquoi, lorsque vous verrez l''''abomination de la désolation, dont a parlé le prophète Daniel, établie en lieu saint, -que celui qui lit fasse attention! -"}, {"numero": 16, "texto": "alors, que ceux qui seront en Judée fuient dans les montagnes;"}, {"numero": 17, "texto": "que celui qui sera sur le toit ne descende pas pour prendre ce qui est dans sa maison;"}, {"numero": 18, "texto": "et que celui qui sera dans les champs ne retourne pas en arrière pour prendre son manteau."}, {"numero": 19, "texto": "Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!"}, {"numero": 20, "texto": "Priez pour que votre fuite n''''arrive pas en hiver, ni un jour de sabbat."}, {"numero": 21, "texto": "Car alors, la détresse sera si grande qu''''il n''''y en a point eu de pareille depuis le commencement du monde jusqu''''à présent, et qu''''il n''''y en aura jamais."}, {"numero": 22, "texto": "Et, si ces jours n''''étaient abrégés, personne ne serait sauvé; mais, à cause des élus, ces jours seront abrégés."}, {"numero": 23, "texto": "Si quelqu''''un vous dit alors: Le Christ est ici, ou: Il est là, ne le croyez pas."}, {"numero": 24, "texto": "Car il s''''élèvera de faux Christs et de faux prophètes; ils feront de grands prodiges et des miracles, au point de séduire, s''''il était possible, même les élus."}, {"numero": 25, "texto": "Voici, je vous l''''ai annoncé d''''avance."}, {"numero": 26, "texto": "Si donc on vous dit: Voici, il est dans le désert, n''''y allez pas; voici, il est dans les chambres, ne le croyez pas."}, {"numero": 27, "texto": "Car, comme l''''éclair part de l''''orient et se montre jusqu''''en occident, ainsi sera l''''avènement du Fils de l''''homme."}, {"numero": 28, "texto": "En quelque lieu que soit le cadavre, là s''''assembleront les aigles."}, {"numero": 29, "texto": "Aussitôt après ces jours de détresse, le soleil s''''obscurcira, la lune ne donnera plus sa lumière, les étoiles tomberont du ciel, et les puissances des cieux seront ébranlées."}, {"numero": 30, "texto": "Alors le signe du Fils de l''''homme paraîtra dans le ciel, toutes les tribus de la terre se lamenteront, et elles verront le Fils de l''''homme venant sur les nuées du ciel avec puissance et une grande gloire."}, {"numero": 31, "texto": "Il enverra ses anges avec la trompette retentissante, et ils rassembleront ses élus des quatre vents, depuis une extrémité des cieux jusqu''''à l''''autre."}, {"numero": 32, "texto": "Instruisez-vous par une comparaison tirée du figuier. Dès que ses branches deviennent tendres, et que les feuilles poussent, vous connaissez que l''''été est proche."}, {"numero": 33, "texto": "De même, quand vous verrez toutes ces choses, sachez que le Fils de l''''homme est proche, à la porte."}, {"numero": 34, "texto": "Je vous le dis en vérité, cette génération ne passera point, que tout cela n''''arrive."}, {"numero": 35, "texto": "Le ciel et la terre passeront, mais mes paroles ne passeront point."}, {"numero": 36, "texto": "Pour ce qui est du jour et de l''''heure, personne ne le sait, ni les anges des cieux, ni le Fils, mais le Père seul."}, {"numero": 37, "texto": "Ce qui arriva du temps de Noé arrivera de même à l''''avènement du Fils de l''''homme."}, {"numero": 38, "texto": "Car, dans les jours qui précédèrent le déluge, les hommes mangeaient et buvaient, se mariaient et mariaient leurs enfants, jusqu''''au jour où Noé entra dans l''''arche;"}, {"numero": 39, "texto": "et ils ne se doutèrent de rien, jusqu''''à ce que le déluge vînt et les emportât tous: il en sera de même à l''''avènement du Fils de l''''homme."}, {"numero": 40, "texto": "Alors, de deux hommes qui seront dans un champ, l''''un sera pris et l''''autre laissé;"}, {"numero": 41, "texto": "de deux femmes qui moudront à la meule, l''''une sera prise et l''''autre laissée."}, {"numero": 42, "texto": "Veillez donc, puisque vous ne savez pas quel jour votre Seigneur viendra."}, {"numero": 43, "texto": "Sachez-le bien, si le maître de la maison savait à quelle veille de la nuit le voleur doit venir, il veillerait et ne laisserait pas percer sa maison."}, {"numero": 44, "texto": "C''''est pourquoi, vous aussi, tenez-vous prêts, car le Fils de l''''homme viendra à l''''heure où vous n''''y penserez pas."}, {"numero": 45, "texto": "Quel est donc le serviteur fidèle et prudent, que son maître a établi sur ses gens, pour leur donner la nourriture au temps convenable?"}, {"numero": 46, "texto": "Heureux ce serviteur, que son maître, à son arrivée, trouvera faisant ainsi!"}, {"numero": 47, "texto": "Je vous le dis en vérité, il l''''établira sur tous ses biens."}, {"numero": 48, "texto": "Mais, si c''''est un méchant serviteur, qui dise en lui-même: Mon maître tarde à venir,"}, {"numero": 49, "texto": "s''''il se met à battre ses compagnons, s''''il mange et boit avec les ivrognes,"}, {"numero": 50, "texto": "le maître de ce serviteur viendra le jour où il ne s''''y attend pas et à l''''heure qu''''il ne connaît pas,"}, {"numero": 51, "texto": "il le mettra en pièces, et lui donnera sa part avec les hypocrites: c''''est là qu''''il y aura des pleurs et des grincements de dents."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 24, 'es', '[{"numero": 1, "texto": "Y SALIDO Jesús, íbase del templo; y se llegaron sus discípulos, para mostrarle los edificios del templo."}, {"numero": 2, "texto": "Y respondiendo él, les dijo: ¿Veis todo esto? de cierto os digo, que no será dejada aquí piedra sobre piedra, que no sea destruída."}, {"numero": 3, "texto": "Y sentándose él en el monte de las Olivas, se llegaron á él los discípulos aparte, diciendo: Dinos, ¿cuándo serán estas cosas, y qué señal habrá de tu venida, y del fin del mundo?"}, {"numero": 4, "texto": "Y respondiendo Jesús, les dijo: Mirad que nadie os engañe."}, {"numero": 5, "texto": "Porque vendrán muchos en mi nombre, diciendo: Yo soy el Cristo; y á muchos engañarán."}, {"numero": 6, "texto": "Y oiréis guerras, y rumores de guerras: mirad que no os turbéis; porque es menester que todo esto acontezca; mas aún no es el fin."}, {"numero": 7, "texto": "Porque se levantará nación contra nación, y reino contra reino; y habrá pestilencias, y hambres, y terremotos por los lugares."}, {"numero": 8, "texto": "Y todas estas cosas, principio de dolores."}, {"numero": 9, "texto": "Entonces os entregarán para ser afligidos, y os matarán; y seréis aborrecidos de todas las gentes por causa de mi nombre."}, {"numero": 10, "texto": "Y muchos entonces serán escandalizados; y se entregarán unos á otros, y unos á otros se aborrecerán."}, {"numero": 11, "texto": "Y muchos falsos profetas se levantarán y engañarán á muchos."}, {"numero": 12, "texto": "Y por haberse multiplicado la maldad, la caridad de muchos se resfriará."}, {"numero": 13, "texto": "Mas el que perseverare hasta el fin, éste será salvo."}, {"numero": 14, "texto": "Y será predicado este evangelio del reino en todo el mundo, por testimonio á todos los Gentiles; y entonces vendrá el fin."}, {"numero": 15, "texto": "Por tanto, cuando viereis la abominación del asolamiento, que fué dicha por Daniel profeta, que estará en el lugar santo, (el que lee, entienda),"}, {"numero": 16, "texto": "Entonces los que están en Judea, huyan á los montes;"}, {"numero": 17, "texto": "Y el que sobre el terrado, no descienda á tomar algo de su casa;"}, {"numero": 18, "texto": "Y el que en el campo, no vuelva atrás á tomar sus vestidos."}, {"numero": 19, "texto": "Mas ¡ay de las preñadas, y de las que crían en aquellos días!"}, {"numero": 20, "texto": "Orad, pues, que vuestra huída no sea en invierno ni en sábado;"}, {"numero": 21, "texto": "Porque habrá entonces grande aflicción, cual no fué desde el principio del mundo hasta ahora, ni será."}, {"numero": 22, "texto": "Y si aquellos días no fuesen acortados, ninguna carne sería salva; mas por causa de los escogidos, aquellos días serán acortados."}, {"numero": 23, "texto": "Entonces, si alguno os dijere: He aquí está el Cristo, ó allí, no creáis."}, {"numero": 24, "texto": "Porque se levantarán falsos Cristos, y falsos profetas, y darán señales grandes y prodigios; de tal manera que engañarán, si es posible, aun á los escogidos."}, {"numero": 25, "texto": "He aquí os lo he dicho antes."}, {"numero": 26, "texto": "Así que, si os dijeren: He aquí en el desierto está; no salgáis: He aquí en las cámaras; no creáis."}, {"numero": 27, "texto": "Porque como el relámpago que sale del oriente y se muestra hasta el occidente, así será también la venida del Hijo del hombre."}, {"numero": 28, "texto": "Porque donde quiera que estuviere el cuerpo muerto, allí se juntarán las águilas."}, {"numero": 29, "texto": "Y luego después de la aflicción de aquellos días, el sol se obscurecerá, y la luna no dará su lumbre, y las estrellas caerán del cielo, y las virtudes de los cielos serán conmovidas."}, {"numero": 30, "texto": "Y entonces se mostrará la señal del Hijo del hombre en el cielo; y entonces lamentarán todas las tribus de la tierra, y verán al Hijo del hombre que vendrá sobre las nubes del cielo, con grande poder y gloria."}, {"numero": 31, "texto": "Y enviará sus ángeles con gran voz de trompeta, y juntarán sus escogidos de los cuatro vientos, de un cabo del cielo hasta el otro."}, {"numero": 32, "texto": "De la higuera aprended la parábola: Cuando ya su rama se enternece, y las hojas brotan, sabéis que el verano está cerca."}, {"numero": 33, "texto": "Así también vosotros, cuando viereis todas estas cosas, sabed que está cercano, á las puertas."}, {"numero": 34, "texto": "De cierto os digo, que no pasará esta generación, que todas estas cosas no acontezcan."}, {"numero": 35, "texto": "El cielo y la tierra pasarán, mas mis palabras no pasarán."}, {"numero": 36, "texto": "Empero del día y hora nadie sabe, ni aun los ángeles de los cielos, sino mi Padre solo."}, {"numero": 37, "texto": "Mas como los días de Noé, así será la venida del Hijo del hombre."}, {"numero": 38, "texto": "Porque como en los días antes del diluvio estaban comiendo y bebiendo, casándose y dando en casamiento, hasta el día que Noé entró en el arca,"}, {"numero": 39, "texto": "Y no conocieron hasta que vino el diluvio y llevó á todos, así será también la venida del Hijo del hombre."}, {"numero": 40, "texto": "Entonces estarán dos en el campo; el uno será tomado, y el otro será dejado:"}, {"numero": 41, "texto": "Dos mujeres moliendo á un molinillo; la una será tomada, y la otra será dejada."}, {"numero": 42, "texto": "Velad pues, porque no sabéis á qué hora ha de venir vuestro Señor."}, {"numero": 43, "texto": "Esto empero sabed, que si el padre de la familia supiese á cuál vela el ladrón había de venir, velaría, y no dejaría minar su casa."}, {"numero": 44, "texto": "Por tanto, también vosotros estad apercibidos; porque el Hijo del hombre ha de venir á la hora que no pensáis."}, {"numero": 45, "texto": "¿Quién pues es el siervo fiel y prudente, al cual puso su señor sobre su familia para que les dé alimento á tiempo?"}, {"numero": 46, "texto": "Bienaventurado aquel siervo, al cual, cuando su señor viniere, le hallare haciendo así."}, {"numero": 47, "texto": "De cierto os digo, que sobre todos sus bienes le pondrá."}, {"numero": 48, "texto": "Y si aquel siervo malo dijere en su corazón: Mi señor se tarda en venir:"}, {"numero": 49, "texto": "Y comenzare á herir á sus consiervos, y aun á comer y á beber con los borrachos;"}, {"numero": 50, "texto": "Vendrá el señor de aquel siervo en el día que no espera, y á la hora que no sabe,"}, {"numero": 51, "texto": "Y le cortará por medio, y pondrá su parte con los hipócritas: allí será el lloro y el crujir de dientes."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 25, 'pt', '[{"numero": 1, "texto": "Então o Reino dos céus será semelhante a dez virgens, que tomaram suas lâmpadas, e saíram ao encontro do noivo."}, {"numero": 2, "texto": "E cinco delas eram prudentes, e cinco tolas."}, {"numero": 3, "texto": "As tolas, quando tomaram as suas lâmpadas, não tomaram azeite consigo."}, {"numero": 4, "texto": "Mas as prudentes tomaram azeite nos seus frascos, com as suas lâmpadas."}, {"numero": 5, "texto": "O noivo demorou, por isso todas cochilaram e adormeceram."}, {"numero": 6, "texto": "Mas à meia-noite houve um grito: “Eis que vem o noivo! Ide ao seu encontro!”."}, {"numero": 7, "texto": "Então todas aquelas virgens se levantaram, e prepararam suas lâmpadas."}, {"numero": 8, "texto": "E as tolas disseram às prudentes: “Dai-nos do vosso azeite, porque as nossas lâmpadas estão se apagando”."}, {"numero": 9, "texto": "Mas as prudentes responderam: “ [Não] ,para que não falte a nós e a vós; em vez disso, ide aos vendedores, e comprai para vós mesmas”."}, {"numero": 10, "texto": "Enquanto elas foram comprar, veio o noivo. As que estavam preparadas entraram com ele à festa do casamento, e fechou-se a porta."}, {"numero": 11, "texto": "Depois vieram também as outras virgens, dizendo: “Senhor, Senhor, abre-nos!”"}, {"numero": 12, "texto": "Mas ele respondeu: “Em verdade vos digo que não vos conheço”."}, {"numero": 13, "texto": "Portanto, vigiai, porque não sabeis o dia nem a hora em que o Filho do homem virá."}, {"numero": 14, "texto": "Pois [é] como um homem, que partindo para fora do país, chamou seus servos, e lhes entregou os seus bens."}, {"numero": 15, "texto": "E a um deu cinco talentos, a outro dois, e ao terceiro um, a cada um conforme a sua habilidade, e logo depois partiu em viagem."}, {"numero": 16, "texto": "Em seguida, o que havia recebido cinco talentos foi fazer negócios com eles, e obteve outros cinco talentos."}, {"numero": 17, "texto": "E, semelhantemente, o que [havia recebido] dois ganhou também outros dois."}, {"numero": 18, "texto": "Mas o que tinha recebido um foi cavar a terra, e escondeu o dinheiro do seu senhor."}, {"numero": 19, "texto": "Muito tempo depois, o senhor daqueles servos veio fazer contas com eles."}, {"numero": 20, "texto": "O que havia recebido cinco talentos chegou trazendo-lhe outros cinco talentos, e disse: ”Senhor, cinco talentos me entregaste, eis que ganhei com eles outros cinco talentos”."}, {"numero": 21, "texto": "E o seu senhor lhe disse: “ [Muito] bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”."}, {"numero": 22, "texto": "E chegando-se também o que havia recebido dois talentos, disse: “Senhor, dois talentos me entregaste, eis que ganhei com eles outros dois talentos”."}, {"numero": 23, "texto": "Seu senhor lhe disse: “ [Muito] bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”."}, {"numero": 24, "texto": "Mas, chegando também o que havia recebido um talento, disse: “Senhor, eu te conhecia, que és homem duro, que colhes onde não semeaste, e ajuntas onde não espalhaste;"}, {"numero": 25, "texto": "E eu, atemorizado, fui e escondi o teu talento na terra; eis aqui tens o que é teu”."}, {"numero": 26, "texto": "Porém seu senhor lhe respondeu: “Servo mau e preguiçoso! Sabias que colho onde não semeei, e ajunto onde não espalhei."}, {"numero": 27, "texto": "Devias, portanto, ter depositado o meu dinheiro com os banqueiros e, quando eu voltasse, receberia o que é meu com juros."}, {"numero": 28, "texto": "Por isso, tirai dele o talento, e dai-o ao que tem dez talentos”."}, {"numero": 29, "texto": "Pois a todo aquele que tiver, lhe será dado, e terá em abundância; porém ao que não tiver, até o que tem lhe será tirado."}, {"numero": 30, "texto": "“E lançai o servo inútil às trevas de fora (ali haverá pranto e ranger de dentes)”."}, {"numero": 31, "texto": "E quando o Filho do homem vier em sua glória, e todos os santos anjos com ele, então ele se assentará sobre o trono de sua glória."}, {"numero": 32, "texto": "E serão ajuntadas diante dele todas as nações, e separará [as pessoas] umas das outras, assim como o pastor separa as ovelhas dos bodes."}, {"numero": 33, "texto": "E porá as ovelhas à sua direita, porém os bodes à esquerda."}, {"numero": 34, "texto": "Então o Rei dirá o rei aos que estiverem à sua direita: “Vinde, benditos de meu Pai! Herdai o Reino que está preparado para vós desde a fundação do mundo."}, {"numero": 35, "texto": "Pois tive fome, e me destes de comer; tive sede, e me destes de beber; fui forasteiro, e me acolhestes;"}, {"numero": 36, "texto": "[estive] nu, e me vestistes; [estive] doente, e cuidastes de mim; estive na prisão, e me visitastes”."}, {"numero": 37, "texto": "Então os justos lhe perguntarão: “Senhor, quando te vimos com fome, e [te] demos de comer, ou com sede, e [te] demos de beber?"}, {"numero": 38, "texto": "E quando te vimos forasteiro, e [te] acolhemos, ou nu, e te vestimos?"}, {"numero": 39, "texto": "E quando te vimos doente, ou na prisão, e viemos te visitar?”"}, {"numero": 40, "texto": "E o Rei lhes responderá: “Em verdade vos digo que, todas as vezes que fizestes a um destes menores dos meus irmãos, fizestes a mim”."}, {"numero": 41, "texto": "Então dirá também aos que [estiverem] à esquerda: “Apartai-vos de mim, malditos, ao fogo eterno, preparado para o Diabo e os seus anjos."}, {"numero": 42, "texto": "Pois tive fome, e não me destes de comer; tive sede, e não me destes de beber."}, {"numero": 43, "texto": "Fui forasteiro, e não me acolhestes; [estive] nu, e não me vestistes; [estive] doente, e na prisão, e não me visitastes."}, {"numero": 44, "texto": "Então também eles lhe perguntarão: “Senhor, quando te vimos com fome, ou com sede, ou forasteiro, ou nu, ou doente, ou na prisão, e não te servimos?”"}, {"numero": 45, "texto": "Então ele lhes responderá, dizendo: “Em verdade vos digo que, todas as vezes que não fizestes a um destes menores, não fizestes a mim”."}, {"numero": 46, "texto": "E estes irão ao tormento eterno, porém os justos à vida eterna."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 25, 'en', '[{"numero": 1, "texto": "Then shall the kingdom of heaven be likened unto ten virgins, which took their lamps, and went forth to meet the bridegroom."}, {"numero": 2, "texto": "And five of them were wise, and five were foolish."}, {"numero": 3, "texto": "They that were foolish took their lamps, and took no oil with them:"}, {"numero": 4, "texto": "But the wise took oil in their vessels with their lamps."}, {"numero": 5, "texto": "While the bridegroom tarried, they all slumbered and slept."}, {"numero": 6, "texto": "And at midnight there was a cry made, Behold, the bridegroom cometh; go ye out to meet him."}, {"numero": 7, "texto": "Then all those virgins arose, and trimmed their lamps."}, {"numero": 8, "texto": "And the foolish said unto the wise, Give us of your oil; for our lamps are gone out."}, {"numero": 9, "texto": "But the wise answered, saying, Not so; lest there be not enough for us and you: but go ye rather to them that sell, and buy for yourselves."}, {"numero": 10, "texto": "And while they went to buy, the bridegroom came; and they that were ready went in with him to the marriage: and the door was shut."}, {"numero": 11, "texto": "Afterward came also the other virgins, saying, Lord, Lord, open to us."}, {"numero": 12, "texto": "But he answered and said, Verily I say unto you, I know you not."}, {"numero": 13, "texto": "Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh."}, {"numero": 14, "texto": "For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods."}, {"numero": 15, "texto": "And unto one he gave five talents, to another two, and to another one; to every man according to his several ability; and straightway took his journey."}, {"numero": 16, "texto": "Then he that had received the five talents went and traded with the same, and made them other five talents."}, {"numero": 17, "texto": "And likewise he that had received two, he also gained other two."}, {"numero": 18, "texto": "But he that had received one went and digged in the earth, and hid his lord''s money."}, {"numero": 19, "texto": "After a long time the lord of those servants cometh, and reckoneth with them."}, {"numero": 20, "texto": "And so he that had received five talents came and brought other five talents, saying, Lord, thou deliveredst unto me five talents: behold, I have gained beside them five talents more."}, {"numero": 21, "texto": "His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord."}, {"numero": 22, "texto": "He also that had received two talents came and said, Lord, thou deliveredst unto me two talents: behold, I have gained two other talents beside them."}, {"numero": 23, "texto": "His lord said unto him, Well done, good and faithful servant; thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord."}, {"numero": 24, "texto": "Then he which had received the one talent came and said, Lord, I knew thee that thou art an hard man, reaping where thou hast not sown, and gathering where thou hast not strawed:"}, {"numero": 25, "texto": "And I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine."}, {"numero": 26, "texto": "His lord answered and said unto him, Thou wicked and slothful servant, thou knewest that I reap where I sowed not, and gather where I have not strawed:"}, {"numero": 27, "texto": "Thou oughtest therefore to have put my money to the exchangers, and then at my coming I should have received mine own with usury."}, {"numero": 28, "texto": "Take therefore the talent from him, and give it unto him which hath ten talents."}, {"numero": 29, "texto": "For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath."}, {"numero": 30, "texto": "And cast ye the unprofitable servant into outer darkness: there shall be weeping and gnashing of teeth."}, {"numero": 31, "texto": "When the Son of man shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:"}, {"numero": 32, "texto": "And before him shall be gathered all nations: and he shall separate them one from another, as a shepherd divideth his sheep from the goats:"}, {"numero": 33, "texto": "And he shall set the sheep on his right hand, but the goats on the left."}, {"numero": 34, "texto": "Then shall the King say unto them on his right hand, Come, ye blessed of my Father, inherit the kingdom prepared for you from the foundation of the world:"}, {"numero": 35, "texto": "For I was an hungred, and ye gave me meat: I was thirsty, and ye gave me drink: I was a stranger, and ye took me in:"}, {"numero": 36, "texto": "Naked, and ye clothed me: I was sick, and ye visited me: I was in prison, and ye came unto me."}, {"numero": 37, "texto": "Then shall the righteous answer him, saying, Lord, when saw we thee an hungred, and fed thee? or thirsty, and gave thee drink?"}, {"numero": 38, "texto": "When saw we thee a stranger, and took thee in? or naked, and clothed thee?"}, {"numero": 39, "texto": "Or when saw we thee sick, or in prison, and came unto thee?"}, {"numero": 40, "texto": "And the King shall answer and say unto them, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me."}, {"numero": 41, "texto": "Then shall he say also unto them on the left hand, Depart from me, ye cursed, into everlasting fire, prepared for the devil and his angels:"}, {"numero": 42, "texto": "For I was an hungred, and ye gave me no meat: I was thirsty, and ye gave me no drink:"}, {"numero": 43, "texto": "I was a stranger, and ye took me not in: naked, and ye clothed me not: sick, and in prison, and ye visited me not."}, {"numero": 44, "texto": "Then shall they also answer him, saying, Lord, when saw we thee an hungred, or athirst, or a stranger, or naked, or sick, or in prison, and did not minister unto thee?"}, {"numero": 45, "texto": "Then shall he answer them, saying, Verily I say unto you, Inasmuch as ye did it not to one of the least of these, ye did it not to me."}, {"numero": 46, "texto": "And these shall go away into everlasting punishment: but the righteous into life eternal."}]'::jsonb, 'King James Version'),
  ('Mt', 25, 'fr', '[{"numero": 1, "texto": "Alors le royaume des cieux sera semblable à dix vierges qui, ayant pris leurs lampes, allèrent à la rencontre de l''''époux."}, {"numero": 2, "texto": "Cinq d''''entre elles étaient folles, et cinq sages."}, {"numero": 3, "texto": "Les folles, en prenant leurs lampes, ne prirent point d''''huile avec elles;"}, {"numero": 4, "texto": "mais les sages prirent, avec leurs lampes, de l''''huile dans des vases."}, {"numero": 5, "texto": "Comme l''''époux tardait, toutes s''''assoupirent et s''''endormirent."}, {"numero": 6, "texto": "Au milieu de la nuit, on cria: Voici l''''époux, allez à sa rencontre!"}, {"numero": 7, "texto": "Alors toutes ces vierges se réveillèrent, et préparèrent leurs lampes."}, {"numero": 8, "texto": "Les folles dirent aux sages: Donnez-nous de votre huile, car nos lampes s''''éteignent."}, {"numero": 9, "texto": "Les sages répondirent: Non; il n''''y en aurait pas assez pour nous et pour vous; allez plutôt chez ceux qui en vendent, et achetez-en pour vous."}, {"numero": 10, "texto": "Pendant qu''''elles allaient en acheter, l''''époux arriva; celles qui étaient prêtes entrèrent avec lui dans la salle des noces, et la porte fut fermée."}, {"numero": 11, "texto": "Plus tard, les autres vierges vinrent, et dirent: Seigneur, Seigneur, ouvre-nous."}, {"numero": 12, "texto": "Mais il répondit: Je vous le dis en vérité, je ne vous connais pas."}, {"numero": 13, "texto": "Veillez donc, puisque vous ne savez ni le jour, ni l''''heure."}, {"numero": 14, "texto": "Il en sera comme d''''un homme qui, partant pour un voyage, appela ses serviteurs, et leur remit ses biens."}, {"numero": 15, "texto": "Il donna cinq talents à l''''un, deux à l''''autre, et un au troisième, à chacun selon sa capacité, et il partit. Aussitôt"}, {"numero": 16, "texto": "celui qui avait reçu les cinq talents s''''en alla, les fit valoir, et il gagna cinq autres talents."}, {"numero": 17, "texto": "De même, celui qui avait reçu les deux talents en gagna deux autres."}, {"numero": 18, "texto": "Celui qui n''''en avait reçu qu''''un alla faire un creux dans la terre, et cacha l''''argent de son maître."}, {"numero": 19, "texto": "Longtemps après, le maître de ces serviteurs revint, et leur fit rendre compte."}, {"numero": 20, "texto": "Celui qui avait reçu les cinq talents s''''approcha, en apportant cinq autres talents, et il dit: Seigneur, tu m''''as remis cinq talents; voici, j''''en ai gagné cinq autres."}, {"numero": 21, "texto": "Son maître lui dit: C''''est bien, bon et fidèle serviteur; tu as été fidèle en peu de chose, je te confierai beaucoup; entre dans la joie de ton maître."}, {"numero": 22, "texto": "Celui qui avait reçu les deux talents s''''approcha aussi, et il dit: Seigneur, tu m''''as remis deux talents; voici, j''''en ai gagné deux autres."}, {"numero": 23, "texto": "Son maître lui dit: C''''est bien, bon et fidèle serviteur; tu as été fidèle en peu de chose, je te confierai beaucoup; entre dans la joie de ton maître."}, {"numero": 24, "texto": "Celui qui n''''avait reçu qu''''un talent s''''approcha ensuite, et il dit: Seigneur, je savais que tu es un homme dur, qui moissonnes où tu n''''as pas semé, et qui amasses où tu n''''as pas vanné;"}, {"numero": 25, "texto": "j''''ai eu peur, et je suis allé cacher ton talent dans la terre; voici, prends ce qui est à toi."}, {"numero": 26, "texto": "Son maître lui répondit: Serviteur méchant et paresseux, tu savais que je moissonne où je n''''ai pas semé, et que j''''amasse où je n''''ai pas vanné;"}, {"numero": 27, "texto": "il te fallait donc remettre mon argent aux banquiers, et, à mon retour, j''''aurais retiré ce qui est à moi avec un intérêt."}, {"numero": 28, "texto": "Otez-lui donc le talent, et donnez-le à celui qui a les dix talents."}, {"numero": 29, "texto": "Car on donnera à celui qui a, et il sera dans l''''abondance, mais à celui qui n''''a pas on ôtera même ce qu''''il a."}, {"numero": 30, "texto": "Et le serviteur inutile, jetez-le dans les ténèbres du dehors, où il y aura des pleurs et des grincements de dents."}, {"numero": 31, "texto": "Lorsque le Fils de l''''homme viendra dans sa gloire, avec tous les anges, il s''''assiéra sur le trône de sa gloire."}, {"numero": 32, "texto": "Toutes les nations seront assemblées devant lui. Il séparera les uns d''''avec les autres, comme le berger sépare les brebis d''''avec les boucs;"}, {"numero": 33, "texto": "et il mettra les brebis à sa droite, et les boucs à sa gauche."}, {"numero": 34, "texto": "Alors le roi dira à ceux qui seront à sa droite: Venez, vous qui êtes bénis de mon Père; prenez possession du royaume qui vous a été préparé dès la fondation du monde."}, {"numero": 35, "texto": "Car j''''ai eu faim, et vous m''''avez donné à manger; j''''ai eu soif, et vous m''''avez donné à boire; j''''étais étranger, et vous m''''avez recueilli;"}, {"numero": 36, "texto": "j''''étais nu, et vous m''''avez vêtu; j''''étais malade, et vous m''''avez visité; j''''étais en prison, et vous êtes venus vers moi."}, {"numero": 37, "texto": "Les justes lui répondront: Seigneur, quand t''''avons-nous vu avoir faim, et t''''avons-nous donné à manger; ou avoir soif, et t''''avons-nous donné à boire?"}, {"numero": 38, "texto": "Quand t''''avons-nous vu étranger, et t''''avons-nous recueilli; ou nu, et t''''avons-nous vêtu?"}, {"numero": 39, "texto": "Quand t''''avons-nous vu malade, ou en prison, et sommes-nous allés vers toi?"}, {"numero": 40, "texto": "Et le roi leur répondra: Je vous le dis en vérité, toutes les fois que vous avez fait ces choses à l''''un de ces plus petits de mes frères, c''''est à moi que vous les avez faites."}, {"numero": 41, "texto": "Ensuite il dira à ceux qui seront à sa gauche: Retirez-vous de moi, maudits; allez dans le feu éternel qui a été préparé pour le diable et pour ses anges."}, {"numero": 42, "texto": "Car j''''ai eu faim, et vous ne m''''avez pas donné à manger; j''''ai eu soif, et vous ne m''''avez pas donné à boire;"}, {"numero": 43, "texto": "j''''étais étranger, et vous ne m''''avez pas recueilli; j''''étais nu, et vous ne m''''avez pas vêtu; j''''étais malade et en prison, et vous ne m''''avez pas visité."}, {"numero": 44, "texto": "Ils répondront aussi: Seigneur, quand t''''avons-nous vu ayant faim, ou ayant soif, ou étranger, ou nu, ou malade, ou en prison, et ne t''''avons-nous pas assisté?"}, {"numero": 45, "texto": "Et il leur répondra: Je vous le dis en vérité, toutes les fois que vous n''''avez pas fait ces choses à l''''un de ces plus petits, c''''est à moi que vous ne les avez pas faites."}, {"numero": 46, "texto": "Et ceux-ci iront au châtiment éternel, mais les justes à la vie éternelle."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 25, 'es', '[{"numero": 1, "texto": "ENTONCES el reino de los cielos será semejante á diez vírgenes, que tomando sus lámparas, salieron á recibir al esposo."}, {"numero": 2, "texto": "Y las cinco de ellas eran prudentes, y las cinco fatuas."}, {"numero": 3, "texto": "Las que eran fatuas, tomando sus lámparas, no tomaron consigo aceite;"}, {"numero": 4, "texto": "Mas las prudentes tomaron aceite en sus vasos, juntamente con sus lámparas."}, {"numero": 5, "texto": "Y tardándose el esposo, cabecearon todas, y se durmieron."}, {"numero": 6, "texto": "Y á la media noche fué oído un clamor: He aquí, el esposo viene; salid á recibirle."}, {"numero": 7, "texto": "Entonces todas aquellas vírgenes se levantaron, y aderezaron sus lámparas."}, {"numero": 8, "texto": "Y las fatuas dijeron á las prudentes: Dadnos de vuestro aceite; porque nuestras lámparas se apagan."}, {"numero": 9, "texto": "Mas las prudentes respondieron, diciendo: Porque no nos falte á nosotras y á vosotras, id antes á los que venden, y comprad para vosotras."}, {"numero": 10, "texto": "Y mientras que ellas iban á comprar, vino el esposo; y las que estaban apercibidas, entraron con él á las bodas; y se cerró la puerta."}, {"numero": 11, "texto": "Y después vinieron también las otras vírgenes, diciendo: Señor, Señor, ábrenos."}, {"numero": 12, "texto": "Mas respondiendo él, dijo: De cierto os digo, que no os conozco."}, {"numero": 13, "texto": "Velad, pues, porque no sabéis el día ni la hora en que el Hijo del hombre ha de venir."}, {"numero": 14, "texto": "Porque el reino de los cielos es como un hombre que partiéndose lejos llamó á sus siervos, y les entregó sus bienes."}, {"numero": 15, "texto": "Y á éste dió cinco talentos, y al otro dos, y al otro uno: á cada uno conforme á su facultad; y luego se partió lejos."}, {"numero": 16, "texto": "Y el que había recibido cinco talentos se fué, y granjeó con ellos, é hizo otros cinco talentos."}, {"numero": 17, "texto": "Asimismo el que había recibido dos, ganó también él otros dos."}, {"numero": 18, "texto": "Mas el que había recibido uno, fué y cavó en la tierra, y escondió el dinero de su señor."}, {"numero": 19, "texto": "Y después de mucho tiempo, vino el señor de aquellos siervos, é hizo cuentas con ellos."}, {"numero": 20, "texto": "Y llegando el que había recibido cinco talentos, trajo otros cinco talentos, diciendo: Señor, cinco talentos me entregaste; he aquí otros cinco talentos he ganado sobre ellos."}, {"numero": 21, "texto": "Y su señor le dijo: Bien, buen siervo y fiel; sobre poco has sido fiel, sobre mucho te pondré: entra en el gozo de tu señor."}, {"numero": 22, "texto": "Y llegando también el que había recibido dos talentos, dijo: Señor, dos talentos me entregaste; he aquí otros dos talentos he ganado sobre ellos."}, {"numero": 23, "texto": "Su señor le dijo: Bien, buen siervo y fiel; sobre poco has sido fiel, sobre mucho te pondré: entra en el gozo de tu señor."}, {"numero": 24, "texto": "Y llegando también el que había recibido un talento, dijo: Señor, te conocía que eres hombre duro, que siegas donde no sembraste, y recoges donde no esparciste;"}, {"numero": 25, "texto": "Y tuve miedo, y fuí, y escondí tu talento en la tierra: he aquí tienes lo que es tuyo."}, {"numero": 26, "texto": "Y respondiendo su señor, le dijo: Malo y negligente siervo, sabías que siego donde no sembré y que recojo donde no esparcí;"}, {"numero": 27, "texto": "Por tanto te convenía dar mi dinero á los banqueros, y viniendo yo, hubiera recibido lo que es mío con usura."}, {"numero": 28, "texto": "Quitadle pues el talento, y dadlo al que tiene diez talentos."}, {"numero": 29, "texto": "Porque á cualquiera que tuviere, le será dado, y tendrá más; y al que no tuviere, aun lo que tiene le será quitado."}, {"numero": 30, "texto": "Y al siervo inútil echadle en las tinieblas de afuera: allí será el lloro y el crujir de dientes."}, {"numero": 31, "texto": "Y cuando el Hijo del hombre venga en su gloria, y todos los santos ángeles con él, entonces se sentará sobre el trono de su gloria."}, {"numero": 32, "texto": "Y serán reunidas delante de él todas las gentes: y los apartará los unos de los otros, como aparta el pastor las ovejas de los cabritos."}, {"numero": 33, "texto": "Y pondrá las ovejas á su derecha, y los cabritos á la izquierda."}, {"numero": 34, "texto": "Entonces el Rey dirá á los que estarán á su derecha: Venid, benditos de mi Padre, heredad el reino preparado para vosotros desde la fundación del mundo:"}, {"numero": 35, "texto": "Porque tuve hambre, y me disteis de comer; tuve sed, y me disteis de beber; fuí huésped, y me recogisteis;"}, {"numero": 36, "texto": "Desnudo, y me cubristeis; enfermo, y me visitasteis; estuve en la cárcel, y vinisteis á mí."}, {"numero": 37, "texto": "Entonces los justos le responderán, diciendo: Señor, ¿cuándo te vimos hambriento, y te sustentamos? ¿ó sediento, y te dimos de beber?"}, {"numero": 38, "texto": "¿Y cuándo te vimos huésped, y te recogimos? ¿ó desnudo, y te cubrimos?"}, {"numero": 39, "texto": "¿O cuándo te vimos enfermo, ó en la cárcel, y vinimos á ti?"}, {"numero": 40, "texto": "Y respondiendo el Rey, les dirá: De cierto os digo que en cuanto lo hicisteis á uno de estos mis hermanos pequeñitos, á mí lo hicisteis."}, {"numero": 41, "texto": "Entonces dirá también á los que estarán á la izquierda: Apartaos de mí, malditos, al fuego eterno preparado para el diablo y para sus ángeles:"}, {"numero": 42, "texto": "Porque tuve hambre, y no me disteis de comer; tuve sed, y no me disteis de beber;"}, {"numero": 43, "texto": "Fuí huésped, y no me recogisteis; desnudo, y no me cubristeis; enfermo, y en la cárcel, y no me visitasteis."}, {"numero": 44, "texto": "Entonces también ellos le responderán, diciendo: Señor, ¿cuándo te vimos hambriento, ó sediento, ó huésped, ó desnudo, ó enfermo, ó en la cárcel, y no te servimos?"}, {"numero": 45, "texto": "Entonces les responderá, diciendo: De cierto os digo que en cuanto no lo hicisteis á uno de estos pequeñitos, ni á mí lo hicisteis."}, {"numero": 46, "texto": "E irán éstos al tormento eterno, y los justos á la vida eterna."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 26, 'pt', '[{"numero": 1, "texto": "E aconteceu que, quando Jesus terminou todas estas palavras, disse aos seus discípulos:"}, {"numero": 2, "texto": "Vós bem sabeis que daqui a dois dias é a Páscoa, e o Filho do homem será entregue para ser crucificado."}, {"numero": 3, "texto": "Então os chefes dos sacerdotes, os escribas, e os anciãos do povo se reuniram na casa do sumo sacerdote, que se chamava Caifás."}, {"numero": 4, "texto": "E conversaram a fim de, usando mentira, prenderem Jesus, e [o] matarem."}, {"numero": 5, "texto": "Porém diziam: Não na festa, para que não haja tumulto entre o povo."}, {"numero": 6, "texto": "Enquanto Jesus estava em Betânia, na casa de Simão o leproso,"}, {"numero": 7, "texto": "veio a ele uma mulher com um vaso de alabastro, de óleo perfumado de grande valor, e derramou sobre a cabeça dele, enquanto estava sentado à mesa."}, {"numero": 8, "texto": "E quando os seus discípulos viram, ficaram indignados, dizendo: Para que este desperdício?"}, {"numero": 9, "texto": "Pois esse óleo perfumado podia ter sido vendido por muito, e o dinheiro dado aos pobres."}, {"numero": 10, "texto": "Porém Jesus, sabendo [disso] ,disse-lhes: Por que perturbais a esta mulher? Ora, ela me fez uma boa obra!"}, {"numero": 11, "texto": "Pois vós sempre tendes os pobres convosco, porém nem sempre me tereis."}, {"numero": 12, "texto": "Pois ela, ao derramar este óleo perfumado sobre o meu corpo, ela o fez para [preparar] o meu sepultamento."}, {"numero": 13, "texto": "Em verdade vos digo que, onde quer que este Evangelho em todo o mundo for pregado, também se dirá o que ela fez, para que seja lembrada."}, {"numero": 14, "texto": "Então um dos doze, chamado Judas Iscariotes, foi aos chefes dos sacerdotes,"}, {"numero": 15, "texto": "e disse: O que quereis me dar, para que eu o entregue a vós? E eles lhe determinaram trinta [moedas] de prata."}, {"numero": 16, "texto": "E desde então ele buscava oportunidade para o entregar."}, {"numero": 17, "texto": "E no primeiro [dia da festa] dos pães sem fermento, os discípulos vieram a Jesus lhe perguntar: Onde queres que te preparemos para comer a Páscoa?"}, {"numero": 18, "texto": "E ele respondeu: Ide à cidade a um tal, e dizei-lhe: “O Mestre diz: ‘Meu tempo está perto. Contigo celebrarei a Páscoa com os meus discípulos’”."}, {"numero": 19, "texto": "Os discípulos fizeram como Jesus havia lhes mandado, e prepararam a Páscoa."}, {"numero": 20, "texto": "E vindo o anoitecer, ele se assentou à mesa com os doze."}, {"numero": 21, "texto": "E enquanto comiam, disse: Em verdade vos digo que um de vós me trairá."}, {"numero": 22, "texto": "Eles ficaram muito tristes, e cada um deles começou a lhe perguntar: Por acaso sou eu, Senhor?"}, {"numero": 23, "texto": "E ele respondeu: O que mete comigo a mão no prato, esse me trairá."}, {"numero": 24, "texto": "De fato, o Filho do homem vai assim como dele está escrito; mas ai daquele homem por quem o Filho do homem é traído! Bom seria a tal homem se não houvesse nascido."}, {"numero": 25, "texto": "E Judas, o que o traía, perguntou: Por acaso sou eu, Rabi? [Jesus] lhe disse: Tu o disseste."}, {"numero": 26, "texto": "E enquanto comiam, Jesus tomou o pão, abençoou-o, e o partiu. Então o deu aos discípulos, e disse: Tomai, comei; isto é o meu corpo."}, {"numero": 27, "texto": "Em seguida tomou o cálice, deu graças, e o deu a eles, dizendo: Bebei dele todos,"}, {"numero": 28, "texto": "porque este é o meu sangue, o [sangue] do novo testamento, o qual é derramado por muitos, para o perdão de pecados."}, {"numero": 29, "texto": "E eu vos digo que desde agora não beberei deste fruto da vide, até aquele dia, quando convosco o beber, novo, no reino do meu Pai."}, {"numero": 30, "texto": "E depois de cantarem um hino, saíram para o monte das Oliveiras."}, {"numero": 31, "texto": "Então Jesus lhes disse: Todos vós falhareis comigo esta noite; porque está escrito: “Ferirei o pastor, e as ovelhas do rebanho serão dispersas”."}, {"numero": 32, "texto": "Mas, depois que eu for ressuscitado, irei adiante de vós para a Galileia."}, {"numero": 33, "texto": "Pedro, porém, respondeu-lhe: Ainda que todos falhem contigo, eu nunca falharei."}, {"numero": 34, "texto": "Jesus lhe disse: Em verdade te digo que, nesta mesma noite, antes do galo cantar, tu me negarás três vezes."}, {"numero": 35, "texto": "Pedro lhe respondeu: Ainda que eu tenha de morrer contigo, em nenhuma maneira te negarei. E todos os discípulos disseram o mesmo."}, {"numero": 36, "texto": "Então Jesus veio com eles a um lugar chamado Getsêmani, e disse aos discípulos: Ficai sentados aqui, enquanto eu vou ali orar."}, {"numero": 37, "texto": "Enquanto trazia consigo Pedro e os dois filhos de Zebedeu, ele começou a se entristecer e a se angustiar muito."}, {"numero": 38, "texto": "Então lhes disse: Minha alma está completamente triste até a morte. Ficai aqui, e vigiai comigo."}, {"numero": 39, "texto": "E indo um pouco mais adiante, prostrou-se sobre o seu rosto, orando, e dizendo: Meu Pai, se é possível, passe de mim este cálice; porém, não [seja] como eu quero, mas sim como tu [queres] ."}, {"numero": 40, "texto": "Então voltou aos seus discípulos, e os encontrou dormindo; e disse a Pedro: Então, nem sequer uma hora pudestes vigiar comigo?"}, {"numero": 41, "texto": "Vigiai e orai, para que não entreis em tentação. De fato, o espírito [está] pronto, mas a carne [é] fraca."}, {"numero": 42, "texto": "Ele foi orar pela segunda vez, dizendo: Meu Pai, se este cálice não pode passar de mim sem que eu o beba, faça-se a tua vontade."}, {"numero": 43, "texto": "Quando voltou, achou-os outra vez dormindo, pois os seus olhos estavam pesados."}, {"numero": 44, "texto": "Então os deixou, e foi orar pela terceira vez, dizendo as mesmas palavras."}, {"numero": 45, "texto": "Depois veio aos seus discípulos, e disse-lhes: Agora dormi e descansai. Eis que chegou a hora em que o Filho do homem é entregue em mãos de pecadores."}, {"numero": 46, "texto": "Levantai-vos, vamos! Eis que chegou o que me trai."}, {"numero": 47, "texto": "Enquanto ele ainda estava falando, eis que veio Judas, um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes e dos anciãos do povo."}, {"numero": 48, "texto": "O seu traidor havia lhes dado sinal, dizendo: Aquele a quem eu beijar, é esse. Prendei-o."}, {"numero": 49, "texto": "Logo ele se aproximou de Jesus, e disse: Felicitações, Rabi! e o beijou."}, {"numero": 50, "texto": "Jesus, porém, lhe perguntou: Amigo, para que vieste? Então chegaram, agarraram Jesus, e o prenderam."}, {"numero": 51, "texto": "E eis que um dos que [estavam] com Jesus estendeu a mão, puxou de sua espada, e feriu o servo do sumo sacerdote, cortando-lhe uma orelha."}, {"numero": 52, "texto": "Jesus, então, lhe disse: Põe de volta tua espada ao seu lugar, pois todos os que pegarem espada, pela espada perecerão."}, {"numero": 53, "texto": "Ou, por acaso, pensas tu que eu não posso agora orar ao meu Pai, e ele me daria mais de doze legiões de anjos?"}, {"numero": 54, "texto": "Como, pois, se cumpririam as Escrituras [que dizem] que assim tem que ser feito?"}, {"numero": 55, "texto": "Naquela hora Jesus disse às multidões: Como a um ladrão saístes com espadas e bastões para me prender? Todo dia eu me sentava convosco, ensinando no templo, e não me prendestes."}, {"numero": 56, "texto": "Porém tudo isto aconteceu para que as Escrituras dos profetas se cumpram.Então todos os discípulos o abandonaram, e fugiram."}, {"numero": 57, "texto": "Os que prenderam Jesus o trouxeram [à casa] de Caifás, o sumo sacerdote, onde os escribas e os anciãos estavam reunidos."}, {"numero": 58, "texto": "E Pedro o seguia de longe, até o pátio do sumo sacerdote; e entrou, e se assentou com os servos, para ver o fim."}, {"numero": 59, "texto": "Os chefes dos sacerdotes, os anciãos, e todo o supremo conselho buscavam falso testemunho contra Jesus, para poderem matá-lo,"}, {"numero": 60, "texto": "mas não encontravam. E ainda que muitas falsas testemunhas se apresentavam, [contudo] não encontravam."}, {"numero": 61, "texto": "Mas, por fim, vieram duas falsas testemunhas, que disseram: Este disse: “Posso derrubar o Templo de Deus e reconstruí-lo em três dias”."}, {"numero": 62, "texto": "Então o sumo sacerdote se levantou, e lhe perguntou: Não respondes nada ao que eles testemunham contra ti?"}, {"numero": 63, "texto": "Porém Jesus ficava calado. Então o sumo sacerdote lhe disse: Ordeno-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho de Deus."}, {"numero": 64, "texto": "Jesus lhe disse: Tu o disseste. Porém eu vos digo que, desde agora, vereis o Filho do homem, sentado à direita do Poderoso, e vindo sobre as nuvens do céu."}, {"numero": 65, "texto": "Então o sumo sacerdote rasgou suas roupas, e disse: Ele blasfemou! Para que necessitamos mais de testemunhas? Eis que agora ouvistes a sua blasfêmia."}, {"numero": 66, "texto": "Que vos parece?E eles responderam: Culpado de morte ele é."}, {"numero": 67, "texto": "Então lhe cuspiram no rosto, e lhe deram socos."}, {"numero": 68, "texto": "Outros lhe deram bofetadas, e diziam: Profetiza-nos, ó Cristo, quem é o que te feriu?"}, {"numero": 69, "texto": "Pedro estava sentado fora no pátio. Uma serva aproximou-se dele, e disse: Também tu estavas com Jesus, o galileu."}, {"numero": 70, "texto": "Mas ele o negou diante de todos, dizendo: Não sei o que dizes."}, {"numero": 71, "texto": "E quando ele saiu em direção à entrada, outra o viu, e disse aos que ali [estavam] : Também este estava com Jesus, o nazareno."}, {"numero": 72, "texto": "E ele o negou outra vez com um juramento: Não conheço [esse] homem."}, {"numero": 73, "texto": "Pouco depois, os que ali estavam se aproximaram, e disseram a Pedro: Verdadeiramente também tu és um deles, pois a tua fala te denuncia."}, {"numero": 74, "texto": "Então ele começou a amaldiçoar e a jurar: Não conheço [esse] homem!E imediatamente o galo cantou."}, {"numero": 75, "texto": "Então Pedro se lembrou da palavra de Jesus, que lhe dissera: Antes do galo cantar, tu me negarás três vezes. Assim ele saiu, e chorou amargamente."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 26, 'en', '[{"numero": 1, "texto": "And it came to pass, when Jesus had finished all these sayings, he said unto his disciples,"}, {"numero": 2, "texto": "Ye know that after two days is the feast of the passover, and the Son of man is betrayed to be crucified."}, {"numero": 3, "texto": "Then assembled together the chief priests, and the scribes, and the elders of the people, unto the palace of the high priest, who was called Caiaphas,"}, {"numero": 4, "texto": "And consulted that they might take Jesus by subtilty, and kill him."}, {"numero": 5, "texto": "But they said, Not on the feast day, lest there be an uproar among the people."}, {"numero": 6, "texto": "Now when Jesus was in Bethany, in the house of Simon the leper,"}, {"numero": 7, "texto": "There came unto him a woman having an alabaster box of very precious ointment, and poured it on his head, as he sat at meat."}, {"numero": 8, "texto": "But when his disciples saw it, they had indignation, saying, To what purpose is this waste?"}, {"numero": 9, "texto": "For this ointment might have been sold for much, and given to the poor."}, {"numero": 10, "texto": "When Jesus understood it, he said unto them, Why trouble ye the woman? for she hath wrought a good work upon me."}, {"numero": 11, "texto": "For ye have the poor always with you; but me ye have not always."}, {"numero": 12, "texto": "For in that she hath poured this ointment on my body, she did it for my burial."}, {"numero": 13, "texto": "Verily I say unto you, Wheresoever this gospel shall be preached in the whole world, there shall also this, that this woman hath done, be told for a memorial of her."}, {"numero": 14, "texto": "Then one of the twelve, called Judas Iscariot, went unto the chief priests,"}, {"numero": 15, "texto": "And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver."}, {"numero": 16, "texto": "And from that time he sought opportunity to betray him."}, {"numero": 17, "texto": "Now the first day of the feast of unleavened bread the disciples came to Jesus, saying unto him, Where wilt thou that we prepare for thee to eat the passover?"}, {"numero": 18, "texto": "And he said, Go into the city to such a man, and say unto him, The Master saith, My time is at hand; I will keep the passover at thy house with my disciples."}, {"numero": 19, "texto": "And the disciples did as Jesus had appointed them; and they made ready the passover."}, {"numero": 20, "texto": "Now when the even was come, he sat down with the twelve."}, {"numero": 21, "texto": "And as they did eat, he said, Verily I say unto you, that one of you shall betray me."}, {"numero": 22, "texto": "And they were exceeding sorrowful, and began every one of them to say unto him, Lord, is it I?"}, {"numero": 23, "texto": "And he answered and said, He that dippeth his hand with me in the dish, the same shall betray me."}, {"numero": 24, "texto": "The Son of man goeth as it is written of him: but woe unto that man by whom the Son of man is betrayed! it had been good for that man if he had not been born."}, {"numero": 25, "texto": "Then Judas, which betrayed him, answered and said, Master, is it I? He said unto him, Thou hast said."}, {"numero": 26, "texto": "And as they were eating, Jesus took bread, and blessed it, and brake it, and gave it to the disciples, and said, Take, eat; this is my body."}, {"numero": 27, "texto": "And he took the cup, and gave thanks, and gave it to them, saying, Drink ye all of it;"}, {"numero": 28, "texto": "For this is my blood of the new testament, which is shed for many for the remission of sins."}, {"numero": 29, "texto": "But I say unto you, I will not drink henceforth of this fruit of the vine, until that day when I drink it new with you in my Father''s kingdom."}, {"numero": 30, "texto": "And when they had sung an hymn, they went out into the mount of Olives."}, {"numero": 31, "texto": "Then saith Jesus unto them, All ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep of the flock shall be scattered abroad."}, {"numero": 32, "texto": "But after I am risen again, I will go before you into Galilee."}, {"numero": 33, "texto": "Peter answered and said unto him, Though all men shall be offended because of thee, yet will I never be offended."}, {"numero": 34, "texto": "Jesus said unto him, Verily I say unto thee, That this night, before the cock crow, thou shalt deny me thrice."}, {"numero": 35, "texto": "Peter said unto him, Though I should die with thee, yet will I not deny thee. Likewise also said all the disciples."}, {"numero": 36, "texto": "Then cometh Jesus with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder."}, {"numero": 37, "texto": "And he took with him Peter and the two sons of Zebedee, and began to be sorrowful and very heavy."}, {"numero": 38, "texto": "Then saith he unto them, My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me."}, {"numero": 39, "texto": "And he went a little farther, and fell on his face, and prayed, saying, O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt."}, {"numero": 40, "texto": "And he cometh unto the disciples, and findeth them asleep, and saith unto Peter, What, could ye not watch with me one hour?"}, {"numero": 41, "texto": "Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak."}, {"numero": 42, "texto": "He went away again the second time, and prayed, saying, O my Father, if this cup may not pass away from me, except I drink it, thy will be done."}, {"numero": 43, "texto": "And he came and found them asleep again: for their eyes were heavy."}, {"numero": 44, "texto": "And he left them, and went away again, and prayed the third time, saying the same words."}, {"numero": 45, "texto": "Then cometh he to his disciples, and saith unto them, Sleep on now, and take your rest: behold, the hour is at hand, and the Son of man is betrayed into the hands of sinners."}, {"numero": 46, "texto": "Rise, let us be going: behold, he is at hand that doth betray me."}, {"numero": 47, "texto": "And while he yet spake, lo, Judas, one of the twelve, came, and with him a great multitude with swords and staves, from the chief priests and elders of the people."}, {"numero": 48, "texto": "Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast."}, {"numero": 49, "texto": "And forthwith he came to Jesus, and said, Hail, master; and kissed him."}, {"numero": 50, "texto": "And Jesus said unto him, Friend, wherefore art thou come? Then came they, and laid hands on Jesus and took him."}, {"numero": 51, "texto": "And, behold, one of them which were with Jesus stretched out his hand, and drew his sword, and struck a servant of the high priest''s, and smote off his ear."}, {"numero": 52, "texto": "Then said Jesus unto him, Put up again thy sword into his place: for all they that take the sword shall perish with the sword."}, {"numero": 53, "texto": "Thinkest thou that I cannot now pray to my Father, and he shall presently give me more than twelve legions of angels?"}, {"numero": 54, "texto": "But how then shall the scriptures be fulfilled, that thus it must be?"}, {"numero": 55, "texto": "In that same hour said Jesus to the multitudes, Are ye come out as against a thief with swords and staves for to take me? I sat daily with you teaching in the temple, and ye laid no hold on me."}, {"numero": 56, "texto": "But all this was done, that the scriptures of the prophets might be fulfilled. Then all the disciples forsook him, and fled."}, {"numero": 57, "texto": "And they that had laid hold on Jesus led him away to Caiaphas the high priest, where the scribes and the elders were assembled."}, {"numero": 58, "texto": "But Peter followed him afar off unto the high priest''s palace, and went in, and sat with the servants, to see the end."}, {"numero": 59, "texto": "Now the chief priests, and elders, and all the council, sought false witness against Jesus, to put him to death;"}, {"numero": 60, "texto": "But found none: yea, though many false witnesses came, yet found they none. At the last came two false witnesses,"}, {"numero": 61, "texto": "And said, This fellow said, I am able to destroy the temple of God, and to build it in three days."}, {"numero": 62, "texto": "And the high priest arose, and said unto him, Answerest thou nothing? what is it which these witness against thee?"}, {"numero": 63, "texto": "But Jesus held his peace, And the high priest answered and said unto him, I adjure thee by the living God, that thou tell us whether thou be the Christ, the Son of God."}, {"numero": 64, "texto": "Jesus saith unto him, Thou hast said: nevertheless I say unto you, Hereafter shall ye see the Son of man sitting on the right hand of power, and coming in the clouds of heaven."}, {"numero": 65, "texto": "Then the high priest rent his clothes, saying, He hath spoken blasphemy; what further need have we of witnesses? behold, now ye have heard his blasphemy."}, {"numero": 66, "texto": "What think ye? They answered and said, He is guilty of death."}, {"numero": 67, "texto": "Then did they spit in his face, and buffeted him; and others smote him with the palms of their hands,"}, {"numero": 68, "texto": "Saying, Prophesy unto us, thou Christ, Who is he that smote thee?"}, {"numero": 69, "texto": "Now Peter sat without in the palace: and a damsel came unto him, saying, Thou also wast with Jesus of Galilee."}, {"numero": 70, "texto": "But he denied before them all, saying, I know not what thou sayest."}, {"numero": 71, "texto": "And when he was gone out into the porch, another maid saw him, and said unto them that were there, This fellow was also with Jesus of Nazareth."}, {"numero": 72, "texto": "And again he denied with an oath, I do not know the man."}, {"numero": 73, "texto": "And after a while came unto him they that stood by, and said to Peter, Surely thou also art one of them; for thy speech bewrayeth thee."}, {"numero": 74, "texto": "Then began he to curse and to swear, saying, I know not the man. And immediately the cock crew."}, {"numero": 75, "texto": "And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly."}]'::jsonb, 'King James Version'),
  ('Mt', 26, 'fr', '[{"numero": 1, "texto": "Lorsque Jésus eut achevé tous ces discours, il dit à ses disciples:"}, {"numero": 2, "texto": "Vous savez que la Pâque a lieu dans deux jours, et que le Fils de l''''homme sera livré pour être crucifié."}, {"numero": 3, "texto": "Alors les principaux sacrificateurs et les anciens du peuple se réunirent dans la cour du souverain sacrificateur, appelé Caïphe;"}, {"numero": 4, "texto": "et ils délibérèrent sur les moyens d''''arrêter Jésus par ruse, et de le faire mourir."}, {"numero": 5, "texto": "Mais ils dirent: Que ce ne soit pas pendant la fête, afin qu''''il n''''y ait pas de tumulte parmi le peuple."}, {"numero": 6, "texto": "Comme Jésus était à Béthanie, dans la maison de Simon le lépreux,"}, {"numero": 7, "texto": "une femme s''''approcha de lui, tenant un vase d''''albâtre, qui renfermait un parfum de grand prix; et, pendant qu''''il était à table, elle répandit le parfum sur sa tête."}, {"numero": 8, "texto": "Les disciples, voyant cela, s''''indignèrent, et dirent: A quoi bon cette perte?"}, {"numero": 9, "texto": "On aurait pu vendre ce parfum très cher, et en donner le prix aux pauvres."}, {"numero": 10, "texto": "Jésus, s''''en étant aperçu, leur dit: Pourquoi faites-vous de la peine à cette femme? Elle a fait une bonne action à mon égard;"}, {"numero": 11, "texto": "car vous avez toujours des pauvres avec vous, mais vous ne m''''avez pas toujours."}, {"numero": 12, "texto": "En répandant ce parfum sur mon corps, elle l''''a fait pour ma sépulture."}, {"numero": 13, "texto": "Je vous le dis en vérité, partout où cette bonne nouvelle sera prêchée, dans le monde entier, on racontera aussi en mémoire de cette femme ce qu''''elle a fait."}, {"numero": 14, "texto": "Alors l''''un des douze, appelé Judas Iscariot, alla vers les principaux sacrificateurs,"}, {"numero": 15, "texto": "et dit: Que voulez-vous me donner, et je vous le livrerai? Et ils lui payèrent trente pièces d''''argent."}, {"numero": 16, "texto": "Depuis ce moment, il cherchait une occasion favorable pour livrer Jésus."}, {"numero": 17, "texto": "Le premier jour des pains sans levain, les disciples s''''adressèrent à Jésus, pour lui dire: Où veux-tu que nous te préparions le repas de la Pâque?"}, {"numero": 18, "texto": "Il répondit: Allez à la ville chez un tel, et vous lui direz: Le maître dit: Mon temps est proche; je ferai chez toi la Pâque avec mes disciples."}, {"numero": 19, "texto": "Les disciples firent ce que Jésus leur avait ordonné, et ils préparèrent la Pâque."}, {"numero": 20, "texto": "Le soir étant venu, il se mit à table avec les douze."}, {"numero": 21, "texto": "Pendant qu''''ils mangeaient, il dit: Je vous le dis en vérité, l''''un de vous me livrera."}, {"numero": 22, "texto": "Ils furent profondément attristés, et chacun se mit à lui dire: Est-ce moi, Seigneur?"}, {"numero": 23, "texto": "Il répondit: Celui qui a mis avec moi la main dans le plat, c''''est celui qui me livrera."}, {"numero": 24, "texto": "Le Fils de l''''homme s''''en va, selon ce qui est écrit de lui. Mais malheur à l''''homme par qui le Fils de l''''homme est livré! Mieux vaudrait pour cet homme qu''''il ne fût pas né."}, {"numero": 25, "texto": "Judas, qui le livrait, prit la parole et dit: Est-ce moi, Rabbi? Jésus lui répondit: Tu l''''as dit."}, {"numero": 26, "texto": "Pendant qu''''ils mangeaient, Jésus prit du pain; et, après avoir rendu grâces, il le rompit, et le donna aux disciples, en disant: Prenez, mangez, ceci est mon corps."}, {"numero": 27, "texto": "Il prit ensuite une coupe; et, après avoir rendu grâces, il la leur donna, en disant: Buvez-en tous;"}, {"numero": 28, "texto": "car ceci est mon sang, le sang de l''''alliance, qui est répandu pour plusieurs, pour la rémission des péchés."}, {"numero": 29, "texto": "Je vous le dis, je ne boirai plus désormais de ce fruit de la vigne, jusqu''''au jour où j''''en boirai du nouveau avec vous dans le royaume de mon Père."}, {"numero": 30, "texto": "Après avoir chanté les cantiques, ils se rendirent à la montagne des oliviers."}, {"numero": 31, "texto": "Alors Jésus leur dit: Je serai pour vous tous, cette nuit, une occasion de chute; car il est écrit: Je frapperai le berger, et les brebis du troupeau seront dispersées."}, {"numero": 32, "texto": "Mais, après que je serai ressuscité, je vous précèderai en Galilée."}, {"numero": 33, "texto": "Pierre, prenant la parole, lui dit: Quand tu serais pour tous une occasion de chute, tu ne le seras jamais pour moi."}, {"numero": 34, "texto": "Jésus lui dit: Je te le dis en vérité, cette nuit même, avant que le coq chante, tu me renieras trois fois."}, {"numero": 35, "texto": "Pierre lui répondit: Quand il me faudrait mourir avec toi, je ne te renierai pas. Et tous les disciples dirent la même chose."}, {"numero": 36, "texto": "Là-dessus, Jésus alla avec eux dans un lieu appelé Gethsémané, et il dit aux disciples: Asseyez-vous ici, pendant que je m''''éloignerai pour prier."}, {"numero": 37, "texto": "Il prit avec lui Pierre et les deux fils de Zébédée, et il commença à éprouver de la tristesse et des angoisses."}, {"numero": 38, "texto": "Il leur dit alors: Mon âme est triste jusqu''''à la mort; restez ici, et veillez avec moi."}, {"numero": 39, "texto": "Puis, ayant fait quelques pas en avant, il se jeta sur sa face, et pria ainsi: Mon Père, s''''il est possible, que cette coupe s''''éloigne de moi! Toutefois, non pas ce que je veux, mais ce que tu veux."}, {"numero": 40, "texto": "Et il vint vers les disciples, qu''''il trouva endormis, et il dit à Pierre: Vous n''''avez donc pu veiller une heure avec moi!"}, {"numero": 41, "texto": "Veillez et priez, afin que vous ne tombiez pas dans la tentation; l''''esprit est bien disposé, mais la chair est faible."}, {"numero": 42, "texto": "Il s''''éloigna une seconde fois, et pria ainsi: Mon Père, s''''il n''''est pas possible que cette coupe s''''éloigne sans que je la boive, que ta volonté soit faite!"}, {"numero": 43, "texto": "Il revint, et les trouva encore endormis; car leurs yeux étaient appesantis."}, {"numero": 44, "texto": "Il les quitta, et, s''''éloignant, il pria pour la troisième fois, répétant les mêmes paroles."}, {"numero": 45, "texto": "Puis il alla vers ses disciples, et leur dit: Vous dormez maintenant, et vous vous reposez! Voici, l''''heure est proche, et le Fils de l''''homme est livré aux mains des pécheurs."}, {"numero": 46, "texto": "Levez-vous, allons; voici, celui qui me livre s''''approche."}, {"numero": 47, "texto": "Comme il parlait encore, voici, Judas, l''''un des douze, arriva, et avec lui une foule nombreuse armée d''''épées et de bâtons, envoyée par les principaux sacrificateurs et par les anciens du peuple."}, {"numero": 48, "texto": "Celui qui le livrait leur avait donné ce signe: Celui que je baiserai, c''''est lui; saisissez-le."}, {"numero": 49, "texto": "Aussitôt, s''''approchant de Jésus, il dit: Salut, Rabbi! Et il le baisa."}, {"numero": 50, "texto": "Jésus lui dit: Mon ami, ce que tu es venu faire, fais-le. Alors ces gens s''''avancèrent, mirent la main sur Jésus, et le saisirent."}, {"numero": 51, "texto": "Et voici, un de ceux qui étaient avec Jésus étendit la main, et tira son épée; il frappa le serviteur du souverain sacrificateur, et lui emporta l''''oreille."}, {"numero": 52, "texto": "Alors Jésus lui dit: Remets ton épée à sa place; car tous ceux qui prendront l''''épée périront par l''''épée."}, {"numero": 53, "texto": "Penses-tu que je ne puisse pas invoquer mon Père, qui me donnerait à l''''instant plus de douze légions d''''anges?"}, {"numero": 54, "texto": "Comment donc s''''accompliraient les Ecritures, d''''après lesquelles il doit en être ainsi?"}, {"numero": 55, "texto": "En ce moment, Jésus dit à la foule: Vous êtes venus, comme après un brigand, avec des épées et des bâtons, pour vous emparer de moi. J''''étais tous les jours assis parmi vous, enseignant dans le temple, et vous ne m''''avez pas saisi."}, {"numero": 56, "texto": "Mais tout cela est arrivé afin que les écrits des prophètes fussent accomplis. Alors tous les disciples l''''abandonnèrent, et prirent la fuite."}, {"numero": 57, "texto": "Ceux qui avaient saisi Jésus l''''emmenèrent chez le souverain sacrificateur Caïphe, où les scribes et les anciens étaient assemblés."}, {"numero": 58, "texto": "Pierre le suivit de loin jusqu''''à la cour du souverain sacrificateur, y entra, et s''''assit avec les serviteurs, pour voir comment cela finirait."}, {"numero": 59, "texto": "Les principaux sacrificateurs et tout le sanhédrin cherchaient quelque faux témoignage contre Jésus, suffisant pour le faire mourir."}, {"numero": 60, "texto": "Mais ils n''''en trouvèrent point, quoique plusieurs faux témoins se fussent présentés. Enfin, il en vint deux,"}, {"numero": 61, "texto": "qui dirent: Celui-ci a dit: Je puis détruire le temple de Dieu, et le rebâtir en trois jours."}, {"numero": 62, "texto": "Le souverain sacrificateur se leva, et lui dit: Ne réponds-tu rien? Qu''''est-ce que ces hommes déposent contre toi?"}, {"numero": 63, "texto": "Jésus garda le silence. Et le souverain sacrificateur, prenant la parole, lui dit: Je t''''adjure, par le Dieu vivant, de nous dire si tu es le Christ, le Fils de Dieu."}, {"numero": 64, "texto": "Jésus lui répondit: Tu l''''as dit. De plus, je vous le déclare, vous verrez désormais le Fils de l''''homme assis à la droite de la puissance de Dieu, et venant sur les nuées du ciel."}, {"numero": 65, "texto": "Alors le souverain sacrificateur déchira ses vêtements, disant: Il a blasphémé! Qu''''avons-nous encore besoin de témoins? Voici, vous venez d''''entendre son blasphème."}, {"numero": 66, "texto": "Que vous en semble? Ils répondirent: Il mérite la mort."}, {"numero": 67, "texto": "Là-dessus, ils lui crachèrent au visage, et lui donnèrent des coups de poing et des soufflets"}, {"numero": 68, "texto": "en disant: Christ, prophétise; dis-nous qui t''''a frappé."}, {"numero": 69, "texto": "Cependant, Pierre était assis dehors dans la cour. Une servante s''''approcha de lui, et dit: Toi aussi, tu étais avec Jésus le Galiléen."}, {"numero": 70, "texto": "Mais il le nia devant tous, disant: Je ne sais ce que tu veux dire."}, {"numero": 71, "texto": "Comme il se dirigeait vers la porte, une autre servante le vit, et dit à ceux qui se trouvaient là; Celui-ci était aussi avec Jésus de Nazareth."}, {"numero": 72, "texto": "Il le nia de nouveau, avec serment: Je ne connais pas cet homme."}, {"numero": 73, "texto": "Peu après, ceux qui étaient là, s''''étant approchés, dirent à Pierre: Certainement tu es aussi de ces gens-là, car ton langage te fait reconnaître."}, {"numero": 74, "texto": "Alors il se mit à faire des imprécations et à jurer: Je ne connais pas cet homme. Aussitôt le coq chanta."}, {"numero": 75, "texto": "Et Pierre se souvint de la parole que Jésus avait dite: Avant que le coq chante, tu me renieras trois fois. Et étant sorti, il pleura amèrement."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 26, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que, como hubo acabado Jesús todas estas palabras, dijo á sus discípulos:"}, {"numero": 2, "texto": "Sabéis que dentro de dos días se hace la pascua, y el Hijo del hombre es entregado para ser crucificado."}, {"numero": 3, "texto": "Entonces los príncipes de los sacerdotes, y los escribas, y los ancianos del pueblo se juntaron al patio del pontífice, el cual se llamaba Caifás;"}, {"numero": 4, "texto": "Y tuvieron consejo para prender por engaño á Jesús, y matarle."}, {"numero": 5, "texto": "Y decían: No en el día de la fiesta, porque no se haga alboroto en el pueblo."}, {"numero": 6, "texto": "Y estando Jesús en Bethania, en casa de Simón el leproso,"}, {"numero": 7, "texto": "Vino á él una mujer, teniendo un vaso de alabastro de ungüento de gran precio, y lo derramó sobre la cabeza de él, estando sentado á la mesa."}, {"numero": 8, "texto": "Lo cual viendo sus discípulos, se enojaron, diciendo: ¿Por qué se pierde esto?"}, {"numero": 9, "texto": "Porque esto se podía vender por gran precio, y darse á los pobres."}, {"numero": 10, "texto": "Y entendiéndolo Jesús, les dijo: ¿Por qué dais pena á esta mujer? pues ha hecho conmigo buena obra."}, {"numero": 11, "texto": "Porque siempre tendréis pobres con vosotros, mas á mí no siempre me tendréis."}, {"numero": 12, "texto": "Porque echando este ungüento sobre mi cuerpo, para sepultarme lo ha hecho."}, {"numero": 13, "texto": "De cierto os digo, que donde quiera que este evangelio fuere predicado en todo el mundo, también será dicho para memoria de ella, lo que ésta ha hecho."}, {"numero": 14, "texto": "Entonces uno de los doce, que se llamaba Judas Iscariote, fué á los príncipes de los sacerdotes,"}, {"numero": 15, "texto": "Y les dijo: ¿Qué me queréis dar, y yo os lo entregaré? Y ellos le señalaron treinta piezas de plata."}, {"numero": 16, "texto": "Y desde entonces buscaba oportunidad para entregarle."}, {"numero": 17, "texto": "Y el primer día de la fiesta de los panes sin levadura, vinieron los discípulos á Jesús, diciéndole: ¿Dónde quieres que aderecemos para ti para comer la pascua?"}, {"numero": 18, "texto": "Y él dijo: Id á la ciudad á cierto hombre, y decidle: El Maestro dice: Mi tiempo está cerca; en tu casa haré la pascua con mis discípulos."}, {"numero": 19, "texto": "Y los discípulos hicieron como Jesús les mandó, y aderezaron la pascua."}, {"numero": 20, "texto": "Y como fué la tarde del día, se sentó á la mesa con los doce."}, {"numero": 21, "texto": "Y comiendo ellos, dijo: De cierto os digo, que uno de vosotros me ha de entregar."}, {"numero": 22, "texto": "Y entristecidos ellos en gran manera, comenzó cada uno de ellos á decirle: ¿Soy yo, Señor?"}, {"numero": 23, "texto": "Entonces él respondiendo, dijo: El que mete la mano conmigo en el plato, ése me ha de entregar."}, {"numero": 24, "texto": "A la verdad el Hijo del hombre va, como está escrito de él; mas ¡ay de aquel hombre por quien el Hijo del hombre es entregado! bueno le fuera al tal hombre no haber nacido."}, {"numero": 25, "texto": "Entonces respondiendo Judas, que le entregaba, dijo: ¿Soy yo, Maestro? Dícele: Tú lo has dicho."}, {"numero": 26, "texto": "Y comiendo ellos, tomó Jesús el pan, y bendijo, y lo partió, y dió á sus discípulos, y dijo: Tomad, comed: esto es mi cuerpo."}, {"numero": 27, "texto": "Y tomando el vaso, y hechas gracias, les dió, diciendo: Bebed de él todos;"}, {"numero": 28, "texto": "Porque esto es mi sangre del nuevo pacto, la cual es derramada por muchos para remisión de los pecados."}, {"numero": 29, "texto": "Y os digo, que desde ahora no beberé más de este fruto de la vid, hasta aquel día, cuando lo tengo de beber nuevo con vosotros en el reino de mi Padre."}, {"numero": 30, "texto": "Y habiendo cantado el himno, salieron al monte de las Olivas."}, {"numero": 31, "texto": "Entonces Jesús les dice: Todos vosotros seréis escandalizados en mí esta noche; porque escrito está: Heriré al Pastor, y las ovejas de la manada serán dispersas."}, {"numero": 32, "texto": "Mas después que haya resucitado, iré delante de vosotros á Galilea."}, {"numero": 33, "texto": "Y respondiendo Pedro, le dijo: Aunque todos sean escandalizados en ti, yo nunca seré escandalizado."}, {"numero": 34, "texto": "Jesús le dice: De cierto te digo que esta noche, antes que el gallo cante, me negarás tres veces."}, {"numero": 35, "texto": "Dícele Pedro: Aunque me sea menester morir contigo, no te negaré. Y todos los discípulos dijeron lo mismo."}, {"numero": 36, "texto": "Entonces llegó Jesús con ellos á la aldea que se llama Gethsemaní, y dice á sus discípulos: Sentaos aquí, hasta que vaya allí y ore."}, {"numero": 37, "texto": "Y tomando á Pedro, y á los dos hijos de Zebedeo, comenzó á entristecerse y á angustiarse en gran manera."}, {"numero": 38, "texto": "Entonces Jesús les dice: Mi alma está muy triste hasta la muerte; quedaos aquí, y velad conmigo."}, {"numero": 39, "texto": "Y yéndose un poco más adelante, se postró sobre su rostro, orando, y diciendo: Padre mío, si es posible, pase de mí este vaso; empero no como yo quiero, sino como tú."}, {"numero": 40, "texto": "Y vino á sus discípulos, y los halló durmiendo, y dijo á Pedro: ¿Así no habéis podido velar conmigo una hora?"}, {"numero": 41, "texto": "Velad y orad, para que no entréis en tentación: el espíritu á la verdad está presto, mas la carne enferma."}, {"numero": 42, "texto": "Otra vez fué, segunda vez, y oró diciendo: Padre mío, si no puede este vaso pasar de mí sin que yo lo beba, hágase tu voluntad."}, {"numero": 43, "texto": "Y vino, y los halló otra vez durmiendo; porque los ojos de ellos estaban agravados."}, {"numero": 44, "texto": "Y dejándolos fuése de nuevo, y oró tercera vez, diciendo las mismas palabras."}, {"numero": 45, "texto": "Entonces vino á sus discípulos y díceles: Dormid ya, y descansad: he aquí ha llegado la hora, y el Hijo del hombre es entregado en manos de pecadores."}, {"numero": 46, "texto": "Levantaos, vamos: he aquí ha llegado el que me ha entregado."}, {"numero": 47, "texto": "Y hablando aún él, he aquí Judas, uno de los doce, vino, y con él mucha gente con espadas y con palos, de parte de los príncipes de los sacerdotes, y de los ancianos del pueblo."}, {"numero": 48, "texto": "Y el que le entregaba les había dado señal, diciendo: Al que yo besare, aquél es: prendedle."}, {"numero": 49, "texto": "Y luego que llegó á Jesús, dijo: Salve, Maestro. Y le besó."}, {"numero": 50, "texto": "Y Jesús le dijo: Amigo, ¿á qué vienes? Entonces llegaron, y echaron mano á Jesús, y le prendieron."}, {"numero": 51, "texto": "Y he aquí, uno de los que estaban con Jesús, extendiendo la mano, sacó su espada, é hiriendo á un siervo del pontífice, le quitó la oreja."}, {"numero": 52, "texto": "Entonces Jesús le dice: Vuelve tu espada á su lugar; porque todos los que tomaren espada, á espada perecerán."}, {"numero": 53, "texto": "¿Acaso piensas que no puedo ahora orar á mi Padre, y él me daría más de doce legiones de ángeles?"}, {"numero": 54, "texto": "¿Cómo, pues, se cumplirían las Escrituras, que así conviene que sea hecho?"}, {"numero": 55, "texto": "En aquella hora dijo Jesús á las gentes: ¿Como á ladrón habéis salido con espadas y con palos á prenderme? Cada día me sentaba con vosotros enseñando en el templo, y no me prendisteis."}, {"numero": 56, "texto": "Mas todo esto se hace, para que se cumplan las Escrituras de los profetas. Entonces todos los discípulos huyeron, dejándole."}, {"numero": 57, "texto": "Y ellos, prendido Jesús, le llevaron á Caifás pontífice, donde los escribas y los ancianos estaban juntos."}, {"numero": 58, "texto": "Mas Pedro le seguía de lejos hasta el patio del pontífice; y entrando dentro, estábase sentado con los criados, para ver el fin."}, {"numero": 59, "texto": "Y los príncipes de los sacerdotes, y los ancianos, y todo el consejo, buscaban falso testimonio contra Jesús, para entregarle á la muerte;"}, {"numero": 60, "texto": "Y no lo hallaron, aunque muchos testigos falsos se llegaban; mas á la postre vinieron dos testigos falsos,"}, {"numero": 61, "texto": "Que dijeron: Este dijo: Puedo derribar el templo de Dios, y en tres días reedificarlo."}, {"numero": 62, "texto": "Y levantándose el pontífice, le dijo: ¿No respondes nada? ¿qué testifican éstos contra ti?"}, {"numero": 63, "texto": "Mas Jesús callaba. Respondiendo el pontífice, le dijo: Te conjuro por el Dios viviente, que nos digas si eres tú el Cristo, Hijo de Dios."}, {"numero": 64, "texto": "Jesús le dijo: Tú lo has dicho: y aun os digo, que desde ahora habéis de ver al Hijo del hombre sentado á la diestra de la potencia de Dios, y que viene en las nubes del cielo."}, {"numero": 65, "texto": "Entonces el pontífice rasgó sus vestidos, diciendo: Blasfemado ha: ¿qué más necesidad tenemos de testigos? He aquí, ahora habéis oído su blasfemia."}, {"numero": 66, "texto": "¿Qué os parece? Y respondiendo ellos, dijeron: Culpado es de muerte."}, {"numero": 67, "texto": "Entonces le escupieron en el rostro, y le dieron de bofetadas; y otros le herían con mojicones,"}, {"numero": 68, "texto": "Diciendo: Profetízanos tú, Cristo, quién es el que te ha herido."}, {"numero": 69, "texto": "Y Pedro estaba sentado fuera en el patio: y se llegó á él una criada, diciendo: Y tú con Jesús el Galileo estabas."}, {"numero": 70, "texto": "Mas él negó delante de todos, diciendo: No sé lo que dices."}, {"numero": 71, "texto": "Y saliendo él á la puerta, le vió otra, y dijo á los que estaban allí: También éste estaba con Jesús Nazareno."}, {"numero": 72, "texto": "Y negó otra vez con juramento: No conozco al hombre."}, {"numero": 73, "texto": "Y un poco después llegaron los que estaban por allí, y dijeron á Pedro: Verdaderamente también tú eres de ellos, porque aun tu habla te hace manifiesto."}, {"numero": 74, "texto": "Entonces comenzó á hacer imprecaciones, y á jurar, diciendo: No conozco al hombre. Y el gallo cantó luego."}, {"numero": 75, "texto": "Y se acordó Pedro de las palabras de Jesús, que le dijo: Antes que cante el gallo, me negarás tres veces. Y saliéndose fuera, lloró amargamente."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 27, 'pt', '[{"numero": 1, "texto": "Vinda a manhã, todos os chefes dos sacerdotes e anciãos do povo juntamente se aconselharam contra Jesus, para o matarem."}, {"numero": 2, "texto": "E o levaram amarrado, e o entregaram a Pôncio Pilatos, o governador."}, {"numero": 3, "texto": "Então Judas, o que o havia traído, ao ver que [Jesus] já estava condenado, devolveu, sentindo remorso, as trinta [moedas] de prata aos chefes dos sacerdotes e aos anciãos;"}, {"numero": 4, "texto": "e disse: Pequei, traindo sangue inocente. Porém eles disseram: Que nos interessa? Isso é problema teu!"}, {"numero": 5, "texto": "Então ele lançou as [moedas] de prata no templo, saiu, e foi enforcar-se."}, {"numero": 6, "texto": "Os chefes dos sacerdotes tomaram as [moedas] de prata, e disseram: Não é lícito pô-las no tesouro das ofertas, pois isto é preço de sangue."}, {"numero": 7, "texto": "Então juntamente se aconselharam, e compraram com elas o campo do oleiro, para ser cemitério dos estrangeiros."}, {"numero": 8, "texto": "Por isso aquele campo tem sido chamado campo de sangue até hoje."}, {"numero": 9, "texto": "Assim se cumpriu o que foi dito pelo profeta Jeremias, que disse: Tomaram as trinta [moedas] de prata, preço avaliado pelos filhos de Israel, o qual eles avaliaram;"}, {"numero": 10, "texto": "e as deram pelo campo do oleiro, conforme o que o Senhor me mandou."}, {"numero": 11, "texto": "Jesus esteve diante do governador, e o governador lhe perguntou: És tu o Rei dos Judeus? E Jesus lhe respondeu: Tu [o] dizes."}, {"numero": 12, "texto": "E, sendo ele foi acusado pelos chefes dos sacerdotes e pelos anciãos, nada respondeu."}, {"numero": 13, "texto": "Pilatos, então, lhe disse: Não ouves quantas coisas estão testemunhando contra ti?"}, {"numero": 14, "texto": "Mas [Jesus] não lhe respondeu uma só palavra, de maneira que o governador ficou muito maravilhado."}, {"numero": 15, "texto": "Na festa o governador costuma soltar um preso ao povo, qualquer um que quisessem."}, {"numero": 16, "texto": "E tinham então um preso bem conhecido, chamado Barrabás."}, {"numero": 17, "texto": "Quando, pois, se ajuntaram, Pilatos lhes perguntou: Qual quereis que vos solte? Barrabás, ou Jesus, que é chamado Cristo?"}, {"numero": 18, "texto": "Pois ele sabia que foi por inveja que o entregaram."}, {"numero": 19, "texto": "E, enquanto ele estava sentado no assento de juiz, sua mulher lhe enviou a seguinte mensagem: Nada [faças] com aquele justo, pois hoje sofri muito em sonhos por causa dele."}, {"numero": 20, "texto": "Mas os chefes dos sacerdotes e os anciãos persuadiram as multidões a pedirem Barrabás, e a exigirem a morte de Jesus."}, {"numero": 21, "texto": "O governador lhes perguntou: Qual destes dois quereis que vos solte? E responderam: Barrabás!"}, {"numero": 22, "texto": "Pilatos lhes disse: Que, pois, farei de Jesus, que é chamado Cristo? Todos lhe disseram: Seja crucificado!"}, {"numero": 23, "texto": "E o governador perguntou: Ora, que mal ele fez? Porém gritavam mais: Seja crucificado!"}, {"numero": 24, "texto": "Quando, pois, Pilatos viu que nada adiantava, em vez disso se fazia mais tumulto, ele pegou água, lavou as mãos diante da multidão, e disse: Estou inocente do sangue deste justo. A responsabilidade é vossa."}, {"numero": 25, "texto": "E todo o povo respondeu: O sangue dele [venha] sobre nós, e sobre os nossos filhos."}, {"numero": 26, "texto": "Então soltou-lhes Barrabás, enquanto que mandou açoitar Jesus, e o entregou para ser crucificado."}, {"numero": 27, "texto": "Em seguida, os soldados do governador levaram Jesus consigo ao pretório, ajuntaram-se a ele toda a unidade miltar."}, {"numero": 28, "texto": "Eles o despiram e o cobriram com um manto vermelho."}, {"numero": 29, "texto": "E, depois de tecerem uma coroa de espinhos, puseram-na sobre a sua cabeça, e uma cana em sua mão direita. Em seguida, puseram-se de joelhos diante dele, zombando-o, e diziam: Felicitações, Rei dos Judeus!"}, {"numero": 30, "texto": "E cuspiram nele, tomaram a cana, e deram-lhe golpes na cabeça."}, {"numero": 31, "texto": "Depois de terem o zombado, despiram-lhe a capa, vestiram-no com suas roupas, e o levaram para crucificar."}, {"numero": 32, "texto": "Ao saírem, encontraram um homem de Cirene, por nome Simão; e obrigaram-no a levar sua cruz."}, {"numero": 33, "texto": "E quando chegaram ao lugar chamado Gólgota, que significa “o lugar da caveira”,"}, {"numero": 34, "texto": "deram-lhe de beber vinagre misturado com fel. E, depois de provar, não quis beber."}, {"numero": 35, "texto": "E havendo-o crucificado, repartiram suas roupas, lançando sortes; para que se cumprisse o que foi dito pelo profeta: Repartiram entre si minhas roupas, e sobre minha túnica lançaram sortes."}, {"numero": 36, "texto": "Então se sentaram, e ali o vigiavam."}, {"numero": 37, "texto": "E puseram, por cima de sua cabeça, sua acusação escrita: ESTE É JESUS, O REI DOS JUDEUS."}, {"numero": 38, "texto": "Então foram crucificados com ele dois criminosos, um à direita, e outro à esquerda."}, {"numero": 39, "texto": "Os que passavam blasfemavam dele, balançando suas cabeças,"}, {"numero": 40, "texto": "e dizendo: Tu, que derrubas o Templo, e em três dias o reconstróis, salva a ti mesmo! Se és Filho de Deus, desce da cruz."}, {"numero": 41, "texto": "E da mesma maneira também os chefes dos sacerdotes, com os escribas e os anciãos, escarnecendo [dele] ,diziam:"}, {"numero": 42, "texto": "Salvou outros, a si mesmo não pode salvar. Se é Rei de Israel, desça agora da cruz, e creremos nele."}, {"numero": 43, "texto": "Confiou em Deus, livre-o agora, se lhe quer bem; pois disse: “Sou Filho de Deus”."}, {"numero": 44, "texto": "E os ladrões que estavam crucificados com ele também lhe insultavam."}, {"numero": 45, "texto": "Desde a hora sexta houve trevas sobre toda a terra até a hora nona."}, {"numero": 46, "texto": "E perto da hora nona, Jesus gritou em alta voz: Eli, Eli, lamá sabactâni?, Isto é: Deus meu, Deus meu, porque me desamparaste?"}, {"numero": 47, "texto": "E alguns dos que ali estavam, quando ouviram, disseram: Ele está chamando Elias."}, {"numero": 48, "texto": "Logo um deles correu e tomou uma esponja. Então a encheu de vinagre, colocou-a em uma cana, e lhe dava de beber."}, {"numero": 49, "texto": "Porém os outros disseram: Deixa, vejamos se Elias vem livrá-lo."}, {"numero": 50, "texto": "Jesus gritou outra vez em alta voz, e entregou o espírito."}, {"numero": 51, "texto": "E eis que o véu do Templo se rasgou em dois, de cima até embaixo, a terra tremeu, e as pedras se fenderam."}, {"numero": 52, "texto": "Os sepulcros se abriram, e muitos corpos de santos que tinham morrido foram ressuscitados."}, {"numero": 53, "texto": "E, depois de ressuscitarem, saíram dos sepulcros, vieram à santa cidade, e apareceram a muitos."}, {"numero": 54, "texto": "E o centurião, e os que com ele vigiavam Jesus, ao verem o terremoto e as coisas que haviam sucedido, tiveram muito medo, e disseram: Verdadeiramente ele era Filho de Deus."}, {"numero": 55, "texto": "Muitas mulheres, que desde a Galileia haviam seguido Jesus, e o serviam, estavam ali, olhando de longe."}, {"numero": 56, "texto": "Entre elas estavam Maria Madalena, e Maria mãe de Tiago e de José, e a mãe dos filhos de Zebedeu."}, {"numero": 57, "texto": "E chegado o entardecer, veio um homem rico de Arimateia, por nome José, que também era discípulo de Jesus."}, {"numero": 58, "texto": "Ele chegou a Pilatos, e pediu o corpo de Jesus. Então Pilatos mandou que o corpo [lhe] fosse entregue."}, {"numero": 59, "texto": "José tomou o corpo, e o envolveu em um lençol limpo, de linho fino,"}, {"numero": 60, "texto": "e o pôs em seu sepulcro novo, que tinha escavado numa rocha; em seguida rolou uma grande pedra à porta do sepulcro, e foi embora."}, {"numero": 61, "texto": "E ali estavam Maria Madalena e a outra Maria, sentadas de frente ao sepulcro."}, {"numero": 62, "texto": "No dia seguinte, que é o depois da preparação, os chefes dos sacerdotes, e os fariseus se reuniram com Pilatos,"}, {"numero": 63, "texto": "e disseram: Senhor, nos lembramos que aquele enganador, enquanto ainda vivia, disse: “Depois de três dias serei ressuscitado”."}, {"numero": 64, "texto": "Portanto, manda que o sepulcro esteja em segurança até o terceiro dia, para que não aconteça dos seus discípulos virem de noite, e o furtem, e digam ao povo que ele ressuscitou dos mortos; e [assim] o último engano será pior que o primeiro."}, {"numero": 65, "texto": "Pilatos lhes disse: Vós tendes uma guarda. Ide fazer segurança como o entendeis."}, {"numero": 66, "texto": "E eles se foram, e fizeram segurança no sepulcro com a guarda, selando a pedra."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 27, 'en', '[{"numero": 1, "texto": "When the morning was come, all the chief priests and elders of the people took counsel against Jesus to put him to death:"}, {"numero": 2, "texto": "And when they had bound him, they led him away, and delivered him to Pontius Pilate the governor."}, {"numero": 3, "texto": "Then Judas, which had betrayed him, when he saw that he was condemned, repented himself, and brought again the thirty pieces of silver to the chief priests and elders,"}, {"numero": 4, "texto": "Saying, I have sinned in that I have betrayed the innocent blood. And they said, What is that to us? see thou to that."}, {"numero": 5, "texto": "And he cast down the pieces of silver in the temple, and departed, and went and hanged himself."}, {"numero": 6, "texto": "And the chief priests took the silver pieces, and said, It is not lawful for to put them into the treasury, because it is the price of blood."}, {"numero": 7, "texto": "And they took counsel, and bought with them the potter''s field, to bury strangers in."}, {"numero": 8, "texto": "Wherefore that field was called, The field of blood, unto this day."}, {"numero": 9, "texto": "Then was fulfilled that which was spoken by Jeremy the prophet, saying, And they took the thirty pieces of silver, the price of him that was valued, whom they of the children of Israel did value;"}, {"numero": 10, "texto": "And gave them for the potter''s field, as the Lord appointed me."}, {"numero": 11, "texto": "And Jesus stood before the governor: and the governor asked him, saying, Art thou the King of the Jews? And Jesus said unto him, Thou sayest."}, {"numero": 12, "texto": "And when he was accused of the chief priests and elders, he answered nothing."}, {"numero": 13, "texto": "Then said Pilate unto him, Hearest thou not how many things they witness against thee?"}, {"numero": 14, "texto": "And he answered him to never a word; insomuch that the governor marvelled greatly."}, {"numero": 15, "texto": "Now at that feast the governor was wont to release unto the people a prisoner, whom they would."}, {"numero": 16, "texto": "And they had then a notable prisoner, called Barabbas."}, {"numero": 17, "texto": "Therefore when they were gathered together, Pilate said unto them, Whom will ye that I release unto you? Barabbas, or Jesus which is called Christ?"}, {"numero": 18, "texto": "For he knew that for envy they had delivered him."}, {"numero": 19, "texto": "When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him."}, {"numero": 20, "texto": "But the chief priests and elders persuaded the multitude that they should ask Barabbas, and destroy Jesus."}, {"numero": 21, "texto": "The governor answered and said unto them, Whether of the twain will ye that I release unto you? They said, Barabbas."}, {"numero": 22, "texto": "Pilate saith unto them, What shall I do then with Jesus which is called Christ? They all say unto him, Let him be crucified."}, {"numero": 23, "texto": "And the governor said, Why, what evil hath he done? But they cried out the more, saying, Let him be crucified."}, {"numero": 24, "texto": "When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it."}, {"numero": 25, "texto": "Then answered all the people, and said, His blood be on us, and on our children."}, {"numero": 26, "texto": "Then released he Barabbas unto them: and when he had scourged Jesus, he delivered him to be crucified."}, {"numero": 27, "texto": "Then the soldiers of the governor took Jesus into the common hall, and gathered unto him the whole band of soldiers."}, {"numero": 28, "texto": "And they stripped him, and put on him a scarlet robe."}, {"numero": 29, "texto": "And when they had platted a crown of thorns, they put it upon his head, and a reed in his right hand: and they bowed the knee before him, and mocked him, saying, Hail, King of the Jews!"}, {"numero": 30, "texto": "And they spit upon him, and took the reed, and smote him on the head."}, {"numero": 31, "texto": "And after that they had mocked him, they took the robe off from him, and put his own raiment on him, and led him away to crucify him."}, {"numero": 32, "texto": "And as they came out, they found a man of Cyrene, Simon by name: him they compelled to bear his cross."}, {"numero": 33, "texto": "And when they were come unto a place called Golgotha, that is to say, a place of a skull,"}, {"numero": 34, "texto": "They gave him vinegar to drink mingled with gall: and when he had tasted thereof, he would not drink."}, {"numero": 35, "texto": "And they crucified him, and parted his garments, casting lots: that it might be fulfilled which was spoken by the prophet, They parted my garments among them, and upon my vesture did they cast lots."}, {"numero": 36, "texto": "And sitting down they watched him there;"}, {"numero": 37, "texto": "And set up over his head his accusation written, This Is Jesus The King Of The Jews."}, {"numero": 38, "texto": "Then were there two thieves crucified with him, one on the right hand, and another on the left."}, {"numero": 39, "texto": "And they that passed by reviled him, wagging their heads,"}, {"numero": 40, "texto": "And saying, Thou that destroyest the temple, and buildest it in three days, save thyself. If thou be the Son of God, come down from the cross."}, {"numero": 41, "texto": "Likewise also the chief priests mocking him, with the scribes and elders, said,"}, {"numero": 42, "texto": "He saved others; himself he cannot save. If he be the King of Israel, let him now come down from the cross, and we will believe him."}, {"numero": 43, "texto": "He trusted in God; let him deliver him now, if he will have him: for he said, I am the Son of God."}, {"numero": 44, "texto": "The thieves also, which were crucified with him, cast the same in his teeth."}, {"numero": 45, "texto": "Now from the sixth hour there was darkness over all the land unto the ninth hour."}, {"numero": 46, "texto": "And about the ninth hour Jesus cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My God, my God, why hast thou forsaken me?"}, {"numero": 47, "texto": "Some of them that stood there, when they heard that, said, This man calleth for Elias."}, {"numero": 48, "texto": "And straightway one of them ran, and took a spunge, and filled it with vinegar, and put it on a reed, and gave him to drink."}, {"numero": 49, "texto": "The rest said, Let be, let us see whether Elias will come to save him."}, {"numero": 50, "texto": "Jesus, when he had cried again with a loud voice, yielded up the ghost."}, {"numero": 51, "texto": "And, behold, the veil of the temple was rent in twain from the top to the bottom; and the earth did quake, and the rocks rent;"}, {"numero": 52, "texto": "And the graves were opened; and many bodies of the saints which slept arose,"}, {"numero": 53, "texto": "And came out of the graves after his resurrection, and went into the holy city, and appeared unto many."}, {"numero": 54, "texto": "Now when the centurion, and they that were with him, watching Jesus, saw the earthquake, and those things that were done, they feared greatly, saying, Truly this was the Son of God."}, {"numero": 55, "texto": "And many women were there beholding afar off, which followed Jesus from Galilee, ministering unto him:"}, {"numero": 56, "texto": "Among which was Mary Magdalene, and Mary the mother of James and Joses, and the mother of Zebedees children."}, {"numero": 57, "texto": "When the even was come, there came a rich man of Arimathaea, named Joseph, who also himself was Jesus'' disciple:"}, {"numero": 58, "texto": "He went to Pilate, and begged the body of Jesus. Then Pilate commanded the body to be delivered."}, {"numero": 59, "texto": "And when Joseph had taken the body, he wrapped it in a clean linen cloth,"}, {"numero": 60, "texto": "And laid it in his own new tomb, which he had hewn out in the rock: and he rolled a great stone to the door of the sepulchre, and departed."}, {"numero": 61, "texto": "And there was Mary Magdalene, and the other Mary, sitting over against the sepulchre."}, {"numero": 62, "texto": "Now the next day, that followed the day of the preparation, the chief priests and Pharisees came together unto Pilate,"}, {"numero": 63, "texto": "Saying, Sir, we remember that that deceiver said, while he was yet alive, After three days I will rise again."}, {"numero": 64, "texto": "Command therefore that the sepulchre be made sure until the third day, lest his disciples come by night, and steal him away, and say unto the people, He is risen from the dead: so the last error shall be worse than the first."}, {"numero": 65, "texto": "Pilate said unto them, Ye have a watch: go your way, make it as sure as ye can."}, {"numero": 66, "texto": "So they went, and made the sepulchre sure, sealing the stone, and setting a watch."}]'::jsonb, 'King James Version'),
  ('Mt', 27, 'fr', '[{"numero": 1, "texto": "Dès que le matin fut venu, tous les principaux sacrificateurs et les anciens du peuple tinrent conseil contre Jésus, pour le faire mourir."}, {"numero": 2, "texto": "Après l''''avoir lié, ils l''''emmenèrent, et le livrèrent à Ponce Pilate, le gouverneur."}, {"numero": 3, "texto": "Alors Judas, qui l''''avait livré, voyant qu''''il était condamné, se repentit, et rapporta les trente pièces d''''argent aux principaux sacrificateurs et aux anciens,"}, {"numero": 4, "texto": "en disant: J''''ai péché, en livrant le sang innocent. Ils répondirent: Que nous importe? Cela te regarde."}, {"numero": 5, "texto": "Judas jeta les pièces d''''argent dans le temple, se retira, et alla se pendre."}, {"numero": 6, "texto": "Les principaux sacrificateurs les ramassèrent, et dirent: Il n''''est pas permis de les mettre dans le trésor sacré, puisque c''''est le prix du sang."}, {"numero": 7, "texto": "Et, après en avoir délibéré, ils achetèrent avec cet argent le champ du potier, pour la sépulture des étrangers."}, {"numero": 8, "texto": "C''''est pourquoi ce champ a été appelé champ du sang, jusqu''''à ce jour."}, {"numero": 9, "texto": "Alors s''''accomplit ce qui avait été annoncé par Jérémie, le prophète: Ils ont pris les trente pièces d''''argent, la valeur de celui qui a été estimé, qu''''on a estimé de la part des enfants d''''Israël;"}, {"numero": 10, "texto": "et ils les ont données pour le champ du potier, comme le Seigneur me l''''avait ordonné."}, {"numero": 11, "texto": "Jésus comparut devant le gouverneur. Le gouverneur l''''interrogea, en ces termes: Es-tu le roi des Juifs? Jésus lui répondit: Tu le dis."}, {"numero": 12, "texto": "Mais il ne répondit rien aux accusations des principaux sacrificateurs et des anciens."}, {"numero": 13, "texto": "Alors Pilate lui dit: N''''entends-tu pas de combien de choses ils t''''accusent?"}, {"numero": 14, "texto": "Et Jésus ne lui donna de réponse sur aucune parole, ce qui étonna beaucoup le gouverneur."}, {"numero": 15, "texto": "A chaque fête, le gouverneur avait coutume de relâcher un prisonnier, celui que demandait la foule."}, {"numero": 16, "texto": "Ils avaient alors un prisonnier fameux, nommé Barabbas."}, {"numero": 17, "texto": "Comme ils étaient assemblés, Pilate leur dit: Lequel voulez-vous que je vous relâche, Barabbas, ou Jésus, qu''''on appelle Christ?"}, {"numero": 18, "texto": "Car il savait que c''''était par envie qu''''ils avaient livré Jésus."}, {"numero": 19, "texto": "Pendant qu''''il était assis sur le tribunal, sa femme lui fit dire: Qu''''il n''''y ait rien entre toi et ce juste; car aujourd''''hui j''''ai beaucoup souffert en songe à cause de lui."}, {"numero": 20, "texto": "Les principaux sacrificateurs et les anciens persuadèrent à la foule de demander Barabbas, et de faire périr Jésus."}, {"numero": 21, "texto": "Le gouverneur prenant la parole, leur dit: Lequel des deux voulez-vous que je vous relâche? Ils répondirent: Barabbas."}, {"numero": 22, "texto": "Pilate leur dit: Que ferai-je donc de Jésus, qu''''on appelle Christ? Tous répondirent: Qu''''il soit crucifié!"}, {"numero": 23, "texto": "Le gouverneur dit: Mais quel mal a-t-il fait? Et ils crièrent encore plus fort: Qu''''il soit crucifié!"}, {"numero": 24, "texto": "Pilate, voyant qu''''il ne gagnait rien, mais que le tumulte augmentait, prit de l''''eau, se lava les mains en présence de la foule, et dit: Je suis innocent du sang de ce juste. Cela vous regarde."}, {"numero": 25, "texto": "Et tout le peuple répondit: Que son sang retombe sur nous et sur nos enfants!"}, {"numero": 26, "texto": "Alors Pilate leur relâcha Barabbas; et, après avoir fait battre de verges Jésus, il le livra pour être crucifié."}, {"numero": 27, "texto": "Les soldats du gouverneur conduisirent Jésus dans le prétoire, et ils assemblèrent autour de lui toute la cohorte."}, {"numero": 28, "texto": "Ils lui ôtèrent ses vêtements, et le couvrirent d''''un manteau écarlate."}, {"numero": 29, "texto": "Ils tressèrent une couronne d''''épines, qu''''ils posèrent sur sa tête, et ils lui mirent un roseau dans la main droite; puis, s''''agenouillant devant lui, ils le raillaient, en disant: Salut, roi des Juifs!"}, {"numero": 30, "texto": "Et ils crachaient contre lui, prenaient le roseau, et frappaient sur sa tête."}, {"numero": 31, "texto": "Après s''''être ainsi moqués de lui, ils lui ôtèrent le manteau, lui remirent ses vêtements, et l''''emmenèrent pour le crucifier."}, {"numero": 32, "texto": "Lorsqu''''ils sortirent, ils rencontrèrent un homme de Cyrène, appelé Simon, et ils le forcèrent à porter la croix de Jésus."}, {"numero": 33, "texto": "Arrivés au lieu nommé Golgotha, ce qui signifie lieu du crâne,"}, {"numero": 34, "texto": "ils lui donnèrent à boire du vin mêlé de fiel; mais, quand il l''''eut goûté, il ne voulut pas boire."}, {"numero": 35, "texto": "Après l''''avoir crucifié, ils se partagèrent ses vêtements, en tirant au sort, afin que s''''accomplît ce qui avait été annoncé par le prophète: Ils se sont partagé mes vêtements, et ils ont tiré au sort ma tunique."}, {"numero": 36, "texto": "Puis ils s''''assirent, et le gardèrent."}, {"numero": 37, "texto": "Pour indiquer le sujet de sa condamnation, on écrivit au-dessus de sa tête: Celui-ci est Jésus, le roi des Juifs."}, {"numero": 38, "texto": "Avec lui furent crucifiés deux brigands, l''''un à sa droite, et l''''autre à sa gauche."}, {"numero": 39, "texto": "Les passants l''''injuriaient, et secouaient la tête,"}, {"numero": 40, "texto": "en disant: Toi qui détruis le temple, et qui le rebâtis en trois jours, sauve-toi toi-même! Si tu es le Fils de Dieu, descends de la croix!"}, {"numero": 41, "texto": "Les principaux sacrificateurs, avec les scribes et les anciens, se moquaient aussi de lui, et disaient:"}, {"numero": 42, "texto": "Il a sauvé les autres, et il ne peut se sauver lui-même! S''''il est roi d''''Israël, qu''''il descende de la croix, et nous croirons en lui."}, {"numero": 43, "texto": "Il s''''est confié en Dieu; que Dieu le délivre maintenant, s''''il l''''aime. Car il a dit: Je suis Fils de Dieu."}, {"numero": 44, "texto": "Les brigands, crucifiés avec lui, l''''insultaient de la même manière."}, {"numero": 45, "texto": "Depuis la sixième heure jusqu''''à la neuvième, il y eut des ténèbres sur toute la terre."}, {"numero": 46, "texto": "Et vers la neuvième heure, Jésus s''''écria d''''une voix forte: Eli, Eli, lama sabachthani? c''''est-à-dire: Mon Dieu, mon Dieu, pourquoi m''''as-tu abandonné?"}, {"numero": 47, "texto": "Quelques-uns de ceux qui étaient là, l''''ayant entendu, dirent: Il appelle Elie."}, {"numero": 48, "texto": "Et aussitôt l''''un d''''eux courut prendre une éponge, qu''''il remplit de vinaigre, et, l''''ayant fixée à un roseau, il lui donna à boire."}, {"numero": 49, "texto": "Mais les autres disaient: Laisse, voyons si Elie viendra le sauver."}, {"numero": 50, "texto": "Jésus poussa de nouveau un grand cri, et rendit l''''esprit."}, {"numero": 51, "texto": "Et voici, le voile du temple se déchira en deux, depuis le haut jusqu''''en bas, la terre trembla, les rochers se fendirent,"}, {"numero": 52, "texto": "les sépulcres s''''ouvrirent, et plusieurs corps des saints qui étaient morts ressuscitèrent."}, {"numero": 53, "texto": "Etant sortis des sépulcres, après la résurrection de Jésus, ils entrèrent dans la ville sainte, et apparurent à un grand nombre de personnes."}, {"numero": 54, "texto": "Le centenier et ceux qui étaient avec lui pour garder Jésus, ayant vu le tremblement de terre et ce qui venait d''''arriver, furent saisis d''''une grande frayeur, et dirent: Assurément, cet homme était Fils de Dieu."}, {"numero": 55, "texto": "Il y avait là plusieurs femmes qui regardaient de loin; qui avaient accompagné Jésus depuis la Galilée, pour le servir."}, {"numero": 56, "texto": "Parmi elles étaient Marie de Magdala, Marie, mère de Jacques et de Joseph, et la mère des fils de Zébédée."}, {"numero": 57, "texto": "Le soir étant venu, arriva un homme riche d''''Arimathée, nommé Joseph, lequel était aussi disciple de Jésus."}, {"numero": 58, "texto": "Il se rendit vers Pilate, et demanda le corps de Jésus. Et Pilate ordonna de le remettre."}, {"numero": 59, "texto": "Joseph prit le corps, l''''enveloppa d''''un linceul blanc,"}, {"numero": 60, "texto": "et le déposa dans un sépulcre neuf, qu''''il s''''était fait tailler dans le roc. Puis il roula une grande pierre à l''''entrée du sépulcre, et il s''''en alla."}, {"numero": 61, "texto": "Marie de Magdala et l''''autre Marie étaient là, assises vis-à-vis du sépulcre."}, {"numero": 62, "texto": "Le lendemain, qui était le jour après la préparation, les principaux sacrificateurs et les pharisiens allèrent ensemble auprès de Pilate,"}, {"numero": 63, "texto": "et dirent: Seigneur, nous nous souvenons que cet imposteur a dit, quand il vivait encore: Après trois jours je ressusciterai."}, {"numero": 64, "texto": "Ordonne donc que le sépulcre soit gardé jusqu''''au troisième jour, afin que ses disciples ne viennent pas dérober le corps, et dire au peuple: Il est ressuscité des morts. Cette dernière imposture serait pire que la première."}, {"numero": 65, "texto": "Pilate leur dit: Vous avez une garde; allez, gardez-le comme vous l''''entendrez."}, {"numero": 66, "texto": "Ils s''''en allèrent, et s''''assurèrent du sépulcre au moyen de la garde, après avoir scellé la pierre."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 27, 'es', '[{"numero": 1, "texto": "Y VENIDA la mañana, entraron en consejo todos los príncipes de los sacerdotes, y los ancianos del pueblo, contra Jesús, para entregarle á muerte."}, {"numero": 2, "texto": "Y le llevaron atado, y le entregaron á Poncio Pilato presidente."}, {"numero": 3, "texto": "Entonces Judas, el que le había entregado, viendo que era condenado, volvió arrepentido las treinta piezas de plata á los príncipes de los sacerdotes y á los ancianos,"}, {"numero": 4, "texto": "Diciendo: Yo he pecado entregando la sangre inocente. Mas ellos dijeron: ¿Qué se nos da á nosotros? Viéraslo tú."}, {"numero": 5, "texto": "Y arrojando las piezas de plata en el templo, partióse; y fué, y se ahorcó."}, {"numero": 6, "texto": "Y los príncipes de los sacerdotes, tomando las piezas de plata, dijeron: No es lícito echarlas en el tesoro de los dones, porque es precio de sangre."}, {"numero": 7, "texto": "Mas habido consejo, compraron con ellas el campo del alfarero, por sepultura para los extranjeros."}, {"numero": 8, "texto": "Por lo cual fué llamado aquel campo, Campo de sangre, hasta el día de hoy."}, {"numero": 9, "texto": "Entonces se cumplió lo que fué dicho por el profeta Jeremías, que dijo: Y tomaron las treinta piezas de plata, precio del apreciado, que fué apreciado por los hijos de Israel;"}, {"numero": 10, "texto": "Y las dieron para el campo del alfarero, como me ordenó el Señor."}, {"numero": 11, "texto": "Y Jesús estuvo delante del presidente; y el presidente le preguntó, diciendo: ¿Eres tú el Rey de los judíos? Y Jesús le dijo: Tú lo dices."}, {"numero": 12, "texto": "Y siendo acusado por los príncipes de los sacerdotes, y por los ancianos, nada respondió."}, {"numero": 13, "texto": "Pilato entonces le dice: ¿No oyes cuántas cosas testifican contra ti?"}, {"numero": 14, "texto": "Y no le respondió ni una palabra; de tal manera que el presidente se maravillaba mucho."}, {"numero": 15, "texto": "Y en el día de la fiesta acostumbraba el presidente soltar al pueblo un preso, cual quisiesen."}, {"numero": 16, "texto": "Y tenían entonces un preso famoso que se llamaba Barrabás."}, {"numero": 17, "texto": "Y juntos ellos, les dijo Pilato: ¿Cuál queréis que os suelte? ¿á Barrabás, ó á Jesús que se dice el Cristo?"}, {"numero": 18, "texto": "Porque sabía que por envidia le habían entregado."}, {"numero": 19, "texto": "Y estando él sentado en el tribunal, su mujer envió á él, diciendo: No tengas que ver con aquel justo; porque hoy he padecido muchas cosas en sueños por causa de él."}, {"numero": 20, "texto": "Mas los príncipes de los sacerdotes y los ancianos, persuadieron al pueblo que pidiese á Barrabás, y á Jesús matase."}, {"numero": 21, "texto": "Y respondiendo el presidente les dijo: ¿Cuál de los dos queréis que os suelte? Y ellos dijeron: A Barrabás."}, {"numero": 22, "texto": "Pilato les dijo: ¿Qué pues haré de Jesús que se dice el Cristo? Dícenle todos: Sea crucificado."}, {"numero": 23, "texto": "Y el presidente les dijo: Pues ¿qué mal ha hecho? Mas ellos gritaban más, diciendo: Sea crucificado."}, {"numero": 24, "texto": "Y viendo Pilato que nada adelantaba, antes se hacía más alboroto, tomando agua se lavó las manos delante del pueblo, diciendo: Inocente soy yo de la sangre de este justo: veréislo vosotros."}, {"numero": 25, "texto": "Y respondiendo todo el pueblo, dijo: Su sangre sea sobre nosotros, y sobre nuestros hijos."}, {"numero": 26, "texto": "Entonces les soltó á Barrabás: y habiendo azotado á Jesús, le entregó para ser crucificado."}, {"numero": 27, "texto": "Entonces los soldados del presidente llevaron á Jesús al pretorio, y juntaron á él toda la cuadrilla;"}, {"numero": 28, "texto": "Y desnudándole, le echaron encima un manto de grana;"}, {"numero": 29, "texto": "Y pusieron sobre su cabeza una corona tejida de espinas, y una caña en su mano derecha; é hincando la rodilla delante de él, le burlaban, diciendo: ¡Salve, Rey de los Judíos!"}, {"numero": 30, "texto": "Y escupiendo en él, tomaron la caña, y le herían en la cabeza."}, {"numero": 31, "texto": "Y después que le hubieron escarnecido, le desnudaron el manto, y le vistieron de sus vestidos, y le llevaron para crucificarle."}, {"numero": 32, "texto": "Y saliendo, hallaron á un Cireneo, que se llamaba Simón: á éste cargaron para que llevase su cruz."}, {"numero": 33, "texto": "Y como llegaron al lugar que se llama Gólgotha, que es dicho, El lugar de la calavera,"}, {"numero": 34, "texto": "Le dieron á beber vinagre mezclado con hiel; y gustando, no quiso beberlo."}, {"numero": 35, "texto": "Y después que le hubieron crucificado, repartieron sus vestidos, echando suertes: para que se cumpliese lo que fué dicho por el profeta: Se repartieron mis vestidos, y sobre mi ropa echaron suertes."}, {"numero": 36, "texto": "Y sentados le guardaban allí."}, {"numero": 37, "texto": "Y pusieron sobre su cabeza su causa escrita: ESTE ES JESUS EL REY DE LOS JUDIOS."}, {"numero": 38, "texto": "Entonces crucificaron con él dos ladrones, uno á la derecha, y otro á la izquierda."}, {"numero": 39, "texto": "Y los que pasaban, le decían injurias, meneando sus cabezas,"}, {"numero": 40, "texto": "Y diciendo: Tú, el que derribas el templo, y en tres días lo reedificas, sálvate á ti mismo: si eres Hijo de Dios, desciende de la cruz."}, {"numero": 41, "texto": "De esta manera también los príncipes de los sacerdotes, escarneciendo con los escribas y los Fariseos y los ancianos, decían:"}, {"numero": 42, "texto": "A otros salvó, á sí mismo no puede salvar: si es el Rey de Israel, descienda ahora de la cruz, y creeremos en él."}, {"numero": 43, "texto": "Confió en Dios: líbrele ahora si le quiere: porque ha dicho: Soy Hijo de Dios."}, {"numero": 44, "texto": "Lo mismo también le zaherían los ladrones que estaban crucificados con él."}, {"numero": 45, "texto": "Y desde la hora de sexta fueron tinieblas sobre toda la tierra hasta la hora de nona."}, {"numero": 46, "texto": "Y cerca de la hora de nona, Jesús exclamó con grande voz, diciendo: Eli, Eli, ¿lama sabachtani? Esto es: Dios mío, Dios mío, ¿por qué me has desamparado?"}, {"numero": 47, "texto": "Y algunos de los que estaban allí, oyéndolo, decían: A Elías llama éste."}, {"numero": 48, "texto": "Y luego, corriendo uno de ellos, tomó una esponja, y la hinchió de vinagre, y poniéndola en una caña, dábale de beber."}, {"numero": 49, "texto": "Y los otros decían: Deja, veamos si viene Elías á librarle."}, {"numero": 50, "texto": "Mas Jesús, habiendo otra vez exclamado con grande voz, dió el espíritu."}, {"numero": 51, "texto": "Y he aquí, el velo del templo se rompió en dos, de alto á bajo: y la tierra tembló, y las piedras se hendieron;"}, {"numero": 52, "texto": "Y abriéronse los sepulcros, y muchos cuerpos de santos que habían dormido, se levantaron;"}, {"numero": 53, "texto": "Y salidos de los sepulcros, después de su resurrección, vinieron á la santa ciudad, y aparecieron á muchos."}, {"numero": 54, "texto": "Y el centurión, y los que estaban con él guardando á Jesús, visto el terremoto, y las cosas que habían sido hechas, temieron en gran manera, diciendo: Verdaderamente Hijo de Dios era éste."}, {"numero": 55, "texto": "Y estaban allí muchas mujeres mirando de lejos, las cuales habían seguido de Galilea á Jesús, sirviéndole:"}, {"numero": 56, "texto": "Entre las cuales estaban María Magdalena, y María la madre de Jacobo y de José, y la madre de los hijos de Zebedeo."}, {"numero": 57, "texto": "Y como fué la tarde del día, vino un hombre rico de Arimatea, llamado José, el cual también había sido discípulo de Jesús."}, {"numero": 58, "texto": "Este llegó á Pilato, y pidió el cuerpo de Jesús: entonces Pilato mandó que se le diese el cuerpo."}, {"numero": 59, "texto": "Y tomando José el cuerpo, lo envolvió en una sábana limpia,"}, {"numero": 60, "texto": "Y lo puso en su sepulcro nuevo, que había labrado en la peña: y revuelta una grande piedra á la puerta del sepulcro, se fué."}, {"numero": 61, "texto": "Y estaban allí María Magdalena, y la otra María, sentadas delante del sepulcro."}, {"numero": 62, "texto": "Y el siguiente día, que es después de la preparación, se juntaron los príncipes de los sacerdotes y los Fariseos á Pilato,"}, {"numero": 63, "texto": "Diciendo: Señor, nos acordamos que aquel engañador dijo, viviendo aún: Después de tres días resucitaré."}, {"numero": 64, "texto": "Manda, pues, que se asegure el sepulcro hasta el día tercero; porque no vengan sus discípulos de noche, y le hurten, y digan al pueblo: Resucitó de los muertos. Y será el postrer error peor que el primero."}, {"numero": 65, "texto": "Y Pilato les dijo: Tenéis una guardia: id, aseguradlo como sabéis."}, {"numero": 66, "texto": "Y yendo ellos, aseguraron el sepulcro, sellando la piedra, con la guardia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 28, 'pt', '[{"numero": 1, "texto": "No fim do sábado, quando já começava a clarear para o primeiro dia da semana, Maria Madalena, e a outra Maria vieram ver o sepulcro."}, {"numero": 2, "texto": "E eis que houve um grande terremoto; porque um anjo do Senhor desceu do céu, chegou, e moveu a pedra da entrada, e ficou sentado sobre ela."}, {"numero": 3, "texto": "A aparência dele era como um relâmpago, e sua roupa branca como neve."}, {"numero": 4, "texto": "E de medo dele os guardas tremeram muito, e ficaram como mortos."}, {"numero": 5, "texto": "Mas o anjo disse às mulheres: Não vos atemorizeis, pois eu sei que buscais Jesus, o que foi crucificado."}, {"numero": 6, "texto": "Ele não está aqui, pois já ressuscitou, como ele disse. Vinde ver o lugar onde o Senhor jazia."}, {"numero": 7, "texto": "Ide depressa dizer aos seus discípulos que ele ressuscitou dos mortos; e eis que vai adiante de vós para a Galileia; ali o vereis. Eis que eu tenho vos dito."}, {"numero": 8, "texto": "Então elas saíram apressadamente do sepulcro, com temor e grande alegria, e correram para anunciar aos seus discípulos."}, {"numero": 9, "texto": "E, enquanto elas iam anunciar aos seus discípulos, eis que Jesus veio ao encontro delas, e disse: Saudações. Elas se aproximaram, pegaram os pés dele, e o adoraram."}, {"numero": 10, "texto": "Jesus, então, lhes disse: Não temais. Ide anunciar aos meus irmãos para eles irem à Galileia, e ali me verão."}, {"numero": 11, "texto": "Enquanto elas iam, eis que alguns da guarda vieram à cidade, e anunciaram aos chefes dos sacerdotes tudo o que havia acontecido."}, {"numero": 12, "texto": "Então eles se reuniram com os anciãos, depois de decidirem em conjunto, deram muito dinheiro aos soldados,"}, {"numero": 13, "texto": "dizendo: Falai: “Os discípulos dele vieram de noite, e o furtaram enquanto estávamos dormindo”."}, {"numero": 14, "texto": "E, se isto for ouvido pelo governador, nós o persuadiremos, e vos manteremos seguros."}, {"numero": 15, "texto": "Eles tomaram o dinheiro e fizeram como foram instruídos. E este dito foi divulgado entre os judeus até hoje."}, {"numero": 16, "texto": "Os onze discípulos se foram para a Galileia, ao monte onde Jesus havia lhes ordenado."}, {"numero": 17, "texto": "E quando o viram, o adoraram; porém alguns duvidaram."}, {"numero": 18, "texto": "Jesus se aproximou deles, e lhes falou: Todo o poder me é dado no céu e na terra."}, {"numero": 19, "texto": "Portanto ide, fazei discípulos a todas as nações, batizando-os em nome do Pai, do Filho, e do Espírito Santo,"}, {"numero": 20, "texto": "ensinando-lhes a guardar todas as coisas que eu vos tenho mandado. E eis que eu estou convosco todos os dias, até o fim dos tempos. Amém."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 28, 'en', '[{"numero": 1, "texto": "In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre."}, {"numero": 2, "texto": "And, behold, there was a great earthquake: for the angel of the Lord descended from heaven, and came and rolled back the stone from the door, and sat upon it."}, {"numero": 3, "texto": "His countenance was like lightning, and his raiment white as snow:"}, {"numero": 4, "texto": "And for fear of him the keepers did shake, and became as dead men."}, {"numero": 5, "texto": "And the angel answered and said unto the women, Fear not ye: for I know that ye seek Jesus, which was crucified."}, {"numero": 6, "texto": "He is not here: for he is risen, as he said. Come, see the place where the Lord lay."}, {"numero": 7, "texto": "And go quickly, and tell his disciples that he is risen from the dead; and, behold, he goeth before you into Galilee; there shall ye see him: lo, I have told you."}, {"numero": 8, "texto": "And they departed quickly from the sepulchre with fear and great joy; and did run to bring his disciples word."}, {"numero": 9, "texto": "And as they went to tell his disciples, behold, Jesus met them, saying, All hail. And they came and held him by the feet, and worshipped him."}, {"numero": 10, "texto": "Then said Jesus unto them, Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me."}, {"numero": 11, "texto": "Now when they were going, behold, some of the watch came into the city, and shewed unto the chief priests all the things that were done."}, {"numero": 12, "texto": "And when they were assembled with the elders, and had taken counsel, they gave large money unto the soldiers,"}, {"numero": 13, "texto": "Saying, Say ye, His disciples came by night, and stole him away while we slept."}, {"numero": 14, "texto": "And if this come to the governor''s ears, we will persuade him, and secure you."}, {"numero": 15, "texto": "So they took the money, and did as they were taught: and this saying is commonly reported among the Jews until this day."}, {"numero": 16, "texto": "Then the eleven disciples went away into Galilee, into a mountain where Jesus had appointed them."}, {"numero": 17, "texto": "And when they saw him, they worshipped him: but some doubted."}, {"numero": 18, "texto": "And Jesus came and spake unto them, saying, All power is given unto me in heaven and in earth."}, {"numero": 19, "texto": "Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"}, {"numero": 20, "texto": "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you always, even unto the end of the world. Amen."}]'::jsonb, 'King James Version'),
  ('Mt', 28, 'fr', '[{"numero": 1, "texto": "Après le sabbat, à l''''aube du premier jour de la semaine, Marie de Magdala et l''''autre Marie allèrent voir le sépulcre."}, {"numero": 2, "texto": "Et voici, il y eut un grand tremblement de terre; car un ange du Seigneur descendit du ciel, vint rouler la pierre, et s''''assit dessus."}, {"numero": 3, "texto": "Son aspect était comme l''''éclair, et son vêtement blanc comme la neige."}, {"numero": 4, "texto": "Les gardes tremblèrent de peur, et devinrent comme morts."}, {"numero": 5, "texto": "Mais l''''ange prit la parole, et dit aux femmes: Pour vous, ne craignez pas; car je sais que vous cherchez Jésus qui a été crucifié."}, {"numero": 6, "texto": "Il n''''est point ici; il est ressuscité, comme il l''''avait dit. Venez, voyez le lieu où il était couché,"}, {"numero": 7, "texto": "et allez promptement dire à ses disciples qu''''il est ressuscité des morts. Et voici, il vous précède en Galilée: c''''est là que vous le verrez. Voici, je vous l''''ai dit."}, {"numero": 8, "texto": "Elles s''''éloignèrent promptement du sépulcre, avec crainte et avec une grande joie, et elles coururent porter la nouvelle aux disciples."}, {"numero": 9, "texto": "Et voici, Jésus vint à leur rencontre, et dit: Je vous salue. Elles s''''approchèrent pour saisir ses pieds, et elles se prosternèrent devant lui."}, {"numero": 10, "texto": "Alors Jésus leur dit: Ne craignez pas; allez dire à mes frères de se rendre en Galilée: c''''est là qu''''ils me verront."}, {"numero": 11, "texto": "Pendant qu''''elles étaient en chemin, quelques hommes de la garde entrèrent dans la ville, et annoncèrent aux principaux sacrificateurs tout ce qui était arrivé."}, {"numero": 12, "texto": "Ceux-ci, après s''''être assemblés avec les anciens et avoir tenu conseil, donnèrent aux soldats une forte somme d''''argent,"}, {"numero": 13, "texto": "en disant: Dites: Ses disciples sont venus de nuit le dérober, pendant que nous dormions."}, {"numero": 14, "texto": "Et si le gouverneur l''''apprend, nous l''''apaiserons, et nous vous tirerons de peine."}, {"numero": 15, "texto": "Les soldats prirent l''''argent, et suivirent les instructions qui leur furent données. Et ce bruit s''''est répandu parmi les Juifs, jusqu''''à ce jour."}, {"numero": 16, "texto": "Les onze disciples allèrent en Galilée, sur la montagne que Jésus leur avait désignée."}, {"numero": 17, "texto": "Quand ils le virent, ils se prosternèrent devant lui. Mais quelques-uns eurent des doutes."}, {"numero": 18, "texto": "Jésus, s''''étant approché, leur parla ainsi: Tout pouvoir m''''a été donné dans le ciel et sur la terre."}, {"numero": 19, "texto": "Allez, faites de toutes les nations des disciples, les baptisant au nom du Père, du Fils et du Saint-Esprit,"}, {"numero": 20, "texto": "et enseignez-leur à observer tout ce que je vous ai prescrit. Et voici, je suis avec vous tous les jours, jusqu''''à la fin du monde."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 28, 'es', '[{"numero": 1, "texto": "Y LA víspera de sábado, que amanece para el primer día de la semana, vino María Magdalena, y la otra María, á ver el sepulcro."}, {"numero": 2, "texto": "Y he aquí, fué hecho un gran terremoto: porque el ángel del Señor, descendiendo del cielo y llegando, había revuelto la piedra, y estaba sentado sobre ella."}, {"numero": 3, "texto": "Y su aspecto era como un relámpago, y su vestido blanco como la nieve."}, {"numero": 4, "texto": "Y de miedo de él los guardas se asombraron, y fueron vueltos como muertos."}, {"numero": 5, "texto": "Y respondiendo el ángel, dijo á las mujeres: No temáis vosotras; porque yo sé que buscáis á Jesús, que fué crucificado."}, {"numero": 6, "texto": "No está aquí; porque ha resucitado, como dijo. Venid, ved el lugar donde fué puesto el Señor."}, {"numero": 7, "texto": "E id presto, decid á sus discípulos que ha resucitado de los muertos: y he aquí va delante de vosotros á Galilea; allí le veréis; he aquí, os lo he dicho."}, {"numero": 8, "texto": "Entonces ellas, saliendo del sepulcro con temor y gran gozo, fueron corriendo á dar las nuevas á sus discípulos. Y mientras iban á dar las nuevas á sus discípulos,"}, {"numero": 9, "texto": "He aquí, Jesús les sale al encuentro, diciendo: Salve. Y ellas se llegaron y abrazaron sus pies, y le adoraron."}, {"numero": 10, "texto": "Entonces Jesús les dice: No temáis: id, dad las nuevas á mis hermanos, para que vayan á Galilea, y allí me verán."}, {"numero": 11, "texto": "Y yendo ellas, he aquí unos de la guardia vinieron á la ciudad, y dieron aviso á los príncipes de los sacerdotes de todas las cosas que habían acontecido."}, {"numero": 12, "texto": "Y juntados con los ancianos, y habido consejo, dieron mucho dinero á los soldados,"}, {"numero": 13, "texto": "Diciendo: Decid: Sus discípulos vinieron de noche, y le hurtaron, durmiendo nosotros."}, {"numero": 14, "texto": "Y si esto fuere oído del presidente, nosotros le persuadiremos, y os haremos seguros."}, {"numero": 15, "texto": "Y ellos, tomando el dinero, hicieron como estaban instruídos: y este dicho fué divulgado entre los Judíos hasta el día de hoy."}, {"numero": 16, "texto": "Mas los once discípulos se fueron á Galilea, al monte donde Jesús les había ordenado."}, {"numero": 17, "texto": "Y como le vieron, le adoraron: mas algunos dudaban."}, {"numero": 18, "texto": "Y llegando Jesús, les habló, diciendo: Toda potestad me es dada en el cielo y en la tierra."}, {"numero": 19, "texto": "Por tanto, id, y doctrinad á todos los Gentiles, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo:"}, {"numero": 20, "texto": "Enseñándoles que guarden todas las cosas que os he mandado: y he aquí, yo estoy con vosotros todos los días, hasta el fin del mundo. Amén."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 1, 'pt', '[{"numero": 1, "texto": "Palavras de Neemias, filho de Hacalias.E aconteceu no mês de Quisleu, no ano vigésimo, enquanto eu estava na fortaleza de Susã,"}, {"numero": 2, "texto": "Veio Hanani, um de meus irmãos, ele e [alguns] homens de Judá, e perguntei-lhes pelos judeus que haviam escapado, que restaram do cativeiro, e por Jerusalém."}, {"numero": 3, "texto": "E me disseram: Os remanescentes, os que restaram do cativeiro lá na província, estão em grande miséria e desprezo; e o muro de Jerusalém está fendido, e suas portas queimadas a fogo."}, {"numero": 4, "texto": "E aconteceu que, quando eu ouvi estas palavras, sentei-me e chorei, e fiquei de luto por [alguns] dias; e jejuei e orei diante do Deus dos céus."}, {"numero": 5, "texto": "E disse: Ó SENHOR, Deus dos céus, Deus grande e temível, que guarda o pacto e a bondade aos que o amam e guardam seus mandamentos!"}, {"numero": 6, "texto": "Estejam, pois, os teus ouvidos atentos, e teus olhos abertos, para ouvires a oração de teu servo, que eu oro hoje diante de ti dia e noite, pelos filhos de Israel, teus servos; e confesso os pecados dos filhos de Israel que pecamos contra ti; também eu e a casa de meu pai pecamos."}, {"numero": 7, "texto": "Agimos muito corruptamente contra ti, e não guardamos os mandamentos, nem o estatutos nem os juízos, que mandaste ao teu servo Moisés."}, {"numero": 8, "texto": "Lembra-te, pois, da palavra que mandaste a teu servo Moisés, dizendo: [Se] vós transgredirdes, eu vos dispersarei entre os povos;"}, {"numero": 9, "texto": "Mas [se] vos converterdes a mim, e guardardes meus mandamentos, e os praticardes; então ainda que os rejeitados estejam nos confins dos céus, de lá eu os ajuntarei, e os trarei ao lugar que escolhi para fazer habitar ali o meu nome."}, {"numero": 10, "texto": "Eles são teus servos e teu povo, que resgataste com teu grande poder, e com tua mão forte."}, {"numero": 11, "texto": "Por favor, SENHOR, estejam teus ouvidos atentos à oração do teu servo, e a oração de teus servos, que desejam temer o teu nome; e, por favor, faze ter sucesso hoje a teu servo, e dá-lhe favor diante deste homem!Pois eu era copeiro do rei."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 1, 'en', '[{"numero": 1, "texto": "The words of Nehemiah the son of Hachaliah. And it came to pass in the month Chisleu, in the twentieth year, as I was in Shushan the palace,"}, {"numero": 2, "texto": "That Hanani, one of my brethren, came, he and certain men of Judah; and I asked them concerning the Jews that had escaped, which were left of the captivity, and concerning Jerusalem."}, {"numero": 3, "texto": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire."}, {"numero": 4, "texto": "And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}, {"numero": 5, "texto": "And said, I beseech thee, O Lord God of heaven, the great and terrible God, that keepeth covenant and mercy for them that love him and observe his commandments:"}, {"numero": 6, "texto": "Let thine ear now be attentive, and thine eyes open, that thou mayest hear the prayer of thy servant, which I pray before thee now, day and night, for the children of Israel thy servants, and confess the sins of the children of Israel, which we have sinned against thee: both I and my father''s house have sinned."}, {"numero": 7, "texto": "We have dealt very corruptly against thee, and have not kept the commandments, nor the statutes, nor the judgments, which thou commandedst thy servant Moses."}, {"numero": 8, "texto": "Remember, I beseech thee, the word that thou commandedst thy servant Moses, saying, If ye transgress, I will scatter you abroad among the nations:"}, {"numero": 9, "texto": "But if ye turn unto me, and keep my commandments, and do them; though there were of you cast out unto the uttermost part of the heaven, yet will I gather them from thence, and will bring them unto the place that I have chosen to set my name there."}, {"numero": 10, "texto": "Now these are thy servants and thy people, whom thou hast redeemed by thy great power, and by thy strong hand."}, {"numero": 11, "texto": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king''s cupbearer."}]'::jsonb, 'King James Version'),
  ('Ne', 1, 'fr', '[{"numero": 1, "texto": "Paroles de Néhémie, fils de Hacalia. Au mois de Kisleu, la vingtième année, comme j''''étais à Suse, dans la capitale,"}, {"numero": 2, "texto": "Hanani, l''''un de mes frères, et quelques hommes arrivèrent de Juda. Je les questionnai au sujet des Juifs réchappés qui étaient restés de la captivité, et au sujet de Jérusalem."}, {"numero": 3, "texto": "Ils me répondirent: Ceux qui sont restés de la captivité sont là dans la province, au comble du malheur et de l''''opprobre; les murailles de Jérusalem sont en ruines, et ses portes sont consumées par le feu."}, {"numero": 4, "texto": "Lorsque j''''entendis ces choses, je m''''assis, je pleurai, et je fus plusieurs jours dans la désolation. Je jeûnai et je priai devant le Dieu des cieux,"}, {"numero": 5, "texto": "et je dis: O Eternel, Dieu des cieux, Dieu grand et redoutable, toi qui gardes ton alliance et qui fais miséricorde à ceux qui t''''aiment et qui observent tes commandements!"}, {"numero": 6, "texto": "Que ton oreille soit attentive et que tes yeux soient ouverts: écoute la prière que ton serviteur t''''adresse en ce moment, jour et nuit, pour tes serviteurs les enfants d''''Israël, en confessant les péchés des enfants d''''Israël, nos péchés contre toi; car moi et la maison de mon père, nous avons péché."}, {"numero": 7, "texto": "Nous t''''avons offensé, et nous n''''avons point observé les commandements, les lois et les ordonnances que tu prescrivis à Moïse, ton serviteur."}, {"numero": 8, "texto": "Souviens-toi de cette parole que tu donnas ordre à Moïse, ton serviteur, de prononcer. Lorsque vous pécherez, je vous disperserai parmi les peuples;"}, {"numero": 9, "texto": "mais si vous revenez à moi, et si vous observez mes commandements et les mettez en pratique, alors, quand vous seriez exilés à l''''extrémité du ciel, de là je vous rassemblerai et je vous ramènerai dans le lieu que j''''ai choisi pour y faire résider mon nom."}, {"numero": 10, "texto": "Ils sont tes serviteurs et ton peuple, que tu as rachetés par ta grande puissance et par ta main forte."}, {"numero": 11, "texto": "Ah! Seigneur, que ton oreille soit attentive à la prière de ton serviteur, et à la prière de tes serviteurs qui veulent craindre ton nom! Donne aujourd''''hui du succès à ton serviteur, et fais-lui trouver grâce devant cet homme! J''''étais alors échanson du roi."}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 1, 'es', '[{"numero": 1, "texto": "PALABRAS de Nehemías, hijo de Hachâlías. Y acaeció en el mes de Chisleu, en el año veinte, estando yo en Susán, capital del reino,"}, {"numero": 2, "texto": "Que vino Hanani, uno de mis hermanos, él y ciertos varones de Judá, y preguntéles por los Judíos que habían escapado, que habían quedado de la cautividad, y por Jerusalem."}, {"numero": 3, "texto": "Y dijéronme: El residuo, los que quedaron de la cautividad allí en la provincia, están en gran mal y afrenta, y el muro de Jerusalem derribado, y sus puertas quemadas á fuego."}, {"numero": 4, "texto": "Y fué que, como yo oí estas palabras, sentéme y lloré, y enlutéme por algunos días, y ayuné y oré delante del Dios de los cielos."}, {"numero": 5, "texto": "Y dije: Ruégote, oh Jehová, Dios de los cielos, fuerte, grande, y terrible, que guarda el pacto y la misericordia á los que le aman y guardan sus mandamientos;"}, {"numero": 6, "texto": "Esté ahora atento tu oído, y tus ojos abiertos, para oir la oración de tu siervo, que yo hago ahora delante de ti día y noche, por los hijos de Israel tus siervos; y confieso los pecados de los hijos de Israel que hemos contra ti cometido; sí, yo y la casa de mi padre hemos pecado."}, {"numero": 7, "texto": "En extremo nos hemos corrompido contra ti, y no hemos guardado los mandamientos, y estatutos y juicios, que mandaste á Moisés tu siervo."}, {"numero": 8, "texto": "Acuérdate ahora de la palabra que ordenaste á Moisés tu siervo, diciendo: Vosotros prevaricaréis, y yo os esparciré por los pueblos:"}, {"numero": 9, "texto": "Mas os volveréis á mí, y guardaréis mis mandamientos, y los pondréis por obra. Si fuere vuestro lanzamiento hasta el cabo de los cielos, de allí os juntaré; y traerlos he al lugar que escogí para hacer habitar allí mi nombre."}, {"numero": 10, "texto": "Ellos pues son tus siervos y tu pueblo, los cuales redimiste con tu gran fortaleza, y con tu mano fuerte."}, {"numero": 11, "texto": "Ruégote, oh Jehová, esté ahora atento tu oído á la oración de tu siervo, y á la oración de tus siervos, quienes desean temer tu nombre: y ahora concede hoy próspero suceso á tu siervo, y dale gracia delante de aquel varón. Porque yo servía de copero al rey."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 2, 'pt', '[{"numero": 1, "texto": "Sucedeu, pois, no mês de Nisã, no ano vigésimo do rei Artaxerxes, que havendo vinho diante dele, tomei o vinho, e [o] dei ao rei. Porém eu nunca havia estado triste diante dele."}, {"numero": 2, "texto": "Por isso o rei me perguntou: Por que o teu rosto está triste, mesmo não estando doente? Isto não pode ser outra coisa, senão tristeza de coração. Tive então muito medo."}, {"numero": 3, "texto": "E disse ao rei: Viva o rei para sempre! Como meu rosto não estaria triste, quando a cidade, o lugar dos sepulcros de meus pais, está arruinada, e suas portas consumidas a fogo?"}, {"numero": 4, "texto": "E o rei me disse: O que pedes? Então orei ao Deus dos céus,"}, {"numero": 5, "texto": "E respondei ao rei: Se for do agrado do rei, e se teu servo é agradável diante de ti, [peço] que me envies a Judá, à cidade dos sepulcros de meus pais, para reconstruí-la."}, {"numero": 6, "texto": "Então o rei me disse (enquanto a rainha estava sentada junto a ele): Por quanto tempo durará tua viagem, e quando voltarás? E agradou ao rei me enviar, depois que eu lhe defini um certo tempo."}, {"numero": 7, "texto": "Disse mais ao rei: Se for do agrado do rei, sejam dadas a mim cartas para os governadores dalém do rio, para que me permitam passar em segurança até que eu chegue a Judá;"}, {"numero": 8, "texto": "Como também um carta para Asafe, guarda do jardim do rei, para que me dê madeira para consertar as portas da fortaleza do templo, para o muro da cidade, e para a casa onde entrarei.E o rei me concedeu, segundo a boa mão do SENHOR sobre mim."}, {"numero": 9, "texto": "Então vim aos governadores dalém do rio, e lhes dei as cartas do rei. E o rei enviou comigo capitães do exército e cavaleiros."}, {"numero": 10, "texto": "Quando então Sambalate, o horonita, e Tobias, o servo amonita, ouviram, desagradou-lhes muito que alguém viesse para buscar o bem aos filhos de Israel."}, {"numero": 11, "texto": "Cheguei, pois, a Jerusalém, e fiquei ali três dias."}, {"numero": 12, "texto": "E de noite me levantei, eu e uns poucos homens comigo, e não declarei a ninguém o que Deus tinha posto em meu coração que fizesse em Jerusalém; e animal nenhum estava comigo, a não ser o o em que eu cavalgava."}, {"numero": 13, "texto": "E de noite saí pela porta do Vale até a fonte do Dragão e à porta do Esterco; e observei os muros de Jerusalém que estavam fendidos, e suas portas estavam consumidas a fogo."}, {"numero": 14, "texto": "E passei à porta da Fonte, e ao tanque do rei; e não houve lugar por onde o animal em que eu estava montado pudesse passar."}, {"numero": 15, "texto": "Então de noite subi pelo vale, e observei o muro; então voltei, e entrei pela porta do Vale, e assim me retornei."}, {"numero": 16, "texto": "E os oficiais não sabiam aonde eu tinha ido, nem o que tinha feito; nem mesmo aos judeus e aos sacerdotes, nem aos nobres e oficiais, nem aos demais que faziam a obra, havia eu declarado coisa alguma."}, {"numero": 17, "texto": "Então eu lhes disse: Com certeza vedes a miséria em que estamos, que Jerusalém está arruinada, e suas portas queimadas a fogo. Vinde, e reconstruamos o muro de Jerusalém, e não sejamos mais humilhados."}, {"numero": 18, "texto": "Então lhes declarei como a mão de meu Deus havia sido boa sobre mim, e também as palavras do rei, que ele tinha me dito. Então disseram: Levantemo-nos, e edifiquemos. Assim esforçaram suas mãos para uma boa obra."}, {"numero": 19, "texto": "Porém, quando Sambalate o horonita, Tobias o servo amonita, e Gesém o árabe, ouviram [isto] ,zombaram de nós, e nos desprezaram, dizendo: O que é isto que vós fazeis? Por acaso estais vos rebelando contra o rei?"}, {"numero": 20, "texto": "Então lhes respondi, dizendo-lhes: O Deus dos céus é quem nos dará sucesso; e nós, servos dele, nos levantaremos e edificaremos; pois vós não tendes parte, nem direito, nem memória em Jerusalém."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 2, 'en', '[{"numero": 1, "texto": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}, {"numero": 2, "texto": "Wherefore the king said unto me, Why is thy countenance sad, seeing thou art not sick? this is nothing else but sorrow of heart. Then I was very sore afraid,"}, {"numero": 3, "texto": "And said unto the king, Let the king live for ever: why should not my countenance be sad, when the city, the place of my fathers'' sepulchres, lieth waste, and the gates thereof are consumed with fire?"}, {"numero": 4, "texto": "Then the king said unto me, For what dost thou make request? So I prayed to the God of heaven."}, {"numero": 5, "texto": "And I said unto the king, If it please the king, and if thy servant have found favour in thy sight, that thou wouldest send me unto Judah, unto the city of my fathers'' sepulchres, that I may build it."}, {"numero": 6, "texto": "And the king said unto me, (the queen also sitting by him,) For how long shall thy journey be? and when wilt thou return? So it pleased the king to send me; and I set him a time."}, {"numero": 7, "texto": "Moreover I said unto the king, If it please the king, let letters be given me to the governors beyond the river, that they may convey me over till I come into Judah;"}, {"numero": 8, "texto": "And a letter unto Asaph the keeper of the king''s forest, that he may give me timber to make beams for the gates of the palace which appertained to the house, and for the wall of the city, and for the house that I shall enter into. And the king granted me, according to the good hand of my God upon me."}, {"numero": 9, "texto": "Then I came to the governors beyond the river, and gave them the king''s letters. Now the king had sent captains of the army and horsemen with me."}, {"numero": 10, "texto": "When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard of it, it grieved them exceedingly that there was come a man to seek the welfare of the children of Israel."}, {"numero": 11, "texto": "So I came to Jerusalem, and was there three days."}, {"numero": 12, "texto": "And I arose in the night, I and some few men with me; neither told I any man what my God had put in my heart to do at Jerusalem: neither was there any beast with me, save the beast that I rode upon."}, {"numero": 13, "texto": "And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire."}, {"numero": 14, "texto": "Then I went on to the gate of the fountain, and to the king''s pool: but there was no place for the beast that was under me to pass."}, {"numero": 15, "texto": "Then went I up in the night by the brook, and viewed the wall, and turned back, and entered by the gate of the valley, and so returned."}, {"numero": 16, "texto": "And the rulers knew not whither I went, or what I did; neither had I as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest that did the work."}, {"numero": 17, "texto": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach."}, {"numero": 18, "texto": "Then I told them of the hand of my God which was good upon me; as also the king''s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work."}, {"numero": 19, "texto": "But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard it, they laughed us to scorn, and despised us, and said, What is this thing that ye do? will ye rebel against the king?"}, {"numero": 20, "texto": "Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem."}]'::jsonb, 'King James Version'),
  ('Ne', 2, 'fr', '[{"numero": 1, "texto": "Au mois de Nisan, la vingtième année du roi Artaxerxès, comme le vin était devant lui, je pris le vin et je l''''offris au roi. Jamais je n''''avais paru triste en sa présence."}, {"numero": 2, "texto": "Le roi me dit: Pourquoi as-tu mauvais visage? Tu n''''es pourtant pas malade; ce ne peut être qu''''un chagrin de coeur. Je fus saisi d''''une grande crainte,"}, {"numero": 3, "texto": "et je répondis au roi: Que le roi vive éternellement! Comment n''''aurais-je pas mauvais visage, lorsque la ville où sont les sépulcres de mes pères est détruite et que ses portes sont consumées par le feu?"}, {"numero": 4, "texto": "Et le roi me dit: Que demandes-tu? Je priai le Dieu des cieux,"}, {"numero": 5, "texto": "et je répondis au roi: Si le roi le trouve bon, et si ton serviteur lui est agréable, envoie-moi en Juda, vers la ville des sépulcres de mes pères, pour que je la rebâtisse."}, {"numero": 6, "texto": "Le roi, auprès duquel la reine était assise, me dit alors: Combien ton voyage durera-t-il, et quand seras-tu de retour? Il plut au roi de me laisser partir, et je lui fixai un temps."}, {"numero": 7, "texto": "Puis je dis au roi: Si le roi le trouve bon, qu''''on me donne des lettres pour les gouverneurs de l''''autre côté du fleuve, afin qu''''ils me laissent passer et entrer en Juda,"}, {"numero": 8, "texto": "et une lettre pour Asaph, garde forestier du roi, afin qu''''il me fournisse du bois de charpente pour les portes de la citadelle près de la maison, pour la muraille de la ville, et pour la maison que j''''occuperai. Le roi me donna ces lettres, car la bonne main de mon Dieu était sur moi."}, {"numero": 9, "texto": "Je me rendis auprès des gouverneurs de l''''autre côté du fleuve, et je leur remis les lettres du roi, qui m''''avait fait accompagner par des chefs de l''''armée et par des cavaliers."}, {"numero": 10, "texto": "Sanballat, le Horonite, et Tobija, le serviteur ammonite, l''''ayant appris, eurent un grand déplaisir de ce qu''''il venait un homme pour chercher le bien des enfants d''''Israël."}, {"numero": 11, "texto": "J''''arrivai à Jérusalem, et j''''y passai trois jours."}, {"numero": 12, "texto": "Après quoi, je me levai pendant la nuit avec quelques hommes, sans avoir dit à personne ce que mon Dieu m''''avait mis au coeur de faire pour Jérusalem. Il n''''y avait avec moi d''''autre bête de somme que ma propre monture."}, {"numero": 13, "texto": "Je sortis de nuit par la porte de la vallée, et je me dirigeai contre la source du dragon et vers la porte du fumier, considérant les murailles en ruines de Jérusalem et réfléchissant à ses portes consumées par le feu."}, {"numero": 14, "texto": "Je passai près de la porte de la source et de l''''étang du roi, et il n''''y avait point de place par où pût passer la bête qui était sous moi."}, {"numero": 15, "texto": "Je montai de nuit par le torrent, et je considérai encore la muraille. Puis je rentrai par la porte de la vallée, et je fus ainsi de retour."}, {"numero": 16, "texto": "Les magistrats ignoraient où j''''étais allé, et ce que je faisais. Jusqu''''à ce moment, je n''''avais rien dit aux Juifs, ni aux sacrificateurs, ni aux grands, ni aux magistrats, ni à aucun de ceux qui s''''occupaient des affaires."}, {"numero": 17, "texto": "Je leur dis alors: Vous voyez le malheureux état où nous sommes! Jérusalem est détruite, et ses portes sont consumées par le feu! Venez, rebâtissons la muraille de Jérusalem, et nous ne serons plus dans l''''opprobre."}, {"numero": 18, "texto": "Et je leur racontai comment la bonne main de mon Dieu avait été sur moi, et quelles paroles le roi m''''avait adressées. Ils dirent: Levons-nous, et bâtissons! Et ils se fortifièrent dans cette bonne résolution."}, {"numero": 19, "texto": "Sanballat, le Horonite, Tobija, le serviteur ammonite, et Guéschem, l''''Arabe, en ayant été informés, se moquèrent de nous et nous méprisèrent. Ils dirent: Que faites-vous là? Vous révoltez-vous contre le roi?"}, {"numero": 20, "texto": "Et je leur fis cette réponse: Le Dieu des cieux nous donnera le succès. Nous, ses serviteurs, nous nous lèverons et nous bâtirons; mais vous, vous n''''avez ni part, ni droit, ni souvenir dans Jérusalem."}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 2, 'es', '[{"numero": 1, "texto": "Y FUÉ en el mes de Nisán, en el año veinte del rey Artajerjes, que estando ya el vino delante de él, tomé el vino, y dílo al rey. Y como yo no había estado antes triste en su presencia,"}, {"numero": 2, "texto": "Díjome el rey: ¿Por qué está triste tu rostro, pues no estás enfermo? No es esto sino quebranto de corazón. Entonces temí en gran manera."}, {"numero": 3, "texto": "Y dije al rey: El rey viva para siempre. ¿Cómo no estará triste mi rostro, cuando la ciudad, casa de los sepulcros de mis padres, está desierta, y sus puertas consumidas del fuego?"}, {"numero": 4, "texto": "Y díjome el rey: ¿Qué cosa pides? Entonces oré al Dios de los cielos,"}, {"numero": 5, "texto": "Y dije al rey: Si al rey place, y si agrada tu siervo delante de ti, que me envíes á Judá, á la ciudad de los sepulcros de mis padres, y la reedificaré."}, {"numero": 6, "texto": "Entonces el rey me dijo, (y la reina estaba sentada junto á él): ¿Hasta cuándo será tu viaje, y cuándo volverás? Y plugo al rey enviarme, después que yo le señalé tiempo."}, {"numero": 7, "texto": "Además dije al rey: Si al rey place, dénseme cartas para los gobernadores de la otra parte del río, que me franqueen el paso hasta que llegue á Judá;"}, {"numero": 8, "texto": "Y carta para Asaph, guarda del bosque del rey, á fin que me dé madera para enmaderar los portales del palacio de la casa, y para el muro de la ciudad, y la casa donde entraré. Y otorgómelo el rey, según la benéfica mano de Jehová sobre mí."}, {"numero": 9, "texto": "Y vine luego á los gobernadores de la otra parte del río, y les dí las cartas del rey. Y el rey envió conmigo capitanes del ejército y gente de á caballo."}, {"numero": 10, "texto": "Y oyéndolo Sanballat Horonita, y Tobías, el siervo Ammonita, disgustóles en extremo que viniese alguno para procurar el bien de los hijos de Israel."}, {"numero": 11, "texto": "Llegué pues á Jerusalem, y estado que hube allí tres días,"}, {"numero": 12, "texto": "Levantéme de noche, yo y unos pocos varones conmigo, y no declaré á hombre alguno lo que Dios había puesto en mi corazón que hiciese en Jerusalem; ni había bestia conmigo, excepto la cabalgadura en que cabalgaba."}, {"numero": 13, "texto": "Y salí de noche por la puerta del Valle hacia la fuente del Dragón y á la puerta del Muladar; y consideré los muros de Jerusalem que estaban derribados, y sus puertas que estaban consumidas del fuego."}, {"numero": 14, "texto": "Pasé luego á la puerta de la Fuente, y al estanque del Rey; mas no había lugar por donde pasase la cabalgadura en que iba."}, {"numero": 15, "texto": "Y subí por el torrente de noche, y consideré el muro, y regresando entré por la puerta del Valle, y volvíme."}, {"numero": 16, "texto": "Y no sabían los magistrados dónde yo había ido, ni qué había hecho; ni hasta entonces lo había yo declarado á los Judíos y sacerdotes, ni á los nobles y magistrados, ni á los demás que hacían la obra."}, {"numero": 17, "texto": "Díjeles pues: Vosotros veis el mal en que estamos, que Jerusalem está desierta, y sus puertas consumidas del fuego: venid, y edifiquemos el muro de Jerusalem, y no seamos más en oprobio."}, {"numero": 18, "texto": "Entonces les declaré cómo la mano de mi Dios era buena sobre mí, y asimismo las palabras del rey, que me había dicho. Y dijeron: Levantémonos, y edifiquemos. Así esforzaron sus manos para bien."}, {"numero": 19, "texto": "Mas habiéndolo oído Samballat Horonita, y Tobías el siervo Ammonita, y Gesem el Arabe, escarnecieron de nosotros, y nos despreciaron, diciendo: ¿Qué es esto que hacéis vosotros? ¿os rebeláis contra el rey?"}, {"numero": 20, "texto": "Y volvíles respuesta, y díjeles: El Dios de los cielos, él nos prosperará, y nosotros sus siervos nos levantaremos y edificaremos: que vosotros no tenéis parte, ni derecho, ni memoria en Jerusalem."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 4, 'pt', '[{"numero": 1, "texto": "E foi que, quando Sambalate ouviu que nós edificávamos o muro, ele se indignou muito, e escarneceu dos judeus."}, {"numero": 2, "texto": "E falou diante de seus irmãos e do exército de Samaria, dizendo: O que fazem estes fracos judeus? Será isso lhes permitido? Farão eles sacrifícios? Acabarão isso algum dia? Ressuscitarão dos amontoados de entulho as pedras que foram queimadas?"}, {"numero": 3, "texto": "E com ele estava Tobias, o amonita, que disse: Ainda que edifiquem, contudo, se uma raposa vier, ela [sozinha] será capaz de derrubar seu muro de pedra."}, {"numero": 4, "texto": "Ouve, ó Deus nosso, que somos desprezados, e devolve a humilhação deles sobre suas cabeças; e entrega-os para o despojo, na terra do cativeiro;"}, {"numero": 5, "texto": "E não cubras a perversidade deles, nem o pecado deles seja riscado diante de teu rosto; pois provocaram à ira diante dos construtores."}, {"numero": 6, "texto": "Edificamos, pois o muro, e todo o muro foi completado até metade [de] sua [altura] ; porque o coração do povo estava disposto a trabalhar."}, {"numero": 7, "texto": "E foi que, quando Sambalate e Tobias, e os árabes, os amonitas, e os de Asdode, ouviram que os muros de Jerusalém estavam sendo reparados, que as brechas já começavam a serem fechadas, eles ficaram muito irados."}, {"numero": 8, "texto": "E todos conspiraram entre si para virem guerrear contra Jerusalém, e causarem confusão nela."}, {"numero": 9, "texto": "Porém nós oramos a nosso Deus; e pusemos guarda contra eles, dia e noite, por causa deles."}, {"numero": 10, "texto": "Então Judá disse: As forças dos carregadores se enfraqueceram, e o entulho é muito; e nós não podemos reconstruir o muro."}, {"numero": 11, "texto": "Porém nossos inimigos diziam: Eles não saibam, nem vejam, até que entremos em meio deles, e os matemos; assim faremos cessar a obra."}, {"numero": 12, "texto": "E foi que, quando os judeus que habitavam entre eles vieram, dez vezes nos disseram: Por todos os lados para que virardes, [eles estão] contra nós."}, {"numero": 13, "texto": "Então pus [guardas] nos lugares baixos, atrás do muro, [e] nos lugares altos; e pus ao povo por [suas] famílias com suas espadas, suas lanças, e seus arcos."}, {"numero": 14, "texto": "Depois olhei, me levantei, e disse aos nobres, aos oficiais, e aos demais do povo: Não os temais; lembrai-vos do Senhor grande e temível, e lutai por vossos irmãos, por vossos filhos e vossas filhas, por vossas mulheres e vossas casas."}, {"numero": 15, "texto": "E foi que, quando nossos inimigos ouviram falar que já sabíamos [de tudo] ,e que Deus havia frustrado o plano deles, todos voltamos ao muro, cada um à sua obra."}, {"numero": 16, "texto": "Sucedeu, porém, que desde aquele dia a metade dos meus servos trabalhava na obra, e outra metade deles tinha lanças, escudos, arcos, e couraças; e os líderes estavam por detrás de toda a casa de Judá."}, {"numero": 17, "texto": "Os que edificavam o muro, e os que traziam as cargas [e] os que carregavam, com uma mão faziam a obra, e na outra tinham armas."}, {"numero": 18, "texto": "E cada um dos construtores trazia sua espada cingida a seus lombos, e [assim] edificavam; e o que tocava a trombeta estava junto a mim."}, {"numero": 19, "texto": "E eu disse aos nobres, aos oficiais, e aos demais do povo: A obra é grande e extensa, e nós estamos separados no muro, longe uns dos outros."}, {"numero": 20, "texto": "No lugar onde ouvirdes o som da trombeta, ali vos ajuntareis conosco; nosso Deus lutará por nós."}, {"numero": 21, "texto": "Assim trabalhávamos na obra; e a metade deles tinham lanças desde a subida do amanhecer até o surgir das estrelas."}, {"numero": 22, "texto": "Também naquele tempo eu disse ao povo: Cada um passe a noite com seu servo dentro de Jerusalém, para que de noite nos sirvam de guarda, e de dia na obra."}, {"numero": 23, "texto": "E nem eu, nem meus irmãos, nem meus servos, nem os homens da guarda que me seguiam, nos despíamos de nossas roupas; cada um [mantinha] sua arma [até para] a água."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 4, 'en', '[{"numero": 1, "texto": "But it came to pass, that when Sanballat heard that we builded the wall, he was wroth, and took great indignation, and mocked the Jews."}, {"numero": 2, "texto": "And he spake before his brethren and the army of Samaria, and said, What do these feeble Jews? will they fortify themselves? will they sacrifice? will they make an end in a day? will they revive the stones out of the heaps of the rubbish which are burned?"}, {"numero": 3, "texto": "Now Tobiah the Ammonite was by him, and he said, Even that which they build, if a fox go up, he shall even break down their stone wall."}, {"numero": 4, "texto": "Hear, O our God; for we are despised: and turn their reproach upon their own head, and give them for a prey in the land of captivity:"}, {"numero": 5, "texto": "And cover not their iniquity, and let not their sin be blotted out from before thee: for they have provoked thee to anger before the builders."}, {"numero": 6, "texto": "So built we the wall; and all the wall was joined together unto the half thereof: for the people had a mind to work."}, {"numero": 7, "texto": "But it came to pass, that when Sanballat, and Tobiah, and the Arabians, and the Ammonites, and the Ashdodites, heard that the walls of Jerusalem were made up, and that the breaches began to be stopped, then they were very wroth,"}, {"numero": 8, "texto": "And conspired all of them together to come and to fight against Jerusalem, and to hinder it."}, {"numero": 9, "texto": "Nevertheless we made our prayer unto our God, and set a watch against them day and night, because of them."}, {"numero": 10, "texto": "And Judah said, The strength of the bearers of burdens is decayed, and there is much rubbish; so that we are not able to build the wall."}, {"numero": 11, "texto": "And our adversaries said, They shall not know, neither see, till we come in the midst among them, and slay them, and cause the work to cease."}, {"numero": 12, "texto": "And it came to pass, that when the Jews which dwelt by them came, they said unto us ten times, From all places whence ye shall return unto us they will be upon you."}, {"numero": 13, "texto": "Therefore set I in the lower places behind the wall, and on the higher places, I even set the people after their families with their swords, their spears, and their bows."}, {"numero": 14, "texto": "And I looked, and rose up, and said unto the nobles, and to the rulers, and to the rest of the people, Be not ye afraid of them: remember the Lord, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses."}, {"numero": 15, "texto": "And it came to pass, when our enemies heard that it was known unto us, and God had brought their counsel to nought, that we returned all of us to the wall, every one unto his work."}, {"numero": 16, "texto": "And it came to pass from that time forth, that the half of my servants wrought in the work, and the other half of them held both the spears, the shields, and the bows, and the habergeons; and the rulers were behind all the house of Judah."}, {"numero": 17, "texto": "They which builded on the wall, and they that bare burdens, with those that laded, every one with one of his hands wrought in the work, and with the other hand held a weapon."}, {"numero": 18, "texto": "For the builders, every one had his sword girded by his side, and so builded. And he that sounded the trumpet was by me."}, {"numero": 19, "texto": "And I said unto the nobles, and to the rulers, and to the rest of the people, The work is great and large, and we are separated upon the wall, one far from another."}, {"numero": 20, "texto": "In what place therefore ye hear the sound of the trumpet, resort ye thither unto us: our God shall fight for us."}, {"numero": 21, "texto": "So we laboured in the work: and half of them held the spears from the rising of the morning till the stars appeared."}, {"numero": 22, "texto": "Likewise at the same time said I unto the people, Let every one with his servant lodge within Jerusalem, that in the night they may be a guard to us, and labour on the day."}, {"numero": 23, "texto": "So neither I, nor my brethren, nor my servants, nor the men of the guard which followed me, none of us put off our clothes, saving that every one put them off for washing."}]'::jsonb, 'King James Version'),
  ('Ne', 4, 'fr', '[{"numero": 1, "texto": "Lorsque Sanballat apprit que nous rebâtissions la muraille, il fut en colère et très irrité. Il se moqua des Juifs,"}, {"numero": 2, "texto": "et dit devant ses frères et devant les soldats de Samarie: A quoi travaillent ces Juifs impuissants? Les laissera-t-on faire? Sacrifieront-ils? Vont-ils achever? Redonneront-ils vie à des pierres ensevelies sous des monceaux de poussière et consumées par le feu?"}, {"numero": 3, "texto": "Tobija, l''''Ammonite, était à côté de lui, et il dit: Qu''''ils bâtissent seulement! Si un renard s''''élance, il renversera leur muraille de pierres!"}, {"numero": 4, "texto": "Ecoute, ô notre Dieu, comme nous sommes méprisés! Fais retomber leurs insultes sur leur tête, et livre-les au pillage sur une terre où ils soient captifs."}, {"numero": 5, "texto": "Ne pardonne pas leur iniquité, et que leur péché ne soit pas effacé de devant toi; car ils ont offensé ceux qui bâtissent."}, {"numero": 6, "texto": "Nous rebâtîmes la muraille, qui fut partout achevée jusqu''''à la moitié de sa hauteur. Et le peuple prit à coeur ce travail."}, {"numero": 7, "texto": "Mais Sanballat, Tobija, les Arabes, les Ammonites et les Asdodiens, furent très irrités en apprenant que la réparation des murs avançait et que les brèches commençaient à se fermer."}, {"numero": 8, "texto": "Ils se liguèrent tous ensemble pour venir attaquer Jérusalem et lui causer du dommage."}, {"numero": 9, "texto": "Nous priâmes notre Dieu, et nous établîmes une garde jour et nuit pour nous défendre contre leurs attaques."}, {"numero": 10, "texto": "Cependant Juda disait: Les forces manquent à ceux qui portent les fardeaux, et les décombres sont considérables; nous ne pourrons pas bâtir la muraille."}, {"numero": 11, "texto": "Et nos ennemis disaient: Ils ne sauront et ne verront rien jusqu''''à ce que nous arrivions au milieu d''''eux; nous les tuerons, et nous ferons ainsi cesser l''''ouvrage."}, {"numero": 12, "texto": "Or les Juifs qui habitaient près d''''eux vinrent dix fois nous avertir, de tous les lieux d''''où ils se rendaient vers nous."}, {"numero": 13, "texto": "C''''est pourquoi je plaçai, dans les enfoncements derrière la muraille et sur des terrains secs, le peuple par familles, tous avec leurs épées, leurs lances et leurs arcs."}, {"numero": 14, "texto": "Je regardai, et m''''étant levé, je dis aux grands, aux magistrats, et au reste du peuple: Ne les craignez pas! Souvenez-vous du Seigneur, grand et redoutable, et combattez pour vos frères, pour vos fils et vos filles, pour vos femmes et pour vos maisons!"}, {"numero": 15, "texto": "Lorsque nos ennemis apprirent que nous étions avertis, Dieu anéantit leur projet, et nous retournâmes tous à la muraille, chacun à son ouvrage."}, {"numero": 16, "texto": "Depuis ce jour, la moitié de mes serviteurs travaillaient, et l''''autre moitié était armée de lances, de boucliers, d''''arcs et de cuirasses. Les chefs étaient derrière toute la maison de Juda."}, {"numero": 17, "texto": "Ceux qui bâtissaient la muraille, et ceux qui portaient ou chargeaient les fardeaux, travaillaient d''''une main et tenaient une arme de l''''autre;"}, {"numero": 18, "texto": "chacun d''''eux, en travaillant, avait son épée ceinte autour des reins. Celui qui sonnait de la trompette se tenait près de moi."}, {"numero": 19, "texto": "Je dis aux grands, aux magistrats, et au reste du peuple: L''''ouvrage est considérable et étendu, et nous sommes dispersés sur la muraille, éloignés les uns des autres."}, {"numero": 20, "texto": "Au son de la trompette, rassemblez-vous auprès de nous, vers le lieu d''''où vous l''''entendrez; notre Dieu combattra pour nous."}, {"numero": 21, "texto": "C''''est ainsi que nous poursuivions l''''ouvrage, la moitié d''''entre nous la lance à la main depuis le lever de l''''aurore jusqu''''à l''''apparition des étoiles."}, {"numero": 22, "texto": "Dans ce même temps, je dis encore au peuple: Que chacun passe la nuit dans Jérusalem avec son serviteur; faisons la garde pendant la nuit, et travaillons pendant le jour."}, {"numero": 23, "texto": "Et nous ne quittions point nos vêtements, ni moi, ni mes frères, ni mes serviteurs, ni les hommes de garde qui me suivaient; chacun n''''avait que ses armes et de l''''eau."}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 4, 'es', '[{"numero": 1, "texto": "Y FUÉ que como oyó Sanballat que nosotros edificábamos el muro, encolerizóse y enojóse en gran manera, é hizo escarnio de los Judíos."}, {"numero": 2, "texto": "Y habló delante de sus hermanos y del ejército de Samaria, y dijo: ¿Qué hacen estos débiles Judíos? ¿hanles de permitir? ¿han de sacrificar? ¿han de acabar en un día? ¿han de resucitar de los montones del polvo las piedras que fueron quemadas?"}, {"numero": 3, "texto": "Y estaba junto á él Tobías Ammonita, el cual dijo: Aun lo que ellos edifican, si subiere una zorra derribará su muro de piedra."}, {"numero": 4, "texto": "Oye, oh Dios nuestro, que somos en menosprecio, y vuelve el baldón de ellos sobre su cabeza, y dalos en presa en la tierra de su cautiverio:"}, {"numero": 5, "texto": "Y no cubras su iniquidad, ni su pecado sea raído delante de tu rostro; porque se airaron contra los que edificaban."}, {"numero": 6, "texto": "Edificamos pues el muro, y toda la muralla fué junta hasta su mitad: y el pueblo tuvo ánimo para obrar."}, {"numero": 7, "texto": "Mas acaeció que oyendo Sanballat y Tobías, y los Arabes, y los Ammonitas, y los de Asdod, que los muros de Jerusalem eran reparados, porque ya los portillos comenzaban á cerrarse, encolerizáronse mucho;"}, {"numero": 8, "texto": "Y conspiraron todos á una para venir á combatir á Jerusalem, y á hacerle daño."}, {"numero": 9, "texto": "Entonces oramos á nuestro Dios, y por causa de ellos pusimos guarda contra ellos de día y de noche."}, {"numero": 10, "texto": "Y dijo Judá: Las fuerzas de los acarreadores se han enflaquecido, y el escombro es mucho, y no podemos edificar el muro."}, {"numero": 11, "texto": "Y nuestros enemigos dijeron: No sepan, ni vean, hasta que entremos en medio de ellos, y los matemos, y hagamos cesar la obra."}, {"numero": 12, "texto": "Sucedió empero, que como vinieron los Judíos que habitaban entre ellos, nos dieron aviso diez veces de todos los lugares de donde volvían á nosotros."}, {"numero": 13, "texto": "Entonces puse por los bajos del lugar, detrás del muro, en las alturas de los peñascos, puse el pueblo por familias con sus espadas, con sus lanzas, y con sus arcos."}, {"numero": 14, "texto": "Después miré, y levantéme, y dije á los principales y á los magistrados, y al resto del pueblo: No temáis delante de ellos: acordaos del Señor grande y terrible, y pelead por vuestros hermanos, por vuestros hijos y por vuestras hijas, por vuestras mujeres y por vuestras casas."}, {"numero": 15, "texto": "Y sucedió que como oyeron nuestros enemigos que lo habíamos entendido, Dios disipó el consejo de ellos, y volvímonos todos al muro, cada uno á su obra."}, {"numero": 16, "texto": "Mas fué que desde aquel día la mitad de los mancebos trabajaba en la obra, y la otra mitad de ellos tenía lanzas y escudos, y arcos, y corazas; y los príncipes estaban tras toda la casa de Judá."}, {"numero": 17, "texto": "Los que edificaban en el muro, y los que llevaban cargas y los que cargaban, con la una mano trabajaban en la obra, y en la otra tenían la espada."}, {"numero": 18, "texto": "Porque los que edificaban, cada uno tenía su espada ceñida á sus lomos, y así edificaban: y el que tocaba la trompeta estaba junto á mí."}, {"numero": 19, "texto": "Y dije á los principales, y á los magistrados y al resto del pueblo: La obra es grande y larga, y nosotros estamos apartados en el muro, lejos los unos de los otros:"}, {"numero": 20, "texto": "En el lugar donde oyereis la voz de la trompeta, reuníos allí á nosotros: nuestro Dios peleará por nosotros."}, {"numero": 21, "texto": "Nosotros pues trabajábamos en la obra; y la mitad de ellos tenían lanzas desde la subida del alba hasta salir las estrellas."}, {"numero": 22, "texto": "También dije entonces al pueblo: Cada uno con su criado se quede dentro de Jerusalem, y hágannos de noche centinela, y de día á la obra."}, {"numero": 23, "texto": "Y ni yo, ni mis hermanos, ni mis mozos, ni la gente de guardia que me seguía, desnudamos nuestro vestido: cada uno se desnudaba solamente para lavarse."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 5, 'pt', '[{"numero": 1, "texto": "Então houve um grande clamor do povo e de suas mulheres contra seus irmãos, os judeus."}, {"numero": 2, "texto": "Pois havia quem dizia: Nós, nossos filhos e nossas filhas, somos muitos; por isso tomamos trigo, para que comamos e vivamos."}, {"numero": 3, "texto": "Também havia quem dizia: Colocamos em penhor nossas terras, nossas vinhas, e nossas casas, para comprarmos trigo durante a fome."}, {"numero": 4, "texto": "E havia quem dizia: Pedimos emprestado até para o tributo do rei [sobre] nossas terras e nossas vinhas."}, {"numero": 5, "texto": "Agora, pois, nossa carne é como a carne de nossos irmãos, [e] nossos filhos como seus filhos; porém eis que nós sujeitamos nossos filhos e nossas filhas por servos, e até [algumas] de nossas filhas estão subjugadas, que não estão em poder de nossas mãos, e outros têm para si nossas terras e nossas vinhas."}, {"numero": 6, "texto": "Quando eu ouvi seu clamor, fiquei muito irado."}, {"numero": 7, "texto": "Então eu meditei em meu coração, e depois briguei com os nobres e com os oficiais, dizendo-lhes: Emprestais com juros cada um a seu irmão?E convoquei contra eles uma grande reunião."}, {"numero": 8, "texto": "E disse-lhes: Nós resgatamos nossos irmãos judeus que haviam sido vendidos às nações, conforme o que nos era possível, e vós novamente venderíeis a vossos irmãos, ou seriam eles vendidos a nós? E ficaram calados, e não acharam o que responder."}, {"numero": 9, "texto": "E eu disse mais: Não é bom o que fazeis. Por acaso não andareis no temor a nosso Deus, para que não haja humilhação da parte das nações [que são] nossas inimigas?"}, {"numero": 10, "texto": "Também eu, meus irmãos, e meus servos, temos lhes emprestado a juros dinheiro e grão. Abandonemos esta cobrança de juros."}, {"numero": 11, "texto": "Devolvei a eles hoje mesmo suas terras, suas vinhas, seus olivais, e suas casas; e a centésima parte do dinheiro e do trigo, do vinho e do azeite que exigis deles."}, {"numero": 12, "texto": "Então disseram: Devolveremos, e nada lhes exigiremos; faremos assim como tu dizes. Então chamei aos sacerdotes, e lhes fiz jurar que fariam conforme esta promessa."}, {"numero": 13, "texto": "Também sacudi minha roupa, e disse: Assim sacuda Deus de sua casa e de seu trabalho a todo homem que não cumprir esta promessa; e assim seja sacudido e esvaziado. E toda a congregação: Amém! E louvaram ao SENHOR. E o povo fez conforme esta promessa."}, {"numero": 14, "texto": "Também desde o dia que fui nomeado governador deles na terra de Judá, desde o ano vinte até o ano trinta e dois do rei Artaxerxes, doze anos, nem eu nem meus irmãos comemos o pão do governador."}, {"numero": 15, "texto": "Mas os primeiros governadores que foram antes de mim, oprimiram ao povo, e tomaram deles pão e pelo vinho, além de quarenta siclos de prata; ainda mais, seus servos dominavam opressivamente sobre o povo; porém eu não fiz assim, por causa do temor a Deus."}, {"numero": 16, "texto": "Além disso, concentrei meus esforços na obra deste muro, e não compramos terra alguma; e todos meus servos se ajuntaram ali para a obra."}, {"numero": 17, "texto": "Também cento e cinquenta homens dos judeus, dos oficiais, e dos que vinha até nós dentre as ns nações que estão ao nosso redor, se punham à minha mesa."}, {"numero": 18, "texto": "E o que se preparava para cada dia era um boi, [e] seis ovelhas escolhidas; também preparavam aves para mim, e cada dez dias todas as variedades de muito vinho; e nem por isso exigi o pão do governador, porque a servidão deste povo era grave."}, {"numero": 19, "texto": "Lembra-te de mim para o bem, ó meu Deus; [e de] tudo o que fiz a este povo."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 5, 'en', '[{"numero": 1, "texto": "And there was a great cry of the people and of their wives against their brethren the Jews."}, {"numero": 2, "texto": "For there were that said, We, our sons, and our daughters, are many: therefore we take up corn for them, that we may eat, and live."}, {"numero": 3, "texto": "Some also there were that said, We have mortgaged our lands, vineyards, and houses, that we might buy corn, because of the dearth."}, {"numero": 4, "texto": "There were also that said, We have borrowed money for the king''s tribute, and that upon our lands and vineyards."}, {"numero": 5, "texto": "Yet now our flesh is as the flesh of our brethren, our children as their children: and, lo, we bring into bondage our sons and our daughters to be servants, and some of our daughters are brought unto bondage already: neither is it in our power to redeem them; for other men have our lands and vineyards."}, {"numero": 6, "texto": "And I was very angry when I heard their cry and these words."}, {"numero": 7, "texto": "Then I consulted with myself, and I rebuked the nobles, and the rulers, and said unto them, Ye exact usury, every one of his brother. And I set a great assembly against them."}, {"numero": 8, "texto": "And I said unto them, We after our ability have redeemed our brethren the Jews, which were sold unto the heathen; and will ye even sell your brethren? or shall they be sold unto us? Then held they their peace, and found nothing to answer."}, {"numero": 9, "texto": "Also I said, It is not good that ye do: ought ye not to walk in the fear of our God because of the reproach of the heathen our enemies?"}, {"numero": 10, "texto": "I likewise, and my brethren, and my servants, might exact of them money and corn: I pray you, let us leave off this usury."}, {"numero": 11, "texto": "Restore, I pray you, to them, even this day, their lands, their vineyards, their oliveyards, and their houses, also the hundredth part of the money, and of the corn, the wine, and the oil, that ye exact of them."}, {"numero": 12, "texto": "Then said they, We will restore them, and will require nothing of them; so will we do as thou sayest. Then I called the priests, and took an oath of them, that they should do according to this promise."}, {"numero": 13, "texto": "Also I shook my lap, and said, So God shake out every man from his house, and from his labour, that performeth not this promise, even thus be he shaken out, and emptied. And all the congregation said, Amen, and praised the Lord. And the people did according to this promise."}, {"numero": 14, "texto": "Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year even unto the two and thirtieth year of Artaxerxes the king, that is, twelve years, I and my brethren have not eaten the bread of the governor."}, {"numero": 15, "texto": "But the former governors that had been before me were chargeable unto the people, and had taken of them bread and wine, beside forty shekels of silver; yea, even their servants bare rule over the people: but so did not I, because of the fear of God."}, {"numero": 16, "texto": "Yea, also I continued in the work of this wall, neither bought we any land: and all my servants were gathered thither unto the work."}, {"numero": 17, "texto": "Moreover there were at my table an hundred and fifty of the Jews and rulers, beside those that came unto us from among the heathen that are about us."}, {"numero": 18, "texto": "Now that which was prepared for me daily was one ox and six choice sheep; also fowls were prepared for me, and once in ten days store of all sorts of wine: yet for all this required not I the bread of the governor, because the bondage was heavy upon this people."}, {"numero": 19, "texto": "Think upon me, my God, for good, according to all that I have done for this people."}]'::jsonb, 'King James Version'),
  ('Ne', 5, 'fr', '[{"numero": 1, "texto": "Il s''''éleva de la part des gens du peuple et de leurs femmes de grandes plaintes contre leurs frères les Juifs."}, {"numero": 2, "texto": "Les uns disaient: Nous, nos fils et nos filles, nous sommes nombreux; qu''''on nous donne du blé, afin que nous mangions et que nous vivions."}, {"numero": 3, "texto": "D''''autres disaient: Nous engageons nos champs, nos vignes, et nos maisons, pour avoir du blé pendant la famine."}, {"numero": 4, "texto": "D''''autres disaient: Nous avons emprunté de l''''argent sur nos champs et nos vignes pour le tribut du roi."}, {"numero": 5, "texto": "Et pourtant notre chair est comme la chair de nos frères, nos enfants sont comme leurs enfants; et voici, nous soumettons à la servitude nos fils et nos filles, et plusieurs de nos filles y sont déjà réduites; nous sommes sans force, et nos champs et nos vignes sont à d''''autres."}, {"numero": 6, "texto": "Je fus très irrité lorsque j''''entendis leurs plaintes et ces paroles-là."}, {"numero": 7, "texto": "Je résolus de faire des réprimandes aux grands et aux magistrats, et je leur dis: Quoi! vous prêtez à intérêt à vos frères! Et je rassemblai autour d''''eux une grande foule,"}, {"numero": 8, "texto": "et je leur dis: Nous avons racheté selon notre pouvoir nos frères les Juifs vendus aux nations; et vous vendriez vous-mêmes vos frères, et c''''est à nous qu''''ils seraient vendus! Ils se turent, ne trouvant rien à répondre."}, {"numero": 9, "texto": "Puis je dis: Ce que vous faites n''''est pas bien. Ne devriez-vous pas marcher dans la crainte de notre Dieu, pour n''''être pas insultés par les nations nos ennemies?"}, {"numero": 10, "texto": "Moi aussi, et mes frères et mes serviteurs, nous leur avons prêté de l''''argent et du blé. Abandonnons ce qu''''ils nous doivent!"}, {"numero": 11, "texto": "Rendez-leur donc aujourd''''hui leurs champs, leurs vignes, leurs oliviers et leurs maisons, et le centième de l''''argent, du blé, du moût et de l''''huile que vous avez exigé d''''eux comme intérêt."}, {"numero": 12, "texto": "Ils répondirent: Nous les rendrons, et nous ne leur demanderons rien, nous ferons ce que tu dis. Alors j''''appelai les sacrificateurs, devant lesquels je les fis jurer de tenir parole."}, {"numero": 13, "texto": "Et je secouai mon manteau, en disant: Que Dieu secoue de la même manière hors de sa maison et de ses biens tout homme qui n''''aura point tenu parole, et qu''''ainsi cet homme soit secoué et laissé à vide! Toute l''''assemblée dit: Amen! On célébra l''''Eternel. Et le peuple tint parole."}, {"numero": 14, "texto": "Dès le jour où le roi m''''établit leur gouverneur dans le pays de Juda, depuis la vingtième année jusqu''''à la trente-deuxième année du roi Artaxerxès, pendant douze ans, ni moi ni mes frères n''''avons vécu des revenus du gouverneur."}, {"numero": 15, "texto": "Avant moi, les premiers gouverneurs accablaient le peuple, et recevaient de lui du pain et du vin, outre quarante sicles d''''argent; leurs serviteurs mêmes opprimaient le peuple. Je n''''ai point agi de la sorte, par crainte de Dieu."}, {"numero": 16, "texto": "Bien plus, j''''ai travaillé à la réparation de cette muraille, et nous n''''avons acheté aucun champ, et mes serviteurs tous ensemble étaient à l''''ouvrage."}, {"numero": 17, "texto": "J''''avais à ma table cent cinquante hommes, Juifs et magistrats, outre ceux qui venaient à nous des nations d''''alentour."}, {"numero": 18, "texto": "On m''''apprêtait chaque jour un boeuf, six moutons choisis, et des oiseaux; et tous les dix jours on préparait en abondance tout le vin nécessaire. Malgré cela, je n''''ai point réclamé les revenus du gouverneur, parce que les travaux étaient à la charge de ce peuple."}, {"numero": 19, "texto": "Souviens-toi favorablement de moi, ô mon Dieu, à cause de tout ce que j''''ai fait pour ce peuple!"}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 5, 'es', '[{"numero": 1, "texto": "ENTONCES fué grande el clamor del pueblo y de sus mujeres contra los Judíos sus hermanos."}, {"numero": 2, "texto": "Y había quien decía: Nosotros, nuestros hijos y nuestras hijas, somos muchos: hemos por tanto tomado grano para comer y vivir."}, {"numero": 3, "texto": "Y había quienes decían: Hemos empeñado nuestras tierras, y nuestras viñas, y nuestras casas, para comprar grano en el hambre."}, {"numero": 4, "texto": "Y había quienes decían: Hemos tomado prestado dinero para el tributo del rey, sobre nuestras tierras y viñas."}, {"numero": 5, "texto": "Ahora bien, nuestra carne es como la carne de nuestros hermanos, nuestros hijos como sus hijos: y he aquí que nosotros sujetamos nuestros hijos y nuestras hijas á servidumbre, y hay algunas de nuestras hijas sujetas: mas no hay facultad en nuestras manos para rescatarlas, porque nuestras tierras y nuestras viñas son de otros."}, {"numero": 6, "texto": "Y enojéme en gran manera cuando oí su clamor y estas palabras."}, {"numero": 7, "texto": "Meditélo entonces para conmigo, y reprendí á los principales y á los magistrados, y díjeles: ¿Tomáis cada uno usura de vuestros hermanos? Y convoqué contra ellos una grande junta."}, {"numero": 8, "texto": "Y díjeles: Nosotros rescatamos á nuestros hermanos Judíos que habían sido vendidos á las gentes, conforme á la facultad que había en nosotros: ¿y vosotros aun vendéis á vuestros hermanos, y serán vendidos á nosotros? Y callaron, que no tuvieron qué responder."}, {"numero": 9, "texto": "Y dije: No es bien lo que hacéis, ¿no andaréis en temor de nuestro Dios, por no ser el oprobio de las gentes enemigas nuestras?"}, {"numero": 10, "texto": "También yo, y mis hermanos, y mis criados, les hemos prestado dinero y grano: relevémosles ahora de este gravamen."}, {"numero": 11, "texto": "Ruégoos que les devolváis hoy sus tierras, sus viñas, sus olivares, y sus casas, y la centésima parte del dinero y grano, del vino y del aceite que demandáis de ellos."}, {"numero": 12, "texto": "Y dijeron: Devolveremos, y nada les demandaremos; haremos así como tú dices. Entonces convoqué los sacerdotes, y juramentélos que harían conforme á esto."}, {"numero": 13, "texto": "Además sacudí mi vestido, y dije: Así sacuda Dios de su casa y de su trabajo á todo hombre que no cumpliere esto, y así sea sacudido y vacío. Y respondió toda la congregación: ¡Amén! Y alabaron á Jehová. Y el pueblo hizo conforme á esto."}, {"numero": 14, "texto": "También desde el día que me mandó el rey que fuese gobernador de ellos en la tierra de Judá, desde el año veinte del rey Artajerjes hasta el año treinta y dos, doce años, ni yo ni mis hermanos comimos el pan del gobernador."}, {"numero": 15, "texto": "Mas los primeros gobernadores que fueron antes de mí, cargaron al pueblo, y tomaron de ellos por el pan y por el vino sobre cuarenta siclos de plata: á más de esto, sus criados se enseñoreaban sobre el pueblo; pero yo no hice así, á causa del temor de Dios."}, {"numero": 16, "texto": "También en la obra de este muro instauré mi parte, y no compramos heredad: y todos mis criados juntos estaban allí á la obra."}, {"numero": 17, "texto": "Además ciento y cincuenta hombres de los Judíos y magistrados, y los que venían á nosotros de las gentes que están en nuestros contornos, estaban á mi mesa."}, {"numero": 18, "texto": "Y lo que se aderezaba para cada día era un buey, seis ovejas escogidas, y aves también se aparejaban para mí, y cada diez días vino en toda abundancia: y con todo esto nunca requerí el pan del gobernador, porque la servidumbre de este pueblo era grave."}, {"numero": 19, "texto": "Acuérdate de mí para bien, Dios mío, y de todo lo que hice á este pueblo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 6, 'pt', '[{"numero": 1, "texto": "Sucedeu, pois, que, quando Sambalate, Tobias, e Gesém o árabe, e os demais de nossos inimigos, ouviram que eu tinha edificado o muro, e que não havia mais brecha nele (ainda que até aquele tempo não tinha posto as portas nas entradas),"}, {"numero": 2, "texto": "Sambalate e Gesém mandaram dizer: Vem, e nos reunamos em alguma das aldeias no vale de Ono. Mas eles haviam pensado em fazer o mal a mim."}, {"numero": 3, "texto": "E enviei-lhes mensageiros, dizendo: Eu faço uma grande obra, por isso não posso descer; porque eu pararia a obra, para a deixar, e ir me encontrar convosco?"}, {"numero": 4, "texto": "E mandaram a mesma mensagem a mim quatro vezes, e eu lhes respondi da mesma maneira."}, {"numero": 5, "texto": "Então Sambalate enviou a mim seu servo pela quinta vez, com uma carta aberta em sua mão,"}, {"numero": 6, "texto": "Em que estava escrito: Ouve-se falar entre as nações, e Gesém disse, que tu e os judeus pensais vos rebelar; e por isso tu edificas o muro, para que tu sejas o rei deles, conforme o que se diz."}, {"numero": 7, "texto": "E que puseste profetas para proclamem de ti em Jerusalém, dizendo: [Este é] o rei em Judá! Assim o rei ouvirá conforme estas palavras. Vem, pois, agora, e nos reunamos."}, {"numero": 8, "texto": "Porém eu mandei lhes dizer: Nada do que dizes aconteceu, mas sim és tu que inventas de tua própria mente."}, {"numero": 9, "texto": "Porque todos eles procuravam nos atemorizar, dizendo: As mãos deles se enfraquecerão da obra, e ela não será feita.Esforça pois minhas mãos, [ó Deus] ."}, {"numero": 10, "texto": "E quando eu vim à casa de Semaías filho de Delaías, filho de Meetabel (que estava encerrado), ele me disse: Vamos juntos à casa de Deus dentro do templo, e cerremos as portas do templo, porque virão para te matar; sim, de noite virão para te matar."}, {"numero": 11, "texto": "Porém eu disse: Um homem como eu fugiria? E poderia alguém como eu entrar no templo para preservar sua vida? De maneira nenhuma entrarei."}, {"numero": 12, "texto": "E percebi, e vi que Deus não tinha o enviado, mas sim que ele falou aquela profecia contra mim, porque Tobias e Sambalate haviam lhe subornado."}, {"numero": 13, "texto": "Para isto ele foi subornado, para me atemorizar, a fim de que assim eu fizesse, e pecasse; para que tivessem alguma coisa para falarem mal de mim."}, {"numero": 14, "texto": "Lembra-te, meu Deus, de Tobias e de Sambalate, conforme estas suas obras, e também da profetiza Noadia, e dos outros profetas que procuravam me atemorizar."}, {"numero": 15, "texto": "O muro foi terminado ao [dia] vinte e cinco do mês de Elul, em cinquenta e dois dias."}, {"numero": 16, "texto": "E foi que, quando todos os nossos inimigos ouviram, todas as nações ao nosso redor temeram, e abateram-se muito em seus olhos, porque reconheceram que foi nosso Deus que fizera esta obra."}, {"numero": 17, "texto": "Também naqueles dias muitas foram escritas de [alguns] dos nobres de Judá a Tobias, e as de Tobias vinham a eles."}, {"numero": 18, "texto": "Porque muitos em Judá haviam feito juramento com ele, porque ele era genro de Secanias, filho de Ara; e seu filho Joanã havia tomado a filha de Mesulão, filho de Berequias."}, {"numero": 19, "texto": "Também contavam diante de mim suas boas obras, e levavam a ele minhas palavras. E Tobias me enviava cartas para me atemorizar."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 6, 'en', '[{"numero": 1, "texto": "Now it came to pass when Sanballat, and Tobiah, and Geshem the Arabian, and the rest of our enemies, heard that I had builded the wall, and that there was no breach left therein; (though at that time I had not set up the doors upon the gates;)"}, {"numero": 2, "texto": "That Sanballat and Geshem sent unto me, saying, Come, let us meet together in some one of the villages in the plain of Ono. But they thought to do me mischief."}, {"numero": 3, "texto": "And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?"}, {"numero": 4, "texto": "Yet they sent unto me four times after this sort; and I answered them after the same manner."}, {"numero": 5, "texto": "Then sent Sanballat his servant unto me in like manner the fifth time with an open letter in his hand;"}, {"numero": 6, "texto": "Wherein was written, It is reported among the heathen, and Gashmu saith it, that thou and the Jews think to rebel: for which cause thou buildest the wall, that thou mayest be their king, according to these words."}, {"numero": 7, "texto": "And thou hast also appointed prophets to preach of thee at Jerusalem, saying, There is a king in Judah: and now shall it be reported to the king according to these words. Come now therefore, and let us take counsel together."}, {"numero": 8, "texto": "Then I sent unto him, saying, There are no such things done as thou sayest, but thou feignest them out of thine own heart."}, {"numero": 9, "texto": "For they all made us afraid, saying, Their hands shall be weakened from the work, that it be not done. Now therefore, O God, strengthen my hands."}, {"numero": 10, "texto": "Afterward I came unto the house of Shemaiah the son of Delaiah the son of Mehetabeel, who was shut up; and he said, Let us meet together in the house of God, within the temple, and let us shut the doors of the temple: for they will come to slay thee; yea, in the night will they come to slay thee."}, {"numero": 11, "texto": "And I said, Should such a man as I flee? and who is there, that, being as I am, would go into the temple to save his life? I will not go in."}, {"numero": 12, "texto": "And, lo, I perceived that God had not sent him; but that he pronounced this prophecy against me: for Tobiah and Sanballat had hired him."}, {"numero": 13, "texto": "Therefore was he hired, that I should be afraid, and do so, and sin, and that they might have matter for an evil report, that they might reproach me."}, {"numero": 14, "texto": "My God, think thou upon Tobiah and Sanballat according to these their works, and on the prophetess Noadiah, and the rest of the prophets, that would have put me in fear."}, {"numero": 15, "texto": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}, {"numero": 16, "texto": "And it came to pass, that when all our enemies heard thereof, and all the heathen that were about us saw these things, they were much cast down in their own eyes: for they perceived that this work was wrought of our God."}, {"numero": 17, "texto": "Moreover in those days the nobles of Judah sent many letters unto Tobiah, and the letters of Tobiah came unto them."}, {"numero": 18, "texto": "For there were many in Judah sworn unto him, because he was the son in law of Shechaniah the son of Arah; and his son Johanan had taken the daughter of Meshullam the son of Berechiah."}, {"numero": 19, "texto": "Also they reported his good deeds before me, and uttered my words to him. And Tobiah sent letters to put me in fear."}]'::jsonb, 'King James Version'),
  ('Ne', 6, 'fr', '[{"numero": 1, "texto": "Je n''''avais pas encore posé les battants des portes, lorsque Sanballat, Tobija, Guéschem, l''''Arabe, et nos autres ennemis apprirent que j''''avais rebâti la muraille et qu''''il n''''y restait plus de brèche."}, {"numero": 2, "texto": "Alors Sanballat et Guéschem m''''envoyèrent dire: Viens, et ayons ensemble une entrevue dans les villages de la vallée d''''Ono. Ils avaient médité de me faire du mal."}, {"numero": 3, "texto": "Je leur envoyai des messagers avec cette réponse: J''''ai un grand ouvrage à exécuter, et je ne puis descendre; le travail serait interrompu pendant que je le quitterais pour aller vers vous."}, {"numero": 4, "texto": "Ils m''''adressèrent quatre fois la même demande, et je leur fis la même réponse."}, {"numero": 5, "texto": "Sanballat m''''envoya ce message une cinquième fois par son serviteur, qui tenait à la main une lettre ouverte."}, {"numero": 6, "texto": "Il y était écrit: Le bruit se répand parmi les nations et Gaschmu affirme que toi et les Juifs vous pensez à vous révolter, et que c''''est dans ce but que tu rebâtis la muraille. Tu vas, dit-on, devenir leur roi,"}, {"numero": 7, "texto": "tu as même établi des prophètes pour te proclamer à Jérusalem roi de Juda. Et maintenant ces choses arriveront à la connaissance du roi. Viens donc, et consultons-nous ensemble."}, {"numero": 8, "texto": "Je fis répondre à Sanballat: Ce que tu dis là n''''est pas; c''''est toi qui l''''inventes!"}, {"numero": 9, "texto": "Tous ces gens voulaient nous effrayer, et ils se disaient: Ils perdront courage, et l''''oeuvre ne se fera pas. Maintenant, ô Dieu, fortifie-moi!"}, {"numero": 10, "texto": "Je me rendis chez Schemaeja, fils de Delaja, fils de Mehétabeel. Il s''''était enfermé, et il dit: Allons ensemble dans la maison de Dieu, au milieu du temple, et fermons les portes du temple; car ils viennent pour te tuer, et c''''est pendant la nuit qu''''ils viendront pour te tuer."}, {"numero": 11, "texto": "Je répondis: Un homme comme moi prendre la fuite! Et quel homme tel que moi pourrait entrer dans le temple et vivre? Je n''''entrerai point."}, {"numero": 12, "texto": "Et je reconnus que ce n''''était pas Dieu qui l''''envoyait. Mais il prophétisa ainsi sur moi parce que Sanballat et Tobija lui avaient donné de l''''argent."}, {"numero": 13, "texto": "En le gagnant ainsi, ils espéraient que j''''aurais peur, et que je suivrais ses avis et commettrais un péché; et ils auraient profité de cette atteinte à ma réputation pour me couvrir d''''opprobre."}, {"numero": 14, "texto": "Souviens-toi, ô mon Dieu, de Tobija et de Sanballat, et de leurs oeuvres! Souviens-toi aussi de Noadia, la prophétesse, et des autres prophètes qui cherchaient à m''''effrayer!"}, {"numero": 15, "texto": "La muraille fut achevée le vingt-cinquième jour du mois d''''Elul, en cinquante-deux jours."}, {"numero": 16, "texto": "Lorsque tous nos ennemis l''''apprirent, toutes les nations qui étaient autour de nous furent dans la crainte; elles éprouvèrent une grande humiliation, et reconnurent que l''''oeuvre s''''était accomplie par la volonté de notre Dieu."}, {"numero": 17, "texto": "Dans ce temps-là, il y avait aussi des grands de Juda qui adressaient fréquemment des lettres à Tobija et qui en recevaient de lui."}, {"numero": 18, "texto": "Car plusieurs en Juda étaient liés à lui par serment, parce qu''''il était gendre de Schecania, fils d''''Arach, et que son fils Jochanan avait pris la fille de Meschullam, fils de Bérékia."}, {"numero": 19, "texto": "Ils disaient même du bien de lui en ma présence, et ils lui rapportaient mes paroles. Tobija envoyait des lettres pour m''''effrayer."}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 6, 'es', '[{"numero": 1, "texto": "Y FUÉ que habiendo oído Sanballat, y Tobías, y Gesem el Arabe, y los demás nuestros enemigos, que había yo edificado el muro, y que no quedaba en él portillo, (aunque hasta aquel tiempo no había puesto en las puertas las hojas,)"}, {"numero": 2, "texto": "Sanballat y Gesem enviaron á decirme: Ven, y compongámonos juntos en alguna de las aldeas en el campo de Ono. Mas ellos habían pensado hacerme mal."}, {"numero": 3, "texto": "Y enviéles mensajeros, diciendo: Yo hago una grande obra, y no puedo ir; porque cesaría la obra, dejándola yo para ir á vosotros."}, {"numero": 4, "texto": "Y enviaron á mí con el mismo asunto por cuatro veces, y yo les respondí de la misma manera."}, {"numero": 5, "texto": "Envió entonces Sanballat á mí su criado, á decir lo mismo por quinta vez, con una carta abierta en su mano,"}, {"numero": 6, "texto": "En la cual estaba escrito: Hase oído entre las gentes, y Gasmu lo dice, que tú y los Judíos pensáis rebelaros; y que por eso edificas tú el muro, con la mira, según estas palabras, de ser tú su rey;"}, {"numero": 7, "texto": "Y que has puesto profetas que prediquen de ti en Jerusalem, diciendo: ¡Rey en Judá! Y ahora serán oídas del rey las tales palabras: ven por tanto, y consultemos juntos."}, {"numero": 8, "texto": "Entonces envié yo á decirle: No hay tal cosa como dices, sino que de tu corazón tú lo inventas."}, {"numero": 9, "texto": "Porque todos ellos nos ponían miedo, diciendo: Debilitaránse las manos de ellos en la obra, y no será hecha. Esfuerza pues mis manos, oh Dios."}, {"numero": 10, "texto": "Vine luego en secreto á casa de Semaías hijo de Delaías, hijo de Mehetabeel, porque él estaba encerrado; el cual me dijo: Juntémonos en la casa de Dios dentro del templo, y cerremos las puertas del templo, porque vienen para matarte; sí, esta noche vendrán á matarte."}, {"numero": 11, "texto": "Entonces dije: ¿Un hombre como yo ha de huir? ¿y quién, que como yo fuera, entraría al templo para salvar la vida? No entraré."}, {"numero": 12, "texto": "Y entendí que Dios no lo había enviado, sino que hablaba aquella profecía contra mí, porque Tobías y Sanballat le habían alquilado por salario."}, {"numero": 13, "texto": "Porque sobornado fué para hacerme temer así, y que pecase, y les sirviera de mal nombre con que fuera yo infamado."}, {"numero": 14, "texto": "Acuérdate, Dios mío, de Tobías y de Sanballat, conforme á estas sus obras, y también de Noadías profetisa, y de los otros profetas que hacían por ponerme miedo."}, {"numero": 15, "texto": "Acabóse pues el muro el veinticinco del mes de Elul, en cincuenta y dos días."}, {"numero": 16, "texto": "Y como lo oyeron todos nuestros enemigos, temieron todas las gentes que estaban en nuestros alrededores, y abatiéronse mucho sus ojos, y conocieron que por nuestro Dios había sido hecha esta obra."}, {"numero": 17, "texto": "Asimismo en aquellos días iban muchas cartas de los principales de Judá á Tobías, y las de Tobías venían á ellos."}, {"numero": 18, "texto": "Porque muchos en Judá se habían conjurado con él, porque era yerno de Sechânías hijo de Ara; y Johanán su hijo había tomado la hija de Mesullam, hijo de Berechîas."}, {"numero": 19, "texto": "También contaban delante de mí sus buenas obras, y referíanle mis palabras. Y enviaba Tobías cartas para atemorizarme."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ne', 8, 'pt', '[{"numero": 1, "texto": "E todo o povo se juntou como um só homem na praça diante da porta das Águas, e disseram ao escriba Esdras que trouxesse o livro da lei de Moisés, que o SENHOR havia mandado a Israel."}, {"numero": 2, "texto": "E Esdras, o sacerdote, trouxe a lei diante da congregação, tanto de homens como de mulheres, e de todos os que tivessem entendimento para ouvir, no primeiro dia do sétimo mês."}, {"numero": 3, "texto": "E leu no [livro] diante da praça que está diante da porta das Águas, desde o amanhecer até o meio-dia, na presença de homens, mulheres e entendidos; e os ouvidos de todo o povo estavam [atentos] ao livro da lei."}, {"numero": 4, "texto": "E o escriba Esdras estava sobre uma plataforma de madeira, que haviam feito para aquilo; e junto a ele estavam Matitias, Sema, Anaías, Urias, Hilquias, e Maaseias, à sua direita; e a sua esquerda, Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias, e Mesulão."}, {"numero": 5, "texto": "E Esdras abriu o livro perante os olhos de todo o povo, porque estava mais alto que todo o povo; e quando ele o abriu, todo o povo se pôs de pé."}, {"numero": 6, "texto": "Então Esdras louvou ao SENHOR, o grande Deus. E todo o povo respondeu: Amém! Amém! levantando suas mãos; e inclinaram-se, e adoraram ao SENHOR com os rostos em terra."}, {"numero": 7, "texto": "E Jesua, Bani, e Serebias, Jamim, Acube, Sabetai, Hodias, Maaseias, Quelita, Azarias, Jozabade, Hanã, Pelaías, e os levitas, ensinavam ao povo a lei; e o povo estava em seu lugar."}, {"numero": 8, "texto": "E leram no livro da lei de Deus o declarando, e explicando o sentido, para que pudessem entender o que era lido."}, {"numero": 9, "texto": "E Neemias (que era o governador), e o sacerdote Esdras, escriba, e os levitas que ensinavam ao povo, disseram a todo o povo: Este dia é consagrado ao SENHOR nosso Deus; não vos entristeçais, nem choreis. Porque todo o povo chorava enquanto ouvia as palavras da lei."}, {"numero": 10, "texto": "E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa força."}, {"numero": 11, "texto": "E os levitas faziam todo o povo ficar calado, dizendo: Calai-vos, que é dia santo, e não vos entristeçais."}, {"numero": 12, "texto": "Então todo o povo foi embora para comer, beber, enviar porções, e celebrar alegremente, porque entenderam as palavras que lhes haviam ensinado."}, {"numero": 13, "texto": "E no dia seguinte se juntaram os líderes das famílias de todo o povo, os sacerdotes, os levitas, o e o escriba Esdras, para estudarem as palavras da lei."}, {"numero": 14, "texto": "E acharam escrito na lei que o SENHOR havia mandado por meio de Moisés, que os filhos de Israel habitassem em tendas na solenidade do mês sétimo;"}, {"numero": 15, "texto": "Por isso eles anunciaram publicamente, e proclamaram por todas as suas cidades e por Jerusalém, dizendo: Saí ao monte, trazei ramos de oliveiras, e ramos de oliveiras silvestres, e ramos de murta, ramos de palmeiras, e ramos de toda árvore espessa, para fazer tendas como está escrito."}, {"numero": 16, "texto": "Saiu, pois, povo, e os trouxeram, e fizeram para si tendas, cada um sobre seu terraço, em seus pátios, nos pátios da casa de Deus, na praça da porta das Águas, e na praça da porta de Efraim."}, {"numero": 17, "texto": "E toda a congregação dos que voltaram do cativeiro fizeram tendas, e em tendas habitaram; porque os filhos de Israel, desde os dias de Josué filho de Num até aquele dia, não haviam feito assim. E houve alegria muito grande."}, {"numero": 18, "texto": "E a cada dia Esdras leu no livro da lei de Deus, desde o primeiro dia até o último; e celebraram a solenidade durante sete dias, e ao oitavo dia houve uma assembleia solene, conforme a ordenança."}]'::jsonb, 'Almeida Livre'),
  ('Ne', 8, 'en', '[{"numero": 1, "texto": "And all the people gathered themselves together as one man into the street that was before the water gate; and they spake unto Ezra the scribe to bring the book of the law of Moses, which the Lord had commanded to Israel."}, {"numero": 2, "texto": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month."}, {"numero": 3, "texto": "And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}, {"numero": 4, "texto": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}, {"numero": 5, "texto": "And Ezra opened the book in the sight of all the people; (for he was above all the people;) and when he opened it, all the people stood up:"}, {"numero": 6, "texto": "And Ezra blessed the Lord, the great God. And all the people answered, Amen, Amen, with lifting up their hands: and they bowed their heads, and worshipped the Lord with their faces to the ground."}, {"numero": 7, "texto": "Also Jeshua, and Bani, and Sherebiah, Jamin, Akkub, Shabbethai, Hodijah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law: and the people stood in their place."}, {"numero": 8, "texto": "So they read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading."}, {"numero": 9, "texto": "And Nehemiah, which is the Tirshatha, and Ezra the priest the scribe, and the Levites that taught the people, said unto all the people, This day is holy unto the Lord your God; mourn not, nor weep. For all the people wept, when they heard the words of the law."}, {"numero": 10, "texto": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the Lord is your strength."}, {"numero": 11, "texto": "So the Levites stilled all the people, saying, Hold your peace, for the day is holy; neither be ye grieved."}, {"numero": 12, "texto": "And all the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared unto them."}, {"numero": 13, "texto": "And on the second day were gathered together the chief of the fathers of all the people, the priests, and the Levites, unto Ezra the scribe, even to understand the words of the law."}, {"numero": 14, "texto": "And they found written in the law which the Lord had commanded by Moses, that the children of Israel should dwell in booths in the feast of the seventh month:"}, {"numero": 15, "texto": "And that they should publish and proclaim in all their cities, and in Jerusalem, saying, Go forth unto the mount, and fetch olive branches, and pine branches, and myrtle branches, and palm branches, and branches of thick trees, to make booths, as it is written."}, {"numero": 16, "texto": "So the people went forth, and brought them, and made themselves booths, every one upon the roof of his house, and in their courts, and in the courts of the house of God, and in the street of the water gate, and in the street of the gate of Ephraim."}, {"numero": 17, "texto": "And all the congregation of them that were come again out of the captivity made booths, and sat under the booths: for since the days of Jeshua the son of Nun unto that day had not the children of Israel done so. And there was very great gladness."}, {"numero": 18, "texto": "Also day by day, from the first day unto the last day, he read in the book of the law of God. And they kept the feast seven days; and on the eighth day was a solemn assembly, according unto the manner."}]'::jsonb, 'King James Version'),
  ('Ne', 8, 'fr', '[{"numero": 1, "texto": "Alors tout le peuple s''''assembla comme un seul homme sur la place qui est devant la porte des eaux. Ils dirent à Esdras, le scribe, d''''apporter le livre de la loi de Moïse, prescrite par l''''Eternel à Israël."}, {"numero": 2, "texto": "Et le sacrificateur Esdras apporta la loi devant l''''assemblée, composée d''''hommes et de femmes et de tous ceux qui étaient capables de l''''entendre. C''''était le premier jour du septième mois."}, {"numero": 3, "texto": "Esdras lut dans le livre depuis le matin jusqu''''au milieu du jour, sur la place qui est devant la porte des eaux, en présence des hommes et des femmes et de ceux qui étaient capables de l''''entendre. Tout le peuple fut attentif à la lecture du livre de la loi."}, {"numero": 4, "texto": "Esdras, le scribe, était placé sur une estrade de bois, dressée à cette occasion. Auprès de lui, à sa droite, se tenaient Matthithia, Schéma, Anaja, Urie, Hilkija et Maaséja, et à sa gauche, Pedaja, Mischaël, Malkija, Haschum, Haschbaddana, Zacharie et Meschullam."}, {"numero": 5, "texto": "Esdras ouvrit le livre à la vue de tout le peuple, car il était élevé au-dessus de tout le peuple; et lorsqu''''il l''''eut ouvert, tout le peuple se tint en place."}, {"numero": 6, "texto": "Esdras bénit l''''Eternel, le grand Dieu, et tout le peuple répondit, en levant les mains: Amen! amen! Et ils s''''inclinèrent et se prosternèrent devant l''''Eternel, le visage contre terre."}, {"numero": 7, "texto": "Josué, Bani, Schérébia, Jamin, Akkub, Schabbethaï, Hodija, Maaséja, Kelitha, Azaria, Jozabad, Hanan, Pelaja, et les Lévites, expliquaient la loi au peuple, et chacun restait à sa place."}, {"numero": 8, "texto": "Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu''''ils avaient lu."}, {"numero": 9, "texto": "Néhémie, le gouverneur, Esdras, le sacrificateur et le scribe, et les Lévites qui enseignaient le peuple, dirent à tout le peuple: Ce jour est consacré à l''''Eternel, votre Dieu; ne soyez pas dans la désolation et dans les larmes! Car tout le peuple pleurait en entendant les paroles de la loi."}, {"numero": 10, "texto": "Ils leur dirent: Allez, mangez des viandes grasses et buvez des liqueurs douces, et envoyez des portions à ceux qui n''''ont rien de préparé, car ce jour est consacré à notre Seigneur; ne vous affligez pas, car la joie de l''''Eternel sera votre force."}, {"numero": 11, "texto": "Les Lévites calmaient tout le peuple, en disant: Taisez-vous, car ce jour est saint; ne vous affligez pas!"}, {"numero": 12, "texto": "Et tout le peuple s''''en alla pour manger et boire, pour envoyer des portions, et pour se livrer à de grandes réjouissances. Car ils avaient compris les paroles qu''''on leur avait expliquées."}, {"numero": 13, "texto": "Le second jour, les chefs de famille de tout le peuple, les sacrificateurs et les Lévites, s''''assemblèrent auprès d''''Esdras, le scribe, pour entendre l''''explication des paroles de la loi."}, {"numero": 14, "texto": "Et ils trouvèrent écrit dans la loi que l''''Eternel avait prescrite par Moïse, que les enfants d''''Israël devaient habiter sous des tentes pendant la fête du septième mois,"}, {"numero": 15, "texto": "et proclamer cette publication dans toutes leurs villes et à Jérusalem: Allez chercher à la montagne des rameaux d''''olivier, des rameaux d''''olivier sauvage, des rameaux de myrte, des rameaux de palmier, et des rameaux d''''arbres touffus, pour faire des tentes, comme il est écrit."}, {"numero": 16, "texto": "Alors le peuple alla chercher des rameaux, et ils se firent des tentes sur le toit de leurs maisons, dans leurs cours, dans les parvis de la maison de Dieu, sur la place de la porte des eaux et sur la place de la porte d''''Ephraïm."}, {"numero": 17, "texto": "Toute l''''assemblée de ceux qui étaient revenus de la captivité fit des tentes, et ils habitèrent sous ces tentes. Depuis le temps de Josué, fils de Nun, jusqu''''à ce jour, les enfants d''''Israël n''''avaient rien fait de pareil. Et il y eut de très grandes réjouissances."}, {"numero": 18, "texto": "On lut dans le livre de la loi de Dieu chaque jour, depuis le premier jour jusqu''''au dernier. On célébra la fête pendant sept jours, et il y eut une assemblée solennelle le huitième jour, comme cela est ordonné."}]'::jsonb, 'Louis Segond 1910'),
  ('Ne', 8, 'es', '[{"numero": 1, "texto": "Y JUNTÓSE todo el pueblo como un solo hombre en la plaza que está delante de la puerta de las Aguas, y dijeron á Esdras el escriba, que trajese el libro de la ley de Moisés, la cual mandó Jehová á Israel."}, {"numero": 2, "texto": "Y Esdras el sacerdote, trajo la ley delante de la congregación, así de hombres como de mujeres, y de todo entendido para escuchar, el primer día del mes séptimo."}, {"numero": 3, "texto": "Y leyó en el libro delante de la plaza que está delante de la puerta de las Aguas, desde el alba hasta el medio día, en presencia de hombres y mujeres y entendidos; y los oídos de todo el pueblo estaban atentos al libro de la ley."}, {"numero": 4, "texto": "Y Esdras el escriba estaba sobre un púlpito de madera, que habían hecho para ello; y junto á él estaban Mathithías, y Sema, y Anías, y Urías, é Hilcías, y Maasías, á su mano derecha; y á su mano izquierda, Pedaía, Misael, y Malchîas, y Hasum, y Hasbedana, Zachârías, y Mesullam."}, {"numero": 5, "texto": "Abrió pues Esdras el libro á ojos de todo el pueblo, (porque estaba más alto que todo el pueblo); y como lo abrió, todo el pueblo estuvo atento."}, {"numero": 6, "texto": "Bendijo entonces Esdras á Jehová, Dios grande. Y todo el pueblo respondió, ¡Amén! ¡Amén! alzando sus manos; y humilláronse, y adoraron á Jehová inclinados á tierra."}, {"numero": 7, "texto": "Y Jesuá, y Bani, y Serebías, Jamín, Accub, Sabethai, Odías, Maasías, Celita, Azarías, Jozabed, Hanán, Pelaía, Levitas, hacían entender al pueblo la ley: y el pueblo estaba en su lugar."}, {"numero": 8, "texto": "Y leían en el libro de la ley de Dios claramente, y ponían el sentido, de modo que entendiesen la lectura."}, {"numero": 9, "texto": "Y Nehemías el Tirsatha, y el sacerdote Esdras, escriba, y los Levitas que hacían entender al pueblo, dijeron á todo el pueblo: Día santo es á Jehová nuestro Dios; no os entristezcáis, ni lloréis: porque todo el pueblo lloraba oyendo las palabras de la ley."}, {"numero": 10, "texto": "Díjoles luego: Id, comed grosuras, y bebed vino dulce, y enviad porciones á los que no tienen prevenido; porque día santo es á nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra fortaleza."}, {"numero": 11, "texto": "Los Levitas pues, hacían callar á todo el pueblo, diciendo: Callad, que es día santo, y no os entristezcáis."}, {"numero": 12, "texto": "Y todo el pueblo se fué á comer y á beber, y á enviar porciones, y á gozar de grande alegría, porque habían entendido las palabras que les habían enseñado."}, {"numero": 13, "texto": "Y el día siguiente se juntaron los príncipes de las familias de todo el pueblo, sacerdotes, y Levitas, á Esdras escriba, para entender las palabras de la ley."}, {"numero": 14, "texto": "Y hallaron escrito en la ley que Jehová había mandado por mano de Moisés, que habitasen los hijos de Israel en cabañas en la solemnidad del mes séptimo;"}, {"numero": 15, "texto": "Y que hiciesen saber, y pasar pregón por todas sus ciudades y por Jerusalem, diciendo: Salid al monte, y traed ramos de oliva, y ramos de pino, y ramos de arrayán, y ramos de palmas, y ramos de todo árbol espeso, para hacer cabañas como está escrito."}, {"numero": 16, "texto": "Salió pues el pueblo, y trajeron, é hiciéronse cabañas, cada uno sobre su terrado, y en sus patios, y en los patios de la casa de Dios, y en la plaza de la puerta de las Aguas, y en la plaza de la puerta de Ephraim."}, {"numero": 17, "texto": "Y toda la congregación que volvió de la cautividad hicieron cabañas, y en cabañas habitaron; porque desde los días de Josué hijo de Nun hasta aquel día, no habían hecho así los hijos de Israel. Y hubo alegría muy grande."}, {"numero": 18, "texto": "Y leyó Esdras en el libro de la ley de Dios cada día, desde el primer día hasta el postrero; é hicieron la solemnidad por siete días, y al octavo día congregación, según el rito."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 9, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés no deserto de Sinai, no segundo ano de sua saída da terra do Egito, no mês primeiro, dizendo:"}, {"numero": 2, "texto": "Os filhos de Israel farão a páscoa a seu tempo."}, {"numero": 3, "texto": "No décimo quarto dia deste mês, entre as duas tardes, a fareis a seu tempo: conforme todos os seus ritos, e conforme todas suas leis a fareis."}, {"numero": 4, "texto": "E falou Moisés aos filhos de Israel, para que fizessem a páscoa."}, {"numero": 5, "texto": "E fizeram a páscoa no mês primeiro, aos catorze dias do mês, entre as duas tardes, no deserto de Sinai: conforme todas as coisas que mandou o SENHOR a Moisés, assim fizeram os filhos de Israel."}, {"numero": 6, "texto": "E houve alguns que estavam impuros por causa de morto, e não puderam fazer a páscoa aquele dia; e chegaram diante de Moisés e diante de Arão aquele dia;"}, {"numero": 7, "texto": "E disseram-lhe aqueles homens: Nós somos impuros por causa de morto; por que seremos impedidos de oferecer oferta ao SENHOR a seu tempo entre os filhos de Israel?"}, {"numero": 8, "texto": "E Moisés lhes respondeu: Esperai, e ouvirei que mandará o SENHOR acerca de vós."}, {"numero": 9, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 10, "texto": "Fala aos filhos de Israel, dizendo: Qualquer um de vós ou de vossas gerações, que for impuro por causa de morto ou estiver de viajem longe, fará páscoa ao SENHOR:"}, {"numero": 11, "texto": "No mês segundo, aos catorze dias do mês, entre as duas tardes, a farão: com pães ázimos e ervas amargas a comerão;"}, {"numero": 12, "texto": "Não deixarão dele para a manhã, nem quebrarão osso nele: conforme todos os ritos da páscoa a farão."}, {"numero": 13, "texto": "Mas o que estiver limpo, e não estiver de viajem, se deixar de fazer a páscoa, a tal pessoa será eliminada de seus povos: porquanto não ofereceu a seu tempo a oferta do SENHOR, o tal homem levará seu pecado."}, {"numero": 14, "texto": "E se morar convosco peregrino, e fizer a páscoa ao SENHOR, conforme o rito da páscoa e conforme suas leis assim a fará: um mesmo rito tereis, tanto o peregrino como o natural da terra."}, {"numero": 15, "texto": "E no dia que o tabernáculo foi levantado, a nuvem cobriu o tabernáculo sobre a tenda do testemunho; e à tarde havia sobre o tabernáculo como uma aparência de fogo, até a manhã."}, {"numero": 16, "texto": "Assim era continuamente: a nuvem o cobria, e de noite a aparência de fogo."}, {"numero": 17, "texto": "E segundo que se erguia a nuvem do tabernáculo, os filhos de Israel se partiam: e no lugar onde a nuvem parava, ali alojavam os filhos de Israel."}, {"numero": 18, "texto": "À ordem do SENHOR os filhos de Israel se partiam: e à ordem do SENHOR assentavam o acampamento: todos os dias que a nuvem estava sobre o tabernáculo, eles estavam parados."}, {"numero": 19, "texto": "E quando a nuvem se detinha sobre o tabernáculo muitos dias, então os filhos de Israel guardavam a ordenança do SENHOR e não partiam."}, {"numero": 20, "texto": "E quando sucedia que a nuvem estava sobre o tabernáculo poucos dias, ao dito do SENHOR alojavam, e ao dito do SENHOR partiam."}, {"numero": 21, "texto": "E quando era que a nuvem se detinha desde a tarde até a manhã, quando à manhã a nuvem se levantava, eles partiam: ou se havia estado no dia, e à noite a nuvem se levantava, então partiam."}, {"numero": 22, "texto": "Ou se dois dias, ou um mês, ou ano, enquanto a nuvem se detinha sobre o tabernáculo ficando sobre ele, os filhos de Israel se estavam acampados e não moviam: mas quando ela se erguia, eles moviam."}, {"numero": 23, "texto": "Ao dito do SENHOR assentavam, e ao dito do SENHOR partiam, guardando a ordenança do SENHOR, como o havia o SENHOR dito por meio de Moisés."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 9, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses in the wilderness of Sinai, in the first month of the second year after they were come out of the land of Egypt, saying,"}, {"numero": 2, "texto": "Let the children of Israel also keep the passover at his appointed season."}, {"numero": 3, "texto": "In the fourteenth day of this month, at even, ye shall keep it in his appointed season: according to all the rites of it, and according to all the ceremonies thereof, shall ye keep it."}, {"numero": 4, "texto": "And Moses spake unto the children of Israel, that they should keep the passover."}, {"numero": 5, "texto": "And they kept the passover on the fourteenth day of the first month at even in the wilderness of Sinai: according to all that the Lord commanded Moses, so did the children of Israel."}, {"numero": 6, "texto": "And there were certain men, who were defiled by the dead body of a man, that they could not keep the passover on that day: and they came before Moses and before Aaron on that day:"}, {"numero": 7, "texto": "And those men said unto him, We are defiled by the dead body of a man: wherefore are we kept back, that we may not offer an offering of the Lord in his appointed season among the children of Israel?"}, {"numero": 8, "texto": "And Moses said unto them, Stand still, and I will hear what the Lord will command concerning you."}, {"numero": 9, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 10, "texto": "Speak unto the children of Israel, saying, If any man of you or of your posterity shall be unclean by reason of a dead body, or be in a journey afar off, yet he shall keep the passover unto the Lord."}, {"numero": 11, "texto": "The fourteenth day of the second month at even they shall keep it, and eat it with unleavened bread and bitter herbs."}, {"numero": 12, "texto": "They shall leave none of it unto the morning, nor break any bone of it: according to all the ordinances of the passover they shall keep it."}, {"numero": 13, "texto": "But the man that is clean, and is not in a journey, and forbeareth to keep the passover, even the same soul shall be cut off from among his people: because he brought not the offering of the Lord in his appointed season, that man shall bear his sin."}, {"numero": 14, "texto": "And if a stranger shall sojourn among you, and will keep the passover unto the Lord; according to the ordinance of the passover, and according to the manner thereof, so shall he do: ye shall have one ordinance, both for the stranger, and for him that was born in the land."}, {"numero": 15, "texto": "And on the day that the tabernacle was reared up the cloud covered the tabernacle, namely, the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning."}, {"numero": 16, "texto": "So it was alway: the cloud covered it by day, and the appearance of fire by night."}, {"numero": 17, "texto": "And when the cloud was taken up from the tabernacle, then after that the children of Israel journeyed: and in the place where the cloud abode, there the children of Israel pitched their tents."}, {"numero": 18, "texto": "At the commandment of the Lord the children of Israel journeyed, and at the commandment of the Lord they pitched: as long as the cloud abode upon the tabernacle they rested in their tents."}, {"numero": 19, "texto": "And when the cloud tarried long upon the tabernacle many days, then the children of Israel kept the charge of the Lord, and journeyed not."}, {"numero": 20, "texto": "And so it was, when the cloud was a few days upon the tabernacle; according to the commandment of the Lord they abode in their tents, and according to the commandment of the Lord they journeyed."}, {"numero": 21, "texto": "And so it was, when the cloud abode from even unto the morning, and that the cloud was taken up in the morning, then they journeyed: whether it was by day or by night that the cloud was taken up, they journeyed."}, {"numero": 22, "texto": "Or whether it were two days, or a month, or a year, that the cloud tarried upon the tabernacle, remaining thereon, the children of Israel abode in their tents, and journeyed not: but when it was taken up, they journeyed."}, {"numero": 23, "texto": "At the commandment of the Lord they rested in the tents, and at the commandment of the Lord they journeyed: they kept the charge of the Lord, at the commandment of the Lord by the hand of Moses."}]'::jsonb, 'King James Version'),
  ('Nm', 9, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, dans le désert de Sinaï, le premier mois de la seconde année après leur sortie du pays d''''Egypte. Il dit:"}, {"numero": 2, "texto": "Que les enfants d''''Israël célèbrent la Pâque au temps fixé."}, {"numero": 3, "texto": "Vous la célébrerez au temps fixé, le quatorzième jour de ce mois, entre les deux soirs; vous la célébrerez selon toutes les lois et toutes les ordonnances qui s''''y rapportent."}, {"numero": 4, "texto": "Moïse parla aux enfants d''''Israël, afin qu''''ils célébrassent la Pâque."}, {"numero": 5, "texto": "Et ils célébrèrent la Pâque le quatorzième jour du premier mois, entre les deux soirs, dans le désert de Sinaï; les enfants d''''Israël se conformèrent à tous les ordres que l''''Eternel avait donnés à Moïse."}, {"numero": 6, "texto": "Il y eut des hommes qui, se trouvant impurs à cause d''''un mort, ne pouvaient pas célébrer la Pâque ce jour-là. Ils se présentèrent le même jour devant Moïse et Aaron;"}, {"numero": 7, "texto": "et ces hommes dirent à Moïse: Nous sommes impurs à cause d''''un mort; pourquoi serions-nous privés de présenter au temps fixé l''''offrande de l''''Eternel au milieu des enfants d''''Israël?"}, {"numero": 8, "texto": "Moïse leur dit: Attendez que je sache ce que l''''Eternel vous ordonne."}, {"numero": 9, "texto": "Et l''''Eternel parla à Moïse, et dit:"}, {"numero": 10, "texto": "Parle aux enfants d''''Israël, et dis-leur: Si quelqu''''un d''''entre vous ou de vos descendants est impur à cause d''''un mort, ou est en voyage dans le lointain, il célébrera la Pâque en l''''honneur de l''''Eternel."}, {"numero": 11, "texto": "C''''est au second mois qu''''ils la célébreront, le quatorzième jour, entre les deux soirs; ils la mangeront avec des pains sans levain et des herbes amères."}, {"numero": 12, "texto": "Ils n''''en laisseront rien jusqu''''au matin, et ils n''''en briseront aucun os. Ils la célébreront selon toutes les ordonnances de la Pâque."}, {"numero": 13, "texto": "Si celui qui est pur et qui n''''est pas en voyage s''''abstient de célébrer la Pâque, celui-là sera retranché de son peuple; parce qu''''il n''''a pas présenté l''''offrande de l''''Eternel au temps fixé, cet homme-là portera la peine de son péché."}, {"numero": 14, "texto": "Si un étranger en séjour chez vous célèbre la Pâque de l''''Eternel, il se conformera aux lois et aux ordonnances de la Pâque. Il y aura une même loi parmi vous, pour l''''étranger comme pour l''''indigène."}, {"numero": 15, "texto": "Le jour où le tabernacle fut dressé, la nuée couvrit le tabernacle, la tente d''''assignation; et, depuis le soir jusqu''''au matin, elle eut sur le tabernacle l''''apparence d''''un feu."}, {"numero": 16, "texto": "Il en fut continuellement ainsi: la nuée couvrait le tabernacle, et elle avait de nuit l''''apparence d''''un feu."}, {"numero": 17, "texto": "Quand la nuée s''''élevait de dessus la tente, les enfants d''''Israël partaient; et les enfants d''''Israël campaient dans le lieu où s''''arrêtait la nuée."}, {"numero": 18, "texto": "Les enfants d''''Israël partaient sur l''''ordre de l''''Eternel, et ils campaient sur l''''ordre de l''''Eternel; ils campaient aussi longtemps que la nuée restait sur le tabernacle."}, {"numero": 19, "texto": "Quand la nuée restait longtemps sur le tabernacle, les enfants d''''Israël obéissaient au commandement de l''''Eternel, et ne partaient point."}, {"numero": 20, "texto": "Quand la nuée restait peu de jours sur le tabernacle, ils campaient sur l''''ordre de l''''Eternel, et ils partaient sur l''''ordre de l''''Eternel."}, {"numero": 21, "texto": "Si la nuée s''''arrêtait du soir au matin, et s''''élevait le matin, ils partaient. Si la nuée s''''élevait après un jour et une nuit, ils partaient."}, {"numero": 22, "texto": "Si la nuée s''''arrêtait sur le tabernacle deux jours, ou un mois, ou une année, les enfants d''''Israël restaient campés, et ne partaient point; et quand elle s''''élevait, ils partaient."}, {"numero": 23, "texto": "Ils campaient sur l''''ordre de l''''Eternel, et ils partaient sur l''''ordre de l''''Eternel; ils obéissaient au commandement de l''''Eternel, sur l''''ordre de l''''Eternel par Moïse."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 9, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés en el desierto de Sinaí, en el segundo año de su salida de la tierra de Egipto, en el mes primero, diciendo:"}, {"numero": 2, "texto": "Los hijos de Israel harán la pascua á su tiempo."}, {"numero": 3, "texto": "El décimocuarto día de este mes, entre las dos tardes, la haréis á su tiempo: conforme á todos sus ritos, y conforme á todas sus leyes la haréis."}, {"numero": 4, "texto": "Y habló Moisés á los hijos de Israel, para que hiciesen la pascua."}, {"numero": 5, "texto": "E hicieron la pascua en el mes primero, á los catorce días del mes, entre las dos tardes, en el desierto de Sinaí: conforme á todas las cosas que mandó Jehová á Moisés, así hicieron los hijos de Israel."}, {"numero": 6, "texto": "Y hubo algunos que estaban inmundos á causa de muerto, y no pudieron hacer la pascua aquel día; y llegaron delante de Moisés y delante de Aarón aquel día;"}, {"numero": 7, "texto": "Y dijéronle aquellos hombres: Nosotros somos inmundos por causa de muerto; ¿por qué seremos impedidos de ofrecer ofrenda á Jehová á su tiempo entre los hijos de Israel?"}, {"numero": 8, "texto": "Y Moisés les respondió: Esperad, y oiré qué mandará Jehová acerca de vosotros."}, {"numero": 9, "texto": "Y Jehová habló á Moisés, diciendo:"}, {"numero": 10, "texto": "Habla á los hijos de Israel, diciendo: Cualquiera de vosotros ó de vuestras generaciones, que fuere inmundo por causa de muerto ó estuviere de viaje lejos, hará pascua á Jehová:"}, {"numero": 11, "texto": "En el mes segundo, á los catorce días del mes, entre las dos tardes, la harán: con cenceñas y hierbas amargas la comerán;"}, {"numero": 12, "texto": "No dejarán de él para la mañana, ni quebrarán hueso en él: conforme á todos los ritos de la pascua la harán."}, {"numero": 13, "texto": "Mas el que estuviere limpio, y no estuviere de viaje, si dejare de hacer la pascua, la tal persona será cortada de sus pueblos: por cuanto no ofreció á su tiempo la ofrenda de Jehová, el tal hombre llevará su pecado."}, {"numero": 14, "texto": "Y si morare con vosotros peregrino, é hiciere la pascua á Jehová, conforme al rito de la pascua y conforme á sus leyes así la hará: un mismo rito tendréis, así el peregrino como el natural de la tierra."}, {"numero": 15, "texto": "Y el día que el tabernáculo fué levantado, la nube cubrió el tabernáculo sobre la tienda del testimonio; y á la tarde había sobre el tabernáculo como una apariencia de fuego, hasta la mañana."}, {"numero": 16, "texto": "Así era continuamente: la nube lo cubría, y de noche la apariencia de fuego."}, {"numero": 17, "texto": "Y según que se alzaba la nube del tabernáculo, los hijos de Israel se partían: y en el lugar donde la nube paraba, allí alojaban los hijos de Israel."}, {"numero": 18, "texto": "Al mandato de Jehová los hijos de Israel se partían: y al mandato de Jehová asentaban el campo: todos los días que la nube estaba sobre el tabernáculo, ellos estaban quedos."}, {"numero": 19, "texto": "Y cuando la nube se detenía sobre el tabernáculo muchos días, entonces los hijos de Israel guardaban la ordenanza de Jehová y no partían."}, {"numero": 20, "texto": "Y cuando sucedía que la nube estaba sobre el tabernáculo pocos días, al dicho de Jehová alojaban, y al dicho de Jehová partían."}, {"numero": 21, "texto": "Y cuando era que la nube se detenía desde la tarde hasta la mañana, cuando á la mañana la nube se levantaba, ellos partían: ó si había estado el día, y á la noche la nube se levantaba, entonces partían."}, {"numero": 22, "texto": "O si dos días, ó un mes, ó un año, mientras la nube se detenía sobre el tabernáculo quedándose sobre él, los hijos de Israel se estaban acampados, y no movían: mas cuando ella se alzaba, ellos movían."}, {"numero": 23, "texto": "Al dicho de Jehová asentaban, y al dicho de Jehová partían, guardando la ordenanza de Jehová, como lo había Jehová dicho por medio de Moisés."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 11, 'pt', '[{"numero": 1, "texto": "E aconteceu que o povo se queixou aos ouvidos do SENHOR: e ouviu-o o SENHOR, e ardeu seu furor, e acendeu-se neles fogo do SENHOR e consumiu a extremidade do acampamento."}, {"numero": 2, "texto": "Então o povo clamou a Moisés, e Moisés orou ao SENHOR, e o fogo se apagou."}, {"numero": 3, "texto": "E chamou a aquele lugar Taberá; porque o fogo do SENHOR se acendeu neles."}, {"numero": 4, "texto": "E o povo misturado que havia no meio deles teve um intenso desejo; então os filhos de Israel voltaram-se, choraram, e disseram: Quem nos dera comer carne!"}, {"numero": 5, "texto": "Nós nos lembramos do peixe que comíamos no Egito de graça, dos pepinos, dos melões, dos alhos-porós, das cebolas, e dos alhos;"}, {"numero": 6, "texto": "mas agora a nossa alma se seca; nada há, a não ser maná, [diante dos] nossos olhos."}, {"numero": 7, "texto": "O maná era como semente de coentro, e sua cor como cor de bdélio."}, {"numero": 8, "texto": "O povo se espalhava, e recolhia, e moía em moinhos, ou malhava em pilões, e o cozia em panelas, ou fazia dele bolos; e o seu sabor era como sabor de azeite fresco."}, {"numero": 9, "texto": "E quando o orvalho descia sobre o acampamento de noite, o maná descia sobre ele."}, {"numero": 10, "texto": "E Moisés ouviu o povo chorar por suas famílias, cada um à porta de sua tenda; e o furor do SENHOR se acendeu grandemente; também pareceu mal a Moisés."}, {"numero": 11, "texto": "E Moisés disse ao SENHOR: Por que fizeste mal a teu servo? E por que não achei favor aos teus olhos, que puseste sobremim a carga de todo este povo?"}, {"numero": 12, "texto": "Por acaso fui eu que concebi todo este povo? Fui o que o dei à luz, para que me digas: Leva-o em teu colo, como uma ama leva um bebê de peito, à terra da qual juraste a seus pais?"}, {"numero": 13, "texto": "De onde eu teria carne para dar a todo este povo? Porque choram a mim, dizendo: Dá-nos carne para comer."}, {"numero": 14, "texto": "Não posso suportar sozinho todo este povo, porque é pesado demais para mim."}, {"numero": 15, "texto": "E se assim fazes tu comigo, eu te rogo que me mates, se achei favor aos teus olhos; e que não me deixes ver a minha calamidade."}, {"numero": 16, "texto": "Então o SENHOR disse a Moisés: Ajunta-me setenta homens dos anciãos de Israel, de quem sabes que são anciãos do povo, e seus oficiais; e traze-os à porta do tabernáculo do testemunho, e esperem ali contigo."}, {"numero": 17, "texto": "E eu descerei e falarei ali contigo; e tomarei do espírito que está sobre ti, e [o] porei neles; e contigo levarão a carga do povo, para que tu não [a] leves sozinho."}, {"numero": 18, "texto": "Porém dirás ao povo: Santificai-vos para amanhã, e comereis carne; porque chorastes em ouvidos do SENHOR, dizendo: Quem nos dera comer carne! Certamente estávamos bem no Egito! O SENHOR, pois, vos dará carne, e comereis."}, {"numero": 19, "texto": "Não comereis um dia, nem dois dias, nem cinco dias, nem dez dias, nem vinte dias;"}, {"numero": 20, "texto": "mas sim, um mês inteiro, até que vos saia pelas narinas, e sintais repulsa dela, porque rejeitastes o SENHOR que está no meio de vós, e chorastes diante dele, dizendo: Para que saímos do Egito?"}, {"numero": 21, "texto": "Então disse Moisés: Seiscentos mil a pé é este povo no meio do qual estou; e tu dizes: Eu lhes darei carne, e comerão um mês inteiro."}, {"numero": 22, "texto": "Por acaso serão degoladas para eles ovelhas e bois que lhes bastem? Ou se ajuntarão para eles todos os peixes do mar para que lhes sejam suficientes?"}, {"numero": 23, "texto": "Porém o SENHOR respondeu a Moisés: Por acaso o poder do SENHOR é curto? Agora verás se a minha palavra te acontecerá ou não."}, {"numero": 24, "texto": "E Moisés saiu, e disse ao povo as palavras do SENHOR; e ajuntou setenta homens dos anciãos do povo, e os pôs ao redor da tenda."}, {"numero": 25, "texto": "Então o SENHOR desceu na nuvem, e lhe falou; e tomou do espírito que estava sobre ele, e o pôs sobre aqueles setenta anciãos; e aconteceu que, quando o espírito repousou sobre eles, profetizaram, mas depois nunca mais."}, {"numero": 26, "texto": "Porém ficaram no acampamento dois homens, um chamado Eldade e o outro Medade, sobre os quais o espírito também repousou (porque estavam entre os inscritos, mas não haviam saído à tenda); e profetizaram no acampamento."}, {"numero": 27, "texto": "Então um jovem correu, e avisou a Moisés, e disse: Eldade e Medade estão profetizando no acampamento."}, {"numero": 28, "texto": "Então Josué, filho de Num, assistente de Moisés desde a sua juventude, respondeu, e disse: Meu senhor Moisés, impede-os."}, {"numero": 29, "texto": "E Moisés lhe respondeu: Tens tu ciúmes por mim? Bom seria se todos do povo do SENHOR fossem profetas, que o SENHOR pusesse seu Espírito sobre eles."}, {"numero": 30, "texto": "E Moisés recolheu-se ao acampamento, ele e os anciãos de Israel."}, {"numero": 31, "texto": "E saiu um vento do SENHOR, que trouxe codornizes do mar, e deixou-as sobre o acampamento, de um dia de caminho de um lado e do outro, ao redor do acampamento, e quase dois côvados sobre a face da terra."}, {"numero": 32, "texto": "Então o povo se levantou e recolheu para si codornizes durante todo aquele dia, e toda a noite, e todo o dia seguinte.O que recolheu menos recolheu dez ômeres; e as estenderam para si ao redor do acampamento."}, {"numero": 33, "texto": "A carne ainda estava entre os dentes deles, antes que fosse mastigada, quando o furor do SENHOR se acendeu no povo, e o SENHOR feriu o povo com uma praga muito grande."}, {"numero": 34, "texto": "Por isso aquele lugar recebeu o nome de Quibrote-Hataavá, porque ali sepultaram o povo que teve o desejo."}, {"numero": 35, "texto": "De Quibrote-Hataavá o povo partiu para Hazerote, e ficaram em Hazerote."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 11, 'en', '[{"numero": 1, "texto": "And when the people complained, it displeased the Lord: and the Lord heard it; and his anger was kindled; and the fire of the Lord burnt among them, and consumed them that were in the uttermost parts of the camp."}, {"numero": 2, "texto": "And the people cried unto Moses; and when Moses prayed unto the Lord, the fire was quenched."}, {"numero": 3, "texto": "And he called the name of the place Taberah: because the fire of the Lord burnt among them."}, {"numero": 4, "texto": "And the mixt multitude that was among them fell a lusting: and the children of Israel also wept again, and said, Who shall give us flesh to eat?"}, {"numero": 5, "texto": "We remember the fish, which we did eat in Egypt freely; the cucumbers, and the melons, and the leeks, and the onions, and the garlick:"}, {"numero": 6, "texto": "But now our soul is dried away: there is nothing at all, beside this manna, before our eyes."}, {"numero": 7, "texto": "And the manna was as coriander seed, and the colour thereof as the colour of bdellium."}, {"numero": 8, "texto": "And the people went about, and gathered it, and ground it in mills, or beat it in a mortar, and baked it in pans, and made cakes of it: and the taste of it was as the taste of fresh oil."}, {"numero": 9, "texto": "And when the dew fell upon the camp in the night, the manna fell upon it."}, {"numero": 10, "texto": "Then Moses heard the people weep throughout their families, every man in the door of his tent: and the anger of the Lord was kindled greatly; Moses also was displeased."}, {"numero": 11, "texto": "And Moses said unto the Lord, Wherefore hast thou afflicted thy servant? and wherefore have I not found favour in thy sight, that thou layest the burden of all this people upon me?"}, {"numero": 12, "texto": "Have I conceived all this people? have I begotten them, that thou shouldest say unto me, Carry them in thy bosom, as a nursing father beareth the sucking child, unto the land which thou swarest unto their fathers?"}, {"numero": 13, "texto": "Whence should I have flesh to give unto all this people? for they weep unto me, saying, Give us flesh, that we may eat."}, {"numero": 14, "texto": "I am not able to bear all this people alone, because it is too heavy for me."}, {"numero": 15, "texto": "And if thou deal thus with me, kill me, I pray thee, out of hand, if I have found favour in thy sight; and let me not see my wretchedness."}, {"numero": 16, "texto": "And the Lord said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee."}, {"numero": 17, "texto": "And I will come down and talk with thee there: and I will take of the spirit which is upon thee, and will put it upon them; and they shall bear the burden of the people with thee, that thou bear it not thyself alone."}, {"numero": 18, "texto": "And say thou unto the people, Sanctify yourselves against to morrow, and ye shall eat flesh: for ye have wept in the ears of the Lord, saying, Who shall give us flesh to eat? for it was well with us in Egypt: therefore the Lord will give you flesh, and ye shall eat."}, {"numero": 19, "texto": "Ye shall not eat one day, nor two days, nor five days, neither ten days, nor twenty days;"}, {"numero": 20, "texto": "But even a whole month, until it come out at your nostrils, and it be loathsome unto you: because that ye have despised the Lord which is among you, and have wept before him, saying, Why came we forth out of Egypt?"}, {"numero": 21, "texto": "And Moses said, The people, among whom I am, are six hundred thousand footmen; and thou hast said, I will give them flesh, that they may eat a whole month."}, {"numero": 22, "texto": "Shall the flocks and the herds be slain for them, to suffice them? or shall all the fish of the sea be gathered together for them, to suffice them?"}, {"numero": 23, "texto": "And the Lord said unto Moses, Is the Lord''S hand waxed short? thou shalt see now whether my word shall come to pass unto thee or not."}, {"numero": 24, "texto": "And Moses went out, and told the people the words of the Lord, and gathered the seventy men of the elders of the people, and set them round about the tabernacle."}, {"numero": 25, "texto": "And the Lord came down in a cloud, and spake unto him, and took of the spirit that was upon him, and gave it unto the seventy elders: and it came to pass, that, when the spirit rested upon them, they prophesied, and did not cease."}, {"numero": 26, "texto": "But there remained two of the men in the camp, the name of the one was Eldad, and the name of the other Medad: and the spirit rested upon them; and they were of them that were written, but went not out unto the tabernacle: and they prophesied in the camp."}, {"numero": 27, "texto": "And there ran a young man, and told Moses, and said, Eldad and Medad do prophesy in the camp."}, {"numero": 28, "texto": "And Joshua the son of Nun, the servant of Moses, one of his young men, answered and said, My lord Moses, forbid them."}, {"numero": 29, "texto": "And Moses said unto him, Enviest thou for my sake? would God that all the Lord''S people were prophets, and that the Lord would put his spirit upon them!"}, {"numero": 30, "texto": "And Moses gat him into the camp, he and the elders of Israel."}, {"numero": 31, "texto": "And there went forth a wind from the Lord, and brought quails from the sea, and let them fall by the camp, as it were a day''s journey on this side, and as it were a day''s journey on the other side, round about the camp, and as it were two cubits high upon the face of the earth."}, {"numero": 32, "texto": "And the people stood up all that day, and all that night, and all the next day, and they gathered the quails: he that gathered least gathered ten homers: and they spread them all abroad for themselves round about the camp."}, {"numero": 33, "texto": "And while the flesh was yet between their teeth, ere it was chewed, the wrath of the Lord was kindled against the people, and the Lord smote the people with a very great plague."}, {"numero": 34, "texto": "And he called the name of that place Kibrothhattaavah: because there they buried the people that lusted."}, {"numero": 35, "texto": "And the people journeyed from Kibrothhattaavah unto Hazeroth; and abode at Hazeroth."}]'::jsonb, 'King James Version'),
  ('Nm', 11, 'fr', '[{"numero": 1, "texto": "Le peuple murmura et cela déplut aux oreilles de l''''Eternel. Lorsque l''''Eternel l''''entendit, sa colère s''''enflamma; le feu de l''''Eternel s''''alluma parmi eux, et dévora l''''extrémité du camp."}, {"numero": 2, "texto": "Le peuple cria à Moïse. Moïse pria l''''Eternel, et le feu s''''arrêta."}, {"numero": 3, "texto": "On donna à ce lieu le nom de Tabeéra, parce que le feu de l''''Eternel s''''était allumé parmi eux."}, {"numero": 4, "texto": "Le ramassis de gens qui se trouvaient au milieu d''''Israël fut saisi de convoitise; et même les enfants d''''Israël recommencèrent à pleurer et dirent: Qui nous donnera de la viande à manger?"}, {"numero": 5, "texto": "Nous nous souvenons des poissons que nous mangions en Egypte, et qui ne nous coûtaient rien, des concombres, des melons, des poireaux, des oignons et des aulx."}, {"numero": 6, "texto": "Maintenant, notre âme est desséchée: plus rien! Nos yeux ne voient que de la manne."}, {"numero": 7, "texto": "La manne ressemblait à de la graine de coriandre, et avait l''''apparence du bdellium."}, {"numero": 8, "texto": "Le peuple se dispersait pour la ramasser; il la broyait avec des meules, ou la pilait dans un mortier; il la cuisait au pot, et en faisait des gâteaux. Elle avait le goût d''''un gâteau à l''''huile."}, {"numero": 9, "texto": "Quand la rosée descendait la nuit sur le camp, la manne y descendait aussi."}, {"numero": 10, "texto": "Moïse entendit le peuple qui pleurait, chacun dans sa famille et à l''''entrée de sa tente. La colère de l''''Eternel s''''enflamma fortement. Moïse fut attristé,"}, {"numero": 11, "texto": "et il dit à l''''Eternel: Pourquoi affliges-tu ton serviteur, et pourquoi n''''ai-je pas trouvé grâce à tes yeux, que tu aies mis sur moi la charge de tout ce peuple?"}, {"numero": 12, "texto": "Est-ce moi qui ai conçu ce peuple? est-ce moi qui l''''ai enfanté, pour que tu me dises: Porte-le sur ton sein, comme le nourricier porte un enfant, jusqu''''au pays que tu as juré à ses pères de lui donner?"}, {"numero": 13, "texto": "Où prendrai-je de la viande pour donner à tout ce peuple? Car ils pleurent auprès de moi, en disant: Donne-nous de la viande à manger!"}, {"numero": 14, "texto": "Je ne puis pas, à moi seul, porter tout ce peuple, car il est trop pesant pour moi."}, {"numero": 15, "texto": "Plutôt que de me traiter ainsi, tue-moi, je te prie, si j''''ai trouvé grâce à tes yeux, et que je ne voie pas mon malheur."}, {"numero": 16, "texto": "L''''Eternel dit à Moïse: Assemble auprès de moi soixante-dix hommes des anciens d''''Israël, de ceux que tu connais comme anciens du peuple et ayant autorité sur lui; amène-les à la tente d''''assignation, et qu''''ils s''''y présentent avec toi."}, {"numero": 17, "texto": "Je descendrai, et là je te parlerai; je prendrai de l''''esprit qui est sur toi, et je le mettrai sur eux, afin qu''''ils portent avec toi la charge du peuple, et que tu ne la portes pas à toi seul."}, {"numero": 18, "texto": "Tu diras au peuple: Sanctifiez-vous pour demain, et vous mangerez de la viande, puisque vous avez pleuré aux oreilles de l''''Eternel, en disant: Qui nous fera manger de la viande? car nous étions bien en Egypte. L''''Eternel vous donnera de la viande, et vous en mangerez."}, {"numero": 19, "texto": "Vous en mangerez non pas un jour, ni deux jours, ni cinq jours, ni dix jours, ni vingt jours,"}, {"numero": 20, "texto": "mais un mois entier, jusqu''''à ce qu''''elle vous sorte par les narines et que vous en ayez du dégoût, parce que vous avez rejeté l''''Eternel qui est au milieu de vous, et parce que vous avez pleuré devant lui, en disant: Pourquoi donc sommes-nous sortis d''''Egypte?"}, {"numero": 21, "texto": "Moïse dit: Six cent mille hommes de pied forment le peuple au milieu duquel je suis, et tu dis: Je leur donnerai de la viande, et ils en mangeront un mois entier!"}, {"numero": 22, "texto": "Egorgera-t-on pour eux des brebis et des boeufs, en sorte qu''''ils en aient assez? ou rassemblera-t-on pour eux tous les poissons de la mer, en sorte qu''''ils en aient assez?"}, {"numero": 23, "texto": "L''''Eternel répondit à Moïse: La main de l''''Eternel serait-elle trop courte? Tu verras maintenant si ce que je t''''ai dit arrivera ou non."}, {"numero": 24, "texto": "Moïse sortit, et rapporta au peuple les paroles de l''''Eternel. Il assembla soixante-dix hommes des anciens du peuple, et les plaça autour de la tente."}, {"numero": 25, "texto": "L''''Eternel descendit dans la nuée, et parla à Moïse; il prit de l''''esprit qui était sur lui, et le mit sur les soixante-dix anciens. Et dès que l''''esprit reposa sur eux, ils prophétisèrent; mais ils ne continuèrent pas."}, {"numero": 26, "texto": "Il y eut deux hommes, l''''un appelé Eldad, et l''''autre Médad, qui étaient restés dans le camp, et sur lesquels l''''esprit reposa; car ils étaient parmi les inscrits, quoiqu''''ils ne fussent point allés à la tente; et ils prophétisèrent dans le camp."}, {"numero": 27, "texto": "Un jeune garçon courut l''''annoncer à Moïse, et dit: Eldad et Médad prophétisent dans le camp."}, {"numero": 28, "texto": "Et Josué, fils de Nun, serviteur de Moïse depuis sa jeunesse, prit la parole et dit: Moïse, mon seigneur, empêche-les!"}, {"numero": 29, "texto": "Moïse lui répondit: Es-tu jaloux pour moi? Puisse tout le peuple de l''''Eternel être composé de prophètes; et veuille l''''Eternel mettre son esprit sur eux!"}, {"numero": 30, "texto": "Et Moïse se retira au camp, lui et les anciens d''''Israël."}, {"numero": 31, "texto": "L''''Eternel fit souffler de la mer un vent, qui amena des cailles, et les répandit sur le camp, environ une journée de chemin d''''un côté et environ une journée de chemin de l''''autre côté, autour du camp. Il y en avait près de deux coudées au-dessus de la surface de la terre."}, {"numero": 32, "texto": "Pendant tout ce jour et toute la nuit, et pendant toute la journée du lendemain, le peuple se leva et ramassa les cailles; celui qui en avait ramassé le moins en avait dix homers. Ils les étendirent pour eux autour du camp."}, {"numero": 33, "texto": "Comme la chair était encore entre leurs dents sans être mâchée, la colère de l''''Eternel s''''enflamma contre le peuple, et l''''Eternel frappa le peuple d''''une très grande plaie."}, {"numero": 34, "texto": "On donna à ce lieu le nom de Kibroth-Hattaava, parce qu''''on y enterra le peuple que la convoitise avait saisi."}, {"numero": 35, "texto": "De Kibroth-Hattaava le peuple partit pour Hatséroth, et il s''''arrêta à Hatséroth."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 11, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que el pueblo se quejó á oídos de Jehová: y oyólo Jehová, y enardecióse su furor, y encendióse en ellos fuego de Jehová y consumió el un cabo del campo."}, {"numero": 2, "texto": "Entonces el pueblo dió voces á Moisés, y Moisés oró á Jehová, y soterróse el fuego."}, {"numero": 3, "texto": "Y llamó á aquel lugar Taberah; porque el fuego de Jehová se encendió en ellos."}, {"numero": 4, "texto": "Y el vulgo que había en medio tuvo un vivo deseo, y volvieron, y aun lloraron los hijos de Israel, y dijeron: ¡Quién nos diera á comer carne!"}, {"numero": 5, "texto": "Nos acordamos del pescado que comíamos en Egipto de balde, de los cohombros, y de los melones, y de los puerros, y de las cebollas, y de los ajos:"}, {"numero": 6, "texto": "Y ahora nuestra alma se seca; que nada sino maná ven nuestros ojos."}, {"numero": 7, "texto": "Y era el maná como semilla de culantro, y su color como color de bdelio."}, {"numero": 8, "texto": "Derramábase el pueblo, y recogían, y molían en molinos, ó majaban en morteros, y lo cocían en caldera, ó hacían de él tortas: y su sabor era como sabor de aceite nuevo."}, {"numero": 9, "texto": "Y cuando descendía el rocío sobre el real de noche, el maná descendía de sobre él."}, {"numero": 10, "texto": "Y oyó Moisés al pueblo, que lloraba por sus familias, cada uno á la puerta de su tienda: y el furor de Jehová se encendió en gran manera; también pareció mal á Moisés."}, {"numero": 11, "texto": "Y dijo Moisés á Jehová: ¿Por qué has hecho mal á tu siervo? ¿y por qué no he hallado gracia en tus ojos, que has puesto la carga de todo este pueblo sobre mí?"}, {"numero": 12, "texto": "¿Concebí yo á todo este pueblo? ¿engendrélo yo, para que me digas: Llévalo en tu seno, como lleva la que cría al que mama, á la tierra de la cual juraste á sus padres?"}, {"numero": 13, "texto": "¿De dónde tengo yo carne para dar á todo este pueblo? porque lloran á mí, diciendo: Danos carne que comamos."}, {"numero": 14, "texto": "No puedo yo solo soportar á todo este pueblo, que me es pesado en demasía."}, {"numero": 15, "texto": "Y si así lo haces tú conmigo, yo te ruego que me des muerte, si he hallado gracia en tus ojos; y que yo no vea mi mal."}, {"numero": 16, "texto": "Entonces Jehová dijo á Moisés: Júntame setenta varones de los ancianos de Israel, que tú sabes que son ancianos del pueblo y sus principales; y tráelos á la puerta del tabernáculo del testimonio, y esperen allí contigo."}, {"numero": 17, "texto": "Y yo descenderé y hablaré allí contigo; y tomaré del espíritu que está en ti, y pondré en ellos; y llevarán contigo la carga del pueblo, y no la llevarás tú solo."}, {"numero": 18, "texto": "Empero dirás al pueblo: Santificaos para mañana, y comeréis carne: pues que habéis llorado en oídos de Jehová, diciendo: ¡Quién nos diera á comer carne! ¡cierto mejor nos iba en Egipto! Jehová, pues, os dará carne, y comeréis."}, {"numero": 19, "texto": "No comeréis un día, ni dos días, ni cinco días, ni diez días, ni veinte días;"}, {"numero": 20, "texto": "Sino hasta un mes de tiempo, hasta que os salga por las narices, y os sea en aborrecimiento: por cuanto menospreciasteis á Jehová que está en medio de vosotros, y llorasteis delante de él, diciendo: ¿Para qué salimos acá de Egipto?"}, {"numero": 21, "texto": "Entonces dijo Moisés: Seiscientos mil de á pie es el pueblo en medio del cual yo estoy; y tú dices: Les daré carne, y comerán el tiempo de un mes."}, {"numero": 22, "texto": "¿Se han de degollar para ellos ovejas y bueyes que les basten? ¿ó se juntarán para ellos todos los peces de la mar para que tengan abasto?"}, {"numero": 23, "texto": "Entonces Jehová respondió á Moisés: ¿Hase acortado la mano de Jehová? ahora verás si te sucede mi dicho, ó no."}, {"numero": 24, "texto": "Y salió Moisés, y dijo al pueblo las palabras de Jehová: y juntó los setenta varones de los ancianos del pueblo, é hízolos estar alrededor del tabernáculo."}, {"numero": 25, "texto": "Entonces Jehová descendió en la nube, y hablóle; y tomó del espíritu que estaba en él, y púsolo en los setenta varones ancianos; y fué que, cuando posó sobre ellos el espíritu, profetizaron, y no cesaron."}, {"numero": 26, "texto": "Y habían quedado en el campo dos varones, llamado el uno Eldad y el otro Medad, sobre los cuales también reposó el espíritu: estaban estos entre los escritos, mas no habían salido al tabernáculo; y profetizaron en el campo."}, {"numero": 27, "texto": "Y corrió un mozo, y dió aviso á Moisés, y dijo: Eldad y Medad profetizan en el campo."}, {"numero": 28, "texto": "Entonces respondió Josué hijo de Nun, ministro de Moisés, uno de sus mancebos, y dijo: Señor mío Moisés, impídelos."}, {"numero": 29, "texto": "Y Moisés le respondió: ¿Tienes tú celos por mí? mas ojalá que todo el pueblo de Jehová fuesen profetas, que Jehová pusiera su espíritu sobre ellos."}, {"numero": 30, "texto": "Y recogióse Moisés al campo, él y los ancianos de Israel."}, {"numero": 31, "texto": "Y salió un viento de Jehová, y trajo codornices de la mar, y dejólas sobre el real, un día de camino de la una parte, y un día de camino de la otra, en derredor del campo, y casi dos codos sobre la haz de la tierra."}, {"numero": 32, "texto": "Entonces el pueblo estuvo levantado todo aquel día, y toda la noche, y todo el día siguiente, y recogiéronse codornices: el que menos, recogió diez montones; y las tendieron para sí á lo largo en derredor del campo."}, {"numero": 33, "texto": "Aun estaba la carne entre los dientes de ellos, antes que fuese mascada, cuando el furor de Jehová se encendió en el pueblo, é hirió Jehová al pueblo con una muy grande plaga."}, {"numero": 34, "texto": "Y llamó el nombre de aquel lugar Kibroth-hattaavah, por cuanto allí sepultaron al pueblo codicioso."}, {"numero": 35, "texto": "De Kibroth-hattaavah movió el pueblo á Haseroth, y pararon en Haseroth."}]'::jsonb, 'Reina-Valera 1909')
